__load("play",{"edison/blackwing":{"win":{"plan":"tempo","pace":"medium","bullets":[{"es":"Gana por tempo: entra Blackwings baratos (Gale y Bora salen gratis de la mano si ya controlás un Blackwing) y sostiene el campo con trampas.","en":"Wins on tempo: gets cheap Blackwings out (Gale and Bora Special Summon from hand for free if you already control a Blackwing) and holds the board with traps."},{"es":"Cierra con Sincros: Black Rose Dragon limpia el campo y Blackwing Armor Master no se destruye en batalla.","en":"Closes with Synchros: Black Rose Dragon wipes the field and Blackwing Armor Master cannot be destroyed by battle."},{"es":"Gale (Limitada en la lista de marzo de 2010) reduce a la mitad el ATK y la DEF de un monstruo rival boca arriba: un Blackwing de 1700 o 2000 de ATK pasa por encima de cuerpos grandes.","en":"Gale (Limited on the March 2010 list) halves the ATK and DEF of a face-up opposing monster: a Blackwing with 1700 or 2000 ATK gets past big bodies."},{"es":"Black Whirlwind (semi-limitada) agrega un Blackwing de menos ATK cada vez que otro entra por invocación normal. Vayu trae desde el Cementerio un Sincro con efectos anulados, e Icarus Attack (tributa un Winged Beast) destruye 2 cartas para abrir camino.","en":"Black Whirlwind (Semi-Limited) adds a Blackwing with less ATK each time another is Normal Summoned. Vayu brings out a Synchro with negated effects from the Graveyard, and Icarus Attack (Tributes a Winged Beast) destroys 2 cards to open the way."}]},"starters":[{"cards":["Blackwing - Shura the Blue Flame","Blackwing - Gale the Whirlwind"],"route":{"es":"Shura (nivel 4) por invocación normal + Gale (Tuner nivel 3) desde la mano: nivel 7 para Black Rose Dragon o Blackwing Armor Master.","en":"Shura (Level 4) by Normal Summon + Gale (Level 3 Tuner) from hand: Level 7 for Black Rose Dragon or Blackwing Armor Master."}},{"cards":["Blackwing - Sirocco the Dawn"],"route":{"es":"Si el rival tiene un monstruo y vos ninguno, Sirocco se invoca sin tributo y ya presiona con 2000 de ATK.","en":"If your opponent has a monster and you have none, Sirocco is Normal Summoned without a Tribute and already pressures with 2000 ATK."}},{"cards":["Blackwing - Blizzard the Far North"],"route":{"es":"Blizzard (Tuner nivel 2) por invocación normal revive del Cementerio, en Defensa, un Blackwing de nivel 4 o menos: con un Kalut enviado antes (nivel 3) da nivel 5, con Shura o Bora (nivel 4) da nivel 6 para un Sincro.","en":"Blizzard (Level 2 Tuner) by Normal Summon revives a Level 4 or lower Blackwing from the Graveyard in Defense Position: with a Kalut sent earlier (Level 3) it makes Level 5, with Shura or Bora (Level 4) Level 6 for a Synchro."}}],"chokepoints":[{"card":"Royal Oppression","step":"summon","stepText":{"es":"En la invocación especial de Gale, Bora o del Sincro.","en":"On the Special Summon of Gale, Bora or the Synchro."},"loss":{"es":"Anula y destruye la invocación pagando 800 LP. Duele más contra el Sincro: los materiales ya se fueron. Invocá primero lo que no importa.","en":"Negates and destroys the Summon for 800 LP. It hurts most against the Synchro: the materials are already gone. Summon what does not matter first."}},{"card":"Solemn Judgment","step":"summon","stepText":{"es":"En cualquier invocación (también la normal) o al activar una Magia/Trampa.","en":"On any Summon (Normal too) or when a Spell/Trap is activated."},"loss":{"es":"Anula la invocación (también la normal) o la activación de una Magia/Trampa pagando la mitad de los LP. Si lo tienen seteado, hacé que lo gaste una invocación barata antes de arriesgar el Sincro.","en":"Negates the Summon (Normal too) or a Spell/Trap activation for half the LP. If they have it set, make a cheap Summon spend it before risking the Synchro."}},{"card":"Torrential Tribute","step":"summon","stepText":{"es":"Cuando se invoca un monstruo: ya hay un Blackwing y el Sincro en el campo.","en":"When a monster is Summoned: a Blackwing and the Synchro are already on the field."},"loss":{"es":"Destruye todos los monstruos del campo, los tuyos incluidos. Invocá de a una pieza por vez y no vacíes la mano en un solo turno.","en":"Destroys all monsters on the field, yours included. Summon one piece at a time and do not empty your hand in a single turn."}},{"card":"Mirror Force","step":"attack","stepText":{"es":"En tu declaración de ataque, con varios monstruos en Posición de Ataque.","en":"On your attack declaration, with several monsters in Attack Position."},"loss":{"es":"Destruye todos tus monstruos en Posición de Ataque. Con trampas boca abajo en el campo rival, atacá con un solo monstruo y dejá el resto en Defensa.","en":"Destroys all your Attack Position monsters. With face-down Traps on the opponent's field, attack with a single monster and keep the rest in Defense."}},{"card":"Skill Drain","step":"main","stepText":{"es":"Boca arriba desde antes de tu Main Phase 1.","en":"Face-up before your Main Phase 1."},"loss":{"es":"Anula los efectos de los monstruos boca arriba en el campo: Sirocco, Shura y Blizzard dejan de funcionar y Gale ya no reduce el ATK. Gale y Bora siguen entrando desde la mano y Vayu actúa desde el Cementerio. Se saca con Mystical Space Typhoon o Heavy Storm.","en":"Negates the effects of face-up monsters on the field: Sirocco, Shura and Blizzard stop working and Gale no longer halves ATK. Gale and Bora can still come in from the hand and Vayu acts from the Graveyard. Remove it with Mystical Space Typhoon or Heavy Storm."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Royal Oppression","qty":1,"why":{"es":"Trampa para el turno 1: te deja pagar 800 LP para anular una invocación especial del rival en su turno (él puede hacer lo mismo con las tuyas).","en":"A turn 1 Trap: lets you pay 800 LP to negate the opponent's Special Summon on their turn (they can do the same to yours)."}}],"out":[{"card":"Brain Control","qty":1,"why":{"es":"Necesita un monstruo rival boca arriba: yendo primero no tiene objetivo.","en":"It needs a face-up opposing monster: going first it has no target."}}]},"second":{"in":[{"card":"Fissure","qty":2,"why":{"es":"Destruye el monstruo de menor ATK: bueno contra un campo de un solo monstruo.","en":"Destroys the lowest ATK monster: good against a one-monster field."}}],"out":[{"card":"Legacy of Yata-Garasu","qty":2,"why":{"es":"Roba, pero no hace nada en el tablero: yendo segundo hace falta interacción.","en":"It draws, but does nothing on the board: going second you need interaction."}}]}},"updated":"2026-10-26","sources":[{"name":"Blackwing - Gale the Whirlwind","url":"https://yugipedia.com/wiki/Blackwing_-_Gale_the_Whirlwind","kind":"cards","checked":"2026-10-27"},{"name":"Blackwing - Blizzard the Far North","url":"https://yugipedia.com/wiki/Blackwing_-_Blizzard_the_Far_North","kind":"cards","checked":"2026-10-27"},{"name":"Edison Format Deck Introduction : Blackwings","url":"https://ygoprodeck.com/article/edison-format-deck-introduction-blackwings-94007","kind":"guide","checked":"2026-10-27"},{"name":"What Deck to play? - EDISON FORMAT","url":"https://www.edisonformat.com/what-deck-to-play.html","kind":"guide","checked":"2026-10-27"},{"name":"What is Edison Format? Rules, best decks, and tips","url":"https://ultimateguard.com/en/blog/edison-format-yu-gi-oh-rules-best-decks-tips","kind":"guide","checked":"2026-10-27"},{"name":"March 2010 Lists (TCG)","url":"https://yugipedia.com/wiki/March_2010_Lists_(TCG)","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Yugipedia muestra el texto actual de las cartas, que en algunos casos difiere del de 2010. Para los rulings y la errata funcional de la época mirá las reglas de edisonformat.com.","en":"Yugipedia shows the current card text, which in some cases differs from the 2010 wording. For period rulings and functional errata, see the rules section of edisonformat.com."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes lista un Side Deck para este mazo.","en":"The Side Deck is editorial judgment: none of the sources lists a Side Deck for this deck."}]},"adv/elfnote":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Medius the Pure suma o invoca un Power Patron del Mazo. Elfnote Power Patron sube 3 niveles al monstruo de tu zona central y hace un Sincro al instante; al ir al Cementerio como material, busca una carta Elfnote.","en":"Medius the Pure adds or Special Summons a Power Patron from the Deck. Elfnote Power Patron raises the monster in your center zone by 3 Levels and Synchro Summons right away; sent to the GY as material, it searches an Elfnote card."},{"es":"Lucina, Fortuna y Regina rotan por la zona central de monstruos. Lucina devuelve a la mano un monstruo rival de nivel 6 o menos y Fortuna un Mágica/Trampa boca arriba, ambas como efecto rápido en el turno rival.","en":"Lucina, Fortuna and Regina rotate through the center Main Monster Zone. Lucina returns a Level 6 or lower opposing monster to the hand and Fortuna a face-up Spell/Trap, both as Quick Effects on the opponent's turn."},{"es":"Elfnotes: Welcome Home protege de la destrucción por efecto al monstruo del centro, y Elfnotes: Rhapsodia of Madness impide que los monstruos rivales ataquen a otro que no sea el del centro; además, al revivir un Elfnote del Cementerio, si controlás un Sincro, niega los efectos de una carta rival boca arriba hasta el final del turno.","en":"Elfnotes: Welcome Home keeps the center monster from being destroyed by card effects, and Elfnotes: Rhapsodia of Madness stops opposing monsters from attacking anything but the center monster; also, when it revives an Elfnote from the GY, if you control a Synchro, it negates the effects of a face-up opposing card until the end of the turn."},{"es":"Elfnote Power Patron (mientras esté boca arriba) y el efecto de invocación de Welcome Home te limitan el Extra Deck a Sincros: terminá cualquier invocación de otro tipo antes de usarlos.","en":"Elfnote Power Patron (while face-up) and Welcome Home's Summon effect limit your Extra Deck to Synchros: finish any other kind of Extra Deck Summon before using them."}]},"starters":[{"cards":["Elfnote Lucina"],"route":{"es":"Lucina entra a la zona central desde la mano y suma otra Elfnote del Mazo (Regina o Power Patron, según lo que falte). Es la apertura más flexible: no te encierra en Sincros desde el primer paso.","en":"Lucina goes to the center zone from the hand and adds another Elfnote from the Deck (Regina or Power Patron, whichever you need). The most flexible opener: it does not lock you into Synchros from the first step."}},{"cards":["Medius the Pure","Elfnote Power Patron"],"route":{"es":"Medius suma o invoca Elfnote Power Patron del Mazo. Power Patron sube el nivel del monstruo del centro y hace un Sincro Elfnote; ya como material en el Cementerio, busca una carta Elfnote para seguir.","en":"Medius adds or Special Summons Elfnote Power Patron from the Deck. Power Patron raises the center monster's Level and makes an Elfnote Synchro; as material in the GY it searches an Elfnote card to keep going."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Lucina o la invocación desde el Mazo de Regina.","en":"On Lucina's search or Regina's Special Summon from the Deck."},"loss":{"es":"Niega ese efecto. Seguí con Regina (efecto rápido desde la mano) o con Medius en lugar de repetir la misma línea.","en":"Negates that effect. Continue with Regina (Quick Effect from hand) or Medius instead of repeating the same line."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Justo después de resolverse la primera búsqueda del Mazo (Lucina, Medius o Power Patron).","en":"Right after the first Deck search resolves (Lucina, Medius or Power Patron)."},"loss":{"es":"Ninguna otra carta puede sumarse del Mazo a la mano ese turno: perdés la búsqueda de Power Patron como material. Pasá a jugadas por invocación especial (Regina, Medius) y no cuentes con más búsquedas.","en":"No other card can be added from the Deck to the hand this turn: you lose Power Patron's material search. Switch to Special Summon plays (Regina, Medius) and do not count on more searches."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"Al llegar la quinta invocación del turno (Lucina, Regina, Medius, Power Patron y el Sincro suman rápido).","en":"On the fifth Summon of the turn (Lucina, Regina, Medius, Power Patron and the Synchro add up fast)."},"loss":{"es":"Tributa todos los monstruos boca arriba, los tuyos incluidos: Welcome Home solo frena la destrucción, no el Tributo. Contá las invocaciones y cortá en la cuarta si el tablero ya alcanza.","en":"Tributes every face-up monster, yours included: Welcome Home only stops destruction, not Tribute. Count your Summons and stop at the fourth if the board is already enough."}},{"card":"Mulcharmy Fuwalos","step":"main","stepText":{"es":"En tu Main Phase 1 si empezás primero: el rival no controla cartas y la activa desde la mano.","en":"In your Main Phase 1 when you go first: the opponent controls no cards and activates it from hand."},"loss":{"es":"Cada invocación tuya desde el Mazo o el Extra Deck le da una carta al rival. No te frena la jugada, pero castiga las rutas largas: elegí las de dos cartas.","en":"Each of your Special Summons from the Deck or Extra Deck gives the opponent a card. It does not stop the play, but it punishes long routes: pick the two-card ones."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En respuesta al efecto de Lucina, Regina o Medius ya en el campo.","en":"In response to the effect of Lucina, Regina or Medius already on the field."},"loss":{"es":"Niega ese efecto y la cadena de búsquedas se corta en el primer eslabón. Dejá una segunda salida en la mano (Regina se invoca como efecto rápido) antes de comprometer la apertura.","en":"Negates that effect and the search chain breaks at the first link. Keep a second exit in hand (Regina Summons herself as a Quick Effect) before committing the opener."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Solemn Judgment","qty":1,"why":{"es":"Primera trampa de tu turno 1: frena la invocación o la activación que más duele en el turno rival.","en":"A turn 1 Trap: stops the Summon or activation that hurts most on the opponent's turn."}},{"card":"Skull Meister","qty":2,"why":{"es":"Niega efectos activados en el Cementerio rival: útil contra mazos que se recuperan desde ahí.","en":"Negates effects activated in the opponent's GY: useful against decks that recover from there."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Se activa solo si no controlás cartas: yendo primero, con tablero, queda muerta en la mano.","en":"It only activates if you control no cards: going first, with a board, it sits dead in hand."}},{"card":"Pendulum Treasure","qty":1,"why":{"es":"Pieza de armado lenta; el cupo se usa mejor en interrupción.","en":"A slow setup piece; the slot is better spent on interruption."}}]},"second":{"in":[{"card":"Typhoon","qty":2,"why":{"es":"Destruye una carta boca arriba que te frene los Sincros o la jugada, y se activa desde la mano si el rival tiene 2 o más Mágicas/Trampas y vos ninguna.","en":"Destroys a face-up card that slows your Synchros or your play, and it can be activated from hand if the opponent has 2 or more Spells/Traps and you have none."}}],"out":[{"card":"Pendulum Treasure","qty":2,"why":{"es":"Segundo, tu prioridad es romper el tablero rival, no sumar piezas de armado.","en":"Going second, your priority is breaking the opposing board, not adding setup pieces."}}]}},"updated":"2026-10-27","sources":[{"name":"Elfnote","url":"https://yugipedia.com/wiki/Elfnote","kind":"guide","checked":"2026-10-27"},{"name":"Elfnote Power Patron","url":"https://yugipedia.com/wiki/Elfnote_Power_Patron","kind":"cards","checked":"2026-10-27"},{"name":"Elfnotes: Welcome Home","url":"https://yugipedia.com/wiki/Elfnotes:_Welcome_Home","kind":"cards","checked":"2026-10-27"},{"name":"Elfnote Guide | Master Duel Meta","url":"https://www.masterduelmeta.com/articles/guides/elfnote-galacticjoey/","kind":"guide","checked":"2026-10-27"},{"name":"YCS Montreal - Yu-Gi-Oh! Tournament","url":"https://ygoprodeck.com/tournament/ycs-montreal-4842","kind":"results","checked":"2026-10-27"},{"name":"Forbidden & Limited Lists - October 19, 2026 | Official Website","url":"https://www.yugioh-card.com/en/limited/list_2026-10-19/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Yugipedia y la guía de Master Duel Meta (mayo de 2026) cuentan a Elfnote Tinia como parte del motor, pero la banlist del 19 de octubre de 2026 la dejó Prohibida: revisá esas líneas antes de copiarlas.","en":"Yugipedia and the Master Duel Meta guide (May 2026) count Elfnote Tinia as part of the engine, but the October 19, 2026 list made it Forbidden: check those lines before copying them."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas lo respalda con estadísticas.","en":"The Side Deck is editorial judgment: none of the linked sources backs it with statistics."}]},"adv/kewl-tune":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Todos los monstruos son Tuners y los Sincros piden casi solo Tuners (Yugipedia). Con Cue, Reco, Mix y Clip se arma una cadena de Sincros que dejan la mano rival y el Mazo expuestos.","en":"Every monster is a Tuner and the Synchros ask almost only for Tuners (Yugipedia). Cue, Reco, Mix and Clip build a chain of Synchros that exposes the opponent's hand and Deck."},{"es":"La interrupción sale al mandar los Tuners al Cementerio como material: Cue excava 2 cartas del Mazo rival y destierra una, Reco destruye un Mágica/Trampa, Mix destruye un monstruo y Clip destierra una carta al azar del Extra Deck rival.","en":"The disruption comes from sending Tuners to the GY as material: Cue excavates 2 cards from the opponent's Deck and banishes one, Reco destroys a Spell/Trap, Mix destroys a monster and Clip banishes a random card from the opponent's Extra Deck."},{"es":"Fydraulis Harmonia es la pieza de interacción en la mano: en el efecto de un monstruo rival se invoca y, mostrando a Harmonia más 5 Sincros del Extra Deck (6 cartas en total), destruye un monstruo (a costa de no poder activar efectos de monstruos del Extra Deck que no sean Sincro hasta el final de tu próximo turno).","en":"Fydraulis Harmonia is the interaction piece in hand: on a monster effect from the opponent it Summons itself and, revealing Harmonia plus 5 Synchros from the Extra Deck (6 cards in total), destroys a monster (at the cost of being unable to activate Extra Deck monster effects other than Synchros until the end of your next turn)."},{"es":"Clip y Kewl Tune Remix hacen Sincros en el turno rival; Kewl Tune B2B es la ruta de daño, con segundo ataque para tus Tuners.","en":"Clip and Kewl Tune Remix make Synchros on the opponent's turn; Kewl Tune B2B is the damage route, giving your Tuners a second attack."}]},"starters":[{"cards":["Kewl Tune Cue"],"route":{"es":"Cue por invocación normal invoca a Mix desde el Mazo; Mix suma otro Kewl Tune (que no sea de nivel 2) y con Cue + Mix (2 + 3) se hace Kewl Tune Remix. Al ir como material, Cue excava el Mazo rival y Mix destruye un monstruo.","en":"Cue Normal Summoned Summons Mix from the Deck; Mix adds another Kewl Tune (not Level 2) and Cue + Mix (2 + 3) make Kewl Tune Remix. As material, Cue excavates the opposing Deck and Mix destroys a monster."}},{"cards":["Kewl Tune Reco","JJ \"Kewl Tune\""],"route":{"es":"Reco suma a Mix; JJ \"Kewl Tune\" da una segunda invocación normal para un Tuner, así que Mix entra también y suma otro Kewl Tune. Reco + Mix hacen Remix y Reco, al ser material, destruye un Mágica/Trampa.","en":"Reco adds Mix; JJ \"Kewl Tune\" gives a second Normal Summon for a Tuner, so Mix also comes down and adds another Kewl Tune. Reco + Mix make Remix and Reco, as material, destroys a Spell/Trap."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Reco o Mix, o la invocación de Cue desde el Mazo.","en":"On Reco's or Mix's search, or Cue's Summon from the Deck."},"loss":{"es":"Niega ese efecto. Con Cue ya en el campo podés reencaminar con otra pieza de la mano o el Cementerio.","en":"Negates that effect. With Cue already on the field you can reroute through another piece from hand or GY."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Tras resolverse la primera búsqueda del Mazo (Reco, Mix, Track Maker o Kewl Tune Synchro).","en":"After the first Deck search resolves (Reco, Mix, Track Maker or Kewl Tune Synchro)."},"loss":{"es":"Bloquea las búsquedas del Mazo que siguen; Reco y Mix todavía pueden sumar un Kewl Tune desde el Cementerio. Priorizá invocaciones sin búsqueda como Cue.","en":"Blocks the Deck searches that follow; Reco and Mix can still add a Kewl Tune from the GY. Favor Summons without a search such as Cue."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta invocación del turno: Tuners y Sincros suman muy rápido.","en":"On the fifth Summon of the turn: Tuners and Synchros add up very fast."},"loss":{"es":"Tributa todo tu tablero y deja una ficha enorme del lado rival. Aprendé en qué invocación vas y frená en la cuarta si la mano ya cierra un tablero útil.","en":"Tributes your whole board and leaves a huge token on the opponent's side. Track your Summon count and stop at the fourth if your hand already closes a useful board."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En respuesta al efecto de Cue, Reco o Mix recién invocados.","en":"In response to the effect of a freshly Summoned Cue, Reco or Mix."},"loss":{"es":"Niega el efecto del Tuner inicial y se pierde la búsqueda o la invocación en cadena. Guardá un segundo Tuner en la mano para rearmar.","en":"Negates the opening Tuner's effect, so the search or chained Summon is lost. Keep a second Tuner in hand to rebuild."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Mannadium Reframing","qty":1,"why":{"es":"Trampa que niega una activación mientras controles un Sincro; Visas Amritara la busca al invocarse.","en":"A Trap that negates an activation while you control a Synchro; Visas Amritara searches it when Summoned."}},{"card":"D.D. Crow","qty":2,"why":{"es":"Efecto rápido desde la mano: destierra una carta del Cementerio rival. No es Tuner, así que no sirve de material para los Sincros del mazo.","en":"Quick Effect from hand: banishes a card from the opponent's GY. It is not a Tuner, so it cannot serve as material for the deck's Synchros."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Necesita que no controles cartas: yendo primero queda muerta.","en":"It needs you to control no cards: going first it is dead."}},{"card":"The Fallen & The Virtuous","qty":1,"why":{"es":"Su primer efecto pide un monstruo del Extra Deck que mencione a Fallen of Albaz (Ecclesia and the Dark Dragon lo hace): con pocos así, una copia alcanza.","en":"Its first effect needs an Extra Deck monster that mentions Fallen of Albaz (Ecclesia and the Dark Dragon does): with few of those, one copy is enough."}}]},"second":{"in":[{"card":"Lightning Storm","qty":1,"why":{"es":"Si no controlás cartas boca arriba, destruye todos los monstruos en Ataque o todas las Mágicas/Trampas rivales.","en":"If you control no face-up cards, destroys all Attack Position monsters or all Spells/Traps the opponent controls."}},{"card":"Illusion Gate","qty":1,"why":{"es":"Destruye todos los monstruos rivales una vez por Duelo y te deja invocar uno de su Cementerio.","en":"Destroys all opposing monsters once per Duel and lets you Summon one from their GY."}},{"card":"Harpie's Feather Duster","qty":1,"why":{"es":"Limita a 1 y limpia el fondo de campo rival cuando vas segundo y el mazo sufre contra tableros armados.","en":"Limited to 1 and clears the opposing backrow when you go second and the deck struggles against built boards."}}],"out":[{"card":"The Fallen & The Virtuous","qty":2,"why":{"es":"Depende de tener en el Extra Deck un monstruo que mencione a Fallen of Albaz; mejor un rompe-tableros.","en":"It depends on having an Extra Deck monster that mentions Fallen of Albaz; a board breaker is better."}},{"card":"Ghost Ogre & Snow Rabbit","qty":1,"why":{"es":"Se cede una interrupción chica a cambio de poder romper el tablero.","en":"You give up a small interruption in exchange for being able to break the board."}}]}},"updated":"2026-10-27","sources":[{"name":"Kewl Tune","url":"https://yugipedia.com/wiki/Kewl_Tune","kind":"guide","checked":"2026-10-27"},{"name":"Kewl Tune Cue","url":"https://yugipedia.com/wiki/Kewl_Tune_Cue","kind":"cards","checked":"2026-10-27"},{"name":"Fydraulis Harmonia","url":"https://yugipedia.com/wiki/Fydraulis_Harmonia","kind":"cards","checked":"2026-10-27"},{"name":"Kewl Tune Deck from Sweep | Master Duel Meta","url":"https://www.masterduelmeta.com/top-decks/master-i/april-2026/kewl-tune/sweep/DkdGu/","kind":"guide","checked":"2026-10-27"},{"name":"YCS Montreal - Yu-Gi-Oh! Tournament","url":"https://ygoprodeck.com/tournament/ycs-montreal-4842","kind":"results","checked":"2026-10-27"},{"name":"Forbidden & Limited Lists - October 19, 2026 | Official Website","url":"https://www.yugioh-card.com/en/limited/list_2026-10-19/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La lista de referencia que muestra la página es anterior a la banlist del 19 de octubre de 2026: lleva Kewl Tune Rotary x3, Albion the Branded Dragon, Triple Tactics Talent y Called by the Grave (Prohibidas) y Droll & Lock Bird x2 (Limitada a 1). Yugipedia y Master Duel Meta (abril) tratan a Rotary como pieza central; la ficha no la usa.","en":"The reference list shown on the page predates the October 19, 2026 list: it has Kewl Tune Rotary x3, Albion the Branded Dragon, Triple Tactics Talent and Called by the Grave (Forbidden) and Droll & Lock Bird x2 (Limited to 1). Yugipedia and Master Duel Meta (April) treat Rotary as a core piece; the sheet does not use it."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas lo respalda con estadísticas.","en":"The Side Deck is editorial judgment: none of the linked sources backs it with statistics."}]},"adv/branded":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Es un mazo de Fusión basado en Mágicas y Trampas: Aluber y Springans Kitt llevan a Branded Fusion y al resto de la familia, y Albion the Shrouded Dragon manda cartas Branded al Cementerio (Yugipedia).","en":"A Spell and Trap based Fusion deck: Aluber and Springans Kitt lead to Branded Fusion and the rest of the family, and Albion the Shrouded Dragon sends Branded cards to the Graveyard (Yugipedia)."},{"es":"Fallen of Albaz fusiona con monstruos de cualquier campo: incluso arrastra a los del rival. Lubellion encadena otra Fusión descartando una carta.","en":"Fallen of Albaz fuses with monsters from either field, taking the opponent's along. Lubellion chains another Fusion by discarding a card."},{"es":"Mirrorjade destierra un monstruo como efecto rápido (mandando al Cementerio una Fusión del Extra Deck que mencione a Fallen of Albaz) y no puede repetirlo el turno siguiente; Granguignol, cuando el rival invoca un monstruo con el efecto activado de otro, se destierra para invocar un Dogmatika del Mazo o un Despia del Extra Deck. Los Albaz del Cementerio sostienen el desgaste.","en":"Mirrorjade banishes a monster as a Quick Effect (sending a Fusion Monster that mentions Fallen of Albaz from the Extra Deck to the GY) and cannot repeat it next turn; Granguignol, when the opponent Special Summons a monster with another monster's activated effect, banishes itself to Special Summon a Dogmatika from the Deck or a Despia from the Extra Deck. The Albaz in the GY sustain the attrition."},{"es":"Branded Retribution niega una activación que invoque algo, devolviendo una Fusión al Extra Deck, y Super Polymerization responde a tableros con una Fusión que no se puede encadenar.","en":"Branded Retribution negates an activation that Summons something by returning a Fusion to the Extra Deck, and Super Polymerization answers boards with a Fusion nobody can chain to."}]},"starters":[{"cards":["Aluber the Jester of Despia"],"route":{"es":"Aluber suma una Mágica/Trampa Branded (en general Branded Fusion o Branded Opening) y desde ahí se arma la primera Fusión con Fallen of Albaz.","en":"Aluber adds a Branded Spell/Trap (usually Branded Fusion or Branded Opening) and the first Fusion with Fallen of Albaz builds from there."}},{"cards":["Nadir Servant","Fallen of Albaz"],"route":{"es":"Nadir Servant manda un monstruo del Extra Deck al Cementerio y suma a Fallen of Albaz (o a un Dogmatika) con ATK igual o menor; Albaz, al invocarse, descarta una carta y hace una Fusión con monstruos de ambos campos.","en":"Nadir Servant sends an Extra Deck monster to the GY and adds Fallen of Albaz (or a Dogmatika) with equal or lower ATK; Albaz, when Summoned, discards a card and Fusion Summons with monsters from both fields."}},{"cards":["Branded Opening"],"route":{"es":"Branded Opening descarta una carta y toma a un Despia (Aluber) del Mazo, a la mano o invocado en Defensa; es la entrada cuando no hay Aluber en la mano.","en":"Branded Opening discards a card and takes a Despia (Aluber) from the Deck, to the hand or Summoned in Defense; it is the entry when Aluber is not in hand."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre el efecto de Aluber o de Branded Fusion.","en":"On the effect of Aluber or Branded Fusion."},"loss":{"es":"Niega el efecto, y según Yugipedia eso recorta mucho las jugadas porque Branded Lost no protege contra esta forma de negación. Super Polymerization (no se puede responder) es la salida.","en":"Negates the effect, and per Yugipedia that cuts the plays a lot because Branded Lost does not protect against this kind of negation. Super Polymerization (cannot be responded to) is the way around it."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Tras resolverse la primera búsqueda de Aluber o de Springans Kitt.","en":"After Aluber's or Springans Kitt's first search resolves."},"loss":{"es":"Se cortan las demás sumas desde el Mazo; Nadir Servant todavía puede sumar a Fallen of Albaz o a un Dogmatika desde el Cementerio. Construí el turno con lo que ya tenés en la mano y los Albaz del Cementerio.","en":"The other adds from the Deck are cut; Nadir Servant can still add Fallen of Albaz or a Dogmatika from the GY. Build the turn from what you already hold and the Albaz in the GY."}},{"card":"Dominus Impulse","step":"activation","stepText":{"es":"Al activar Branded Fusion o el efecto de Fallen of Albaz, que invocan monstruos.","en":"When activating Branded Fusion or Fallen of Albaz's effect, which Summon monsters."},"loss":{"es":"Niega el efecto que invoca y, si el rival tiene una Trampa en su Cementerio, destruye la carta. Si la activó desde la mano, él no puede activar efectos de monstruos LIGHT, EARTH ni WIND el resto del Duelo. Ante dos negaciones posibles, abrí con Super Polymerization.","en":"Negates the Summoning effect and, if the opponent has a Trap in their GY, destroys the card. If they activated it from the hand, they cannot activate LIGHT, EARTH or WIND monster effects for the rest of the Duel. Facing two possible negations, open with Super Polymerization."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"En respuesta al efecto que apunta a un Albaz o a un monstruo Fusión en el Cementerio.","en":"In response to the effect that targets an Albaz or a Fusion Monster in the GY."},"loss":{"es":"Destierra el objetivo y la recuperación se cae: Guiding Quem, Branded Retribution y las recuperaciones de Dogmatika dependen del Cementerio, según Yugipedia el punto débil de la ventaja del mazo.","en":"Banishes the target and the recovery fails: Guiding Quem, Branded Retribution and the Dogmatika recoveries rely on the GY, which per Yugipedia is the weak spot of the deck's advantage."}},{"card":"Non-Fusion Area","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase 1.","en":"Face-up before your Main Phase 1."},"loss":{"es":"Nadie puede invocar por Fusión: el mazo se queda sin su motor. Hay que quitarla con Mystical Space Typhoon o Typhoon; sin ellas la mano se juega con Fallen of the White Dragon y los Ecclesia de a uno.","en":"Nobody can Fusion Summon: the deck loses its engine. Remove it with Mystical Space Typhoon or Typhoon; without them the hand plays out with Fallen of the White Dragon and the Ecclesia monsters one by one."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Mistaken Arrest","qty":2,"why":{"es":"Impide que el rival sume cartas del Mazo en su turno; tené presente que también corta tus búsquedas hasta el final de tu turno siguiente.","en":"Stops the opponent from adding cards from the Deck on their turn; remember it also cuts your own searches until the end of your next turn."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Se activa solo si no controlás cartas: yendo primero tenés tablero.","en":"It only activates if you control no cards: going first you have a board."}}]},"second":{"in":[{"card":"Typhoon","qty":2,"why":{"es":"Branded no tiene respuesta propia a un fondo de campo boca arriba como Non-Fusion Area; Typhoon la destruye.","en":"Branded has no built-in answer to a face-up backrow such as Non-Fusion Area; Typhoon destroys it."}}],"out":[{"card":"Gold Sarcophagus","qty":1,"why":{"es":"Tarda dos turnos en dar su carta; yendo segundo necesitás efecto inmediato.","en":"It takes two turns to give its card; going second you need immediate effect."}},{"card":"Cocatorium the Heavy Metal Avian","qty":1,"why":{"es":"Se invoca tributando una Bestia, Bestia Guerrera o Alada y se destierra al salir del campo: es la pieza del Main menos ligada al plan de Fusión, así que cede su lugar a una carta de respuesta.","en":"It Special Summons by Tributing a Beast, Beast-Warrior or Winged Beast and is banished when it leaves the field: the Main Deck piece least tied to the Fusion plan, so it gives its slot to a response card."}}]}},"updated":"2026-10-27","sources":[{"name":"Branded","url":"https://yugipedia.com/wiki/Branded","kind":"guide","checked":"2026-10-27"},{"name":"Fallen of Albaz","url":"https://yugipedia.com/wiki/Fallen_of_Albaz","kind":"cards","checked":"2026-10-27"},{"name":"Branded Retribution","url":"https://yugipedia.com/wiki/Branded_Retribution","kind":"cards","checked":"2026-10-27"},{"name":"In-Depth Branded Bystial Guide | Master Duel Meta","url":"https://www.masterduelmeta.com/articles/guides/branded-bystial-vector","kind":"guide","checked":"2026-10-27"},{"name":"YCS Montreal - Yu-Gi-Oh! Tournament","url":"https://ygoprodeck.com/tournament/ycs-montreal-4842","kind":"results","checked":"2026-10-27"},{"name":"Forbidden & Limited Lists - October 19, 2026 | Official Website","url":"https://www.yugioh-card.com/en/limited/list_2026-10-19/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Yugipedia nombra a Albion the Branded Dragon como uno de los buscadores del mazo, y desde el 19 de octubre de 2026 está Prohibida: las guías y la página de Yugipedia cuentan con una carta que ya no se puede jugar.","en":"Yugipedia names Albion the Branded Dragon as one of the deck's searchers, and since October 19, 2026 it is Forbidden: the guides and the Yugipedia page count on a card that can no longer be played."},{"es":"La única guía de estrategia enlazada es de junio de 2023 y de Master Duel: sirve para la lógica del mazo, no para la lista actual.","en":"The only strategy guide linked is from June 2023 and for Master Duel: it works for the deck's logic, not for the current list."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas lo respalda con estadísticas.","en":"The Side Deck is editorial judgment: none of the linked sources backs it with statistics."}]},"adv/maliss":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Los Maliss se auto-destierran para llenar el campo de material de Link: casi todos se invocan de nuevo del destierro por 300 LP (los Link por 900), y el Extra Deck queda limitado a Links (Yugipedia).","en":"Maliss monsters banish themselves to fill the field with Link material: nearly all come back from the banishment for 300 LP (the Links for 900), and the Extra Deck is limited to Links (Yugipedia)."},{"es":"Maliss in Underground destierra una carta Maliss al activarse, y con 3 Trampas Maliss distintas desterradas los Link Maliss ganan 3000 ATK; además los monstruos rivales solo pueden atacar a esos Link.","en":"Maliss in Underground banishes a Maliss card when activated, and with 3 different Maliss Traps banished the Maliss Links gain 3000 ATK; opposing monsters can only attack those Links."},{"es":"Cyberse Wicckid y Backup @Ignister dan la salida cuando no hay Maliss en la mano; Maliss in the Mirror (Mágica Rápida) niega los efectos de un monstruo rival boca arriba desterrando un monstruo Maliss de tu mano o campo y, al ser desterrada, destierra una carta Maliss del Cementerio para sumar otra del mismo tipo del Mazo.","en":"Cyberse Wicckid and Backup @Ignister are the way out when there is no Maliss in hand; Maliss in the Mirror (a Quick-Play Spell) negates a face-up opposing monster's effects by banishing a Maliss monster from your hand or field and, when banished, banishes a Maliss card from the GY to add another of the same type from the Deck."}]},"starters":[{"cards":["Maliss in Underground"],"route":{"es":"Al activarse (es una Mágica de Campo) destierra un Maliss <P> del Mazo, que por 300 LP se invoca de nuevo: ya tenés un cuerpo para Link Summon. Es la ruta más corta, y encadena con White Rabbit, Dormouse o March Hare.","en":"When activated (it is a Field Spell) it banishes a Maliss <P> from the Deck, which Special Summons itself again for 300 LP: you already have a body for a Link Summon. The shortest route, and it chains with White Rabbit, Dormouse or March Hare."}},{"cards":["Cyberse Wicckid","Backup @Ignister"],"route":{"es":"Wicckid (2 Cyberse) destierra un Cyberse del Cementerio al invocarse algo en su zona y suma a Backup @Ignister (Tuner Cyberse); Backup, al normal o especial, suma un Cyberse OSCURO del Mazo, sea un Maliss, y descarta una carta.","en":"Wicckid (2 Cyberse) banishes a Cyberse from the GY when something is Summoned to its zone and adds Backup @Ignister (a Cyberse Tuner); Backup, Normal or Special Summoned, adds a DARK Cyberse (a Maliss) from the Deck and discards a card."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Backup @Ignister o de Wicckid.","en":"On the search of Backup @Ignister or Wicckid."},"loss":{"es":"Niega la búsqueda que lleva a la ruta de Maliss. Si Ash cae en Backup, retomá con Maliss in Underground y el destierro propio, que no es una búsqueda.","en":"Negates the search that leads into the Maliss route. If Ash hits Backup, resume with Maliss in Underground and its own banishing, which is not a search."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera suma del Mazo (Backup, Wicckid o Maliss in the Mirror).","en":"After the first add from the Deck (Backup, Wicckid or Maliss in the Mirror)."},"loss":{"es":"Frena el resto de las búsquedas (Wicckid, Backup, Maliss in the Mirror). Abrí con Maliss in Underground, que destierra y no busca nada.","en":"Stops the rest of the searches (Wicckid, Backup, Maliss in the Mirror). Open with Maliss in Underground, which banishes and searches nothing."}},{"card":"Artifact Lancea","step":"activation","stepText":{"es":"En respuesta a Maliss in Underground o a cualquier efecto que destierre.","en":"In response to Maliss in Underground or any effect that banishes."},"loss":{"es":"Nadie puede desterrar cartas ese turno y se apaga el motor Maliss. Yugipedia lo cita junto a Chaos Hunter e Imperial Iron Wall. Con Lancea en mano rival, jugá las ramas que no destierran (Backup, Wicckid).","en":"Neither player can banish cards this turn and the Maliss engine shuts off. Yugipedia lists it alongside Chaos Hunter and Imperial Iron Wall. Against Lancea in hand, play the branches that do not banish (Backup, Wicckid)."}},{"card":"Imperial Iron Wall","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase 1.","en":"Face-up before your Main Phase 1."},"loss":{"es":"Nadie puede desterrar: ni Maliss in Underground ni los efectos de Link funcionan. Se saca con Typhoon o Mystical Space Typhoon; Cosmic Cyclone no sirve porque desterrar está prohibido. Sin respuestas, el turno se juega con Ignister y Ars Magna.","en":"Nobody can banish: neither Maliss in Underground nor the Link effects work. It is removed with Typhoon or Mystical Space Typhoon; Cosmic Cyclone is no use because banishing is forbidden. With no answers, the turn is played with Ignister and Ars Magna."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre el efecto de un Link Maliss o de Allied Code Talker ya en el campo.","en":"On the effect of a Maliss Link or Allied Code Talker already on the field."},"loss":{"es":"Niega el efecto del Link y deja el tablero sin su interacción. Si Maliss in the Mirror está en el Cementerio, desterrarla (por ejemplo con Maliss in Underground) suma una carta Maliss del mismo tipo que otra del Cementerio.","en":"Negates the Link's effect and leaves the board without its interaction. If Maliss in the Mirror is in the GY, banishing it (for example with Maliss in Underground) adds a Maliss card of the same type as another one in the GY."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Dominus Impulse","qty":3,"why":{"es":"Los Maliss y los Ignister son OSCUROS y no sufren su bloqueo de LIGHT, EARTH y WIND, pero Ars Magna the Finite and the Infinite (EARTH) y los demás monstruos de esos atributos del mazo sí lo sufren; frena las invocaciones del rival.","en":"Maliss and Ignister monsters are DARK and do not suffer its LIGHT, EARTH and WIND lock, but Ars Magna the Finite and the Infinite (EARTH) and the deck's other monsters of those Attributes do; it stops the opponent's Summons."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":3,"why":{"es":"Se activa solo sin cartas propias: yendo primero queda en la mano sin uso.","en":"It only activates with no cards of your own: going first it stays unused in hand."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":2,"why":{"es":"Niega los efectos de todos los monstruos rivales por un turno y evita el daño; arma el turno donde el motor Maliss sufre contra un tablero armado.","en":"Negates every opposing monster effect for a turn and prevents damage; it sets up the turn where the Maliss engine struggles against a built board."}}],"out":[{"card":"Gold Sarcophagus","qty":1,"why":{"es":"Tarda dos turnos, demasiado para un mazo que necesita romper el tablero ya.","en":"Takes two turns, too slow for a deck that needs to break the board now."}},{"card":"Terraforming","qty":1,"why":{"es":"Carta lenta que no empuja el turno de quiebre.","en":"A slow card that does not push the board-breaking turn."}}]}},"updated":"2026-10-27","sources":[{"name":"Maliss","url":"https://yugipedia.com/wiki/Maliss","kind":"guide","checked":"2026-10-27"},{"name":"Maliss in Underground","url":"https://yugipedia.com/wiki/Maliss_in_Underground","kind":"cards","checked":"2026-10-27"},{"name":"Artifact Lancea","url":"https://yugipedia.com/wiki/Artifact_Lancea","kind":"cards","checked":"2026-10-27"},{"name":"Introduction to Maliss | Master Duel Meta","url":"https://www.masterduelmeta.com/articles/guides/maliss-joey/","kind":"guide","checked":"2026-10-27"},{"name":"Forbidden & Limited Lists - October 19, 2026 | Official Website","url":"https://www.yugioh-card.com/en/limited/list_2026-10-19/","kind":"list","checked":"2026-10-27"},{"name":"Backup @Ignister","url":"https://yugipedia.com/wiki/Backup_@Ignister","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"La guía de Master Duel Meta (2025) apoya el plan en Maliss <Q> White Binder, que quedó Prohibida en el TCG el 19 de octubre de 2026.","en":"The Master Duel Meta guide (2025) builds the plan around Maliss <Q> White Binder, which became Forbidden in the TCG on October 19, 2026."},{"es":"Para este mazo no hay resultados de torneo enlazados: el plan se apoya en el texto de las cartas y en la guía de Master Duel Meta.","en":"There are no linked tournament results for this deck: the plan rests on the card texts and the Master Duel Meta guide."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas lo respalda con estadísticas.","en":"The Side Deck is editorial judgment: none of the linked sources backs it with statistics."}]},"adv/invoked":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"El motor original: Aleister the Invoker busca Invocation, Invocation hace la Fusión desterrando material de la mano, el campo y los Cementerios, y al volver al Mazo trae de nuevo a Aleister (Yugipedia).","en":"The original engine: Aleister the Invoker searches Invocation, Invocation Fusion Summons with material from hand, field and GYs, and returning to the Deck brings Aleister back (Yugipedia)."},{"es":"Aiwass, Aleister the Reminiscent y Virakam sostienen la búsqueda y la invocación propias; Magical Meltdown hace que las Fusiones del mazo no se puedan negar ni responder.","en":"Aiwass, Aleister the Reminiscent and Virakam sustain the searching and self-Summons; Magical Meltdown makes the deck's Fusions impossible to negate or respond to."},{"es":"Invoked Mechaba (Aleister + LIGHT) niega y destierra una carta descartando una del mismo tipo; Raidjin voltea un monstruo y Augoeides destruye un monstruo rival (apuntando) cuando se invoca o cuando el rival invoca por Especial.","en":"Invoked Mechaba (Aleister + LIGHT) negates and banishes a card by sending one of the same type from hand; Raidjin flips a monster face-down and Augoeides destroys an opposing monster (targeting) when it is Summoned or when the opponent Special Summons."},{"es":"Hyperinvoked Aeon (2 o más Fusiones de distinto atributo) destierra tantas cartas del campo y los Cementerios como materiales usados y, si usaste 3 o más, puede mirar el Extra Deck rival y desterrar hasta 3 cartas de ahí.","en":"Hyperinvoked Aeon (2 or more Fusions with different Attributes) banishes cards from the field and GYs up to the number of materials used and, if you used 3 or more, can look at the opposing Extra Deck and banish up to 3 cards from it."}]},"starters":[{"cards":["Aleister the Reminiscent"],"route":{"es":"Se invoca por normal, o por Especial desde la mano si hay un Hechicero o una Fusión en el campo; al invocarse destierra un Invoked del Extra Deck y suma Invocation (o una Mágica que la mencione). Por invocación normal es una apertura de una sola carta.","en":"Normal Summon it, or Special Summon it from hand if there is a Spellcaster or Fusion Monster on the field; when Summoned it banishes an Invoked from the Extra Deck and adds Invocation (or a Spell that mentions it). By Normal Summon it is a one-card opener."}},{"cards":["Magical Meltdown","Aleister the Invoker"],"route":{"es":"Magical Meltdown suma a Aleister the Invoker; invocarlo por normal busca Invocation, y con la Fusión resultante nadie puede responder porque Meltdown ya blindó la activación.","en":"Magical Meltdown adds Aleister the Invoker; Normal Summoning it searches Invocation, and nobody can respond to the resulting Fusion because Meltdown already shielded the activation."}},{"cards":["Aiwass, Divine Spirit of the Law"],"route":{"es":"Aiwass se destierra de la mano y suma a cualquier Aleister; si lo hacés desde el campo, además permite una invocación normal extra de un Spellcaster.","en":"Aiwass banishes itself from hand and adds any Aleister; from the field, it also allows an extra Normal Summon of a Spellcaster."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del Mazo (Aleister the Invoker o Aleister the Reminiscent).","en":"After the first Deck search (Aleister the Invoker or Aleister the Reminiscent)."},"loss":{"es":"Impide buscar Invocation salvo que la hayas robado (Yugipedia). Abrí con Invocation en mano, o con Virakam o Crowley si el rival ya mostró Droll.","en":"Stops you from searching Invocation unless you drew it (Yugipedia). Open with Invocation in hand, or with Virakam or Crowley if the opponent already showed Droll."}},{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Aleister the Invoker o de Invoked Baybarron.","en":"On the search of Aleister the Invoker or Invoked Baybarron."},"loss":{"es":"Yugipedia dice que una interrupción 1 a 1 como Ash frena el motor salvo que Invocation salga de la mano, y que es más fuerte contra Invoked Baybarron. Tené Meltdown o Sacred Spirit Sword Aiwass como segunda ruta.","en":"Yugipedia says a one-for-one interruption such as Ash stops the engine unless Invocation comes from hand, and that it is strongest against Invoked Baybarron. Keep Meltdown or Sacred Spirit Sword Aiwass as a second route."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En respuesta al efecto de Aleister que busca Invocation.","en":"In response to the Aleister effect that searches Invocation."},"loss":{"es":"Niega el efecto de Aleister y se pierde la búsqueda. Meltdown protege las Fusiones, no a Aleister: tené lista una segunda búsqueda (Reminiscent o Virakam).","en":"Negates Aleister's effect and the search is lost. Meltdown protects the Fusions, not Aleister: keep a second search ready (Reminiscent or Virakam)."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"En cuanto Aleister the Invoker queda en el Cementerio, antes de que Invocation lo tome como material.","en":"As soon as Aleister the Invoker sits in the GY, before Invocation takes it as material."},"loss":{"es":"Destierra a Aleister del Cementerio antes de que Invocation lo use como material y la Fusión pierde ese material (Invocation todavía puede recuperar a un Aleister desterrado desde su efecto en el Cementerio). Yugipedia nombra a Bystial, Mudora y D.D. Crow como el mismo problema.","en":"Banishes Aleister from the GY before Invocation uses it as material, so the Fusion loses that material (Invocation can still retrieve a banished Aleister through its GY effect). Yugipedia names Bystial, Mudora and D.D. Crow as the same problem."}},{"card":"Non-Fusion Area","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase 1.","en":"Face-up before your Main Phase 1."},"loss":{"es":"Nadie puede invocar por Fusión, así que ni Invocation ni Super Polymerization funcionan. Yugipedia lo cita con Dimensional Barrier y Fossil Dyna Pachycephalo (hoy Prohibidas en el TCG); el mazo de la lista no lleva una respuesta propia a Mágicas/Trampas.","en":"Nobody can Fusion Summon, so neither Invocation nor Super Polymerization works. Yugipedia cites it with Dimensional Barrier and Fossil Dyna Pachycephalo (both Forbidden in the TCG today); the list's deck carries no Spell/Trap answer of its own."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Solemn Judgment","qty":1,"why":{"es":"Frena la invocación o la activación del turno rival.","en":"Stops the opponent's Summon or activation on their turn."}},{"card":"Effect Veiler","qty":2,"why":{"es":"Niega el efecto de un monstruo rival en su Main Phase desde la mano.","en":"Negates an opposing monster's effect during their Main Phase from hand."}}],"out":[{"card":"Mulcharmy Purulia","qty":3,"why":{"es":"Se activa solo si no controlás cartas: yendo primero, con tablero, queda muerta en la mano.","en":"It only activates if you control no cards: going first, with a board, it sits dead in hand."}}]},"second":{"in":[{"card":"Nibiru, the Primal Being","qty":2,"why":{"es":"Contra un tablero que invoca 5 veces, tributa todo; Invoked no tiene tablero que perder yendo segundo.","en":"Against a board that Summons 5 times, tributes everything; Invoked has no board to lose going second."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Se recortan para meter una respuesta al tablero rival.","en":"Trimmed to make room for an answer to the opposing board."}}]}},"updated":"2026-10-27","sources":[{"name":"Invoked","url":"https://yugipedia.com/wiki/Invoked","kind":"guide","checked":"2026-10-27"},{"name":"Invocation","url":"https://yugipedia.com/wiki/Invocation","kind":"cards","checked":"2026-10-27"},{"name":"Magical Meltdown","url":"https://yugipedia.com/wiki/Magical_Meltdown","kind":"cards","checked":"2026-10-27"},{"name":"Invoked Guide | Master Duel Meta","url":"https://www.masterduelmeta.com/articles/guides/invoked-taffy/","kind":"guide","checked":"2026-10-27"},{"name":"Forbidden & Limited Lists - October 19, 2026 | Official Website","url":"https://www.yugioh-card.com/en/limited/list_2026-10-19/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La guía de Master Duel Meta (13 de octubre de 2026) es de Master Duel: sirve para el plan, pero sus listas y su banlist no son las del TCG.","en":"The Master Duel Meta guide (October 13, 2026) is for Master Duel: it works for the plan, but its lists and banlist are not the TCG's."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas lo respalda con estadísticas.","en":"The Side Deck is editorial judgment: none of the linked sources backs it with statistics."}]},"adv/angelechy":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Los monstruos Angelechy van a la Zona de Mágicas y Trampas como Mágicas Continuas y desde ahí hacen de floodgate: Castellan limita a 1 activación por cadena, Shatranga a 5 efectos de monstruo por turno y Destrier inflige 500 por cada activación rival.","en":"Angelechy monsters go to the Spell & Trap Zone as Continuous Spells and act as floodgates from there: Castellan limits to 1 activation per Chain, Shatranga to 5 monster effects per turn and Destrier inflicts 500 for each opposing activation."},{"es":"Angelechy Opening to e4 (una Trampa Normal) se activa desde la mano en la Standby Phase del primer turno rival si él empieza: pone el Campo, invoca un Angelechy de nivel 2 o 7 y coloca otro en la Zona de Mágicas. Yugipedia indica que el mazo está pensado para ir segundo.","en":"Angelechy Opening to e4 (a Normal Trap) activates from hand in the opponent's first Standby Phase if they go first: it places the Field Spell, Summons a Level 2 or 7 Angelechy and puts another in the Spell & Trap Zone. Yugipedia says the deck is meant to go second."},{"es":"Angelechy Verdict con 5 o más monstruos Angelechy en el campo destierra todas las cartas rivales; Angelechy Bastion protege de la destrucción por efecto a las demás.","en":"Angelechy Verdict with 5 or more Angelechy Monster Cards on the field banishes all of the opponent's cards; Angelechy Bastion protects the others from destruction by card effects."}]},"starters":[{"cards":["Angelechy Opening to e4"],"route":{"es":"Yendo segundo, se activa desde la mano en la Standby Phase del primer turno rival y arma todo antes de que el rival juegue su Main Phase. Hasta el final de tu próximo turno no podés invocar del Extra Deck salvo Sincros.","en":"Going second, it activates from hand in the opponent's first Standby Phase and builds the board before they play their Main Phase. Until the end of your next turn you cannot Special Summon from the Extra Deck except Synchros."}},{"cards":["Angelechy Problem"],"route":{"es":"Angelechy Problem es una Mágica de Campo: una vez por turno, descartá una Mágica/Trampa para invocar un Angelechy de nivel 2 del Extra Deck y poner otro Angelechy como Mágica Continua. Es el arranque de cualquier mano con una Mágica/Trampa para descartar.","en":"Angelechy Problem is a Field Spell: once per turn, discard a Spell/Trap to Special Summon a Level 2 Angelechy from the Extra Deck and place another Angelechy as a Continuous Spell. It starts any hand that holds a Spell/Trap to discard."}},{"cards":["Witness of the Ancient","Glitch Clutch Nullgainer"],"route":{"es":"Witness of the Ancient (Tuner de nivel 8) se invoca de la mano si tenés un Sincro en el campo o en el Cementerio y coloca hasta 3 Sincros distintos como Mágicas Continuas; Glitch Clutch Nullgainer, al invocarse por Sincro, suma un monstruo de nivel 8 o más con 0 ATK del Mazo. Sirve cuando no tenés el Opening to e4.","en":"Witness of the Ancient (a Level 8 Tuner) Special Summons from hand if you have a Synchro in the field or GY and places up to 3 different Synchros as Continuous Spells; Glitch Clutch Nullgainer, when Synchro Summoned, adds a Level 8 or higher monster with 0 ATK from the Deck. It works when you lack Opening to e4."}}],"chokepoints":[{"card":"Cosmic Cyclone","step":"main","stepText":{"es":"Contra un Angelechy puesto como Mágica Continua.","en":"Against an Angelechy placed as a Continuous Spell."},"loss":{"es":"Cosmic Cyclone (paga 1000 LP) destierra la carta en vez de destruirla, así que Angelechy Bastion no la protege (Yugipedia). Perdés el floodgate que sostenía ese monstruo; reponelo con Angelechy Problem o con el efecto de Angelechy Verdict desde el Cementerio, que colocan otro Angelechy como Mágica Continua.","en":"Cosmic Cyclone (pays 1000 LP) banishes the card instead of destroying it, so Angelechy Bastion does not protect it (Yugipedia). You lose the floodgate that monster held; replace it with Angelechy Problem or Angelechy Verdict's effect from the GY, which place another Angelechy as a Continuous Spell."}},{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Angelechy Strategy Score o de Destrier.","en":"On the search of Angelechy Strategy Score or Destrier."},"loss":{"es":"Niega la búsqueda de la Mágica/Trampa Angelechy. El mazo juega con pocos monstruos de Main, así que seguí con Problem o con la mano que ya tenías en lugar de repetir la misma carta.","en":"Negates the search of the Angelechy Spell/Trap. The deck plays few Main Deck monsters, so continue with Problem or the hand you already have instead of repeating the same card."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda (Strategy Score, Destrier o Shatranga).","en":"After the first search (Strategy Score, Destrier or Shatranga)."},"loss":{"es":"Corta las siguientes búsquedas del Mazo, incluida la de Disturbance desde el Cementerio. Problem, Brilliant Move, Strategy Score y Verdict desde el Cementerio no suman del Mazo y siguen disponibles.","en":"Cuts the following Deck searches, including Disturbance's from the GY. Problem, Brilliant Move, Strategy Score and Verdict from the GY do not add from the Deck and stay available."}},{"card":"Solemn Warning","step":"activation","stepText":{"es":"Sobre la activación de Angelechy Opening to e4 en la Standby Phase (invoca monstruos).","en":"On the activation of Angelechy Opening to e4 in the Standby Phase (it Summons monsters)."},"loss":{"es":"Paga 2000 LP, niega la activación y la destruye: perdés el arranque del turno. Si el rival va primero con Trampas Seteadas, tené otra salida lista (Problem, Witness).","en":"Pays 2000 LP, negates the activation and destroys it: you lose the turn opening. If the opponent goes first with Set Traps, have another exit ready (Problem, Witness)."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Chaos Hunter","qty":3,"why":{"es":"Se invoca desde la mano descartando una carta cuando el rival invoca por Especial, y mientras esté en el campo el rival no puede desterrar cartas (el Cosmic Cyclone es la respuesta que más le duele al mazo, según Yugipedia).","en":"It Special Summons from hand by discarding a card when the opponent Special Summons, and while it is on the field the opponent cannot banish cards (Cosmic Cyclone is the answer that hurts the deck most, per Yugipedia)."}}],"out":[{"card":"Angelechy Opening to e4","qty":2,"why":{"es":"Yendo primero no se puede activar en la Standby Phase rival y hay que Setearla; Yugipedia señala que el mazo está diseñado para ir segundo.","en":"Going first it cannot be activated in the opponent's Standby Phase and has to be Set; Yugipedia notes the deck is designed to go second."}},{"card":"Mulcharmy Fuwalos","qty":1,"why":{"es":"Se activa solo sin cartas propias.","en":"It only activates with no cards of your own."}}]},"second":{"in":[{"card":"Pot of Sloth","qty":2,"why":{"es":"Robás tantas cartas como cartas controle el rival y devolvés al fondo del Mazo todas menos una; yendo segundo, contra un tablero armado, es donde más rinde.","en":"Draw as many cards as the opponent controls, then put all but one back on the bottom of the Deck; going second, against a built board, it is worth the most."}}],"out":[{"card":"Typhoon","qty":1,"why":{"es":"Con el Opening to e4 ya se arma el tablero, la respuesta a backrow cuesta menos que robar.","en":"With Opening to e4 the board is already built, and the backrow answer matters less than drawing."}},{"card":"Terraforming","qty":1,"why":{"es":"Carta de búsqueda lenta que no empuja el tablero del turno.","en":"A slow search card that does not push the turn's board."}}]}},"updated":"2026-10-27","sources":[{"name":"Angelechy","url":"https://yugipedia.com/wiki/Angelechy","kind":"guide","checked":"2026-10-27"},{"name":"Angelechy Opening to e4","url":"https://yugipedia.com/wiki/Angelechy_Opening_to_e4","kind":"cards","checked":"2026-10-27"},{"name":"Angelechy Verdict","url":"https://yugipedia.com/wiki/Angelechy_Verdict","kind":"cards","checked":"2026-10-27"},{"name":"Pure Angelechy - YGOPRODeck","url":"https://ygoprodeck.com/deck/pure-angelechy-734749","kind":"guide","checked":"2026-10-27"},{"name":"Forbidden & Limited Lists - October 19, 2026 | Official Website","url":"https://www.yugioh-card.com/en/limited/list_2026-10-19/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La única guía de jugada es una lista de un jugador en YGOPRODeck (categoría Theorycrafting), no un análisis de torneo, y no hay resultados enlazados que muestren al mazo ganando.","en":"The only play guide is one player's list on YGOPRODeck (Theorycrafting category), not a tournament analysis, and there are no linked results showing the deck winning."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas lo respalda con estadísticas.","en":"The Side Deck is editorial judgment: none of the linked sources backs it with statistics."}]},"adv/artmage":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Artmage Academic Arcane Arts Acropolis busca cualquier monstruo Artmage descartando una Mágica/Trampa. Finmel, Graflare y Litera se invocan solos de la mano si ya controlás una carta Artmage y dan un robo, una Mágica Artmage y una recuperación (Yugipedia).","en":"Artmage Academic Arcane Arts Acropolis searches any Artmage monster by discarding a Spell/Trap. Finmel, Graflare and Litera Summon themselves from hand if you already control an Artmage card and give a draw, an Artmage Spell and a recovery (Yugipedia)."},{"es":"Medius the Pure suma o invoca un Power Patron; Artmage Power Patron hace una Fusión rápida con Medius, por ejemplo Artmage Diactorus, que niega con 3 o más Tipos de monstruo distintos.","en":"Medius the Pure adds or Summons a Power Patron; Artmage Power Patron makes a Quick Fusion with Medius, for example Artmage Diactorus, which negates with 3 or more different Monster Types."},{"es":"Artmage Non-Finito hace una Fusión extra en el turno rival y, al invocarse por Especial, pone una Mágica/Trampa Artmage del Mazo, por ejemplo Artmage Impasto -Recapture-, que niega la activación de un efecto de monstruo (desterrando una de tus Fusiones hasta la End Phase), destruye ese monstruo y, con 3 Tipos distintos, devuelve las Mágicas/Trampas rivales a la mano.","en":"Artmage Non-Finito makes an extra Fusion Summon on the opponent's turn and, when Special Summoned, Sets an Artmage Spell/Trap from the Deck, for example Artmage Impasto -Recapture-, which negates a monster effect's activation (banishing one of your Fusions until the End Phase), destroys that monster and, with 3 different Types, returns the opposing Spells/Traps to the hand."},{"es":"Nerva the Power Patron of Creation convierte el efecto de un monstruo Artmage en \"destruí todas las cartas rivales\".","en":"Nerva the Power Patron of Creation turns an Artmage monster effect into \"destroy all of the opponent's cards\"."}]},"starters":[{"cards":["Artmage Academic Arcane Arts Acropolis"],"route":{"es":"Se activa de la mano: descartás una Mágica/Trampa y declarás un monstruo Artmage para sumarlo del Mazo, y te deja Normal Invocar a Medius the Pure además de tu Invocación Normal. Medius suma o invoca un Power Patron.","en":"Activate it from hand: discard a Spell/Trap and declare an Artmage monster to add from the Deck, and it lets you Normal Summon Medius the Pure in addition to your Normal Summon. Medius adds or Summons a Power Patron."}},{"cards":["Medius the Pure","Artmage Power Patron"],"route":{"es":"Medius suma o invoca a Artmage Power Patron del Mazo; Power Patron lo fusiona con Medius como efecto rápido (Medius + un Artmage) y deja un Artmage Diactorus.","en":"Medius adds or Summons Artmage Power Patron from the Deck; Power Patron fuses with Medius as a Quick Effect (Medius + an Artmage) leaving Artmage Diactorus."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda del Acropolis o de Medius.","en":"On Acropolis' or Medius' search."},"loss":{"es":"Niega la búsqueda que da el monstruo Artmage. Artmage Power Patron aún suma una Mágica/Trampa Artmage del Mazo cuando se manda al Cementerio desde la mano o el campo, y el Acropolis permite buscar otro nombre en el mismo turno.","en":"Negates the search that gives the Artmage monster. Artmage Power Patron can still add an Artmage Spell/Trap from the Deck when sent to the GY from hand or field, and the Acropolis lets you search another name the same turn."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del Acropolis o de Power Patron.","en":"After the first search by Acropolis or Power Patron."},"loss":{"es":"Corta todas las siguientes y el mazo depende de varias. Armá la jugada con Finmel, Graflare y Litera, que se invocan de la mano, y no con más búsquedas.","en":"Cuts all following ones and the deck relies on several. Build the play with Finmel, Graflare and Litera, which Summon from hand, and not with more searches."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta invocación: Artmage invoca varios monstruos de la mano y Fusiones.","en":"On the fifth Summon: Artmage Summons several monsters from hand and Fusions."},"loss":{"es":"Tributa todo el tablero Artmage y deja una ficha del tamaño de lo tributado. Jugá con el Tipo distinto de cada monstruo y cortá antes de la quinta si ya tenés Diactorus.","en":"Tributes the whole Artmage board and leaves a token the size of what was Tributed. Play each monster's different Type and stop before the fifth if you already have Diactorus."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En respuesta al efecto rápido de Artmage Power Patron o de Non-Finito.","en":"In response to the Quick Effect of Artmage Power Patron or Non-Finito."},"loss":{"es":"Niega el efecto del monstruo antes de la Fusión. Con Theorealize Past Lull, Medius se invoca de nuevo sin que el rival pueda activar nada en respuesta.","en":"Negates the monster's effect before the Fusion. With Theorealize Past Lull, Medius is Summoned again without the opponent being able to activate anything in response."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Ash Blossom & Joyous Spring","qty":3,"why":{"es":"Interrupción de mano para el turno rival cuando vas primero.","en":"Hand interruption for the opponent's turn when you go first."}}],"out":[{"card":"Mulcharmy Purulia","qty":3,"why":{"es":"Se activa solo si no controlás cartas: yendo primero, con tablero, queda muerta en la mano.","en":"It only activates if you control no cards: going first, with a board, it sits dead in hand."}}]},"second":{"in":[{"card":"Forbidden Crown","qty":1,"why":{"es":"Anula los efectos de un monstruo boca arriba y le impide atacar ese turno (también lo vuelve inmune a efectos y no se puede usar como material).","en":"Negates a face-up monster's effects and stops it from attacking that turn (it also becomes unaffected by effects and cannot be used as material)."}},{"card":"Pot of Sloth","qty":1,"why":{"es":"Robás tantas cartas como cartas controle el rival y devolvés al fondo del Mazo todas menos una; sirve cuando vas segundo.","en":"Draw as many cards as the opponent controls, then put all but one back on the bottom of the Deck; it fits when you go second."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Se recorta para meter respuestas al tablero rival.","en":"Trimmed to make room for answers to the opposing board."}}]}},"updated":"2026-10-27","sources":[{"name":"Artmage Academic Arcane Arts Acropolis","url":"https://yugipedia.com/wiki/Artmage_Academic_Arcane_Arts_Acropolis","kind":"cards","checked":"2026-10-27"},{"name":"Artmage Power Patron","url":"https://yugipedia.com/wiki/Artmage_Power_Patron","kind":"cards","checked":"2026-10-27"},{"name":"Artmage Diactorus","url":"https://yugipedia.com/wiki/Artmage_Diactorus","kind":"cards","checked":"2026-10-27"},{"name":"Explore the Divine Synergy of Artmage | Archetype Starter Guide","url":"https://tcg-corner.com/pt/blogs/news/respectygo-explore-the-divine-synergy-of-artmage-archetype-starter-guide","kind":"guide","checked":"2026-10-27"},{"name":"Forbidden & Limited Lists - October 19, 2026 | Official Website","url":"https://www.yugioh-card.com/en/limited/list_2026-10-19/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La lista de referencia que muestra la página es anterior a la banlist del 19 de octubre de 2026: lleva Called by the Grave, Varudras y Charmer Quartet in Bloom (Prohibidas) y Droll & Lock Bird x2 (Limitada a 1). También incluye Artmage Varnish -Alteration-, Vandalism -Assault- y Pact -Awakening-, que no existen en el TCG (solo OCG y Master Duel).","en":"The reference list shown on the page predates the October 19, 2026 list: it has Called by the Grave, Varudras and Charmer Quartet in Bloom (Forbidden) and Droll & Lock Bird x2 (Limited to 1). It also includes Artmage Varnish -Alteration-, Vandalism -Assault- and Pact -Awakening-, which do not exist in the TCG (OCG and Master Duel only)."},{"es":"Yugipedia tiene sobre el arquetipo solo un esbozo sin estrategia, y la guía de iniciación es de un blog de tienda sin fecha clara. No hay resultados de torneo enlazados y el Side Deck es criterio de la redacción.","en":"Yugipedia has only a stub on the archetype with no strategy, and the starter guide is from a shop blog with no clear date. There are no linked tournament results and the Side Deck is editorial judgment."}]},"adv/sky-striker":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Es un mazo de control basado en Mágicas: las Sky Striker Normal y Mecha solo se activan si no controlás monstruos en la Zona de Monstruos Principal y ganan un efecto extra con 3 o más Mágicas en el Cementerio (Yugipedia).","en":"A Spell-based control deck: the Normal and Mecha Sky Striker Spells only activate if you control no monsters in the Main Monster Zone and gain an extra effect with 3 or more Spells in the GY (Yugipedia)."},{"es":"Sky Striker Ace - Raye cambia entre los Link-1 Ace: se tributa como efecto rápido para invocar un Ace del Extra Deck y vuelve del Cementerio si ese Ace se va por batalla o por un efecto rival.","en":"Sky Striker Ace - Raye swaps between the Link-1 Aces: it Tributes as a Quick Effect to Summon an Ace from the Extra Deck and comes back from the GY if that Ace leaves by battle or an opposing effect."},{"es":"El plan del primer turno según la guía de Konami: Ace - Shizuku en el campo con 4 o 5 cartas Seteadas (como Widow Anchor); al turno siguiente, Mobilize - Linkage! cierra la jugada.","en":"The turn 1 plan per Konami's guide: Ace - Shizuku on the field with 4 or 5 Set cards (such as Widow Anchor); next turn, Mobilize - Linkage! finishes the play."},{"es":"Sky Striker Mecha - Widow Anchor niega un efecto de monstruo y, con 3 Mágicas en el Cementerio, te deja robar el control de ese monstruo hasta la End Phase.","en":"Sky Striker Mecha - Widow Anchor negates a monster's effect and, with 3 Spells in the GY, lets you take control of that monster until the End Phase."}]},"starters":[{"cards":["Sky Striker Mobilize - Engage!"],"route":{"es":"Sin monstruos en la Zona Principal, suma una carta Sky Striker del Mazo (que no sea otra Engage!) y, con 3 Mágicas en el Cementerio, también robás una. Es el arranque estándar.","en":"With no monsters in the Main Monster Zone, it adds a Sky Striker card from the Deck (not another Engage!) and, with 3 Spells in the GY, you also draw one. The standard opener."}},{"cards":["Sky Striker Ace - Raye"],"route":{"es":"Raye se tributa como efecto rápido para invocar un Ace al Extra Monster Zone; Kagari recupera una Mágica Sky Striker del Cementerio al invocarse. Si el Ace se va por efecto rival, Raye vuelve.","en":"Raye Tributes as a Quick Effect to Summon an Ace into the Extra Monster Zone; Kagari recovers a Sky Striker Spell from the GY when Summoned. If the Ace leaves by an opposing effect, Raye returns."}},{"cards":["Sky Striker Mobilize - Linkage!","Sky Striker Ace - Roze"],"route":{"es":"Linkage! manda una carta al Cementerio e invoca un Ace; Roze se invoca de la mano cuando entra un Ace, y Raye + Roze permiten el Link Summon de Ace = Zero.","en":"Linkage! sends a card to the GY and Summons an Ace; Roze Summons itself from hand when an Ace comes in, and Raye + Roze allow the Link Summon of Ace = Zero."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre el efecto de Engage! o de Reinforcement of the Army.","en":"On the effect of Engage! or Reinforcement of the Army."},"loss":{"es":"Niega la búsqueda que da la Mágica o el Raye. Con Kagari o Hayate en el Extra Deck (que no dependen de una búsqueda del Mazo), seguís con la mano restante.","en":"Negates the search that gives the Spell or Raye. With Kagari or Hayate in the Extra Deck (which do not rely on a Deck search), you continue with the remaining hand."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Tras resolverse la primera búsqueda del Mazo (Engage!, Reinforcement of the Army o Shizuku en la End Phase).","en":"After the first Deck search resolves (Engage!, Reinforcement of the Army or Shizuku in the End Phase)."},"loss":{"es":"Bloquea las búsquedas siguientes. Yugipedia indica que Kagari y Hayate pueden esquivar efectos anti-búsqueda, así que apuntá a ellos para seguir el turno.","en":"Blocks the following searches. Yugipedia notes Kagari and Hayate can get around anti-search effects, so aim for them to keep the turn going."}},{"card":"Solemn Accusation","step":"activation","stepText":{"es":"Contra la activación de Engage! o Hornet Drones.","en":"Against the activation of Engage! or Hornet Drones."},"loss":{"es":"Yugipedia lo cita entre las trampas más molestas contra esas cartas: niega y destruye la Mágica, y ninguno puede activar otra con el mismo nombre ese turno. Jugá primero la que menos duele.","en":"Yugipedia lists it among the most annoying Traps against those cards: it negates and destroys the Spell, and nobody can activate another with the same name that turn. Play the one that hurts least first."}},{"card":"Harpie's Feather Duster","step":"main","stepText":{"es":"En su Main Phase 1 cuando tenés las Mágicas Seteadas del turno anterior.","en":"In their Main Phase 1 when you have the previous turn's Set Spells."},"loss":{"es":"Destruye todas tus Mágicas/Trampas: perdés Widow Anchor y el resto del setup de primer turno. Yugipedia lo cita entre las Mágicas de destrucción masiva que neutralizan el tablero yendo primero.","en":"Destroys all your Spells/Traps: you lose Widow Anchor and the rest of the turn 1 setup. Yugipedia lists it among the mass Spell/Trap removal that neutralizes the board going first."}},{"card":"Santa Claws","step":"summon","stepText":{"es":"Al invocarse en tu campo tributando un Ace de la Extra Monster Zone.","en":"When Summoned to your field by Tributing an Ace from the Extra Monster Zone."},"loss":{"es":"Queda un monstruo en la Zona Principal y las Mágicas Sky Striker que piden zona libre no se pueden activar. Además, Raye no vuelve porque el Ace no dejó el campo por un efecto rival (Yugipedia).","en":"A monster stays in the Main Monster Zone and the Sky Striker Spells that need a free zone cannot be activated. Also, Raye does not return because the Ace did not leave the field by an opposing effect (Yugipedia)."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Evenly Matched","qty":2,"why":{"es":"Con un tablero chico tuyo, en el fin de la Battle Phase rival podés hacerle desterrar boca abajo hasta igualar tus cartas.","en":"With a small board of yours, at the end of the opponent's Battle Phase you can make them banish face-down until card counts match."}}],"out":[{"card":"Forbidden Crown","qty":2,"why":{"es":"Interacción de monstruo que rinde poco con un tablero mínimo; mejor una respuesta masiva.","en":"Monster interaction that does little with a minimal board; a mass answer is better."}}]},"second":{"in":[{"card":"Mulcharmy Fuwalos","qty":3,"why":{"es":"Yendo segundo no controlás cartas en el primer turno rival, así que se activan; el mazo juega sin monstruos de campo.","en":"Going second you control no cards on the opponent's first turn, so they activate; the deck plays with no monsters on the field."}}],"out":[{"card":"Forbidden Crown","qty":2,"why":{"es":"Se cambia por interacción que se activa desde la mano.","en":"Swapped for interaction that activates from hand."}},{"card":"Ghost Ogre & Snow Rabbit","qty":1,"why":{"es":"Se cede una copia para sumar un Mulcharmy.","en":"One copy is given up to add a Mulcharmy."}}]}},"updated":"2026-10-27","sources":[{"name":"Sky Striker","url":"https://yugipedia.com/wiki/Sky_Striker","kind":"guide","checked":"2026-10-27"},{"name":"Legendary Modern Decks 2026 – Sky Striker","url":"https://yugiohblog.konami.com/2026/news-updates/product-guide/legendary-modern-decks-2026-sky-striker/","kind":"guide","checked":"2026-10-27"},{"name":"Sky Striker Mecha - Widow Anchor","url":"https://yugipedia.com/wiki/Sky_Striker_Mecha_-_Widow_Anchor","kind":"cards","checked":"2026-10-27"},{"name":"Forbidden & Limited Lists - October 19, 2026 | Official Website","url":"https://www.yugioh-card.com/en/limited/list_2026-10-19/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La guía de Konami explica el Structure Deck Legendary Modern Decks 2026, no una lista de torneo: el plan de primer turno es el de esa guía.","en":"Konami's guide covers the Legendary Modern Decks 2026 Structure Deck, not a tournament list: the turn 1 plan is that guide's."},{"es":"La lista de referencia que muestra la página es anterior a la banlist del 19 de octubre de 2026: lleva Albion the Branded Dragon, Triple Tactics Talent y Called by the Grave (Prohibidas) y Droll & Lock Bird x2 (Limitada a 1).","en":"The reference list shown on the page predates the October 19, 2026 list: it has Albion the Branded Dragon, Triple Tactics Talent and Called by the Grave (Forbidden) and Droll & Lock Bird x2 (Limited to 1)."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas lo respalda con estadísticas.","en":"The Side Deck is editorial judgment: none of the linked sources backs it with statistics."}]},"adv/chaos-ritual":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"El objetivo es invocar por Ritual a Black Luster Soldier o a Magician of Dark Chaos - Black Chaos: ignoran los efectos activados rivales salvo los que los apuntan, y el segundo protege además tus Mágicas/Trampas.","en":"The goal is to Ritual Summon Black Luster Soldier or Magician of Dark Chaos - Black Chaos: they ignore the opponent's activated effects unless those target, and the latter also protects your Spells/Traps."},{"es":"Black Chaos se descarta para poner Mind Shuffle sin usar la invocación normal; Mind Shuffle suma un monstruo que mencione a Light and Darkness Ritual y cambia un monstruo de nivel 7+ por un Ritual desde la mano contra un efecto rival.","en":"Black Chaos discards itself to place Mind Shuffle without using your Normal Summon; Mind Shuffle adds a monster that mentions Light and Darkness Ritual and swaps a Level 7+ monster for a Ritual from hand against an opposing effect."},{"es":"Skull Archfiend of Chaos, al ir al Cementerio, manda una Mágica Ritual y suma el Ritual de ella; Light and Darkness Ritual vuelve de nuevo a la mano desde el Cementerio.","en":"Skull Archfiend of Chaos, sent to the GY, sends a Ritual Spell and adds its Ritual Monster; Light and Darkness Ritual returns to the hand from the GY."},{"es":"Black Luster Soldier destierra una carta al invocarse y Black Chaos destierra dos más sin apuntar, antes de atacar.","en":"Black Luster Soldier banishes a card when Special Summoned and Black Chaos banishes two more without targeting, before attacking."}]},"starters":[{"cards":["Black Chaos"],"route":{"es":"Se descarta para poner Mind Shuffle boca arriba desde el Mazo o Cementerio, sin gastar la invocación normal y sin dar una activación que Ash pueda negar.","en":"Discards itself to place Mind Shuffle face-up from the Deck or GY, without using your Normal Summon and without giving an activation Ash can negate."}},{"cards":["Griffoh"],"route":{"es":"Se descarta como efecto rápido para Setear una Rápida o Trampa que mencione a Light and Darkness Ritual (Mind Shuffle) y activarla el mismo turno. También sirve de Tributo único para un Ritual de nivel 8.","en":"Discards as a Quick Effect to Set a Quick-Play or Trap that mentions Light and Darkness Ritual (Mind Shuffle) and activate it the same turn. It can also serve as the whole Tribute for a Level 8 Ritual."}},{"cards":["Ragged Records of Rites"],"route":{"es":"Muestra una Mágica Ritual (Light and Darkness Ritual) y suma un monstruo que la mencione, normalmente Black Chaos; vuelve a la mano desde el Cementerio si un Ritual tuyo deja el campo por efecto y no controlás otros monstruos que no sean Ritual.","en":"Reveals a Ritual Spell (Light and Darkness Ritual) and adds a monster that mentions it, usually Black Chaos; it returns to the hand from the GY if a Ritual Monster of yours leaves the field by effect and you control no non-Ritual monsters."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la primera suma de Mind Shuffle, la carta mandada por Archfiend o Ragged Records.","en":"On Mind Shuffle's first add, the card sent by Archfiend or Ragged Records."},"loss":{"es":"Niega el efecto. Poner Mind Shuffle descartando a Black Chaos no suma, invoca ni manda nada desde el Mazo, así que Ash no tiene qué negar ahí: abrí con esa ruta.","en":"Negates the effect. Placing Mind Shuffle by discarding Black Chaos does not add, Summon or send anything from the Deck, so Ash has nothing to negate there: open with that route."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Tras resolverse la primera suma (Mind Shuffle o Ragged Records).","en":"After the first add resolves (Mind Shuffle or Ragged Records)."},"loss":{"es":"Frena las siguientes sumas del Mazo. Si ya tenés Light and Darkness Ritual en el Cementerio, su efecto trae la Mágica y una carta que la mencione sin pasar por el Mazo.","en":"Stops the following adds from the Deck. If you already have Light and Darkness Ritual in the GY, its effect returns the Spell and a card that mentions it without going through the Deck."}},{"card":"Ghost Ogre & Snow Rabbit","step":"activation","stepText":{"es":"Cuando se activa un efecto de Mind Shuffle (carta ya boca arriba).","en":"When a Mind Shuffle effect (an already face-up card) is activated."},"loss":{"es":"Destruye Mind Shuffle al activarse, salvo que ya tengas a Magician of Dark Chaos - Black Chaos en el campo: sus Mágicas/Trampas no se pueden destruir por efectos rivales. Abrí con Black Chaos y Griffoh antes de comprometer a Mind Shuffle.","en":"Destroys Mind Shuffle as it activates, unless Magician of Dark Chaos - Black Chaos is already on the field: your Spells/Traps cannot be destroyed by opposing effects. Open with Black Chaos and Griffoh before committing Mind Shuffle."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Black Chaos o el Ritual en el campo, antes de que resuelva su efecto de destierro.","en":"On Black Chaos or the Ritual on the field, before its banish effect resolves."},"loss":{"es":"Niega el efecto del monstruo y se pierde el destierro. Black Chaos solo es inmune a efectos activados rivales mientras tengas una Mágica Ritual en el Cementerio: antes de eso, Imperm y Veiler sí lo frenan. Como apuntan, también frenan a los Rituales aunque ignoren los efectos no dirigidos.","en":"Negates the monster's effect and the banish is lost. Black Chaos is only unaffected by opposing activated effects while you have a Ritual Spell in the GY: before that, Imperm and Veiler do stop it. Since they target, they also stop the Ritual Monsters even though those ignore non-targeting effects."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"Con una Mágica Ritual en tu Cementerio, sobre ella.","en":"With a Ritual Spell in your GY, targeting it."},"loss":{"es":"Destierra la Mágica Ritual y Black Chaos pierde su protección frente a efectos rivales, que depende de tener una Mágica Ritual en el Cementerio (texto de la carta).","en":"Banishes the Ritual Spell and Black Chaos loses its protection against opposing effects, which depends on having a Ritual Spell in the GY (card text)."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Solemn Judgment","qty":1,"why":{"es":"Cubre la invocación o la activación del turno rival, donde este mazo tiene menos protección.","en":"Covers the opponent's Summon or activation, where this deck has less protection."}},{"card":"Bystial Magnamhut","qty":1,"why":{"es":"Se invoca desterrando un LIGHT o DARK del Cementerio, incluidos tus Rituales.","en":"Summons itself by banishing a LIGHT or DARK from the GY, your Rituals included."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Se activa solo sin cartas propias: yendo primero tenés tablero.","en":"It only activates with no cards of your own: going first you have a board."}}]},"second":{"in":[{"card":"Harpie's Feather Duster","qty":1,"why":{"es":"Quita todo el fondo de campo rival antes del turno de quiebre.","en":"Removes the whole opposing backrow before the breaking turn."}},{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"Responde a un tablero rival que invocó 5 veces mientras vos no tenés tablero que perder.","en":"Answers an opposing board that Summoned 5 times while you have no board to lose."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":1,"why":{"es":"Se recorta una copia para meter respuestas.","en":"One copy is trimmed to make room for answers."}},{"card":"Mulcharmy Purulia","qty":1,"why":{"es":"Se cede una copia para meter la respuesta.","en":"One copy is given up to add the answer."}}]}},"updated":"2026-10-27","sources":[{"name":"Light and Darkness Ritual (series)","url":"https://yugipedia.com/wiki/ROLAD","kind":"guide","checked":"2026-10-27"},{"name":"Mind Shuffle","url":"https://yugipedia.com/wiki/Mind_Shuffle","kind":"cards","checked":"2026-10-27"},{"name":"Black Chaos","url":"https://yugipedia.com/wiki/Black_Chaos","kind":"cards","checked":"2026-10-27"},{"name":"YCS Montreal - Yu-Gi-Oh! Tournament","url":"https://ygoprodeck.com/tournament/ycs-montreal-4842","kind":"results","checked":"2026-10-27"},{"name":"Forbidden & Limited Lists - October 19, 2026 | Official Website","url":"https://www.yugioh-card.com/en/limited/list_2026-10-19/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La tabla de YCS Montreal agrupa todos los mazos bajo la etiqueta «Light and Darkness Ritual»: no distingue versiones puras de las que llevan otros motores.","en":"The YCS Montreal table groups every deck under the label \"Light and Darkness Ritual\": it does not tell pure versions from ones with other engines."},{"es":"La lista de referencia que muestra la página es anterior a la banlist del 19 de octubre de 2026: lleva Albion the Branded Dragon y Called by the Grave (Prohibidas), Droll & Lock Bird x2, Branded in High Spirits x2 y Griffoh x3 (Limitadas a 1).","en":"The reference list shown on the page predates the October 19, 2026 list: it has Albion the Branded Dragon and Called by the Grave (Forbidden), Droll & Lock Bird x2, Branded in High Spirits x2 and Griffoh x3 (Limited to 1)."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas lo respalda con estadísticas.","en":"The Side Deck is editorial judgment: none of the linked sources backs it with statistics."}]},"dl/wyrms-rush":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Gana por combo de Fusión: Destructor Wyrm Bakhamut y Destructor Soldier Helmet se fusionan en Explosive Destructor Wyrm Dangerous Bakhamut (3000 de ATK), que elige 1 carta tuya boca arriba y 1 o 2 monstruos rivales y los destruye (la tuya también), y quema 500 por cada monstruo destruido.","en":"Wins with a Fusion combo: Destructor Wyrm Bakhamut and Destructor Soldier Helmet fuse into Explosive Destructor Wyrm Dangerous Bakhamut (3000 ATK), which chooses 1 face-up card of yours and 1 or 2 enemy monsters and destroys them (yours too), and burns 500 for each monster destroyed."},{"es":"Todo el Main son Wyrms: eso enciende el Skill (tutor de 2 cartas) y deja que Helmet y Canteen reciclen la Magia de Fusión y los materiales desde el Cementerio, turno tras turno.","en":"The whole Main Deck is Wyrms: that turns on the Skill (2-card tutor) and lets Helmet and Canteen recycle the Fusion spell and the materials from the Graveyard, turn after turn."},{"es":"Autumn Leaves of Blisstopia da 300 de ATK y daño perforante a los Wyrms, y Destructor Claw Shield protege al Wyrm equipado (en Ataque no se destruye en batalla y, con una Magia de Campo, tampoco por efectos): un Wyrm grande remata de un solo golpe.","en":"Autumn Leaves of Blisstopia gives Wyrms 300 ATK and piercing damage, and Destructor Claw Shield protects the equipped Wyrm (in Attack Position it cannot be destroyed by battle and, while a Field Spell is out, neither by card effects): one big Wyrm finishes in a single hit."},{"es":"Wyrm Excavator the Heavy Cavalry Draco (Maximum, 2500 de ATK) no se destruye por Trampas rivales; tributar ese Maximum habilita a Infinite Heavy Cavalry Buildragoon, que roba 1 y fusiona otra vez.","en":"Wyrm Excavator the Heavy Cavalry Draco (Maximum, 2500 ATK) cannot be destroyed by enemy Traps; Tributing that Maximum Monster enables Infinite Heavy Cavalry Buildragoon, which draws 1 and Fusion Summons again."}]},"starters":[{"cards":["Destructor Soldier Helmet","Destructor Wyrm Bakhamut"],"route":{"es":"Helmet (descartás 1 carta y pagás 500 LP) devuelve la Magia de Fusión del Cementerio a la mano; con Bakhamut y Helmet boca arriba en tu campo fusionás Dangerous Bakhamut, que destruye 1 carta tuya boca arriba y hasta 2 monstruos rivales.","en":"Helmet (discard 1 card and pay 500 LP) returns the Fusion spell from the Graveyard to hand; with Bakhamut and Helmet face-up on your field you fuse Dangerous Bakhamut, which destroys 1 face-up card of yours and up to 2 enemy monsters."}},{"cards":["Destructor Soldier Canteen"],"route":{"es":"Canteen manda un Wyrm del Cementerio al Deck, da +100 de ATK y recupera a Helmet (o un Wyrm Normal): repone el material que gastaste en la fusión anterior.","en":"Canteen puts a Wyrm from the Graveyard back in the Deck, gives +100 ATK and retrieves Helmet (or a Wyrm Normal Monster): it refills the material you spent on the last fusion."}},{"cards":["Wyrm Excavator the Heavy Cavalry Draco","Infinite Heavy Cavalry Buildragoon"],"route":{"es":"Invocás el Maximum de Draco y después lo tributás para Buildragoon (pide 10 o más cartas en el Deck y solo Wyrms en el Cementerio): robás 1 y fusionás con Wyrms de la mano o del campo. Es la ruta para el OTK yendo segundo.","en":"Maximum Summon Draco, then Tribute that Maximum Monster for Buildragoon (it needs 10+ cards in the Deck and only Wyrms in the Graveyard): draw 1 and Fusion Summon with Wyrms from hand or field. This is the route for the going-second OTK."}}],"chokepoints":[{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, cuando invocás un Wyrm: da vuelta hasta 2 monstruos con efecto a Defensa boca abajo.","en":"On your turn, when you summon a Wyrm: flips up to 2 Effect Monsters to face-down Defense."},"loss":{"es":"Dangerous Bakhamut queda boca abajo y no ataca; si el monstruo tenía 2600 o más de ATK original, el rival además gana 1500 LP. Hacé primero la invocación que menos importe.","en":"Dangerous Bakhamut ends face-down and cannot attack; if the monster had 2600+ original ATK, the opponent also gains 1500 LP. Make the summon that matters least first."}},{"card":"Forever Freeze","step":"summon","stepText":{"es":"Cuando Invocás de Normal a Buildragoon (2500 de ATK).","en":"When you Normal Summon Buildragoon (2500 ATK)."},"loss":{"es":"Manda al Buildragoon al fondo del Deck y se cae la fusión que venía detrás. El rival paga mandando un monstruo suyo al Cementerio. El Maximum de Draco no es una Invocación Normal, así que esta carta no lo toca.","en":"Sends Buildragoon to the bottom of the Deck and the fusion that followed falls apart. The opponent pays by sending a monster of theirs to the Graveyard. Draco's Maximum Summon is not a Normal Summon, so this card does not touch it."}},{"card":"Widespread Ruin","step":"attack","stepText":{"es":"En tu declaración de ataque.","en":"On your attack declaration."},"loss":{"es":"Al declarar el ataque destruye a tu monstruo en Ataque con más ATK. Con Trampas boca abajo, abrí con Primal Howling (una Magia que manda una Magia/Trampa rival al fondo del Deck, con un Wyrm boca arriba) o con Draco, que resiste Trampas.","en":"On your attack declaration it destroys your Attack Position monster with the highest ATK. Into face-down Traps, open with Primal Howling (a Spell that puts an enemy Spell/Trap on the bottom of the Deck, with a face-up Wyrm) or with Draco, which resists Traps."}},{"card":"Ace Sword Slash","step":"main","stepText":{"es":"En su Main Phase.","en":"On their Main Phase."},"loss":{"es":"Destruye 1 carta tuya y puede revivir un Máquina LIGHT de 2500/1600 (Ace Breaker). Es una Magia: Draco solo resiste Trampas, así que cae igual. Guardá un Wyrm de reserva en la mano para rearmar.","en":"Destroys 1 card of yours and can revive a LIGHT Machine with 2500/1600 (Ace Breaker). It is a Spell: Draco only resists Traps, so it still falls. Keep a spare Wyrm in hand to rebuild."}}],"skills":[{"name":"Activated Wyrm of Black Metal","why":{"es":"Desde el turno 2, si todo tu Deck son Wyrms, mostrás Bakhamut o Helmet y agregás hasta 2 cartas del Deck o Cementerio (monstruos de nivel 8, de 400 de DEF, la Magia de Fusión, Magias de Campo o de Equipo); después descartás 1. Es el motor del mazo.","en":"From turn 2, if your whole Deck is Wyrms, you reveal Bakhamut or Helmet and add up to 2 cards from Deck or Graveyard (Level 8 monsters, 400 DEF monsters, the Fusion spell, Field or Equip Spells); then discard 1. It is the deck engine."}}],"side":{"first":{"in":[{"card":"Destructor Art - Total Destruction","qty":1,"why":{"es":"Yendo primero no atacás el primer turno y el rival sí puede atacar el suyo: esta Trampa responde a su ataque, recicla Wyrms al Deck y, si suman nivel 16 o más, destruye sus monstruos en Ataque.","en":"Going first you do not attack on turn 1 and the opponent can attack on theirs: this Trap answers their attack, recycles Wyrms into the Deck and, with 16+ total Levels, destroys their Attack Position monsters."}}],"out":[{"card":"Destructor Soldier Haken","qty":1,"why":{"es":"Haken pide que el rival tenga 1 carta o menos en la mano: casi nunca pasa en tu primer turno.","en":"Haken needs the opponent to have 1 card or fewer in hand: that almost never happens on your first turn."}}]},"second":{"in":[{"card":"Destructor Integration Scrap Gate","qty":1,"why":{"es":"Yendo segundo la Magia de Campo habilita a Bakhamut y deja fusionar devolviendo solo Wyrms del Cementerio. Un jugador de KOG la cuenta como un buen habilitador.","en":"Going second this Field Spell enables Bakhamut and lets you fuse by returning only Wyrms from the Graveyard. A KOG player calls it a strong enabler."}}],"out":[{"card":"Destructor Soldier Haken","qty":1,"why":{"es":"Haken te obliga a atacar con un solo monstruo y depende de la mano rival; la ranura rinde más como Magia de Campo para Bakhamut.","en":"Haken limits you to one attacker and depends on the opponent's hand; the slot is worth more as a Field Spell for Bakhamut."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Explosive Destructor Wyrm Dangerous Bakhamut","url":"https://yugipedia.com/wiki/Explosive_Destructor_Wyrm_Dangerous_Bakhamut","kind":"cards","checked":"2026-10-27"},{"name":"Wyrm Excavator the Heavy Cavalry Draco","url":"https://yugipedia.com/wiki/Wyrm_Excavator_the_Heavy_Cavalry_Draco","kind":"cards","checked":"2026-10-27"},{"name":"Wyrms : Rush! Deck from Collin.C 1120 | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/october-2026/wyrms-rush!/collin.c-1120/2GYw8/","kind":"guide","checked":"2026-10-27"},{"name":"October 2026 Skill Rebalancing","url":"https://yugipedia.com/wiki/October_2026_Skill_Rebalancing","kind":"cards","checked":"2026-10-27"},{"name":"Duel Links Meta Snapshot: October 2026 - Week #1","url":"https://www.duellinksmeta.com/articles/competitive/tournament-analysis/2026/october/1","kind":"results","checked":"2026-10-27"},{"name":"Wyrms : Rush! Deck from 闇Mic | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/october-2026/wyrms-rush!/%E9%97%87mic/ajYdM/","kind":"guide","checked":"2026-10-27"}],"limits":[{"es":"Hay una sola lista con notas posterior al 8 de octubre, cuando se debilitó el Skill Activated Wyrm of Black Metal, y su autor dice que el mazo hay que reajustarlo: tomá la ficha como punto de partida, no como lista cerrada.","en":"There is only one annotated list from after October 8, when the Activated Wyrm of Black Metal Skill was weakened, and its author says the deck needs retuning: treat the sheet as a starting point, not a final list."},{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the by-turn adjustments are editorial judgment."}]},"dl/ether-dragon":{"win":{"plan":"otk","pace":"fast","bullets":[{"es":"Gana con Eternity Ether Dragon (nivel 9, 2500 de ATK): al invocarlo pagás 500 LP y destruís 1 carta rival. Se invoca por Tributo, y el Skill hace que cada monstruo cuente como 2 Tributos.","en":"Wins with Eternity Ether Dragon (Level 9, 2500 ATK): when summoned you pay 500 LP and destroy 1 enemy card. It is Tribute Summoned, and the Skill makes each monster count as 2 Tributes."},{"es":"Los monstruos baratos arman la mano: Evil Dragon of Darkness recupera al Ether Dragon desde el Cementerio, Balloon Butier invoca de Especial un monstruo de nivel 6 o menos de los que caen del Deck y Amazing Dealer manda 3 cartas al Cementerio y roba 3.","en":"Cheap monsters build the hand: Evil Dragon of Darkness retrieves Ether Dragon from the Graveyard, Balloon Butier Special Summons a Level 6 or lower monster among the cards milled and Amazing Dealer sends 3 cards to the Graveyard and draws 3."},{"es":"Otra línea es la de Ultimate Flag: agrega a la mano desde el Cementerio un Máquina LIGHT de 2500/1600 (por ejemplo Ace Breaker) y a Ace Sword Slash, y después podés invocar a Ace Breaker de Especial. Ace Breaker destruye un monstruo rival (mandando 2 monstruos de la mano al Cementerio) y Ace Sword Slash una carta, sin costo el primer turno de quien va segundo.","en":"Another line is Ultimate Flag: it adds from the Graveyard a LIGHT Machine with 2500/1600 (for example Ace Breaker) and Ace Sword Slash to hand, and then you can Special Summon Ace Breaker. Ace Breaker destroys an enemy monster (sending 2 monsters from hand to the Graveyard) and Ace Sword Slash a card, at no cost on the first turn of the player going second."}]},"starters":[{"cards":["Evil Dragon of Darkness","Eternity Ether Dragon"],"route":{"es":"Evil Dragon manda 2 cartas al Cementerio y agrega a Eternity Ether Dragon (o un Dragón de nivel 9 con 2500 de ATK) a la mano; con el Skill lo invocás tributando un solo monstruo.","en":"Evil Dragon sends 2 cards to the Graveyard and adds Eternity Ether Dragon (or a Level 9, 2500 ATK Dragon) to hand; with the Skill you summon it by Tributing a single monster."}},{"cards":["The Ultimate Flag","Ace Sword Slash"],"route":{"es":"The Ultimate Flag se manda sola al Cementerio y agrega a la mano desde el Cementerio un Máquina LIGHT de 2500/1600 y a Ace Sword Slash; después invocás Ace Breaker de Especial desde la mano y ya tenés dos destrucciones preparadas.","en":"The Ultimate Flag sends itself to the Graveyard and adds to hand from the Graveyard a LIGHT Machine with 2500/1600 and Ace Sword Slash; then you Special Summon Ace Breaker from hand and already have two removals lined up."}},{"cards":["Amazing Dealer","Innocent Fadrawl"],"route":{"es":"Fadrawl hace robar a ambos jugadores; Amazing Dealer manda 3 cartas al Cementerio y roba 3 (cuesta 300 LP si tenés 3 monstruos o menos en el Cementerio). Lo que cae al Cementerio alimenta a Evil Dragon y a Ace Sword Slash.","en":"Fadrawl makes both players draw; Amazing Dealer sends 3 cards to the Graveyard and draws 3 (it costs 300 LP if you have 3 or fewer monsters in the Graveyard). What lands in the Graveyard feeds Evil Dragon and Ace Sword Slash."}}],"chokepoints":[{"card":"Forever Freeze","step":"summon","stepText":{"es":"Cuando Invocás de Normal a Eternity Ether Dragon (2500 de ATK).","en":"When you Normal Summon Eternity Ether Dragon (2500 ATK)."},"loss":{"es":"Manda al Ether Dragon al fondo del Deck antes de que uses su efecto; el rival paga mandando un monstruo suyo al Cementerio. Jugá primero el Ace Breaker o un Butier y dejá el Ether para después de ver si activan.","en":"Sends Ether Dragon to the bottom of the Deck before you can use its effect; the opponent pays by sending a monster of theirs to the Graveyard. Play Ace Breaker or a Butier first and keep Ether until you see whether they activate."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar un monstruo.","en":"On your turn, when you summon a monster."},"loss":{"es":"Da vuelta hasta 2 monstruos con efecto a Defensa boca abajo: Ether Dragon no ataca. Con 2500 de ATK original no le da los 1500 LP al rival (eso pasa desde 2600). El rival paga descartando 1 carta. Hacé primero la invocación menos importante.","en":"Flips up to 2 Effect Monsters to face-down Defense: Ether Dragon cannot attack. With 2500 original ATK it does not give the opponent the 1500 LP (that needs 2600+). The opponent pays by discarding 1 card. Make the least important summon first."}},{"card":"Star Protector's Protection","step":"summon","stepText":{"es":"Cuando Invocás de Normal o de Especial, o cuando robás en tu turno.","en":"When you Normal or Special Summon, or draw on your turn."},"loss":{"es":"Ese turno solo podés declarar un ataque, así que el golpe final tiene que salir de un solo monstruo. El costo (mandar un monstruo suyo al Cementerio) lo paga el rival, no vos.","en":"That turn you can only declare one attack, so the finishing blow has to come from a single monster. The cost (sending a monster of theirs to the Graveyard) is paid by the opponent, not you."}},{"card":"Widespread Ruin","step":"attack","stepText":{"es":"En tu declaración de ataque.","en":"On your attack declaration."},"loss":{"es":"Al declarar el ataque destruye al monstruo en Ataque con más ATK, normalmente el Ether Dragon. Si hay Trampas boca abajo, limpiá antes con Ace Sword Slash (destruye 1 carta).","en":"On your attack declaration it destroys your Attack Position monster with the highest ATK, usually Ether Dragon. If Traps are face-down, clear them first with Ace Sword Slash (destroys 1 card)."}}],"skills":[{"name":"Destiny Draw: Divine Dragons","why":{"es":"Desde el turno 2, antes de tu robo normal, pone a Eternity Ether Dragon del Deck arriba, te hace robar hasta 6 en lugar de 5 y cada monstruo tuyo cuenta como 2 Tributos para invocarlo. Se usa 2 veces yendo primero y 3 yendo segundo.","en":"From turn 2, before your normal draw, it puts Eternity Ether Dragon from the Deck on top, makes you draw up to 6 instead of 5 and each of your monsters counts as 2 Tributes to summon it. 2 uses going first, 3 going second."}}],"side":{"first":{"in":[{"card":"Ultimate Flag Beast Boltricorn","qty":1,"why":{"es":"Yendo primero conviene que el Ether Dragon entre sin Trampa de por medio: Boltricorn impide que una Magia/Trampa boca abajo se active hasta el final del próximo turno rival.","en":"Going first you want Ether Dragon to land without a Trap in the way: Boltricorn stops a face-down Spell/Trap from activating until the end of the opponent's next turn."}}],"out":[{"card":"Curse of the Rising Light","qty":1,"why":{"es":"Exige que el rival tenga 1 carta o menos en la mano, y robar 2 solo pasa si activó una Trampa o es el primer turno de quien va segundo: yendo primero rinde menos.","en":"It needs the opponent to have 1 card or fewer in hand, and its draw-2 only happens if they activated a Trap or it is the first turn of the player going second: weaker going first."}}]},"second":{"in":[{"card":"Ultimate Flag Beast Boltricorn","qty":1,"why":{"es":"Yendo segundo enfrentás un tablero con Trampas armadas: Boltricorn apaga una boca abajo para que Ace Sword Slash y Ether Dragon pasen.","en":"Going second you face a board with set Traps: Boltricorn shuts off a face-down card so Ace Sword Slash and Ether Dragon get through."}}],"out":[{"card":"Great Maju Garzett","qty":1,"why":{"es":"Maju (nivel 6, 0 de ATK) vale el doble del ATK original del monstruo tributado: es de las cartas más situacionales de la lista, así que es la primera que sale.","en":"Maju (Level 6, 0 ATK) is worth twice the original ATK of the Tributed monster: it is one of the most situational cards in the list, so it is the first to come out."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Eternity Ether Dragon","url":"https://yugipedia.com/wiki/Eternity_Ether_Dragon","kind":"cards","checked":"2026-10-27"},{"name":"The Ultimate Flag","url":"https://yugipedia.com/wiki/The_Ultimate_Flag","kind":"cards","checked":"2026-10-27"},{"name":"Ether Dragon Deck from neo_noah | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/october-2026/ether-dragon/neo_noah/q5Hig/","kind":"results","checked":"2026-10-27"},{"name":"Destiny Draw: Divine Dragons | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Destiny%20Draw%3A%20Divine%20Dragons","kind":"cards","checked":"2026-10-27"},{"name":"Duel Links Meta Snapshot: October 2026 - Week #1","url":"https://www.duellinksmeta.com/articles/competitive/tournament-analysis/2026/october/1","kind":"results","checked":"2026-10-27"},{"name":"Tier List | Best Ladder & Tournament Decktypes | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the by-turn adjustments are editorial judgment."}]},"dl/dark-magician-rush":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"El mazo gira en torno a Dark Magician (nivel 7, 2500 de ATK, Normal): revivirlo desde el Cementerio con Wizened Dark Magician, Secret Order o Stone of the Dark Magicians evita el Tributo.","en":"The deck revolves around Dark Magician (Level 7, 2500 ATK, Normal Monster): reviving it from the Graveyard with Wizened Dark Magician, Secret Order or Stone of the Dark Magicians skips the Tribute."},{"es":"Con Dark Magician en el campo se habilitan Thousand Knives (destruye un monstruo) y Dark Magic Attack (destruye todas las Magias y Trampas rivales): abrís camino sin gastar monstruos.","en":"With Dark Magician on the field, Thousand Knives (destroys a monster) and Dark Magic Attack (destroys all enemy Spells and Traps) come online: you clear a path without spending monsters."},{"es":"Dark Resonance Burst suma +1000 de ATK, o +2000 si hay Dark Magician o Dark Magician Girl: cierra el duelo rápido. Dark Magician Girl crece 300 por cada Dark Magician en el Cementerio.","en":"Dark Resonance Burst adds +1000 ATK, or +2000 if Dark Magician or Dark Magician Girl is out: it closes the duel fast. Dark Magician Girl grows 300 per Dark Magician in the Graveyard."}]},"starters":[{"cards":["Wizened Dark Magician","Dark Magician"],"route":{"es":"Wizened manda de la mano un Lanzador de Conjuros OSCURO (por ejemplo el propio Dark Magician), roba 1 e invoca de Especial a Dark Magician desde el Cementerio.","en":"Wizened sends a DARK Spellcaster from hand (for example Dark Magician itself), draws 1 and Special Summons Dark Magician from the Graveyard."}},{"cards":["Stone of the Dark Magicians","Dark Eradicator Sorcerer"],"route":{"es":"Stone invoca de Especial un OSCURO de 2500 de ATK y/o uno de 2000 (Sorcerer y Dark Magician Girl) desde la mano o el Cementerio, sin Tributo: dos cuerpos en un turno.","en":"Stone Special Summons a DARK Spellcaster with 2500 ATK and/or one with 2000 ATK (Sorcerer and Dark Magician Girl) from hand or Graveyard, with no Tribute: two bodies in one turn."}},{"cards":["Secret Order","Dark Magician"],"route":{"es":"Secret Order invoca de Especial un Normal de nivel 7 (Dark Magician) desde la mano o el Cementerio con +700 de ATK (3200) y sin poder ser destruido por efectos de Trampa rival: la jugada más segura contra una Trampa que destruye.","en":"Secret Order Special Summons a Level 7 Normal Monster (Dark Magician) from hand or Graveyard with +700 ATK (3200) and unable to be destroyed by enemy Trap effects: the safest play into a Trap that destroys."}}],"chokepoints":[{"card":"Rice Terrace Crisis","step":"summon","stepText":{"es":"Cuando invocás de Especial desde la mano o el Cementerio (Wizened, Secret Order, Stone).","en":"When you Special Summon from hand or Graveyard (Wizened, Secret Order, Stone)."},"loss":{"es":"Da vuelta hasta 2 monstruos tuyos boca arriba (niveles totales de 12 o menos) a Defensa boca abajo. Dark Magician pasa a Defensa boca abajo y no ataca ese turno; guardá Thousand Knives para el turno siguiente.","en":"Flips up to 2 of your face-up monsters (total Levels 12 or less) to face-down Defense. Dark Magician goes to face-down Defense and cannot attack that turn; save Thousand Knives for the next turn."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar tu monstruo.","en":"On your turn, when you summon your monster."},"loss":{"es":"Solo da vuelta monstruos con efecto: Dark Magician (Normal) no se ve afectado, pero Dark Magician Girl, Dark Eradicator Sorcerer y Wizened sí. Invocá primero un Normal si podés.","en":"It only flips Effect Monsters: Dark Magician (a Normal Monster) is unaffected, but Dark Magician Girl, Dark Eradicator Sorcerer and Wizened are. Summon the Normal first if you can."}},{"card":"Widespread Ruin","step":"attack","stepText":{"es":"En tu declaración de ataque.","en":"On your attack declaration."},"loss":{"es":"Al declarar el ataque se lleva a tu Dark Magician reforzado. Usá Dark Magic Attack antes (una Magia que destruye las Magias y Trampas rivales) y atacá después.","en":"On your attack declaration it takes your boosted Dark Magician. Use Dark Magic Attack first (a Spell that destroys all enemy Spells and Traps) and attack afterward."}},{"card":"Buffered Slime","step":"attack","stepText":{"es":"Cuando tu monstruo de nivel 8 o menos declara un ataque.","en":"When your Level 8 or lower monster declares an attack."},"loss":{"es":"Ese turno el rival no recibe daño de batalla (con 3000 o más de LP se hace 2000 de daño a sí mismo) y el OTK se corta. Dark Magic Attack antes del ataque borra la Trampa.","en":"The opponent takes no battle damage that turn (with 3000+ LP it deals 2000 damage to itself) and the OTK is cut. Dark Magic Attack before the attack removes the Trap."}}],"skills":[{"name":"Illusion of Execution","why":{"es":"Desde el turno 2, si todos los monstruos son Lanzadores de Conjuros y los de nivel 5+ son solo Dark Magician, Dark Magician Girl o Dark Eradicator Sorcerer, mostrás uno y excavás 3 cartas: agregás 1 Magia, mandás el resto al Cementerio y después podés mandar a Dark Magician del Deck. Una vez por Duelo.","en":"From turn 2, if all monsters are Spellcasters and Level 5+ ones are only Dark Magician, Dark Magician Girl or Dark Eradicator Sorcerer, you reveal one and excavate 3 cards: add 1 Spell, send the rest to the Graveyard and then you may send Dark Magician from the Deck. Once per Duel."}}],"side":{"first":{"in":[{"card":"Widespread Ruin","qty":1,"why":{"es":"Yendo primero no atacás el primer turno, así que una Trampa defensiva rinde más. Aparece en una lista de KOG del mazo.","en":"Going first you do not attack on turn 1, so a defensive Trap is worth more. It shows up in a KOG list of the deck."}}],"out":[{"card":"Pierce!","qty":1,"why":{"es":"Pierce! solo sirve al atacar a un monstruo en Defensa, algo que no vas a poder hacer el primer turno.","en":"Pierce! only helps when attacking a Defense Position monster, which you cannot do on the first turn."}}]},"second":{"in":[{"card":"Monster Calling","qty":1,"why":{"es":"Yendo segundo robás 1 y revivís un monstruo no-Efecto de 2000 de ATK o 2100 de DEF: Dark Magician (2500/2100) califica y vuelve sin Tributo. Aparece en una lista de KOG del mazo.","en":"Going second you draw 1 and revive a non-Effect monster with 2000 ATK or 2100 DEF: Dark Magician (2500/2100) qualifies and returns with no Tribute. It shows up in a KOG list of the deck."}}],"out":[{"card":"Stealthagic","qty":1,"why":{"es":"El robo extra de Stealthagic exige mandar una Magia y tener 1000 LP o menos; Monster Calling encaja mejor con tu plan de revivir.","en":"Stealthagic's extra draw needs you to send a Spell and have 1000 LP or less; Monster Calling fits your revive plan better."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Secret Order","url":"https://yugipedia.com/wiki/Secret_Order","kind":"cards","checked":"2026-10-27"},{"name":"Dark Magician: Rush! Deck from Kyru | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/october-2026/dark-magician-rush!/kyru/6vGk8/","kind":"results","checked":"2026-10-27"},{"name":"Dark Magician: Rush! Deck from JuanSnowPro | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/october-2026/dark-magician-rush!/juansnowpro/wvtC6/","kind":"results","checked":"2026-10-27"},{"name":"Illusion of Execution | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Illusion%20of%20Execution","kind":"cards","checked":"2026-10-27"},{"name":"Dark Magician: Rush! Deck from Paulo Carvalho | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/october-2026/dark-magician-rush!/paulo-carvalho/9hwhb/","kind":"results","checked":"2026-10-27"},{"name":"October 2026 Lists (Duel Links Rush Duel)","url":"https://yugipedia.com/wiki/October_2026_Lists_(Duel_Links_Rush_Duel)","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the by-turn adjustments are editorial judgment."},{"es":"Las listas de KOG enlazadas casi no traen notas de estrategia: el plan sale sobre todo del texto de las cartas. Thousand Knives está en Limited 2 en la lista del 8 de octubre, y el tope de Limited 2 es de 2 cartas por Deck.","en":"The linked KOG lists carry almost no strategy notes: the plan comes mostly from card text. Thousand Knives is Limited 2 on the October 8 list, and the Limited 2 cap is 2 cards per Deck."}]},"dl/elemental-hero-rush":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Combo de Fusión con Guerreros: Rising HERO Argent excava el Deck en busca de los materiales (Avian, Burstinatrix, Sparkman), Elemental Circulation roba 3 y los fusionás en Wingmen de nivel 5 a 8.","en":"Warrior Fusion combo: Rising HERO Argent excavates the Deck for the materials (Avian, Burstinatrix, Sparkman), Elemental Circulation draws 3 and you fuse them into Level 5 to 8 Wingmen."},{"es":"Los Normales son el material: Hero Descent y Star Restart los reviven desde el Cementerio, y Star Restart además devuelve la Magia de Fusión a la mano. Nyta jugaría 2 Hero Descent si las tuviera (la receta de esta página ya lleva 2), porque se enfrentó sobre todo a Wyrms y al espejo.","en":"The Normal Monsters are the material: Hero Descent and Star Restart revive them from the Graveyard, and Star Restart also returns the Fusion spell to hand. Nyta would play 2 Hero Descent if they had them (the decklist on this page already runs 2), having faced mostly Wyrms and the mirror."},{"es":"Elemental HERO Heliosphere (nivel 7, 2800) roba 1 y, si sale monstruo, destruye 1 carta rival; Shining Flare Wingman gana 300 por cada monstruo Guerrero del Cementerio y quema por el ATK del monstruo que destruye.","en":"Elemental HERO Heliosphere (Level 7, 2800) draws 1 and, if it is a monster, destroys 1 enemy card; Shining Flare Wingman gains 300 per Warrior monster in the Graveyard and burns for the ATK of the monster it destroys."}]},"starters":[{"cards":["Rising HERO Argent","Elemental HERO Burst Wingman"],"route":{"es":"Argent muestra un Fusión Guerrero de nivel 6 o 7 (Burst Wingman), excava 4 y agrega hasta 2 Normales que sean sus materiales (Avian y Burstinatrix): fusión lista en el mismo turno.","en":"Argent reveals a Level 6 or 7 Warrior Fusion (Burst Wingman), excavates 4 and adds up to 2 Normal Monsters that are its materials (Avian and Burstinatrix): a fusion ready the same turn."}},{"cards":["Elemental Circulation","Star Restart"],"route":{"es":"Circulation (mostrás un Fusión Guerrero de nivel 6 o 7 y mandás un material de la mano al Cementerio) roba 3 y descarta 1; Star Restart revive un Normal de nivel 5 o menos y recupera la Magia de Fusión del Cementerio.","en":"Circulation (reveal a Level 6 or 7 Warrior Fusion and send a material from hand to the Graveyard) draws 3 and discards 1; Star Restart revives a Level 5 or lower Normal Monster and returns the Fusion spell from the Graveyard."}},{"cards":["Elemental HERO Voltic Wingman","Elemental HERO Sparkman"],"route":{"es":"Voltic Wingman (Sparkman + Avian) fusiona de nuevo a un Guerrero de nivel 6 a 8 barajando monstruos del Cementerio como material: encadena una segunda fusión.","en":"Voltic Wingman (Sparkman + Avian) Fusion Summons a Level 6 to 8 Warrior by shuffling Graveyard monsters as material: it chains into a second fusion."}}],"chokepoints":[{"card":"Rice Terrace Crisis","step":"summon","stepText":{"es":"Cuando invocás de Especial desde la mano o el Cementerio (Hero Descent, Star Restart).","en":"When you Special Summon from hand or Graveyard (Hero Descent, Star Restart)."},"loss":{"es":"Da vuelta hasta 2 monstruos tuyos boca arriba (niveles totales de 12 o menos) a Defensa boca abajo, y la Fusión pide monstruos boca arriba. Si podés, fusioná antes de revivir con Hero Descent o Star Restart.","en":"Flips up to 2 of your face-up monsters (total Levels 12 or less) to face-down Defense, and the Fusion needs face-up monsters. If you can, fuse before reviving with Hero Descent or Star Restart."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar tu Wingman.","en":"On your turn, when you summon your Wingman."},"loss":{"es":"Da vuelta hasta 2 monstruos con efecto a Defensa boca abajo: los Wingmen tienen efecto y quedan sin atacar. Los Normales (Avian, Burstinatrix, Sparkman) no se ven afectados.","en":"Flips up to 2 Effect Monsters to face-down Defense: Wingmen have effects and cannot attack. Normals (Avian, Burstinatrix, Sparkman) are unaffected."}},{"card":"Widespread Ruin","step":"attack","stepText":{"es":"En tu declaración de ataque.","en":"On your attack declaration."},"loss":{"es":"Al declarar el ataque destruye al monstruo en Ataque con más ATK (el Heliosphere o el Wingman principal). Limpiá las Trampas con Burst Wingman o Avian Spell Tactics (destruyen una Magia/Trampa) antes de pegar.","en":"On your attack declaration it destroys your Attack Position monster with the highest ATK (Heliosphere or the main Wingman). Clear Traps with Burst Wingman or Avian Spell Tactics (each destroys a Spell/Trap) before attacking."}}],"skills":[{"name":"Hero Rush Rising","why":{"es":"Mandando 1 carta de tu campo al Cementerio (con los monstruos de 1600+ de ATK todos LIGHT Guerreros y el Extra solo Guerreros), un monstruo cualquiera pierde 600 de ATK/DEF y agregás la Magia de Fusión del Deck o el Cementerio. Te asegura el arranque.","en":"By sending 1 card from your field to the Graveyard (with all 1600+ ATK monsters being LIGHT Warriors and the Extra Deck only Warriors), a monster loses 600 ATK/DEF and you add the Fusion spell from Deck or Graveyard. It secures your start."}}],"side":{"first":{"in":[{"card":"Widespread Ruin","qty":1,"why":{"es":"Yendo primero no atacás el primer turno: sumá una copia de esta Trampa para cubrir el ataque rival de su primer turno. Aparece en la lista de Mizar y en la de Nyta.","en":"Going first you do not attack on turn 1: add a copy of this Trap to cover the opponent's attack on their first turn. It appears in Mizar's list and in Nyta's."}}],"out":[{"card":"Avian Spell Tactics","qty":1,"why":{"es":"Necesita 2 Guerreros o Bestias Aladas boca arriba y destruye una Magia/Trampa rival: el primer turno no hay nada que destruir.","en":"It needs 2 face-up Warriors or Winged Beasts and destroys an enemy Spell/Trap: on the first turn there is nothing to destroy."}}]},"second":{"in":[{"card":"Hero Descent","qty":1,"why":{"es":"Una copia más de Hero Descent (la receta parte de 2): revive hasta 2 Normales de nivel total 7 o menos en Defensa, y ese turno solo atacan Guerreros.","en":"One more copy of Hero Descent (the decklist starts at 2): it revives up to 2 Normal Monsters of total Level 7 or lower in Defense, and only Warriors can attack that turn."}}],"out":[{"card":"Shiny Shady","qty":1,"why":{"es":"Solo reacciona a invocaciones rivales y da vuelta únicamente monstruos con efecto: yendo segundo preferís una fuente más de material para fusionar.","en":"It only reacts to enemy summons and flips only Effect Monsters: going second you prefer one more source of fusion material."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Rising HERO Argent","url":"https://yugipedia.com/wiki/Rising_HERO_Argent","kind":"cards","checked":"2026-10-27"},{"name":"Elemental HERO Heliosphere","url":"https://yugipedia.com/wiki/Elemental_HERO_Heliosphere","kind":"cards","checked":"2026-10-27"},{"name":"Hero Rush Rising | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Hero%20Rush%20Rising","kind":"cards","checked":"2026-10-27"},{"name":"Elemental HERO: Rush! Deck from Nyta | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/september-2026/elemental-hero-rush!/nyta/TUb_p/","kind":"guide","checked":"2026-10-27"},{"name":"Elemental HERO: Rush! Deck from Mizar | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/october-2026/elemental-hero-rush!/mizar/SuZfA/","kind":"results","checked":"2026-10-27"},{"name":"Tier List | Best Ladder & Tournament Decktypes | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the by-turn adjustments are editorial judgment."},{"es":"El mazo no figura en el ranking de poder de Rush de Duel Links Meta (solo aparecen Ether Dragon, Wyrms, Gradius, Dark Magician y Music Princess): la ficha no tiene un tier de poder propio.","en":"The deck is not in the Duel Links Meta Rush power ranking (only Ether Dragon, Wyrms, Gradius, Dark Magician and Music Princess appear): the sheet has no power tier of its own."},{"es":"Las listas de octubre de este mazo casi no traen notas de autor: la única nota con contenido es una frase de Nyta (22 de septiembre) sobre Hero Descent.","en":"The October lists of this deck carry almost no author notes: the only note with content is one sentence from Nyta (September 22) about Hero Descent."}]},"dl/voidvelg":{"win":{"plan":"otk","pace":"fast","bullets":[{"es":"Plan de OTK con Voidvelg Requiem (nivel 8, 2500): gana 300 de ATK por cada monstruo OSCURO que controlás y 600 más si el rival tiene uno LIGHT. Con el Skill, un monstruo cuenta como 2 Tributos.","en":"OTK plan with Voidvelg Requiem (Level 8, 2500): gains 300 ATK per DARK monster you control and 600 more if the opponent has a LIGHT one. With the Skill, one monster counts as 2 Tributes."},{"es":"Dark Matter Requiem (Requiem + Contact Darkmatter Explorer, por Fusión por Contacto) llega a 3000 y gana 1300 de ATK con daño perforante, además de dar vuelta un monstruo rival.","en":"Dark Matter Requiem (Requiem + Contact Darkmatter Explorer, by Contact Fusion) reaches 3000 and gains 1300 ATK with piercing damage, while flipping an enemy monster face-down."},{"es":"Dark Hole Device destruye todos los monstruos (cuesta 3 OSCUROS Galaxy de la mano o un Fusión OSCURO Galaxy en el campo) y recupera un Galaxy del Cementerio. Un jugador de KOG armó la lista sin Trampas para ganar consistencia.","en":"Dark Hole Device destroys all monsters (costs 3 DARK Galaxy from hand or a DARK Galaxy Fusion on your field) and retrieves a Galaxy from the Graveyard. A KOG player built the list with no Traps for consistency."}]},"starters":[{"cards":["Voidvelg Whiterider","Voidvelg Requiem"],"route":{"es":"Whiterider se vuelve Palerider, excava 3 cartas y agrega a Voidvelg Requiem o un Galaxy OSCURO Normal: busca el cuerpo principal.","en":"Whiterider becomes Palerider, excavates 3 cards and adds Voidvelg Requiem or a DARK Galaxy Normal Monster: it finds the main body."}},{"cards":["Voidvelg Stork","Voidvelg Requiem"],"route":{"es":"Stork (descartando una carta de la mano) se vuelve Requiem, o mandando 2 cartas del Deck se vuelve Contact Darkmatter Explorer para la Fusión por Contacto con Requiem.","en":"Stork (discarding a card from hand) becomes Requiem, or by milling 2 cards becomes Contact Darkmatter Explorer for the Contact Fusion with Requiem."}},{"cards":["Chaos Coolstars","Voidvelg Requiem"],"route":{"es":"Coolstars descarta un Galaxy LIGHT/DARK para robar 1 y cuenta como 2 Tributos para Invocar de Tributo a Requiem en Ataque: el Tributo sale barato.","en":"Coolstars discards a LIGHT/DARK Galaxy to draw 1 and counts as 2 Tributes to Tribute Summon Requiem in Attack Position: the Tribute comes cheap."}}],"chokepoints":[{"card":"Forever Freeze","step":"summon","stepText":{"es":"Cuando Invocás de Normal a Requiem (2500 de ATK).","en":"When you Normal Summon Requiem (2500 ATK)."},"loss":{"es":"Manda a Requiem al fondo del Deck y se corta el OTK de ese turno; el rival paga mandando un monstruo suyo al Cementerio. Abrí con un Galaxy de menos de 2500 de ATK o con una Fusión por Contacto, que no son una Invocación Normal de 2500 o más.","en":"Sends Requiem to the bottom of the Deck and the OTK is cut that turn; the opponent pays by sending a monster of theirs to the Graveyard. Open with a Galaxy under 2500 ATK or with a Contact Fusion, which are not a 2500+ ATK Normal Summon."}},{"card":"Trap Hole","step":"summon","stepText":{"es":"Cuando Invocás de Normal un monstruo de 1000 o más de ATK.","en":"When you Normal Summon a monster with 1000 or more ATK."},"loss":{"es":"Destruye al monstruo recién invocado, sea Requiem o Whiterider. Mostrá antes un cuerpo barato (por ejemplo Stork, de 1100 de ATK) si querés forzar la Trampa.","en":"Destroys the freshly summoned monster, Requiem or Whiterider. Show a cheap body first (for example Stork, 1100 ATK) if you want to bait the Trap."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar tu monstruo.","en":"On your turn, when you summon your monster."},"loss":{"es":"Da vuelta hasta 2 monstruos con efecto a Defensa boca abajo. Whiterider y Stork siguen siendo de Efecto aunque cambien de nombre; solo un Voidvelg Palerider real (Normal) no se ve afectado.","en":"Flips up to 2 Effect Monsters to face-down Defense. Whiterider and Stork remain Effect Monsters even when they change names; only a real Voidvelg Palerider (a Normal Monster) is unaffected."}},{"card":"Buffered Slime","step":"attack","stepText":{"es":"Cuando tu monstruo de nivel 8 o menos declara un ataque.","en":"When your Level 8 or lower monster declares an attack."},"loss":{"es":"Ese turno el rival no recibe daño de batalla (con 3000 o más de LP se hace 2000 de daño a sí mismo) y el OTK pierde el último golpe. Universal Storm antes del ataque limpia la Trampa.","en":"The opponent takes no battle damage that turn (with 3000+ LP it deals 2000 damage to itself) and the OTK loses its last hit. Universal Storm before the attack clears the Trap."}}],"skills":[{"name":"Requiem Contact","why":{"es":"Desde el turno 2, con todos los monstruos del Deck OSCUROS Galaxy, pone a Voidvelg Requiem o a un Normal del Deck o Cementerio arriba de tu Deck, hace que cada monstruo cuente como 2 Tributos para invocar a Requiem en Ataque y podés robar 1. Una vez por Duelo.","en":"From turn 2, with all Deck monsters being DARK Galaxy, it puts Voidvelg Requiem or a Normal Monster from Deck or Graveyard on top of your Deck, makes each monster count as 2 Tributes to summon Requiem in Attack Position and lets you draw 1. Once per Duel."}}],"side":{"first":{"in":[{"card":"Universal Storm","qty":1,"why":{"es":"Yendo primero no atacás el primer turno: Universal Storm destruye una Magia/Trampa rival con un Galaxy en el campo y prepara el OTK siguiente. Aparece en una lista de KOG del mazo.","en":"Going first you do not attack on turn 1: Universal Storm destroys an enemy Spell/Trap with a Galaxy on the field and prepares the next-turn OTK. It shows up in a KOG list of the deck."}}],"out":[{"card":"Pot of Avarice","qty":1,"why":{"es":"Necesita 5 monstruos en el Cementerio, algo raro de tener en el primer turno.","en":"It needs 5 monsters in the Graveyard, which is rare on the first turn."}}]},"second":{"in":[{"card":"Talismanic Seal Array","qty":1,"why":{"es":"Un autor de KOG duda de Dark Hole Device y la cambiaría por esta: baja el ATK de un monstruo rival 200 por nivel sin borrar tus cuerpos, a cambio de barajar 4 monstruos del Cementerio.","en":"A KOG author doubts Dark Hole Device and would swap it for this: it lowers an enemy monster's ATK by 200 per Level without clearing your bodies, at the cost of shuffling 4 monsters from the Graveyard."}}],"out":[{"card":"Dark Hole Device","qty":1,"why":{"es":"Destruye también tus propios monstruos, y yendo segundo muchas veces ya tenés el campo armado.","en":"It destroys your own monsters too, and going second you often already have the board set up."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Voidvelg Requiem","url":"https://yugipedia.com/wiki/Voidvelg_Requiem","kind":"cards","checked":"2026-10-27"},{"name":"Voidvelg Deck from Kaiser | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/september-2026/voidvelg/kaiser/QfwAe/","kind":"guide","checked":"2026-10-27"},{"name":"Voidvelg Deck from Alex | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/august-2026/voidvelg/ptrnrushteam/XTV7u/","kind":"results","checked":"2026-10-27"},{"name":"Requiem Contact | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Requiem%20Contact","kind":"cards","checked":"2026-10-27"},{"name":"October 2026 Lists (Duel Links Rush Duel)","url":"https://yugipedia.com/wiki/October_2026_Lists_(Duel_Links_Rush_Duel)","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Las dos listas con notas son de agosto y septiembre, anteriores a la lista del 8 de octubre: Voidvelg Whiterider figura en Limited 3, Dark Hole Device en Limited 2 y Voidvelg Beyond Probe y Voidvelg Chrysaor en Limited 1. Revisá que tu lista las cumpla.","en":"The two annotated lists are from August and September, before the October 8 list: Voidvelg Whiterider is Limited 3, Dark Hole Device is Limited 2, and Voidvelg Beyond Probe and Voidvelg Chrysaor are Limited 1. Check that your list complies."},{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the by-turn adjustments are editorial judgment."}]},"dl/royal-rebel-s":{"win":{"plan":"otk","pace":"fast","bullets":[{"es":"Plan de OTK con Fiends de nivel 8 que se Invocan de Normal tributando uno o dos Fiends de nivel alto: Royal Rebel's Doom Metal (2 Tributos) destruye todos los monstruos rivales y quema según el nivel.","en":"OTK plan with Level 8 Fiends Normal Summoned by Tributing one or two high-Level Fiends: Royal Rebel's Doom Metal (2 Tributes) destroys all enemy monsters and burns by Level."},{"es":"Royal Rebel's Progrock (1 Tributo de nivel 5+) destruye una Magia/Trampa y una carta boca abajo y abre el camino. Hard Rock (2 Tributos) hace daño por la diferencia de ATK.","en":"Royal Rebel's Progrock (1 Tribute of Level 5+) destroys a Spell/Trap and a face-down card and opens the path. Hard Rock (2 Tributes) deals damage by ATK difference."},{"es":"El Skill pone 2 monstruos de nivel 7 u 8 en Defensa y ese turno los monstruos de nivel original 7+ pueden atacar directo una vez: es el empujón final.","en":"The Skill places 2 Level 7 or 8 monsters in Defense and that turn monsters with original Level 7+ can attack directly once: that is the final push."}]},"starters":[{"cards":["Faceless Culdesac","Royal Rebel's Progrock"],"route":{"es":"Culdesac (nivel 6) se invoca de Especial desde la mano mostrando otro Fiend y da +300 de ATK a los Fiends: la Invocación Normal queda libre para Progrock, con Culdesac de Tributo de nivel 5+.","en":"Culdesac (Level 6) Special Summons from hand by revealing another Fiend and gives Fiends +300 ATK: your Normal Summon stays free for Progrock, with Culdesac as the Level 5+ Tribute."}},{"cards":["Trade-In","Royal Rebel's Doom Metal"],"route":{"es":"Trade-In descarta un nivel 8 y roba 2: el nivel 8 en el Cementerio queda para revivirlo, y con la mano nueva juntás los 2 Tributos que pide Doom Metal.","en":"Trade-In discards a Level 8 and draws 2: the Level 8 in the Graveyard is left for revival, and the new hand gathers the 2 Tributes Doom Metal asks for."}},{"cards":["Royal Rebel's Doom Metal","Perion the Star Knight"],"route":{"es":"El Skill deja 2 monstruos de nivel 7/8 (por ejemplo Perion) en Defensa y los tributás para Doom Metal: ese turno destruís todos los monstruos rivales y atacás directo.","en":"The Skill places 2 Level 7/8 monsters (for example Perion) in Defense and you Tribute them for Doom Metal: that turn you destroy all enemy monsters and attack directly."}}],"chokepoints":[{"card":"Forever Freeze","step":"summon","stepText":{"es":"Cuando Invocás de Normal un jefe (todos tienen 2500 de ATK).","en":"When you Normal Summon a boss (all have 2500 ATK)."},"loss":{"es":"El jefe vuelve al fondo del Deck y perdés los Tributos; el rival paga mandando un monstruo suyo al Cementerio. Jugá primero un Culdesac para ver si hay Trampa.","en":"The boss goes to the bottom of the Deck and you lose the Tributes; the opponent pays by sending a monster of theirs to the Graveyard. Play Culdesac first to see whether there is a Trap."}},{"card":"Trap Hole","step":"summon","stepText":{"es":"Cuando Invocás de Normal un monstruo de 1000 o más de ATK.","en":"When you Normal Summon a monster with 1000 or more ATK."},"loss":{"es":"Destruye al jefe recién invocado antes de que uses su efecto. Por eso conviene Heavenly Selection o Genie's Fire Breath para sacar la Trampa antes.","en":"Destroys the freshly summoned boss before you use its effect. That is why Heavenly Selection or Genie's Fire Breath is worth running to remove the Trap first."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar tu monstruo.","en":"On your turn, when you summon your monster."},"loss":{"es":"Da vuelta hasta 2 de tus monstruos con efecto a Defensa boca abajo (todos los jefes lo son) y no atacan. Se evita invocando recién después de limpiar las Trampas.","en":"Flips up to 2 of your Effect Monsters to face-down Defense (all bosses are) and they cannot attack. You avoid it by summoning only after clearing Traps."}},{"card":"Buffered Slime","step":"attack","stepText":{"es":"Cuando tu monstruo de nivel 8 o menos declara un ataque.","en":"When your Level 8 or lower monster declares an attack."},"loss":{"es":"Ese turno el rival no recibe daño de batalla (con 3000 o más de LP se hace 2000 de daño a sí mismo) y el ataque directo no le saca vida. Progrock o Heavenly Selection antes de atacar lo evitan.","en":"The opponent takes no battle damage that turn (with 3000+ LP it deals 2000 damage to itself) and the direct attack takes no life. Progrock or Heavenly Selection before attacking avoids it."}}],"skills":[{"name":"Hard Rock Overture","why":{"es":"Mandando de la mano un monstruo de nivel 7 u 8 (con todo el Deck Fiend LIGHT) ponés hasta 2 monstruos de nivel 7/8 de la mano o el Cementerio en Defensa; desde el turno 2 sumás uno del Cementerio a la mano, y ese turno los de nivel original 7+ atacan directo una vez.","en":"By sending a Level 7 or 8 monster from hand (with a full LIGHT Fiend deck) you place up to 2 Level 7/8 monsters from hand or Graveyard in Defense; from turn 2 you also add one from the Graveyard to hand, and that turn monsters with original Level 7+ attack directly once."}}],"side":{"first":{"in":[{"card":"Widespread Ruin","qty":1,"why":{"es":"Yendo primero no atacás el primer turno: esta Trampa cubre el ataque rival de su primer turno mientras armás el tablero.","en":"Going first you do not attack on turn 1: this Trap covers the opponent's attack on their first turn while you build the board."}}],"out":[{"card":"Heavenly Selection","qty":1,"why":{"es":"Necesita 10 niveles en tu campo y una Magia/Trampa rival: en el primer turno no tenés ni lo uno ni lo otro.","en":"It needs 10 Levels on your field and an enemy Spell/Trap: on the first turn you have neither."}}]},"second":{"in":[{"card":"Genie's Fire Breath","qty":1,"why":{"es":"Con un Fiend en el campo devuelve una Magia/Trampa rival a la mano: despeja las Trampas que ya tiene armadas yendo segundo. Aparece en una lista de KOG del mazo.","en":"With a Fiend on the field it returns an enemy Spell/Trap to hand: it clears Traps they already have set when you go second. It shows up in a KOG list of the deck."}}],"out":[{"card":"Kheiron the Star Knight","qty":1,"why":{"es":"Su daño perforante solo sirve contra un monstruo en Defensa; yendo segundo preferís la remoción de Trampas.","en":"Its piercing damage only works against a Defense Position monster; going second you prefer Trap removal."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Royal Rebel's Doom Metal","url":"https://yugipedia.com/wiki/Royal_Rebel%27s_Doom_Metal","kind":"cards","checked":"2026-10-27"},{"name":"Hard Rock Overture | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Hard%20Rock%20Overture","kind":"cards","checked":"2026-10-27"},{"name":"Royal Rebel's Deck from Nova | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/september-2026/royal-rebel's/nova/Q3DJ7/","kind":"results","checked":"2026-10-27"},{"name":"Royal Rebel's Deck from nakami2 | Duel Links Meta","url":"https://www.duellinksmeta.com/top-decks/king-of-games/september-2026/royal-rebel's/nakami2/bfcZa/","kind":"results","checked":"2026-10-27"},{"name":"Duel Links Meta Snapshot: October 2026 - Week #1","url":"https://www.duellinksmeta.com/articles/competitive/tournament-analysis/2026/october/1","kind":"results","checked":"2026-10-27"},{"name":"Tier List | Best Ladder & Tournament Decktypes | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Las listas de KOG enlazadas son de septiembre y casi no traen notas; el único resultado reciente es un 2.º puesto en Rush Duel Dynasty #49, y el mazo no figura en el ranking de poder de Rush.","en":"The linked KOG lists are from September and carry almost no notes; the only recent result is 2nd place at Rush Duel Dynasty #49, and the deck is not in the Rush power ranking."},{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the by-turn adjustments are editorial judgment."}]},"dl/branded":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Gana por combo de Fusión: Fallen of Albaz, Blazing Cartesia y Branded Fusion sacan Albion, Mirrorjade, Granguignol o Lubellion en el mismo turno y dejan un campo con negaciones y destierro.","en":"Wins with a Fusion combo: Fallen of Albaz, Blazing Cartesia and Branded Fusion bring out Albion, Mirrorjade, Granguignol or Lubellion in one turn and leave a board of negates and banish effects."},{"es":"Los Bystial (Druiswurm, Magnamhut, Saronir) se Invocan solos desde la mano desterrando un monstruo LIGHT o DARK de algún Cementerio, y como Efecto Rápido si el rival controla un monstruo: así arman el turno del rival.","en":"The Bystials (Druiswurm, Magnamhut, Saronir) Special Summon themselves from hand by banishing a LIGHT or DARK monster from a GY, as a Quick Effect if the opponent controls a monster: that is how the deck plays on the opponent's turn."},{"es":"Magnamhut busca un Dragon en la End Phase (por ejemplo otro Fallen of Albaz), así que el combo sigue en el turno siguiente aunque te rompan el campo.","en":"Magnamhut adds a Dragon in the End Phase (for example another Fallen of Albaz), so the combo continues next turn even if your board gets broken."},{"es":"Skill Beasts from the Abyss: solo permite sacar del Extra Deck monstruos LIGHT o DARK de Nivel 8 o más; su segundo efecto (una vez por Duelo) manda un Fallen de tu Deck al Cementerio y te da un Bystial más un monstruo que lo mencione.","en":"Beasts from the Abyss Skill: only LIGHT or DARK Level 8 or higher monsters may come from the Extra Deck; its second effect (once per Duel) sends a Fallen from your Deck to the GY and gives you a Bystial plus a monster that mentions it."}]},"starters":[{"cards":["Fallen of Albaz","Branded Fusion"],"route":{"es":"Branded Fusion con Fallen of Albaz y un Bystial del Deck como material (Bystial es Dragon, DARK, 2500 de ATK): sale Lubellion, Titaniklad o Alba-Lenatus sin gastar la Invocación Normal.","en":"Branded Fusion with Fallen of Albaz and a Bystial from the Deck as material (Bystial is a DARK Dragon with 2500 ATK): Lubellion, Titaniklad or Alba-Lenatus comes out without using the Normal Summon."}},{"cards":["Blazing Cartesia, the Virtuous","Fallen of Albaz"],"route":{"es":"Con Fallen en el Cementerio (el Skill lo manda desde el Deck), Cartesia se Invoca de la mano y en la Main Phase hace una Fusión de Nivel 8 o más con monstruos de la mano o el campo, como Efecto Rápido.","en":"With Fallen in the GY (the Skill sends it from the Deck), Cartesia Special Summons from hand and, in the Main Phase, Fusion Summons a Level 8 or higher monster from hand or field as a Quick Effect."}},{"cards":["Bystial Magnamhut","Bystial Druiswurm"],"route":{"es":"Si el rival tiene un monstruo y hay un LIGHT o DARK en un Cementerio, el Bystial entra como Efecto Rápido en su turno; Magnamhut busca un Dragon al final y Druiswurm, al irse del campo al Cementerio, manda al Cementerio un monstruo Invocado Especial del rival.","en":"If the opponent has a monster and a LIGHT or DARK is in a GY, the Bystial comes in as a Quick Effect on their turn; Magnamhut adds a Dragon at the end and Druiswurm, when sent from the field to the GY, sends an opposing Special Summoned monster to the GY."}}],"chokepoints":[{"card":"Artifact Lancea","step":"activation","stepText":{"es":"En respuesta a la activación de un Bystial.","en":"In response to a Bystial's activation."},"loss":{"es":"Con Lancea resuelta ninguno puede desterrar, y el Bystial necesita desterrar para Invocarse. Jugá primero la Fusión que no depende del destierro y guardá los Bystial para después de ver si la tienen.","en":"Once Lancea resolves neither player can banish, and the Bystial needs to banish to Summon itself. Play the Fusion that does not rely on banish first and keep the Bystials until you see if they have it."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse un Bystial o Springans Kitt.","en":"When a Bystial or Springans Kitt activates."},"loss":{"es":"Niega cualquier efecto que destierre del Cementerio o agregue desde el Cementerio, y casi todo el deck lo hace. Si ves que el rival juega Ghost Belle, aguantá y jugá la parte del combo que no toca el Cementerio.","en":"It negates any effect that banishes from the GY or adds from the GY, and most of the deck does one of the two. If the opponent plays Ghost Belle, wait it out and play the part of the combo that does not touch the GY."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Branded Lost, Springans Kitt, Tri-Brigade Mercourier).","en":"Right after the first search resolves (Branded Lost, Springans Kitt, Tri-Brigade Mercourier)."},"loss":{"es":"Después de esa búsqueda no podés agregar nada más del Deck en el turno. Ordená el combo para que la búsqueda que más necesitás sea la primera y el resto salga de Branded Fusion, que usa el Deck como material y no lo agrega a la mano.","en":"After that search nothing else can be added from the Deck this turn. Sequence the combo so the search you need most comes first and the rest comes from Branded Fusion, which uses the Deck as material instead of adding."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta Invocación del turno (Fallen, Cartesia y dos o tres Fusiones llegan rápido).","en":"On the fifth Summon of the turn (Fallen, Cartesia and two or three Fusions get there fast)."},"loss":{"es":"Tributa todo tu campo y te deja un Token enorme. Contá las Invocaciones: si ya vas por cuatro, cerrá con una Fusión menos y dejá el Bystial para el turno del rival.","en":"It Tributes your whole board and leaves you a huge Token. Count Summons: if you are at four, stop one Fusion early and keep the Bystial for the opponent's turn."}},{"card":"Mulcharmy Fuwalos","step":"summon","stepText":{"es":"Cada Invocación Especial desde el Extra Deck le da una carta al rival (se activa si no controla cartas).","en":"Each Special Summon from the Extra Deck gives the opponent a card (it activates if they control no cards)."},"loss":{"es":"Branded hace varias Fusiones por turno y cada una le regala una carta al rival. Usá menos Fusiones intermedias si la ves venir.","en":"Branded makes several Fusions per turn and each one gifts the opponent a card. Use fewer intermediate Fusions if you see it coming."}}],"skills":[{"name":"Beasts from the Abyss","why":{"es":"Es el Skill del mazo (100% de las listas). Su segundo efecto asegura la apertura: revelás un Bystial o Cartesia, mandás un Fallen del Deck al Cementerio y agregás un Bystial y un monstruo que mencione a Fallen. El tercero, con solo el rival con monstruo, manda a The Bystial Alba Los desde fuera del Deck al Cementerio para buscar otro Bystial.","en":"The deck's Skill (100% of lists). Its second effect secures the opening: reveal a Bystial or Cartesia, send a Fallen from the Deck to the GY and add a Bystial plus a monster that mentions Fallen. The third, with only the opponent controlling a monster, sends The Bystial Alba Los from outside the Deck to the GY to add another Bystial."}}],"side":{"first":{"in":[{"card":"Ghost Belle & Haunted Mansion","qty":1,"why":{"es":"Yendo primero el rival juega su turno con el Cementerio lleno de efectos (Memento, Horus): Belle frena revivir y desterrar.","en":"Going first the opponent plays a GY-heavy turn (Memento, Horus): Belle stops revival and banish effects."}}],"out":[{"card":"Screams of the Branded","qty":1,"why":{"es":"Yendo primero ese Trap es de las cartas más lentas: no hay turno para recuperar una Fusión del Cementerio.","en":"Going first that Trap is among the slowest cards: there is no turn to bring a Fusion back from the GY."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":1,"why":{"es":"Yendo segundo rompés el campo del rival con una sola carta y negás sus efectos de monstruo antes de tu combo.","en":"Going second you break the opponent's board with a single card and negate their monster effects before your combo."}},{"card":"Lava Golem","qty":1,"why":{"es":"Yendo segundo el rival ya tiene monstruos: Lava Golem tributa dos de ellos y es una salida que no pide Extra Deck.","en":"Going second the opponent already has monsters: Lava Golem Tributes two of them and is an out that does not need the Extra Deck."}}],"out":[{"card":"Screams of the Branded","qty":1,"why":{"es":"Se recorta la recuperación lenta para hacer lugar a cartas que rompen el campo.","en":"The slow recovery card is cut to make room for board breakers."}},{"card":"Branded Sword","qty":1,"why":{"es":"Las fichas de Branded Sword llegan tarde cuando necesitás romper primero el campo del rival.","en":"Branded Sword tokens arrive late when you first need to break the opponent's board."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Branded Deck Breakdown | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list/deck-types/Branded","kind":"results","checked":"2026-10-27"},{"name":"Beasts from the Abyss | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Beasts%20from%20the%20Abyss","kind":"cards","checked":"2026-10-27"},{"name":"Fallen of Albaz | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Fallen%20of%20Albaz","kind":"cards","checked":"2026-10-27"},{"name":"Blazing Cartesia, the Virtuous | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Blazing%20Cartesia%2C%20the%20Virtuous","kind":"cards","checked":"2026-10-27"},{"name":"Bystial Druiswurm | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Bystial%20Druiswurm","kind":"cards","checked":"2026-10-27"},{"name":"Tier List Update | Duel Links Meta","url":"https://www.duellinksmeta.com/articles/tier-list/updates/2026/october-26","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the per-turn adjustments are the editors' judgment."}]},"dl/horus":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Arma un muro de monstruos Horus de Nivel 8 protegidos: King's Sarcophagus (o Walls of the Imperial Tomb, que toma ese nombre en la Zona de Campo) los hace inmunes a destrucción por efectos que no los apunten.","en":"Builds a wall of protected Level 8 Horus monsters: King's Sarcophagus (or Walls of the Imperial Tomb, which takes that name in the Field Zone) makes them immune to destruction by effects that do not target them."},{"es":"King's Sarcophagus manda cartas de tu mano al Cementerio para mandar Horus del Deck (hasta cuatro veces por turno), y Hapi, Imsety, Qebehsenuef y Duamutef vuelven solos del Cementerio mientras la controlás.","en":"King's Sarcophagus sends cards from your hand to the GY to send Horus monsters from the Deck (up to four times a turn), and Hapi, Imsety, Qebehsenuef and Duamutef come back on their own from the GY while you control it."},{"es":"Canopic Protector responde a cualquier activación del rival e Invoca un Horus de la mano o el Cementerio; Horus the Black Flame Deity entra si uno de los tuyos sale por un efecto del rival y puede mandar todo el resto al Cementerio.","en":"Canopic Protector answers any opposing activation and Special Summons a Horus from hand or GY; Horus the Black Flame Deity comes in if one of yours leaves the field to an opposing effect and can send all other monsters to the GY."},{"es":"Lleva muchos handtraps (Droll, Nibiru, Veiler, Ghost Belle, D.D. Crow) y Lava Golem: yendo primero, Droll más Nibiru suelen ser la mano ganadora.","en":"Plays many hand traps (Droll, Nibiru, Veiler, Ghost Belle, D.D. Crow) and Lava Golem: going first, Droll plus Nibiru is often the winning hand."}]},"starters":[{"cards":["Walls of the Imperial Tomb"],"route":{"es":"Activada como carta de campo es King's Sarcophagus y busca un monstruo Horus (normalmente Imsety) a la mano, dejando una carta de la mano abajo del Deck.","en":"Activated as a Field Spell it is King's Sarcophagus and adds a Horus monster (usually Imsety) to hand, putting a card from hand on the bottom of the Deck."}},{"cards":["Imsety, Glory of Horus"],"route":{"es":"Mandando dos cartas de la mano (incluida ella) al Cementerio agregás King's Sarcophagus del Deck y robás 1: una sola carta abre el turno.","en":"Sending two cards from hand (itself included) to the GY adds King's Sarcophagus from the Deck and draws 1: a single card opens the turn."}},{"cards":["King's Sarcophagus","Canopic Protector"],"route":{"es":"Sarcophagus vuelca Horus al Cementerio y Canopic Protector (seteada) los trae al campo en la respuesta a cualquier carta del rival: muro de cuerpos en su turno.","en":"Sarcophagus dumps Horus monsters into the GY and a Set Canopic Protector brings them to the field in response to any opposing card: a wall of bodies on their turn."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda o robo extra (Walls, Imsety).","en":"Right after the first search or extra draw resolves (Walls, Imsety)."},"loss":{"es":"Corta el resto de las búsquedas del turno. Buscá lo más importante primero (normalmente King's Sarcophagus) y recordá que Sarcophagus manda al Cementerio, no agrega a la mano.","en":"It stops the rest of the turn's searches. Search the most important card first (usually King's Sarcophagus) and remember Sarcophagus sends to the GY instead of adding to hand."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Cuando activás Canopic Protector, Hapi, Imsety o Qebehsenuef para Invocar desde el Cementerio.","en":"When you activate Canopic Protector, Hapi, Imsety or Qebehsenuef to Special Summon from the GY."},"loss":{"es":"Niega esa activación. Activá primero con la pieza que menos importa para gastar a Belle, y guardá a Horus the Black Flame Deity, que entra desde la mano y no desde el Cementerio.","en":"It negates that activation. Activate with the piece that matters least to bait Belle, and hold Horus the Black Flame Deity, which comes in from the hand rather than the GY."}},{"card":"Number 68: Sanaphond the Sky Prison","step":"main","stepText":{"es":"En la Main Phase del rival, desasocia un material: hasta el final de tu próximo turno nadie Invoca del Cementerio.","en":"In the opponent's Main Phase, detaching a material: until the end of your next turn neither player Special Summons from the GY."},"loss":{"es":"Apaga las revividas del Cementerio (Hapi, Imsety, Qebehsenuef, Duamutef, Canopic desde el Cementerio). Armá el turno con lo que ya tenés en mano y campo.","en":"It shuts off GY revival (Hapi, Imsety, Qebehsenuef, Duamutef, Canopic from the GY). Build the turn with what you already have in hand and on the field."}},{"card":"Necrovalley","step":"main","stepText":{"es":"En la Main Phase del rival, reemplazando a Walls of the Imperial Tomb en la Zona de Campo.","en":"In the opponent's Main Phase, replacing Walls of the Imperial Tomb in the Field Zone."},"loss":{"es":"Niega los efectos que mueven cartas del Cementerio a otro lugar, o sea toda la revivida de Horus, y saca a Walls de la Zona de Campo. Si tenés otro Walls en la mano, podés reemplazar a Necrovalley con él; si no, jugá con lo que hay en el campo.","en":"It negates effects that move cards from the GY to another place, which is all of Horus's revival, and it removes Walls from the Field Zone. If you have another Walls in hand you can replace Necrovalley with it; if not, play with what is on the field."}}],"skills":[{"name":"Precious Cards of the Dark","why":{"es":"El más usado (57%). Una vez por turno y hasta dos por Duelo (si el Deck tiene 6 o más monstruos DARK): mandás una carta al fondo del Deck o al Cementerio y robás 2, más 1 extra si vas segundo en tu primer turno. Sirve para llegar a Sarcophagus o a un handtrap.","en":"The most used (57%). Once per turn and up to twice per Duel (if the Deck has 6 or more DARK monsters): place a card on the bottom or send it to the GY and draw 2, plus 1 extra if you are going second on your first turn. It finds Sarcophagus or a hand trap."}},{"name":"Precious Cards of the Light","why":{"es":"La misma versión del Skill con otro requisito: 6 o más monstruos LIGHT en el Deck. Duel Links Meta la registra en 16 de las 63 listas de Horus.","en":"The same Skill with a different requirement: 6 or more LIGHT monsters in the Deck. Duel Links Meta records it in 16 of the 63 Horus lists."}},{"name":"Precious Cards of the Wind","why":{"es":"Otra variante del mismo robo: pide 6 o más monstruos WIND (Hapi, Mulcharmy Fuwalos y similares). Se elige según los atributos que lleve tu lista.","en":"Another variant of the same draw: it needs 6 or more WIND monsters (Hapi, Mulcharmy Fuwalos and similar). Pick by the attributes your list runs."}}],"side":{"first":{"in":[{"card":"Ghost Ogre & Snow Rabbit","qty":1,"why":{"es":"Yendo primero armás el muro y Ogre destruye un monstruo o una Continua que active su efecto: Canopic Protector del espejo, por ejemplo.","en":"Going first you build the wall and Ogre destroys a monster or Continuous card that activates its effect: the mirror's Canopic Protector, for example."}},{"card":"Ghost Mourner & Moonlit Chill","qty":1,"why":{"es":"Frena una Invocación Especial del rival en su turno y le cuesta daño si ese monstruo deja el campo.","en":"It stops an opposing Special Summon on their turn and costs them damage if that monster leaves the field."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Fuwalos solo se activa si no controlás cartas, y yendo primero ya tenés Walls o Canopic en la mesa en el turno del rival.","en":"Fuwalos only activates if you control no cards, and going first you already have Walls or Canopic on the table on the opponent's turn."}}]},"second":{"in":[{"card":"Lava Golem","qty":1,"why":{"es":"Yendo segundo el rival ya armó cuerpos: Lava Golem tributa dos de ellos y es la única \"invocación normal\" que usa el mazo.","en":"Going second the opponent already built bodies: Lava Golem Tributes two of them and is the only \"normal summon\" the deck uses."}}],"out":[{"card":"Soul Servant","qty":1,"why":{"es":"Es la carta de ranura libre de la lista (un +1 de Dark Magician of Destruction); un Lava Golem más rinde más cuando vas segundo.","en":"It is the list's flex slot (a +1 for Dark Magician of Destruction); one more Lava Golem does more when you go second."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Horus Deck Breakdown | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list/deck-types/Horus","kind":"results","checked":"2026-10-27"},{"name":"Precious Cards of the Dark | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Precious%20Cards%20of%20the%20Dark","kind":"cards","checked":"2026-10-27"},{"name":"King's Sarcophagus | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/King%27s%20Sarcophagus","kind":"cards","checked":"2026-10-27"},{"name":"Canopic Protector | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Canopic%20Protector","kind":"cards","checked":"2026-10-27"},{"name":"Imsety, Glory of Horus | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Imsety%2C%20Glory%20of%20Horus","kind":"cards","checked":"2026-10-27"},{"name":"Tier List Update | Duel Links Meta","url":"https://www.duellinksmeta.com/articles/tier-list/updates/2026/october-26","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Los porcentajes de uso de los Skills salen de una muestra de 63 listas en Duel Links Meta el 27 de octubre de 2026 (Dark 57%, Light 25%, Wind 16%) y se mueven unos puntos con cada actualización.","en":"Skill usage percentages come from a sample of 63 lists on Duel Links Meta on October 27, 2026 (Dark 57%, Light 25%, Wind 16%) and shift a few points with each update."},{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the per-turn adjustments are the editors' judgment."}]},"dl/snake-eye":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Combo de FIRE de Nivel 1: Snake-Eye Ash, Oak, Birch y Poplar se encadenan para llegar a Snake-Eyes Flamberge Dragon, que deja monstruos en la Zona de Magias y Trampas como Magias Continuas y los trae de vuelta en el turno del rival.","en":"Level 1 FIRE combo: Snake-Eye Ash, Oak, Birch and Poplar chain into Snake-Eyes Flamberge Dragon, which leaves monsters in the Spell & Trap Zone as Continuous Spells and brings them back on the opponent's turn."},{"es":"Divine Temple of the Snake-Eye revive uno de esos monstruos cada vez que el rival Invoca, y Diabellstar the Black Witch busca los Sinful Spoils (Original, Subversion, Rciela, Silvera) que sostienen el campo.","en":"Divine Temple of the Snake-Eye brings back one of those monsters each time the opponent Summons, and Diabellstar the Black Witch fetches the Sinful Spoils (Original, Subversion, Rciela, Silvera) that hold the board."},{"es":"El cierre típico es Lyrilusc - Assembled Nightingale (Xyz Rango 1 que ataca directo) o Promethean Princess con Topologic Trisbaena, más I:P Masquerena y Knightmare Phoenix para romper cartas.","en":"The typical finish is Lyrilusc - Assembled Nightingale (a Rank 1 Xyz that attacks directly) or Promethean Princess with Topologic Trisbaena, plus I:P Masquerena and Knightmare Phoenix to break cards."},{"es":"Skill Eyes of Sovereign Defiance: tu daño de efecto es 0 y en tu Main Phase solo podés Invocar monstruos FIRE o Diabellstar (el Extra Deck queda libre). Su segundo efecto trae hasta 2 Sinful Spoils o Divine Temple.","en":"Eyes of Sovereign Defiance Skill: your effect damage is 0 and in your Main Phase you can only Summon FIRE monsters or Diabellstar (the Extra Deck is exempt). Its second effect fetches up to 2 Sinful Spoils or Divine Temple."}]},"starters":[{"cards":["Diabellstar the Black Witch"],"route":{"es":"Se Invoca de la mano mandando una carta al Cementerio y Setea un Sinful Spoils del Deck; es el único monstruo no FIRE que el Skill te deja Invocar, y WANTED la trae del Deck o del Cementerio.","en":"Special Summons from hand by sending a card to the GY and Sets a Sinful Spoils from the Deck; it is the only non-FIRE monster the Skill lets you Summon, and WANTED brings it from the Deck or GY."}},{"cards":["Snake-Eye Ash","Snake-Eye Oak"],"route":{"es":"Ash busca un FIRE de Nivel 1 y Ash u Oak, mandando 2 cartas boca arriba al Cementerio, Invocan otro Snake-Eye de la mano o el Deck: así llegás a Flamberge Dragon.","en":"Ash adds a Level 1 FIRE and Ash or Oak, sending 2 face-up cards to the GY, Special Summon another Snake-Eye from hand or Deck: that is how you reach Flamberge Dragon."}},{"cards":["Divine Temple of the Snake-Eye","Snake-Eyes Poplar"],"route":{"es":"Poplar (Invocación Normal) busca un Spell/Trap Snake-Eye; Temple deja un Snake-Eye como Magia Continua y le da +1100 de ATK a los FIRE de Nivel 1.","en":"Poplar (Normal Summon) adds a Snake-Eye Spell/Trap; Temple places a Snake-Eye as a Continuous Spell and gives Level 1 FIRE monsters +1100 ATK."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Poplar, Ash, WANTED).","en":"Right after the first search resolves (Poplar, Ash, WANTED)."},"loss":{"es":"Corta el resto de las búsquedas del turno. Abrí con la que más necesitás y apoyate en Oak y Original Sinful Spoils, que Invocan o recuperan del Cementerio.","en":"It cuts the rest of the turn's searches. Open with the one you need most and lean on Oak and Original Sinful Spoils, which Summon or recover from the GY."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse Oak, Flamberge o Promethean para revivir o agregar desde el Cementerio.","en":"When Oak, Flamberge or Promethean activate to revive or add from the GY."},"loss":{"es":"Niega Invocar o agregar desde el Cementerio, y casi todo el recurso del mazo vive ahí. Jugá primero lo que no toca el Cementerio y guardá a Flamberge.","en":"It negates Summoning or adding from the GY and most of the deck's resources live there. Play what does not touch the GY first and hold Flamberge."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta Invocación del turno (Snake-Eye llega a 5 sin esfuerzo).","en":"On the fifth Summon of the turn (Snake-Eye reaches 5 with ease)."},"loss":{"es":"Tributa todo tu campo y los Snake-Eye pierden su ventaja. Frená en 4 Invocaciones si ya tenés una buena base y dejá los Quick Effects de Birch y Temple para su turno.","en":"It Tributes your whole board and Snake-Eye loses its edge. Stop at 4 Summons if you already have a good base and leave Birch's and Temple's Quick Effects for their turn."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Snake-Eye Ash, Flamberge o Diabellstar apenas activan su efecto.","en":"On Snake-Eye Ash, Flamberge or Diabellstar as soon as they activate their effect."},"loss":{"es":"Anula el efecto clave y, seteada, también apaga las Magias/Trampas de esa columna (por ejemplo un Temple). Poné las piezas importantes en columnas distintas.","en":"It negates the key effect and, if Set, also shuts down Spells/Traps in that column (a Temple, for example). Put important pieces in different columns."}},{"card":"Canopic Protector","step":"activation","stepText":{"es":"En respuesta a tu primer efecto, Invoca un Horus de la mano o el Cementerio una vez por Cadena.","en":"In response to your first effect, it Special Summons a Horus from hand or GY once per Chain."},"loss":{"es":"Es la pesadilla del mazo: cada efecto tuyo puede ser respondido con un cuerpo de Nivel 8 protegido. Hay que atraer la primera Canopic con Phoenix o una pieza barata antes del resto.","en":"It is the deck's nightmare: each of your effects can be answered with a protected Level 8 body. Bait the first Canopic with Phoenix or a cheap piece before the rest."}}],"skills":[{"name":"Eyes of Sovereign Defiance","why":{"es":"Es el Skill del mazo (100%). Cambia el daño de efecto a 0 y te limita a FIRE y Diabellstar en la Main Phase, pero su segundo efecto te trae Divine Temple o Sinful Spoils, y el tercero (solo con monstruo rival) manda a Silvera al Cementerio y Setea un WANTED que se activa el mismo turno.","en":"The deck's Skill (100%). It turns your effect damage into 0 and limits you to FIRE and Diabellstar in the Main Phase, but its second effect fetches Divine Temple or Sinful Spoils, and the third (only with an opposing monster) sends Silvera to the GY and Sets a WANTED you can activate the same turn."}}],"side":{"first":{"in":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Yendo primero el rival juega su turno con búsquedas: el tercer Droll corta su plan, y tenés el turno siguiente completo para usar las tuyas.","en":"Going first the opponent plays a turn full of searches: the third Droll cuts their plan, and you have the whole following turn to use yours."}}],"out":[{"card":"Hey, Trunade!","qty":1,"why":{"es":"Yendo primero el rival no tiene cartas Seteadas que devolver: Trunade no hace nada en tu primer turno.","en":"Going first the opponent has no Set cards to return: Trunade does nothing in your first turn."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":1,"why":{"es":"Yendo segundo rompés el campo del rival y negás sus monstruos antes de empezar el combo.","en":"Going second you break the opponent's board and negate their monsters before starting the combo."}}],"out":[{"card":"Startling Stare of the Snake-Eyes","qty":1,"why":{"es":"Es una Trampa: se Setea y recién se activa el turno siguiente. Yendo segundo querés resolver todo en tu primer turno, y romper el campo con Dark Ruler No More rinde más.","en":"It is a Trap: you Set it and it can only be activated the next turn. Going second you want to resolve everything in your first turn, and breaking the board with Dark Ruler No More does more."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Snake-Eye Deck Breakdown | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list/deck-types/Snake-Eye","kind":"results","checked":"2026-10-27"},{"name":"Eyes of Sovereign Defiance | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Eyes%20of%20Sovereign%20Defiance","kind":"cards","checked":"2026-10-27"},{"name":"Snake-Eye Ash | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Snake-Eye%20Ash","kind":"cards","checked":"2026-10-27"},{"name":"Divine Temple of the Snake-Eye | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Divine%20Temple%20of%20the%20Snake-Eye","kind":"cards","checked":"2026-10-27"},{"name":"Tier List Update | Duel Links Meta","url":"https://www.duellinksmeta.com/articles/tier-list/updates/2026/october-26","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the per-turn adjustments are the editors' judgment."}]},"dl/memento":{"win":{"plan":"otk","pace":"fast","bullets":[{"es":"Gana por ataque directo: Mementotlan Akihiron deja que los Memento de Nivel 9 o más ataquen directo, y Mementoal Tecuhtlica - Combined Creation tiene 5000 de ATK contra 4000 LP de partida. Yendo segundo se puede ganar en el primer turno.","en":"Wins by direct attack: Mementotlan Akihiron lets Level 9 or higher Memento attack directly, and Mementoal Tecuhtlica - Combined Creation has 5000 ATK against 4000 starting LP. Going second it can win on the first turn."},{"es":"Los Memento se destruyen entre sí para buscar o mandar al Cementerio (Dark Blade, Goblin, Mace, Tatsunootoshigo, Angwitch); Ghattic y Akihiron se Invocan solos del Cementerio cuando eso pasa.","en":"Memento destroy each other to search or send to the GY (Dark Blade, Goblin, Mace, Tatsunootoshigo, Angwitch); Ghattic and Akihiron Special Summon themselves from the GY when that happens."},{"es":"Combined Creation se Invoca barajando 5 Memento distintos de la mano y el Cementerio, y una vez por turno, cuando el rival activa algo, Invoca otro Memento. Cierra con respaldo de Trampas (Fracture Dance) y el campo Mementomictlan.","en":"Combined Creation is Special Summoned by shuffling 5 different Memento from hand and GY, and once per turn, when the opponent activates something, it Special Summons another Memento. It finishes with Trap backup (Fracture Dance) and the Mementomictlan field."},{"es":"Sus rutas son largas: conviene practicar las líneas antes de jugarlo.","en":"Its lines are long: practice the routes before playing it."}]},"starters":[{"cards":["Mementotlan Dark Blade","Mementotlan Angwitch"],"route":{"es":"Dark Blade (Invocación Normal) se destruye y trae de Deck un Memento de Nivel 3 o menos (Angwitch); Angwitch busca otro Memento (por ejemplo Tatsunootoshigo) con el que seguís.","en":"Dark Blade (Normal Summon) destroys itself and brings a Level 3 or lower Memento from the Deck (Angwitch); Angwitch adds another Memento (Tatsunootoshigo, for instance) to keep going."}},{"cards":["Mementotlan Shleepy"],"route":{"es":"Shleepy se Invoca y hace una Fusión Memento con monstruos de la mano o el campo: Twin Dragon o Creation King, que a su vez buscan las piezas que faltan.","en":"Shleepy is Summoned and makes a Memento Fusion with monsters from hand or field: Twin Dragon or Creation King, which in turn fetch the missing pieces."}},{"cards":["Mementotlan Goblin","Mementotlan Tatsunootoshigo"],"route":{"es":"Goblin se destruye y manda Tatsunootoshigo y Ghattic al Cementerio; Ghattic se Invoca solo y agrega una carta. Tatsunootoshigo después manda lo que falte para Combined Creation.","en":"Goblin destroys itself and sends Tatsunootoshigo and Ghattic to the GY; Ghattic Special Summons itself and adds a card. Tatsunootoshigo then sends what Combined Creation still needs."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Angwitch, Mace, Twin Dragon, Bone Party).","en":"Right after the first search resolves (Angwitch, Mace, Twin Dragon, Bone Party)."},"loss":{"es":"Corta las demás búsquedas del turno y el mazo depende de varias. Practicá la línea que arranca por la búsqueda más importante y la que sigue usando solo el Cementerio.","en":"It stops the other searches of the turn and the deck relies on several. Practice the line that starts with the most important search and the one that keeps going with only the GY."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse Ghattic, Akihiron o Angwitch para Invocarse o agregar desde el Cementerio.","en":"When Ghattic, Akihiron or Angwitch activate to Summon or add from the GY."},"loss":{"es":"Niega el efecto que reanima o recupera del Cementerio, y casi todos los Memento viven de eso. Dejá a Belle ir a una pieza menor antes de usar el combo largo.","en":"It negates the effect that revives or recovers from the GY, and nearly every Memento lives off that. Let Belle hit a minor piece before using the long combo."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta Invocación del turno, algo que Memento alcanza con facilidad.","en":"On the fifth Summon of the turn, something Memento reaches easily."},"loss":{"es":"Tributa todos tus monstruos y deja un Token con el ATK combinado. Contá Invocaciones y no llegues a cinco sin tener el cierre ya resuelto.","en":"It Tributes all your monsters and leaves a Token with the combined ATK. Count Summons and do not reach five without the finish already secured."}},{"card":"Book of Eclipse","step":"main","stepText":{"es":"En tu Battle Phase, si la tenían Seteada, antes del ataque directo.","en":"In your Battle Phase, if they had it Set, before the direct attack."},"loss":{"es":"Pone todos los monstruos boca abajo en Defensa: Combined Creation no ataca directo ese turno. Es un Quick-Play que el rival debe Setear antes: si ves una Spell Seteada, dejá a otro Memento listo para el siguiente turno.","en":"It turns all monsters face-down Defense: Combined Creation does not attack directly that turn. It is a Quick-Play the opponent must Set first: if you see a Set Spell, leave another Memento ready for the next turn."}},{"card":"Forbidden Droplet","step":"attack","stepText":{"es":"En tu declaración de ataque (si la tenían Seteada) o en la activación de Combined Creation.","en":"On your attack declaration (if they had it Set) or on Combined Creation's activation."},"loss":{"es":"Baja a la mitad el ATK de Combined Creation (5000 a 2500) y niega sus efectos: el daño ya no alcanza para los 4000. Dejá un Memento más para hacer daño o tené otra vía de victoria.","en":"It halves Combined Creation's ATK (5000 to 2500) and negates its effects: the damage no longer reaches 4000. Keep another Memento for damage or have a second win route."}}],"skills":[{"name":"Precious Cards of the Dark","why":{"es":"El más usado (96%). Si el Deck tiene 6 o más monstruos DARK, una vez por turno y hasta dos veces por Duelo mandás una carta de la mano al fondo del Deck o al Cementerio y robás 2 (más 1 si vas segundo en tu primer turno). Es opcional: según la mano, a veces ni hace falta usarlo.","en":"The most used (96%). If the Deck has 6 or more DARK monsters, once per turn and up to twice per Duel you put a card from hand on the bottom or in the GY and draw 2 (plus 1 if you go second on your first turn). It is optional: depending on the hand you sometimes do not need it."}}],"side":{"first":{"in":[{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"Yendo primero esperás el turno del rival: Nibiru castiga una jugada larga y Memento no la lleva en el Main.","en":"Going first you wait for the opponent's turn: Nibiru punishes a long play and Memento does not run it in the Main."}}],"out":[{"card":"Hey, Trunade!","qty":1,"why":{"es":"Yendo primero el rival no tiene cartas Seteadas en tu turno; Trunade queda muerta.","en":"Going first the opponent has no Set cards on your turn; Trunade is dead."}}]},"second":{"in":[{"card":"Lava Golem","qty":1,"why":{"es":"Yendo segundo el rival ya armó cuerpos: si Akihiron o Combined Creation quedan negados, Golem le saca dos monstruos y te deja pelear con ataques normales.","en":"Going second the opponent already built bodies: if Akihiron or Combined Creation get negated, Golem takes two monsters and lets you fight with normal attacks."}}],"out":[{"card":"Mementotlan-Horned Dragon","qty":1,"why":{"es":"Pide tres Memento distintos en el Cementerio: es una pieza de toolbox, más lenta que la presión de un Golem.","en":"It asks for three different Memento in the GY: it is a toolbox piece, slower than a Golem's pressure."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Memento Deck Breakdown | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list/deck-types/Memento","kind":"results","checked":"2026-10-27"},{"name":"Precious Cards of the Dark | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Precious%20Cards%20of%20the%20Dark","kind":"cards","checked":"2026-10-27"},{"name":"Mementoal Tecuhtlica - Combined Creation | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Mementoal%20Tecuhtlica%20-%20Combined%20Creation","kind":"cards","checked":"2026-10-27"},{"name":"Mementotlan Akihiron | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Mementotlan%20Akihiron","kind":"cards","checked":"2026-10-27"},{"name":"Yu-Gi-Oh! Duel Links - Yugipedia","url":"https://yugipedia.com/wiki/Yu-Gi-Oh!_Duel_Links","kind":"rules","checked":"2026-10-27"},{"name":"Tier List Update | Duel Links Meta","url":"https://www.duellinksmeta.com/articles/tier-list/updates/2026/october-26","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the per-turn adjustments are the editors' judgment."}]},"dl/vaalmonica":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Juega con Pendulum Zones (las da el Skill) y junta Resonance Counters ganando LP con un Hechizo y recibiendo daño con otro: Angello y Dimonno, en las escalas, los acumulan.","en":"Plays with Pendulum Zones (given by the Skill) and gathers Resonance Counters by gaining LP with one Spell and taking damage with another: Angello and Dimonno, in the scales, accumulate them."},{"es":"Con 3 contadores en la escala sale Duralume o Zebufera por Link; Zebufera protege lo tuyo de la destrucción gastando 3 contadores, y Varar niega y destruye una Invocación del rival.","en":"With 3 counters on a scale, Duralume or Zebufera comes out by Link Summon; Zebufera protects your cards from destruction by spending 3 counters, and Varar negates and destroys an opposing Summon."},{"es":"Los Traps cierran el turno: Vaalmonica Ereditare niega una carta si controlás un Link Vaalmonica, Followed Rhythm destruye o devuelve a la mano, y Creation Link Summon cuando el rival Invoca.","en":"Traps finish the turn: Vaalmonica Ereditare negates a card if you control a Vaalmonica Link, Followed Rhythm destroys or bounces, and Creation Link Summons when the opponent Summons."},{"es":"Gana las partidas largas: Ereditare baraja Vaalmonica del Cementerio y de los desterrados al Deck y Disarmonia los recupera: el mazo se recarga solo.","en":"It wins long games: Ereditare shuffles Vaalmonica from the GY and banishment into the Deck and Disarmonia gets them back: the deck refills itself."}]},"starters":[{"cards":["Angello Vaalmonica","Dimonno Vaalmonica"],"route":{"es":"Descartando una carta, Angello trae a Dimonno del Deck (o viceversa) y los dos van a las Pendulum Zones: base para contadores y para Link Summon.","en":"Discarding a card, Angello takes Dimonno from the Deck (or vice versa) and both go to the Pendulum Zones: the base for counters and for Link Summons."}},{"cards":["Selettrice Vaalmonica"],"route":{"es":"Por Invocación Normal busca cualquier carta Vaalmonica, y si la mandás al Cementerio con dos Vaalmonica en las escalas, vuelve a la mano.","en":"Normal Summoned it adds any Vaalmonica card, and if you send it to the GY with two Vaalmonica in the Pendulum Zones it returns to hand."}},{"cards":["Vaalmonica Scelta"],"route":{"es":"Con un Vaalmonica en la escala elegís: ganar 500 LP y robar 2, o recibir 250 de daño y agregar un Vaalmonica Spell/Trap. Con las escalas puestas, los dos efectos dan contadores.","en":"With a Vaalmonica in the Pendulum Zone you choose: gain 500 LP and draw 2, or take 250 damage and add a Vaalmonica Spell/Trap. With the scales set, both effects give counters."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Selettrice, Scelta, Versare).","en":"Right after the first search resolves (Selettrice, Scelta, Versare)."},"loss":{"es":"Corta las búsquedas siguientes del turno y el mazo depende de varias búsquedas por turno. Abrí con la búsqueda que más necesitás.","en":"It cuts the next searches of the turn and the deck relies on several searches per turn. Open with the search you need most."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse Selettrice o Disarmonia para agregar desde el Cementerio.","en":"When Selettrice or Disarmonia activate to add from the GY."},"loss":{"es":"Niega esa recuperación y con ella el bucle de Ereditare más Disarmonia. Guardá una segunda forma de recuperar y no dependas de un único recurso.","en":"It negates that recovery and with it the Ereditare plus Disarmonia loop. Keep a second way to recover and do not rely on a single resource."}},{"card":"Mulcharmy Fuwalos","step":"summon","stepText":{"es":"En cada Link Summon: roba una carta al rival por cada Invocación desde el Extra Deck.","en":"On each Link Summon: draws the opponent a card for each Extra Deck Summon."},"loss":{"es":"Vaalmonica hace varios Links por turno y el Main Deck ronda las 20 cartas, así que cada robo regalado pesa. Limitá los Links intermedios.","en":"Vaalmonica makes several Links per turn and the Main Deck averages about 20 cards, so each gifted draw hurts. Limit intermediate Links."}},{"card":"Dark Ruler No More","step":"main","stepText":{"es":"En la Main Phase del rival, antes de tu Link Summon o durante su Battle Phase.","en":"In the opponent's Main Phase, before your Link Summon or during their Battle Phase."},"loss":{"es":"Niega los efectos de monstruos de tu campo y nadie responde con efectos de monstruo: Varar y Zebufera no pueden usar su negación ni su protección. Los Traps Vaalmonica siguen en pie.","en":"It negates your monsters' effects and nobody can respond with monster effects: Varar and Zebufera cannot use their negation or protection. The Vaalmonica Traps remain."}}],"skills":[{"name":"Whispers of Good and Evil","why":{"es":"Es el Skill del mazo (100%): al inicio del Duelo te da las Pendulum Zones y evita que te apunten los Vaalmonica de la escala. Su segundo efecto busca un Vaalmonica revelando un monstruo; el tercero (si el rival controla una carta) Setea un Vaalmonica Spell/Trap activable el mismo turno y, si venía de la mano, robás 2 y barajás 1.","en":"The deck's Skill (100%): at the start of the Duel it gives you the Pendulum Zones and prevents opponents from targeting the Vaalmonica in them. Its second effect adds a Vaalmonica by revealing a monster; the third (if the opponent controls a card) Sets a Vaalmonica Spell/Trap you can activate the same turn and, if from hand, you draw 2 and shuffle 1."}}],"side":{"first":{"in":[{"card":"Droll & Lock Bird","qty":2,"why":{"es":"Yendo primero esperás el turno del rival y Droll corta su búsqueda.","en":"Going first you wait for the opponent's turn and Droll cuts their search."}}],"out":[{"card":"Forbidden Droplet","qty":1,"why":{"es":"Droplet rinde más yendo segundo (manda Creation al Cementerio con contadores); yendo primero queda floja.","en":"Droplet does more going second (it sends Creation to the GY for counters); going first it is weaker."}},{"card":"Book of Eclipse","qty":1,"why":{"es":"Yendo primero el rival no tiene campo que romper en tu primer turno.","en":"Going first the opponent has no board to break in your first turn."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":1,"why":{"es":"Yendo segundo es el rompe-campo del rival antes de armar tu tablero, y se puede robar con las cartas de robo de Vaalmonica.","en":"Going second it is your board breaker before setting up, and it can be drawn with Vaalmonica's draw cards."}}],"out":[{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"El rival juega primero y rara vez llega a 5 Invocaciones; la ranura se usa mejor como rompe-campo.","en":"The opponent plays first and rarely reaches 5 Summons; the slot works better as a board breaker."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Vaalmonica Deck Breakdown | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list/deck-types/Vaalmonica","kind":"results","checked":"2026-10-27"},{"name":"Whispers of Good and Evil | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Whispers%20of%20Good%20and%20Evil","kind":"cards","checked":"2026-10-27"},{"name":"Angello Vaalmonica | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Angello%20Vaalmonica","kind":"cards","checked":"2026-10-27"},{"name":"Vaalmonica Scelta | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Vaalmonica%20Scelta","kind":"cards","checked":"2026-10-27"},{"name":"Tier List Update | Duel Links Meta","url":"https://www.duellinksmeta.com/articles/tier-list/updates/2026/october-26","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Hay pocas listas de Vaalmonica: Duel Links Meta cuenta 13 en total y 7 de torneo, así que las estadísticas de uso se mueven mucho con una lista más o menos.","en":"There are few Vaalmonica lists: Duel Links Meta counts 13 in total and 7 from tournaments, so usage statistics swing a lot with one list more or less."},{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the per-turn adjustments are the editors' judgment."}]},"dl/centur-ion":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Centur-Ion deja sus monstruos en la Zona de Magias y Trampas como Trampas Continuas (con Trudea, Emblema Oath, Bonds) y los Invoca de ahí en la Main Phase; Emeth VI entra en el turno del rival.","en":"Centur-Ion places its monsters in the Spell & Trap Zone as Continuous Traps (with Trudea, Emblema Oath, Bonds) and Special Summons them from there in the Main Phase; Emeth VI comes in on the opponent's turn."},{"es":"Stand Up Centur-Ion! permite hacer un Synchro apenas se Invoca Especialmente un monstruo; el cierre usa Shooting Quasar Dragon (niega y destruye), Red Supernova Dragon (destierra todo el campo rival cuando activa un efecto o ataca) y Crimson Dragon.","en":"Stand Up Centur-Ion! lets you Synchro Summon whenever a monster is Special Summoned; the finish uses Shooting Quasar Dragon (negate and destroy), Red Supernova Dragon (banishes the opposing board when they activate an effect or attack) and Crimson Dragon."},{"es":"Skill The Courage to Rise: en tu turno solo podés Invocar Centur-Ion (el Extra Deck queda libre), y aun así hay lugar para handtraps (Effect Veiler, Ghost Belle, D.D. Crow) que juegan en el turno del rival.","en":"The Courage to Rise Skill: on your turn you can only Summon Centur-Ion (the Extra Deck is exempt), and there is still room for hand traps (Effect Veiler, Ghost Belle, D.D. Crow) that play on the opponent's turn."},{"es":"Buena parte de la apertura pone cartas del Deck en la Zona de Magias y Trampas en lugar de agregarlas a la mano, así que Droll & Lock Bird, que reacciona cuando se agrega una carta del Deck a la mano, lo frena menos que a otros mazos.","en":"Much of the opening places cards from the Deck into the Spell & Trap Zone instead of adding them to hand, so Droll & Lock Bird, which reacts to adding from the Deck, stops it less than other decks."}]},"starters":[{"cards":["Centur-Ion Primera"],"route":{"es":"Invocación Normal: agrega una carta Centur-Ion; como Trampa Continua, se Invoca sola en la Main Phase. Es la apertura de una sola carta.","en":"Normal Summon: adds a Centur-Ion card; as a Continuous Trap, it Special Summons itself in the Main Phase. It is a one-card opening."}},{"cards":["Centur-Ion Trudea"],"route":{"es":"Pone a Trudea y a otro Centur-Ion de la mano o el Deck en la Zona de Magias y Trampas; Trudea vuelve al campo y puede subir a Nivel 8 para el Synchro.","en":"Places Trudea and another Centur-Ion from hand or Deck in the Spell & Trap Zone; Trudea returns to the field and can go up to Level 8 for the Synchro."}},{"cards":["Emblema Oath","Stand Up Centur-Ion!"],"route":{"es":"Emblema Oath pone un Centur-Ion del Deck como Trampa Continua o Setea una Spell/Trap Centur-Ion; Stand Up hace el Synchro en cuanto se Invoca un monstruo.","en":"Emblema Oath places a Centur-Ion from the Deck as a Continuous Trap or Sets a Centur-Ion Spell/Trap; Stand Up Synchro Summons as soon as a monster is Summoned."}}],"chokepoints":[{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta Invocación del turno, justo antes del Synchro final.","en":"On the fifth Summon of the turn, right before the final Synchro."},"loss":{"es":"Tributa todos los monstruos del campo y deja un Token con el ATK combinado de lo que armaste. Armá la parte de Synchro más cara en cuarto lugar y guardá el resto para el turno del rival.","en":"It Tributes every monster on the field and leaves a Token with the combined ATK of what you built. Do the most expensive Synchro fourth and save the rest for the opponent's turn."}},{"card":"Artifact Lancea","step":"activation","stepText":{"es":"En respuesta a Emblema Salvation, Phalanx o Red Supernova Dragon.","en":"In response to Emblema Salvation, Phalanx or Red Supernova Dragon."},"loss":{"es":"Ninguno puede desterrar por el resto del turno, y el mazo destierra para romper cartas: Salvation, Phalanx y Red Supernova quedan sin efecto. Jugá primero lo que no destierra (Quasar, True Awakening).","en":"Neither player can banish for the rest of the turn, and the deck banishes to break cards: Salvation, Phalanx and Red Supernova lose their effect. Play what does not banish first (Quasar, True Awakening)."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Legatia, Primera Primus o Auxila apenas activan su efecto al ser Invocados.","en":"On Legatia, Primera Primus or Auxila as soon as they activate on Summon."},"loss":{"es":"Anula el efecto de búsqueda o de roba/destrucción del Synchro. Dejá que respondan con Impermanence a una pieza menor antes de lo importante.","en":"It negates the Synchro's search or draw/destroy effect. Let them spend Impermanence on a minor piece before the important one."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Primera, Auxila o Primera Primus).","en":"Right after the first search resolves (Primera, Auxila or Primera Primus)."},"loss":{"es":"Corta las búsquedas siguientes, pero Emblema Oath (que Setea desde el Deck) y las colocaciones en la Zona de Magias y Trampas siguen funcionando. Por eso el mazo juega bien contra Droll.","en":"It stops later searches, but Emblema Oath (which Sets from the Deck) and placements into the Spell & Trap Zone still work. That is why the deck plays well against Droll."}}],"skills":[{"name":"The Courage to Rise","why":{"es":"Es el Skill del mazo (100%). Durante tu turno solo podés Invocar Centur-Ion (salvo Extra Deck), su segundo efecto revela un Centur-Ion y agrega otro del Deck, y el tercero (con Legatia o monstruo rival) busca una carta Emblema y pone un Centur-Ion en el Cementerio o en la Zona de Magias y Trampas.","en":"The deck's Skill (100%). During your turn you can only Summon Centur-Ion (except from the Extra Deck), its second effect reveals a Centur-Ion and adds another from the Deck, and the third (with Legatia or an opposing monster) adds an Emblema card and sends a Centur-Ion to the GY or places it in the Spell & Trap Zone."}}],"side":{"first":{"in":[{"card":"Forbidden Droplet","qty":1,"why":{"es":"Quick-Play: Seteada en tu primer turno se activa en el turno del rival, que es cuando más necesitás frenar su jugada yendo primero.","en":"Quick-Play: Set in your first turn it activates on the opponent's turn, which is when you most need to stop their play going first."}}],"out":[{"card":"Synchro Rumble","qty":1,"why":{"es":"Yendo primero queda como seguimiento lento y su restricción de Extra Deck pesa en tu turno de armado.","en":"Going first it is a slow follow-up and its Extra Deck restriction weighs on your setup turn."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":1,"why":{"es":"Yendo segundo rompe el campo del rival antes de tu turno de armado y nadie responde con efectos de monstruo.","en":"Going second it breaks the opponent's board before your setup turn and nobody can respond with monster effects."}}],"out":[{"card":"Synchro Rumble","qty":1,"why":{"es":"Es la carta menos necesaria cuando ya tenés que romper campo en vez de revivir Synchros.","en":"It is the least necessary card when you need to break a board instead of reviving Synchros."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Centur-Ion Deck Breakdown | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list/deck-types/Centur-Ion","kind":"results","checked":"2026-10-27"},{"name":"The Courage to Rise | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/The%20Courage%20to%20Rise","kind":"cards","checked":"2026-10-27"},{"name":"Centur-Ion Primera | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Centur-Ion%20Primera","kind":"cards","checked":"2026-10-27"},{"name":"Stand Up Centur-Ion! | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Stand%20Up%20Centur-Ion%21","kind":"cards","checked":"2026-10-27"},{"name":"Tier List Update | Duel Links Meta","url":"https://www.duellinksmeta.com/articles/tier-list/updates/2026/october-26","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Hay pocas listas de Centur-Ion: Duel Links Meta cuenta 11 en total y 9 de torneo, así que las estadísticas de uso se mueven mucho con una lista más o menos.","en":"There are few Centur-Ion lists: Duel Links Meta counts 11 in total and 9 from tournaments, so usage statistics swing a lot with one list more or less."},{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the per-turn adjustments are the editors' judgment."}]},"dl/dark-magician":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Roba muchas cartas con Soul Servant, Magicians' Souls y Coach King Giantrainer y cierra con un tablero de interrupciones.","en":"Draws many cards with Soul Servant, Magicians' Souls and Coach King Giantrainer and finishes with a board of interruptions."},{"es":"El cierre típico: I:P Masquerena, S:P Little Knight o Red-Eyes Dark Dragoon, Dark Magical Circle (destierro), Eternal Soul, Magicians' Combination (negación) y Number 90: Galaxy-Eyes Photon Lord.","en":"The typical finish: I:P Masquerena, S:P Little Knight or Red-Eyes Dark Dragoon, Dark Magical Circle (banish), Eternal Soul, Magicians' Combination (negation) and Number 90: Galaxy-Eyes Photon Lord."},{"es":"Timaeus the United Dragon es el centro: se Invoca de la mano mandando al Cementerio un Spellcaster o una S/T de Dark Magician, y hace Fusión cada turno. Si lo abrís, jugás a través de Droll.","en":"Timaeus the United Dragon is the center: it Special Summons from hand by sending a Spellcaster or a Dark Magician S/T, and Fusion Summons each turn. If you open it, you play through Droll."},{"es":"Dark Magical Curtain (Quick-Play) pone un DARK Spellcaster en ambos lados sin efectos, y su Skill es de su propio arquetipo.","en":"Dark Magical Curtain (Quick-Play) puts a DARK Spellcaster on both sides without effects, and its Skill belongs to the archetype."}]},"starters":[{"cards":["Timaeus the United Dragon"],"route":{"es":"Con el Skill (barajás una carta de la mano) se juega Timaeus de la mano y se agregan 2 cartas de Dark Magician; después Fusión con un Spellcaster para Dragoon.","en":"With the Skill (shuffle a card) Timaeus is played from hand and 2 Dark Magician cards are added; then Fusion with a Spellcaster for Dragoon."}},{"cards":["Dark Magical Curtain"],"route":{"es":"Invoca un DARK Spellcaster de la mano o el Deck de cada lado: tuyo es Dark Magician o Dark Magician Girl, que además te agrega una Spell/Trap que lo mencione.","en":"Special Summons a DARK Spellcaster from hand or Deck for each side: yours is Dark Magician or Dark Magician Girl, which also adds a Spell/Trap that mentions it."}},{"cards":["Magician's Rod"],"route":{"es":"Invocación Normal: agrega una Spell/Trap que mencione a Dark Magician (por ejemplo Soul Servant o Dark Magical Circle), que abre el robo masivo.","en":"Normal Summon: adds a Spell/Trap that mentions Dark Magician (such as Soul Servant or Dark Magical Circle), which opens the mass draw."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda o robo (Rod, Souls, Soul Servant).","en":"Right after the first search or draw resolves (Rod, Souls, Soul Servant)."},"loss":{"es":"Yendo primero corta el robo masivo. Abrir Timaeus permite seguir jugando a través de Droll.","en":"Going first it cuts the mass draw. Opening Timaeus lets you keep playing through Droll."}},{"card":"Artifact Lancea","step":"activation","stepText":{"es":"En respuesta a Dark Magical Circle, S:P Little Knight o cualquier efecto que destierre.","en":"In response to Dark Magical Circle, S:P Little Knight or any banish effect."},"loss":{"es":"Ninguno puede desterrar, y esos son los cierres de interrupción del mazo.","en":"Neither player can banish, and those are the deck's interruption finishers."}},{"card":"Bystial Druiswurm","step":"activation","stepText":{"es":"Entra como Efecto Rápido en el turno del rival desterrando un LIGHT o DARK de tu Cementerio.","en":"Comes in as a Quick Effect on the opponent's turn by banishing a LIGHT or DARK from your GY."},"loss":{"es":"Se lleva a tu Dark Magician o Girl del Cementerio, que sostienen Salvation, Eternal Soul y Combination.","en":"It takes your Dark Magician or Girl from the GY, which Salvation, Eternal Soul and Combination rely on."}},{"card":"Mulcharmy Fuwalos","step":"summon","stepText":{"es":"En cada Invocación Especial desde el Extra Deck (Dragoon, I:P, S:P, Photon Lord).","en":"On each Special Summon from the Extra Deck (Dragoon, I:P, S:P, Photon Lord)."},"loss":{"es":"Le da una carta al rival por cada monstruo del Extra Deck; con Decks tan chicos cada robo regalado pesa. Recortá las Invocaciones del Extra Deck innecesarias.","en":"It gives the opponent a card per Extra Deck monster; with such small Decks each gifted draw hurts. Cut the unnecessary Extra Deck Summons."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse Salvation, Eternal Soul o Magicians' Combination para Invocar del Cementerio.","en":"When Salvation, Eternal Soul or Magicians' Combination activate to Special Summon from the GY."},"loss":{"es":"Niega la reanimación de Dark Magician y Dark Magician Girl, que es el motor del mazo. Jugá primero la parte que no pasa por el Cementerio.","en":"It negates the revival of Dark Magician and Dark Magician Girl, the deck's engine. Play the part that does not use the GY first."}}],"skills":[{"name":"The Eye of the United Dragon","why":{"es":"El más usado (cerca del 80%). Si el Deck tiene 15 o más Dark Magician o cartas que lo mencionen: una vez por Duelo barajás una carta, jugás a Timaeus de la mano y agregás 2 cartas de Dark Magician. El tercero juega a Dark Magician o Girl boca abajo y da The Eye of Timaeus.","en":"The most used (about 80%). If the Deck has 15 or more Dark Magician or cards that mention it: once per Duel you shuffle a card, play Timaeus from hand and add 2 Dark Magician cards. The third plays Dark Magician or Girl face-down and gives The Eye of Timaeus."}},{"name":"Master of the Dark & Chaos","why":{"es":"Alternativa que usa una minoría de las listas de Duel Links Meta: solo podés Invocar monstruos de Nivel 8 LIGHT o EARTH y Spellcasters DARK, pero buscás dos cartas de Dark Magician mandando una Dark Magician Girl de la mano o el Deck al Cementerio.","en":"An alternative used by a minority of the Duel Links Meta lists: you can only Summon Level 8 LIGHT or EARTH monsters and DARK Spellcasters, but you add two Dark Magician cards by sending a Dark Magician Girl from hand or Deck to the GY."}}],"side":{"first":{"in":[{"card":"D.D. Crow","qty":1,"why":{"es":"Contra Branded, Memento y Horus, que viven del Cementerio, Crow quita un recurso en el turno del rival.","en":"Against Branded, Memento and Horus, which live off the GY, Crow removes a resource on the opponent's turn."}},{"card":"Ghost Belle & Haunted Mansion","qty":1,"why":{"es":"Frena el Cementerio del rival en su turno.","en":"It stops the opponent's GY on their turn."}}],"out":[{"card":"Lava Golem","qty":2,"why":{"es":"Yendo primero el rival no tiene monstruos que tributar en tu primer turno: Lava Golem queda muerto en la mano.","en":"Going first the opponent has no monsters to Tribute on your first turn: Lava Golem is dead in hand."}}]},"second":{"in":[{"card":"Mulcharmy Fuwalos","qty":1,"why":{"es":"Yendo segundo no controlás cartas en el turno del rival y Fuwalos se activa; roba por cada Invocación del Extra Deck.","en":"Going second you control no cards on the opponent's turn and Fuwalos activates; it draws for each Extra Deck Summon."}}],"out":[{"card":"Illusion of Chaos","qty":1,"why":{"es":"Dos copias son más de las que hacen falta; se recorta una para sumar techs.","en":"Two copies are more than needed; one is cut to add techs."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Dark Magician Deck Breakdown | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list/deck-types/Dark%20Magician","kind":"results","checked":"2026-10-27"},{"name":"The Eye of the United Dragon | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/The%20Eye%20of%20the%20United%20Dragon","kind":"cards","checked":"2026-10-27"},{"name":"Master of the Dark & Chaos | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Master%20of%20the%20Dark%20%26%20Chaos","kind":"cards","checked":"2026-10-27"},{"name":"Timaeus the United Dragon | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Timaeus%20the%20United%20Dragon","kind":"cards","checked":"2026-10-27"},{"name":"Tier List Update | Duel Links Meta","url":"https://www.duellinksmeta.com/articles/tier-list/updates/2026/october-26","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"La muestra de Dark Magician es chica: Duel Links Meta cuenta unas 30 listas, así que los porcentajes de Skill cambian con una lista más o menos.","en":"The Dark Magician sample is small: Duel Links Meta counts about 30 lists, so Skill percentages change with one list more or less."},{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the per-turn adjustments are the editors' judgment."}]},"dl/shining-sarcophagus":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Shining Sarcophagus busca cada turno una carta que lo mencione y no se destruye por efectos de monstruos; Dark Magician the Magician of Black Magic y Dark Magician Girl the Magician's Apprentice se Invocan solos alrededor de él.","en":"Shining Sarcophagus adds a card that mentions it each turn and cannot be destroyed by monster effects; Dark Magician the Magician of Black Magic and Dark Magician Girl the Magician's Apprentice Special Summon themselves around it."},{"es":"Silent Magician Zero niega una Spell del rival mientras Sarcophagus esté en el campo, Silent Swordsman Zero niega efectos que apunten a tus monstruos de Sarcophagus, y Future Silence y Turn Silence (Quick-Play) buscan y protegen.","en":"Silent Magician Zero negates an opposing Spell while Sarcophagus is on the field, Silent Swordsman Zero negates effects that target your Sarcophagus monsters, and Future Silence and Turn Silence (Quick-Plays) fetch and protect."},{"es":"Gandora-G the Dragon of Destruction se Invoca de la mano si controlás a Shining Sarcophagus; pagando la mitad de los LP, destruye y destierra las demás cartas del campo (también las tuyas); con Lava Golem es la salida para campos grandes.","en":"Gandora-G the Dragon of Destruction Special Summons from hand if you control Shining Sarcophagus; by paying half your LP, it destroys and banishes the other cards on the field (yours too); with Lava Golem it is the out for big boards."},{"es":"Number 90 y Number 68 (Xyz de Rango 8) son el cierre.","en":"Number 90 and Number 68 (Rank 8 Xyz) are the finish."}]},"starters":[{"cards":["Dark Magician Girl the Magician's Apprentice"],"route":{"es":"Se Invoca de la mano descartando una carta y, al Invocarse, agrega Shining Sarcophagus del Deck. Con el Skill, revelarla permite buscar hasta 2 cartas del arquetipo.","en":"Special Summons from hand by discarding a card and, when Summoned, adds Shining Sarcophagus from the Deck. With the Skill, revealing her lets you add up to 2 cards from the archetype."}},{"cards":["Gadget Trio"],"route":{"es":"Invocación Normal: agrega Shining Sarcophagus o una Spell/Trap que lo mencione. Si lo destruyen, Setea Stronghold the Hidden Fortress.","en":"Normal Summon: adds Shining Sarcophagus or a Spell/Trap that mentions it. If destroyed, it Sets Stronghold the Hidden Fortress."}},{"cards":["Shining Sarcophagus","Dark Magician the Magician of Black Magic"],"route":{"es":"Con Sarcophagus en el campo, Dark Magician the Magician of Black Magic se Invoca de la mano sin Tributo; una vez por turno Sarcophagus busca la pieza que falta.","en":"With Sarcophagus on the field, Dark Magician the Magician of Black Magic Special Summons from hand without Tribute; once per turn Sarcophagus adds the missing piece."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (DMG Apprentice, Gadget Trio, Sarcophagus).","en":"Right after the first search resolves (DMG Apprentice, Gadget Trio, Sarcophagus)."},"loss":{"es":"Corta las demás búsquedas del turno. Abrí con la que más necesitás: Shining Sarcophagus busca una carta por turno en tu Main Phase.","en":"It cuts the other searches of the turn. Open with the one you need most: Shining Sarcophagus adds a card each turn in your Main Phase."}},{"card":"Mulcharmy Fuwalos","step":"summon","stepText":{"es":"En cada Invocación del Extra Deck (Number 90, Number 68, Dragoon).","en":"On each Extra Deck Summon (Number 90, Number 68, Dragoon)."},"loss":{"es":"Le da una carta al rival por cada Xyz que sacás. Sacá solo los Xyz que cambian la partida.","en":"It gives the opponent a card for each Xyz you summon. Only summon the Xyz that change the game."}},{"card":"Powersink Stone","step":"activation","stepText":{"es":"Cada efecto de monstruo activado le pone un contador; con dos, los monstruos del campo dejan de activar efectos.","en":"Each activated monster effect puts a counter on it; with two, monsters on the field cannot activate effects."},"loss":{"es":"El mazo depende de efectos de monstruo (Gadget Trio, Silent Magician Zero, Gandora) y se traba. Activá primero los efectos de Spell (Sarcophagus, Future Silence) y evitá gastar el segundo contador.","en":"The deck relies on monster effects (Gadget Trio, Silent Magician Zero, Gandora) and locks up. Activate Spell effects first (Sarcophagus, Future Silence) and avoid spending the second counter."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Gandora-G apenas activa su efecto, o sobre Silent Magician Zero.","en":"On Gandora-G as soon as it activates, or on Silent Magician Zero."},"loss":{"es":"Anula el efecto con el costo de la mitad de los LP ya pagado en Gandora. Esperá a que respondan con Impermanence a otra pieza o activá Gandora con LP de sobra.","en":"It negates the effect with Gandora's half-LP cost already paid. Wait for them to spend Impermanence on another piece or activate Gandora with LP to spare."}}],"skills":[{"name":"Light the Way to the Future","why":{"es":"Es el Skill del mazo (100%). Anula el daño de efecto salvo el de cartas que mencionan a Shining Sarcophagus. Su segundo efecto busca hasta 2 cartas de Sarcophagus o monstruos que lo mencionen revelando un Spellcaster; el tercero, desde el turno 2, cambia Silent Swordsman Zero por Silent Swordsman LV7 boca abajo y agrega Silent Sword Slash.","en":"The deck's Skill (100%). It nullifies effect damage except from cards that mention Shining Sarcophagus. Its second effect adds up to 2 Sarcophagus cards or monsters that mention it by revealing a Spellcaster; the third, from turn 2, swaps Silent Swordsman Zero for a face-down Silent Swordsman LV7 and adds Silent Sword Slash."}}],"side":{"first":{"in":[{"card":"Ghost Belle & Haunted Mansion","qty":1,"why":{"es":"Contra Horus y Memento, que viven del Cementerio, Belle frena su turno sin depender de una Necrovalley.","en":"Against Horus and Memento, which live off the GY, Belle stops their turn without relying on a Necrovalley."}}],"out":[{"card":"Witch of the Black Forest","qty":1,"why":{"es":"Es la ranura de menos impacto; el handtrap la reemplaza mejor en el turno del rival.","en":"It is the lowest-impact slot; the hand trap replaces it better on the opponent's turn."}}]},"second":{"in":[{"card":"Lava Golem","qty":2,"why":{"es":"Yendo segundo el rival ya tiene monstruos y Golem los tributa; no depende de que el rival llegue a cinco Invocaciones, como Nibiru.","en":"Going second the opponent already has monsters and Golem Tributes them; it does not depend on the opponent reaching five Summons, as Nibiru does."}}],"out":[{"card":"Nibiru, the Primal Being","qty":2,"why":{"es":"Yendo segundo Nibiru casi nunca llega a las 5 Invocaciones del rival; Golem rompe el campo ya armado.","en":"Going second Nibiru rarely reaches the opponent's 5 Summons; Golem breaks the board that is already built."}}]},"basis":"editorial"},"updated":"2026-10-27","sources":[{"name":"Shining Sarcophagus Deck Breakdown | Duel Links Meta","url":"https://www.duellinksmeta.com/tier-list/deck-types/Shining%20Sarcophagus","kind":"results","checked":"2026-10-27"},{"name":"Light the Way to the Future | Skill | Duel Links Meta","url":"https://www.duellinksmeta.com/skills/Light%20the%20Way%20to%20the%20Future","kind":"cards","checked":"2026-10-27"},{"name":"Shining Sarcophagus | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Shining%20Sarcophagus","kind":"cards","checked":"2026-10-27"},{"name":"Gandora-G the Dragon of Destruction | Duel Links Meta","url":"https://www.duellinksmeta.com/cards/Gandora-G%20the%20Dragon%20of%20Destruction","kind":"cards","checked":"2026-10-27"},{"name":"Tier List Update | Duel Links Meta","url":"https://www.duellinksmeta.com/articles/tier-list/updates/2026/october-26","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"El Top Player Council sacó a Shining Sarcophagus de la tier list el 26 de octubre de 2026: dice que no puede jugar yendo segundo y que su turno 1 se rompe fácil. La ficha explica cómo juega, no que sea competitivo hoy.","en":"The Top Player Council removed Shining Sarcophagus from the tier list on October 26, 2026: it says the deck cannot play going second and its Turn 1 breaks easily. The card explains how it plays, not that it is competitive today."},{"es":"Duel Links no tiene Side Deck: los ajustes por turno son criterio de la redacción.","en":"Duel Links has no Side Deck: the per-turn adjustments are the editors' judgment."}]},"edison/vayu-turbo":{"win":{"plan":"tempo","pace":"fast","bullets":[{"es":"Gana por tempo: llena el Cementerio con Blackwings y Vayu los convierte en Sincros grandes sin gastar Sintonizador ni materiales de la mano.","en":"Wins on tempo: fills the Graveyard with Blackwings and Vayu turns them into big Synchros without spending a Tuner or hand materials."},{"es":"El motor es tirar a Vayu y a Sirocco al Cementerio: Vayu se destierra con un Blackwing no Sintonizador y trae un Sincro cuyo nivel es la suma (Vayu 1 + Sirocco 5 da nivel 6, Armed Wing). Los efectos del Sincro quedan anulados.","en":"The engine is getting Vayu and Sirocco into the Graveyard: Vayu banishes itself plus a non-Tuner Blackwing and brings out a Synchro whose Level is the sum (Vayu 1 + Sirocco 5 gives Level 6, Armed Wing). The Synchro's effects are negated."},{"es":"Dark Grepher y Armageddon Knight mandan DARKs al Cementerio. Hamster y Ryko resuelven los problemas del rival: Ryko destruye una carta y manda 3 del Deck al Cementerio.","en":"Dark Grepher and Armageddon Knight send DARK monsters to the Graveyard. Hamster and Ryko handle the opponent's problem cards: Ryko destroys a card and mills 3."},{"es":"Blackwing Armor Master (2500 de ATK) no se destruye en batalla y no te hace recibir daño de batalla en los ataques que lo involucran. Se invoca con un Sintonizador Blackwing y uno o más no Sintonizadores, y el Sincro que trajo Vayu, aunque tenga los efectos anulados, sirve como uno de esos materiales.","en":"Blackwing Armor Master (2500 ATK) cannot be destroyed by battle and you take no battle damage from attacks involving it. It is Synchro Summoned with a Blackwing Tuner and one or more non-Tuners, and the Synchro that Vayu brought out, even with its effects negated, works as one of those materials."}]},"starters":[{"cards":["Dark Grepher","Blackwing - Sirocco the Dawn"],"route":{"es":"Dark Grepher entra desde la mano descartando a Sirocco (nivel 5 DARK); después su efecto, descartando otro monstruo DARK, manda a Vayu desde el Deck: Sirocco y Vayu quedan en el Cementerio para el Sincro.","en":"Dark Grepher Special Summons from hand by discarding Sirocco (Level 5 DARK); then its effect, discarding another DARK monster, sends Vayu from the Deck: Sirocco and Vayu are in the Graveyard for the Synchro."}},{"cards":["Armageddon Knight"],"route":{"es":"Al invocarlo manda a Vayu desde el Deck al Cementerio. Es la entrada más barata cuando Sirocco ya está en el Cementerio.","en":"When Summoned it sends Vayu from the Deck to the Graveyard. It is the cheapest entry when Sirocco is already in the Graveyard."}},{"cards":["Super-Nimble Mega Hamster"],"route":{"es":"Hamster boca abajo, al darse vuelta, trae a Ryko boca abajo desde el Deck. Ryko destruye una carta y manda 3 al Cementerio (combustible para Vayu).","en":"Hamster set face-down flips to bring Ryko face-down from the Deck. Ryko destroys a card and mills 3 (fuel for Vayu)."}}],"chokepoints":[{"card":"Deck Devastation Virus","step":"resolution","stepText":{"es":"Al resolverse: el rival tributó un DARK de 2000 o más de ATK, mira tu mano y destruye tus monstruos con 1500 o menos de ATK, también los que robes hasta el final de su 3.er turno.","en":"On resolution: the opponent Tributed a DARK monster with 2000+ ATK, looks at your hand and destroys your monsters with 1500 or less ATK, including the ones you draw until the end of their 3rd turn."},"loss":{"es":"Vayu (800), Necro Gardna, Plaguespreader y los Armageddon Knight (1400) caen, en el campo y en la mano. Resisten los monstruos de más de 1500 de ATK y los Sincros, que esperan en el Extra Deck: no comprometas cuerpos chicos mientras dure.","en":"Vayu (800), Necro Gardna, Plaguespreader and the Armageddon Knights (1400) die, on the field and in hand. Monsters with more than 1500 ATK and Synchros, which wait in the Extra Deck, survive: do not commit small bodies while it lasts."}},{"card":"Imperial Iron Wall","step":"resolution","stepText":{"es":"Cuando Vayu intenta desterrarse a sí mismo y a un Blackwing para traer el Sincro.","en":"When Vayu tries to banish itself and a Blackwing to bring out the Synchro."},"loss":{"es":"Con el Muro puesto nadie puede desterrar, así que el efecto de Vayu no invoca nada. Sacalo con MST o Dust Tornado antes de activar a Vayu.","en":"With the Wall out nobody can banish, so Vayu's effect summons nothing. Remove it with MST or Dust Tornado before activating Vayu."}},{"card":"Royal Decree","step":"activation","stepText":{"es":"Boca arriba, cuando activás tus propias Trampas (Bottomless, Prison, Virus, Mirror Force).","en":"Face-up, when you activate your own Traps (Bottomless, Prison, Virus, Mirror Force)."},"loss":{"es":"Anula los efectos de todas las demás Trampas del campo: el mazo juega muchas y pierde su interacción. Sacala con Mystical Space Typhoon: Dust Tornado no sirve, porque es una Trampa y su efecto queda anulado.","en":"Negates the effects of every other Trap on the field: the deck plays many and loses its interaction. Remove it with Mystical Space Typhoon: Dust Tornado does not work, because it is a Trap and its effect is negated."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de que Grepher o Knight manden a Vayu al Cementerio.","en":"Face-up before Grepher or Knight send Vayu to the Graveyard."},"loss":{"es":"Todo monstruo que iría al Cementerio se destierra: Vayu y Sirocco no llegan y el motor entero se apaga. Sacala del campo antes de armar la jugada.","en":"Every monster that would go to the Graveyard is banished: Vayu and Sirocco never arrive and the whole engine shuts off. Remove it before starting the play."}}],"side":{"first":{"in":[{"card":"Dust Tornado","qty":2,"why":{"es":"Saca Imperial Iron Wall, Dimensional Fissure y otras cartas que cortan el motor, y te deja volver a setear una Magia o Trampa. No sirve contra Royal Decree: es una Trampa y queda anulada.","en":"Removes Imperial Iron Wall, Dimensional Fissure and other cards that cut the engine, and lets you set another Spell or Trap. It does not work against Royal Decree: it is a Trap and gets negated."}}],"out":[{"card":"Card Trooper","qty":1,"why":{"es":"Manda de 1 a 3 cartas de arriba del Deck sin que elijas cuáles: no asegura que Vayu llegue al Cementerio.","en":"Sends 1 to 3 cards from the top of the Deck without choosing which: it does not make sure Vayu reaches the Graveyard."}},{"card":"Trap Dustshoot","qty":1,"why":{"es":"Seteada no avanza el motor: recién actúa en el turno del rival, y yendo primero lo que querés es armar el Cementerio.","en":"Set, it does not advance the engine: it only acts on the opponent's turn, and going first what you want is to build the Graveyard."}}]},"second":{"in":[{"card":"Royal Oppression","qty":2,"why":{"es":"Cualquiera de los dos puede pagar 800 LP para anular una invocación especial y destruir ese monstruo: te sirve contra el rival, pero él también puede anular las tuyas.","en":"Either player can pay 800 LP to negate a Special Summon and destroy that monster: it works against the opponent, but they can also negate yours."}}],"out":[{"card":"Plaguespreader Zombie","qty":1,"why":{"es":"Cuerpo flojo cuando necesitás presionar el tablero del rival.","en":"A weak body when you need to pressure the opponent's board."}},{"card":"Chaos Sorcerer","qty":1,"why":{"es":"Pide DARK y LIGHT en el Cementerio para desterrar, y compite con tu propio uso del Cementerio.","en":"Needs DARK and LIGHT in the Graveyard to banish, and competes with your own Graveyard usage."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Blackwing - Vayu the Emblem of Honor","url":"https://yugipedia.com/wiki/Blackwing_-_Vayu_the_Emblem_of_Honor","kind":"cards","checked":"2026-10-27"},{"name":"Dark Grepher","url":"https://yugipedia.com/wiki/Dark_Grepher","kind":"cards","checked":"2026-10-27"},{"name":"Edison Format's Top 10 Decks to Look Out For","url":"https://ygoprodeck.com/article/edison-format-s-top-10-decks-to-look-out-for-302221","kind":"guide","checked":"2026-10-27"},{"name":"What is Edison Format? Rules, best decks, and tips","url":"https://ultimateguard.com/en/blog/edison-format-yu-gi-oh-rules-best-decks-tips","kind":"guide","checked":"2026-10-27"},{"name":"Edison Format Deck Introduction : Blackwings","url":"https://ygoprodeck.com/article/edison-format-deck-introduction-blackwings-94007","kind":"guide","checked":"2026-10-27"},{"name":"March 2010 Lists (TCG)","url":"https://yugipedia.com/wiki/March_2010_Lists_(TCG)","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Yugipedia muestra el texto actual de las cartas, que en algunos casos difiere del de 2010: leé los rulings de la época antes de copiar una secuencia.","en":"Yugipedia shows the current card text, which in some cases differs from the 2010 wording: read the period rulings before copying a sequence."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes lista un Side Deck para este mazo.","en":"The Side Deck is editorial judgment: none of the sources lists a Side Deck for this deck."}]},"edison/lightsworn":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Gana a base de milling: manda cartas al Cementerio para juntar 4 Lightsworn de nombre distinto y tirar a Judgment Dragon (3000 de ATK) directo desde la mano.","en":"Wins through milling: send cards to the Graveyard to collect 4 differently named Lightsworn and drop Judgment Dragon (3000 ATK) straight from the hand."},{"es":"Judgment Dragon paga 1000 LP para destruir todas las demás cartas del campo: barre el tablero y vos te quedás con el único monstruo.","en":"Judgment Dragon pays 1000 LP to destroy every other card on the field: it wipes the board and leaves you with the only monster."},{"es":"Lyla, Ryko y Celestia sacan cartas del campo rival mientras llenan el Cementerio. Wulf se invoca solo si lo mandás del Deck al Cementerio, y Lumina revive Lightsworn de nivel 4 o menos.","en":"Lyla, Ryko and Celestia remove opposing cards while filling the Graveyard. Wulf Special Summons itself if sent from the Deck to the Graveyard, and Lumina revives Level 4 or lower Lightsworn."},{"es":"El riesgo propio es el Deck: varios Lightsworn mandan cartas al Cementerio cada End Phase y podés quedarte sin cartas antes de cerrar.","en":"The deck's own risk is decking out: several Lightsworn mill cards every End Phase and you can run out of cards before closing."}]},"starters":[{"cards":["Charge of the Light Brigade"],"route":{"es":"Manda 3 al Cementerio y agrega un Lightsworn de nivel 4 o menos: llena el Cementerio y arma la mano con una sola carta.","en":"Sends 3 to the Graveyard and adds a Level 4 or lower Lightsworn: fills the Graveyard and builds the hand with one card."}},{"cards":["Solar Recharge","Ryko, Lightsworn Hunter"],"route":{"es":"Descartás a Ryko (u otro Lightsworn), robás 2 y mandás 2 más al Cementerio. Gasta mano pero aporta Lightsworn distintos para Judgment Dragon.","en":"Discard Ryko (or another Lightsworn), draw 2 and send 2 more to the Graveyard. Costs hand but adds distinct Lightsworn for Judgment Dragon."}},{"cards":["Lumina, Lightsworn Summoner"],"route":{"es":"Descartando 1 carta revive un Lightsworn de nivel 4 o menos, y manda 3 al Cementerio en cada End Phase: motor de recursos y de Cementerio a la vez.","en":"Discarding 1 card revives a Level 4 or lower Lightsworn, and it mills 3 each End Phase: resource and Graveyard engine at once."}}],"chokepoints":[{"card":"Royal Oppression","step":"summon","stepText":{"es":"En la invocación especial de Judgment Dragon, de Wulf o de un Lightsworn revivido por Lumina.","en":"On the Special Summon of Judgment Dragon, Wulf or a Lightsworn revived by Lumina."},"loss":{"es":"El rival paga 800 LP, anula la invocación y la destruye. Duele sobre todo contra Judgment Dragon. Guardá Mystical Space Typhoon o Heavy Storm para sacarla antes.","en":"The opponent pays 800 LP, negates the Summon and destroys it. It hurts most against Judgment Dragon. Keep Mystical Space Typhoon or Heavy Storm to remove it first."}},{"card":"Macro Cosmos","step":"main","stepText":{"es":"Mientras esté boca arriba: todo lo que iría al Cementerio se destierra.","en":"While face-up: everything that would go to the Graveyard is banished instead."},"loss":{"es":"El milling deja de llenar el Cementerio y Judgment Dragon nunca llega a los 4 Lightsworn. Hay que sacarla del campo.","en":"Milling no longer fills the Graveyard and Judgment Dragon never reaches 4 Lightsworn. It has to be removed from the field."}},{"card":"Vanity's Fiend","step":"main","stepText":{"es":"Durante la Main Phase, una vez que está en el campo.","en":"During the Main Phase, once it is on the field."},"loss":{"es":"Ninguno de los dos puede invocar de forma especial: Judgment, Wulf y Lumina quedan bloqueados. Destruilo con Ryko (su Flip no es una invocación especial) o con Celestia, o ponelo boca abajo con Book of Moon.","en":"Neither player can Special Summon: Judgment, Wulf and Lumina are locked out. Destroy it with Ryko (its Flip is not a Special Summon) or Celestia, or flip it face-down with Book of Moon."}},{"card":"Light-Imprisoning Mirror","step":"activation","stepText":{"es":"Cuando activás el efecto de un Lightsworn, que son monstruos LIGHT.","en":"When you activate a Lightsworn effect, since they are LIGHT monsters."},"loss":{"es":"Anula los efectos activados de monstruos LIGHT en el campo y en el Cementerio. Lyla, Ryko, Celestia, Lumina y el revive de Wulf quedan inertes. Sacala con Mystical Space Typhoon o Heavy Storm.","en":"Negates activated LIGHT monster effects on the field and in the Graveyard. Lyla, Ryko, Celestia, Lumina and Wulf's revival go dead. Remove it with Mystical Space Typhoon or Heavy Storm."}}],"side":{"first":{"in":[{"card":"My Body as a Shield","qty":1,"why":{"es":"Protege a un Lightsworn de Torrential Tribute o de Smashing Ground: niega cartas que destruyen monstruos. Cuesta 1500 LP.","en":"Protects a Lightsworn from Torrential Tribute or Smashing Ground: it negates cards that destroy monsters. Costs 1500 LP."}},{"card":"Book of Moon","qty":1,"why":{"es":"Pone boca abajo a un monstruo rival boca arriba (una amenaza grande o Vanity's Fiend) con una sola carta.","en":"Flips a face-up opposing monster face-down (a big threat or Vanity's Fiend) with a single card."}}],"out":[{"card":"Card Trooper","qty":1,"why":{"es":"Con 400 de ATK pierde contra los beatsticks Blackwing cuando vas primero.","en":"With 400 ATK it loses to Blackwing beatsticks when you go first."}},{"card":"Plaguespreader Zombie","qty":1,"why":{"es":"Mano floja en un duelo que depende de la presión.","en":"A weak draw in a duel that comes down to pressure."}}]},"second":{"in":[{"card":"My Body as a Shield","qty":1,"why":{"es":"Protege a tu cuerpo principal de las cartas que destruyen monstruos. Cuesta 1500 LP.","en":"Protects your main body from cards that destroy monsters. Costs 1500 LP."}}],"out":[{"card":"Plaguespreader Zombie","qty":1,"why":{"es":"Cuerpo flojo contra un tablero Blackwing.","en":"A weak body against a Blackwing board."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Judgment Dragon","url":"https://yugipedia.com/wiki/Judgment_Dragon","kind":"cards","checked":"2026-10-27"},{"name":"Charge of the Light Brigade","url":"https://yugipedia.com/wiki/Charge_of_the_Light_Brigade","kind":"cards","checked":"2026-10-27"},{"name":"What Deck to play? - EDISON FORMAT","url":"https://www.edisonformat.com/what-deck-to-play.html","kind":"guide","checked":"2026-10-27"},{"name":"Edison Format's Top 10 Decks to Look Out For","url":"https://ygoprodeck.com/article/edison-format-s-top-10-decks-to-look-out-for-302221","kind":"guide","checked":"2026-10-27"},{"name":"Deck Profile: Patrick Clarey's Dandysworn Deck","url":"https://yugiohblog.konami.com/2010/sjc/10-04-75thsjc/deck-profile-patrick-clareys-dandysworn-deck/","kind":"results","checked":"2026-10-27"},{"name":"March 2010 Lists (TCG)","url":"https://yugipedia.com/wiki/March_2010_Lists_(TCG)","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"El Side Deck es criterio de la redacción: no hay una lista de Side Deck de Lightsworn de torneo enlazada que lo respalde.","en":"The Side Deck is editorial judgment: there is no linked tournament Lightsworn Side Deck list that backs it."},{"es":"Lumina, Charge of the Light Brigade y Judgment Dragon están limitadas o semi-limitadas en la lista de marzo de 2010: revisá cuántas copias entran antes de armar el mazo.","en":"Lumina, Charge of the Light Brigade and Judgment Dragon are limited or semi-limited on the March 2010 list: check how many copies fit before building."},{"es":"Yugipedia muestra el texto actual de las cartas, que en algunos casos difiere del de 2010. Para los rulings y la errata funcional de la época mirá las reglas de edisonformat.com.","en":"Yugipedia shows the current card text, which in some cases differs from the 2010 wording. For period rulings and functional errata, see the rules section of edisonformat.com."}]},"edison/gladiator-beast":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Gladiator Beast pelea y escapa: al final de la Battle Phase vuelven al Deck y traen a otro Gladiador, que dispara su efecto por entrar invocado por un efecto de Gladiator Beast.","en":"Gladiator Beasts fight and escape: at the end of the Battle Phase they shuffle back and bring in another Gladiator, which fires its effect for being Special Summoned by a Gladiator Beast effect."},{"es":"Gyzarus (2400) es la jugada fuerte: fusión de contacto con Bestiari + otro Gladiador, destruye hasta 2 cartas al entrar y, si peleó, vuelve al Extra Deck al final de la Battle Phase e invoca 2 Gladiadores más.","en":"Gyzarus (2400) is the strong play: contact fusion with Bestiari + another Gladiator, destroys up to 2 cards on entering and, if it battled, returns to the Extra Deck at the end of the Battle Phase and Special Summons 2 more Gladiators."},{"es":"Gladiator Beast War Chariot, seteada, anula un efecto de monstruo mientras controles un Gladiador boca arriba. Con Heraklinos (3000, descarta 1 para anular una Magia/Trampa) el mazo juega de control.","en":"Gladiator Beast War Chariot, set, negates a monster effect while you control a face-up Gladiator. With Heraklinos (3000, discard 1 to negate a Spell/Trap) the deck plays as control."},{"es":"Con Prisma y Test Tiger la versión combo gana tempo y va más rápido; la versión base con Bestiari es más lenta y se apoya en las Trampas.","en":"With Prisma and Test Tiger the combo version gains tempo and goes faster; the base version with Bestiari is slower and leans on Traps."}]},"starters":[{"cards":["Gladiator Beast Bestiari","Test Tiger"],"route":{"es":"Bestiari por invocación normal habilita a Test Tiger desde la mano. Tributá a Test Tiger apuntando a Bestiari: lo barajás y traés otro Gladiador del Deck como si entrara por efecto (Murmillo destruye un monstruo). Test Tiger no es un «Gladiator Beast», así que no sirve de material de Gyzarus.","en":"Bestiari by Normal Summon lets Test Tiger in from the hand. Tribute Test Tiger targeting Bestiari: you shuffle it and bring out another Gladiator from the Deck as if by effect (Murmillo destroys a monster). Test Tiger is not a \"Gladiator Beast\", so it cannot be Gyzarus material."}},{"cards":["Elemental HERO Prisma","Test Tiger"],"route":{"es":"Prisma muestra a Gyzarus y manda a Bestiari del Deck al Cementerio, tomando su nombre hasta el End Phase. Con ese nombre hace de Bestiari en la fusión de contacto con otro Gladiator Beast: no hace falta un Bestiari real. Test Tiger sale de la mano y cambia a un Gladiador por otro.","en":"Prisma reveals Gyzarus and sends Bestiari from the Deck to the Graveyard, taking its name until the End Phase. With that name it acts as Bestiari in the contact fusion with another Gladiator Beast: no real Bestiari is needed. Test Tiger comes out of the hand and swaps one Gladiator for another."}},{"cards":["Test Tiger"],"route":{"es":"Con un Gladiador boca arriba, Test Tiger sale de la mano. Tributarlo cambia ese Gladiador por otro del Deck (por ejemplo Murmillo, que destruye un monstruo) como si entrara por efecto.","en":"With a face-up Gladiator, Test Tiger comes out of the hand. Tributing it swaps that Gladiator for another from the Deck (for example Murmillo, which destroys a monster) as if effect-summoned."}}],"chokepoints":[{"card":"Royal Oppression","step":"summon","stepText":{"es":"En la invocación especial de Gyzarus, de Heraklinos o de cualquier Gladiador que entra por tag out.","en":"On the Special Summon of Gyzarus, Heraklinos or any Gladiator coming in through a tag out."},"loss":{"es":"El rival paga 800 LP, anula la invocación y la destruye. Los materiales de la fusión ya volvieron al Deck, así que perdés dos cartas por una. Hacé primero la invocación que menos importa.","en":"The opponent pays 800 LP, negates the Summon and destroys it. The fusion materials already returned to the Deck, so you lose two cards for one. Make the least important Summon first."}},{"card":"Fossil Dyna Pachycephalo","step":"resolution","stepText":{"es":"Al resolverse su efecto de Flip.","en":"On resolution of its Flip effect."},"loss":{"es":"Destruye todos los monstruos invocados especialmente y nadie puede invocar de forma especial. Como el tag out es una invocación especial, el mazo no puede reemplazar nada. Book of Moon no sirve antes del Flip: necesita un monstruo boca arriba. Jugá de a una invocación frente a un monstruo boca abajo.","en":"Destroys all Special Summoned monsters and nobody can Special Summon. Since the tag out is a Special Summon, the deck cannot replace anything. Book of Moon does not work before the Flip: it needs a face-up monster. Summon one at a time against a face-down monster."}},{"card":"Vanity's Fiend","step":"main","stepText":{"es":"Mientras esté en el campo, durante tu Main Phase.","en":"While it is on the field, during your Main Phase."},"loss":{"es":"Bloquea toda invocación especial: sin tag out ni fusión de contacto el mazo queda con cuerpos de ATK bajo. Sacalo con Smashing Ground o Compulsory Evacuation Device.","en":"Blocks every Special Summon: with no tag out and no contact fusion the deck is left with low ATK bodies. Remove it with Smashing Ground or Compulsory Evacuation Device."}},{"card":"Solemn Judgment","step":"summon","stepText":{"es":"En la invocación de la fusión de contacto o al activar tu Trampa seteada.","en":"On the contact fusion Summon or when you activate your set Trap."},"loss":{"es":"Anula y destruye la invocación pagando la mitad de los LP. Una Gyzarus anulada son dos Gladiadores fuera del campo. Si lo tienen seteado, hacé que lo gasten primero en una invocación o una Trampa que importe menos.","en":"Negates and destroys the Summon for half the LP. A negated Gyzarus costs two Gladiators off the field. If they have it set, make them spend it first on a Summon or Trap that matters less."}}],"side":{"first":{"in":[{"card":"Starlight Road","qty":1,"why":{"es":"Si un efecto va a destruir 2 o más cartas tuyas (Heavy Storm, Torrential Tribute), lo anula y trae a un Stardust Dragon.","en":"If an effect would destroy 2 or more of your cards (Heavy Storm, Torrential Tribute), it negates it and brings out a Stardust Dragon."}}],"out":[{"card":"Rescue Cat","qty":1,"why":{"es":"Más lenta que el arranque propio del mazo cuando vas primero.","en":"Slower than the deck's own opening when going first."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":1,"why":{"es":"Saca la Trampa seteada que frena tu avance (Royal Decree, Solemn Judgment) cuando tenés que forzar el ritmo.","en":"Removes the set Trap that stalls your advance (Royal Decree, Solemn Judgment) when you must force the pace."}}],"out":[{"card":"Cold Wave","qty":1,"why":{"es":"Cuando vas segundo necesitás tus propias Magias y Trampas activas.","en":"When going second you need your own Spells and Traps active."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Gladiator Beast Gyzarus","url":"https://yugipedia.com/wiki/Gladiator_Beast_Gyzarus","kind":"cards","checked":"2026-10-27"},{"name":"Test Tiger","url":"https://yugipedia.com/wiki/Test_Tiger","kind":"cards","checked":"2026-10-27"},{"name":"Edison Format's Top 10 Decks to Look Out For","url":"https://ygoprodeck.com/article/edison-format-s-top-10-decks-to-look-out-for-302221","kind":"guide","checked":"2026-10-27"},{"name":"What Deck to play? - EDISON FORMAT","url":"https://www.edisonformat.com/what-deck-to-play.html","kind":"guide","checked":"2026-10-27"},{"name":"March 2010 Lists (TCG)","url":"https://yugipedia.com/wiki/March_2010_Lists_(TCG)","kind":"list","checked":"2026-10-27"},{"name":"Deck Profile: The Djuiricin Brothers' Froggy Monarch Decks","url":"https://yugiohblog.konami.com/2010/sjc/10-04-75thsjc/deck-profile-the-djuiricin-brothers-froggy-monarch-decks/","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Gyzarus y Test Tiger están leídos con el texto actual de Yugipedia. En 2010 «tag out» se resolvía distinto en algunos casos (ver la errata funcional en edisonformat.com), así que verificá las secuencias antes de copiarlas.","en":"Gyzarus and Test Tiger are read from the current Yugipedia text. In 2010 the tag out resolved differently in some cases (see the functional errata on edisonformat.com), so check the sequences before copying them."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes lista un Side Deck para este mazo.","en":"The Side Deck is editorial judgment: none of the sources lists a Side Deck for this deck."}]},"edison/frog-monarch":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Juego lento y consistente: Substitoad trae Frogs que no se destruyen en batalla, y Treeborn Frog vuelve del Cementerio cada Standby Phase si no controlás Magias ni Trampas.","en":"Slow, consistent play: Substitoad brings Frogs that cannot be destroyed by battle, and Treeborn Frog returns from the Graveyard each Standby Phase if you control no Spells or Traps."},{"es":"Los Frogs son el sacrificio: dos cuerpos baratos pagan el Tribute de Caius (destierra y pega 1000 si es DARK) y de Raiza (devuelve una carta a la cima del Deck).","en":"The Frogs are the sacrifice: two cheap bodies pay the Tribute for Caius (banish and 1000 damage if DARK) and Raiza (places a card on top of the Deck)."},{"es":"Dupe Frog repone la mano: al irse al Cementerio trae otro Frog, y Pot of Avarice y Salvage reciclan Frogs para seguir.","en":"Dupe Frog refills the hand: when it goes to the Graveyard it adds another Frog, and Pot of Avarice and Salvage recycle Frogs to keep going."}]},"starters":[{"cards":["Substitoad","Treeborn Frog"],"route":{"es":"Tributás a Treeborn con Substitoad para traer a Swap Frog del Deck. Treeborn vuelve en tu Standby Phase si no controlás Magias ni Trampas.","en":"Tribute Treeborn with Substitoad to bring Swap Frog from the Deck. Treeborn comes back on your Standby Phase if you control no Spells or Traps."}},{"cards":["Substitoad","Dupe Frog"],"route":{"es":"Tributás a Dupe Frog: Substitoad invoca otro Frog y Dupe, al ir al Cementerio, trae un Frog más a la mano.","en":"Tribute Dupe Frog: Substitoad Special Summons another Frog and Dupe, going to the Graveyard, adds one more Frog to hand."}},{"cards":["Substitoad","Caius the Shadow Monarch"],"route":{"es":"Substitoad arma dos cuerpos Frog para el doble Tribute de Caius, que destierra una carta rival y pega 1000 si es DARK.","en":"Substitoad makes two Frog bodies for Caius's double Tribute, which banishes an opposing card and deals 1000 if it is DARK."}}],"chokepoints":[{"card":"Fossil Dyna Pachycephalo","step":"resolution","stepText":{"es":"Al resolverse su Flip.","en":"On resolution of its Flip."},"loss":{"es":"Destruye los monstruos invocados especialmente y evita nuevas invocaciones: frena a Substitoad, Treeborn y Swap Frog. La remoción de Magias/Trampas no sirve. Book of Moon tampoco (necesita un monstruo boca arriba): solo Raiza, que apunta a una carta boca abajo, lo saca antes del Flip.","en":"Destroys Special Summoned monsters and prevents new Summons: it stops Substitoad, Treeborn and Swap Frog. Spell/Trap removal does not help. Neither does Book of Moon (it needs a face-up monster): only Raiza, which targets a face-down card, removes it before the Flip."}},{"card":"Vanity's Fiend","step":"main","stepText":{"es":"Mientras esté en el campo, durante tu Main Phase.","en":"While it is on the field, during your Main Phase."},"loss":{"es":"Nadie puede invocar de forma especial: Substitoad no trae nada y Treeborn no vuelve. Respondé con Raiza o Caius tributando un Frog normal, o con Soul Exchange.","en":"Nobody can Special Summon: Substitoad brings nothing and Treeborn does not return. Answer with Raiza or Caius Tributing a normal Frog, or with Soul Exchange."}},{"card":"Dimensional Fissure","step":"activation","stepText":{"es":"Cuando tributás con Substitoad: el Frog tributado se destierra.","en":"When you Tribute with Substitoad: the Tributed Frog is banished."},"loss":{"es":"Treeborn y Dupe Frog no llegan al Cementerio, así que no vuelven ni traen otro Frog. Pot of Avarice y Salvage quedan sin objetivo. Sacala con MST.","en":"Treeborn and Dupe Frog do not reach the Graveyard, so they neither return nor fetch another Frog. Pot of Avarice and Salvage have no targets. Remove it with MST."}},{"card":"Mask of Restrict","step":"activation","stepText":{"es":"Cuando querés tributar con Substitoad o para un Monarca.","en":"When you want to Tribute with Substitoad or for a Monarch."},"loss":{"es":"Nadie puede tributar: Substitoad, Caius y Raiza quedan apagados. Destruila con Heavy Storm o MST.","en":"Nobody can Tribute: Substitoad, Caius and Raiza are shut off. Destroy it with Heavy Storm or MST."}}],"side":{"first":{"in":[{"card":"D.D. Crow","qty":2,"why":{"es":"Quick Effect que desterra una carta del Cementerio rival (Vayu, Lightsworn) sin pagar con tu mano fuerte.","en":"A Quick Effect that banishes a card from the opposing Graveyard (Vayu, Lightsworn) without spending a key card."}}],"out":[{"card":"Phoenix Wing Wind Blast","qty":2,"why":{"es":"Setear Trampas rompe a Treeborn, que pide no controlar Magias ni Trampas.","en":"Setting Traps breaks Treeborn, which needs you to control no Spells or Traps."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":1,"why":{"es":"Saca la Trampa o el Fissure que apaga tu ciclo de Frogs.","en":"Removes the Trap or Fissure that shuts off your Frog loop."}},{"card":"Lightning Vortex","qty":1,"why":{"es":"Descartás 1 carta y destruís todos los monstruos rivales boca arriba. Los Frogs resisten batalla, no efectos, así que barrés un tablero más rápido que el tuyo.","en":"Discard 1 card to destroy all face-up opposing monsters. Frogs resist battle, not effects, so you sweep a board faster than yours."}}],"out":[{"card":"Phoenix Wing Wind Blast","qty":1,"why":{"es":"Lenta y con costo de mano cuando el rival ya te lleva ventaja.","en":"Slow and card-costly when the opponent is already ahead."}},{"card":"Spiritual Water Art - Aoi","qty":1,"why":{"es":"Pide tributar un WATER y, seteada, rompe a Treeborn.","en":"Needs a WATER Tribute and, set, breaks Treeborn."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Substitoad","url":"https://yugipedia.com/wiki/Substitoad","kind":"cards","checked":"2026-10-27"},{"name":"Treeborn Frog","url":"https://yugipedia.com/wiki/Treeborn_Frog","kind":"cards","checked":"2026-10-27"},{"name":"Edison Format's Top 10 Decks to Look Out For","url":"https://ygoprodeck.com/article/edison-format-s-top-10-decks-to-look-out-for-302221","kind":"guide","checked":"2026-10-27"},{"name":"March 2010 Lists (TCG)","url":"https://yugipedia.com/wiki/March_2010_Lists_(TCG)","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Substitoad no figura en la lista de marzo de 2010, por eso entra hasta 3 copias. Hoy está Limitada, y el artículo de YGOPRODeck enlazado, de una época posterior, la da por Prohibida: no la busques en una lista actual.","en":"Substitoad is not on the March 2010 list, which is why up to 3 copies are legal. Today it is Limited, and the linked YGOPRODeck article, written in a later period, calls it Forbidden: do not look for it on a current list."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes lista un Side Deck para este mazo.","en":"The Side Deck is editorial judgment: none of the sources lists a Side Deck for this deck."}]},"gen/blitzclique":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Juega desde la mano: Surge, Grain y Crackle se revelan para destruir una carta e invocar de Especial un Trueno de la mano, y Emi lo hace al ser agregado a la mano sin robarlo. No gasta la Invocación Normal.","en":"Plays from hand: Surge, Grain and Crackle are revealed to destroy a card and Special Summon a Thunder from hand, and Emi does the same when added to hand by a non-draw effect. It does not use the Normal Summon."},{"es":"Cada destrucción por efecto activa a los monstruos que ya están en el campo: Surge busca otro Blitzclique, Grain una Magia o Hideout, Emi una Trampa. Steppleader, Breakaway, Overvolt y Hideout vuelven a la mano desde el Cementerio si un efecto Blitzclique destruyó algo.","en":"Every effect destruction activates monsters already on the field: Surge searches another Blitzclique, Grain a Spell or Hideout, Emi a Trap. Steppleader, Breakaway, Overvolt and Hideout return to hand from the GY if a Blitzclique effect destroyed something."},{"es":"Cierra con Whisker Blitzclique (hasta 3 Truenos de la mano y destruye hasta 3 cartas) y se protege con Return Stroke y Alternator. Después de cada efecto solo se invoca de Especial desde la mano, así que el Extra Deck casi no se usa.","en":"It finishes with Whisker Blitzclique (up to 3 Thunders from hand, destroys up to 3 cards) and protects itself with Return Stroke and Alternator. After each effect you can only Special Summon from the hand, so the Extra Deck barely matters."},{"es":"Genesys no permite monstruos Link, así que Link Apple nunca encuentra un Link: se revela, destierra al azar una carta boca abajo del Extra Deck y, como esa carta no es un Link, se descarta para robar 1.","en":"Genesys does not allow Link monsters, so Link Apple never finds a Link: it is revealed, banishes a random face-down Extra Deck card and, since that card is not a Link, discards itself to draw 1."}]},"starters":[{"cards":["Hideout in the Sky, Coulomb","Surge Blitzclique"],"route":{"es":"Coulomb pone un Mech Beast Token en el campo rival y busca un Blitzclique. Surge se revela, destruye ese Token, invoca un Trueno de la mano y busca otro Blitzclique.","en":"Coulomb puts a Mech Beast Token on the opponent's field and searches a Blitzclique. Surge is revealed, destroys that Token, Special Summons a Thunder from hand and searches another Blitzclique."}},{"cards":["Blitzclique - Steppleader","Surge Blitzclique"],"route":{"es":"Steppleader invoca de Especial a Surge desde la mano y se destruye: esa destrucción activa el efecto de Surge, que busca un monstruo Blitzclique.","en":"Steppleader Special Summons Surge from hand and destroys itself: that destruction activates Surge, which searches a Blitzclique monster."}},{"cards":["Crackle Blitzclique"],"route":{"es":"En el turno rival, cuando activan un efecto de monstruo en el campo, Crackle se revela, destruye ese monstruo e invoca un Trueno de la mano: la cadena arranca en su turno.","en":"On the opponent's turn, when they activate a monster effect on the field, Crackle is revealed, destroys that monster and Special Summons a Thunder from hand: the chain starts on their turn."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa la búsqueda de Surge, Grain o Emi, o el Token de Hideout que busca un Blitzclique.","en":"When a Surge, Grain or Emi search, or Hideout's Token plus search, is activated."},"loss":{"es":"Niega ese efecto entero: sin búsqueda ni Token no hay siguiente eslabón. Abrí con Steppleader u Overvolt, que no buscan del Deck, para que Ash caiga en una jugada menor.","en":"It negates that whole effect: no search or Token means no next link. Open with Steppleader or Overvolt, which do not search the Deck, so Ash lands on a minor play."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta invocación del turno, por ejemplo cuando Whisker pone 3 Truenos de la mano.","en":"On the fifth summon of the turn, for example when Whisker puts out 3 Thunders from hand."},"loss":{"es":"Tributa todos los monstruos boca arriba del campo (también los tuyos) y deja un Token enorme en tu lado. Contá las invocaciones y frená antes de la quinta si te quedan recursos para el turno siguiente.","en":"It Tributes every face-up monster on the field (yours too) and leaves a huge Token on your side. Count your summons and stop before the fifth if you still have resources for next turn."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno, cuando se agrega una carta a tu mano desde el Deck.","en":"After the first search of the turn, when a card is added to your hand from the Deck."},"loss":{"es":"Ninguna otra búsqueda ese turno, y buena parte de la cadena depende de búsquedas. Hacé primero la destrucción que no busca y guardá la búsqueda importante para después.","en":"No other search that turn, and a good part of the chain depends on searches. Make the destruction that does not search first and save the important search for later."}},{"card":"Runick Slumber","step":"resolution","stepText":{"es":"En cadena sobre el monstruo que vas a destruir con Surge o Breakaway.","en":"In chain on the monster you are about to destroy with Surge or Breakaway."},"loss":{"es":"Esa vez no se destruye, falla el 'si lo hacés' y no hay Trueno ni efectos que se activen por la destrucción. Apuntá a una Magia o Trampa con Grain u Overvolt: Runick Slumber solo protege monstruos.","en":"That time it is not destroyed, the 'if you do' fails and there is no Thunder or destruction-triggered effect. Aim at a Spell or Trap with Grain or Overvolt: Runick Slumber only protects monsters."}},{"card":"The Eye of Truth","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase 1, con tu mano revelada.","en":"Face-up before your Main Phase 1, with your hand revealed."},"loss":{"es":"Te obliga a mantener la mano revelada: el rival ve qué Blitzclique y qué Truenos tenés y juega alrededor de lo que vas a revelar. Sacala con Typhoon, MST o Double Cyclone.","en":"It forces you to keep your hand revealed: the opponent sees which Blitzclique and Thunders you hold and plays around what you are about to reveal. Remove it with Typhoon, MST or Double Cyclone."}}],"side":{"first":{"in":[{"card":"Debunk","qty":2,"why":{"es":"Niega y destierra un efecto de monstruo activado en la mano o el Cementerio (Ash, Nibiru, Shifter), lo que te interrumpe yendo primero. También frena los tuyos (Surge, Grain, Crackle): jugala con cuidado.","en":"Negates and banishes a monster effect activated in the hand or GY (Ash, Nibiru, Shifter), which is what interrupts you going first. It also stops yours (Surge, Grain, Crackle): play it with care."}}],"out":[{"card":"Skull Meister","qty":2,"why":{"es":"Solo niega efectos activados en el Cementerio rival; Debunk cubre eso y también la mano.","en":"It only negates effects activated in the opponent's GY; Debunk covers that and the hand too."}}]},"second":{"in":[{"card":"Veidos the Eruption Dragon of Extinction","qty":2,"why":{"es":"Se juega desde la mano al campo rival sobre una carta en una Zona de Campo y la destruye; si va de su campo a tu Cementerio, destruye todos los monstruos del campo.","en":"It goes from hand to their field against a card in a Field Zone and destroys it; if it goes from their field to your GY, it destroys all monsters on the field."}}],"out":[{"card":"Link Apple","qty":2,"why":{"es":"En Genesys no hay Links, así que Link Apple siempre termina descartándose para robar 1; contra un tablero armado conviene una respuesta.","en":"In Genesys there are no Links, so Link Apple always ends up discarding itself to draw 1; against an established board an answer is better."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Surge Blitzclique","url":"https://yugipedia.com/wiki/Surge_Blitzclique","kind":"cards","checked":"2026-10-27"},{"name":"Link Apple","url":"https://yugipedia.com/wiki/Link_Apple","kind":"cards","checked":"2026-10-27"},{"name":"Ride The Lightning with \"Blitzclique\" [CORI]","url":"https://ygorganization.com/youvebeenthunderstruck/","kind":"guide","checked":"2026-10-27"},{"name":"Springfield Genesys Regional - Yu-Gi-Oh! Tournament","url":"https://ygoprodeck.com/tournament/springfield-genesys-regional-5020","kind":"results","checked":"2026-10-27"},{"name":"Genesys 1st Anniversary Update [GENESYS]","url":"https://ygorganization.com/genesys-1st-anniversary-update-genesys","kind":"list","checked":"2026-10-27"},{"name":"Yu-Gi-Oh! GENESYS | Official Website","url":"https://www.yugioh-card.com/en/genesys/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La guía de YGOrganization es de cuando salió el set (CORI) y no analiza puntos de Genesys: respalda las cartas y el plan, no los costos ni el Side.","en":"The YGOrganization guide dates from the set's release (CORI) and does not analyze Genesys points: it backs the cards and the plan, not the costs or the Side Deck."},{"es":"El 5 de octubre de 2026 subieron los puntos de Whisker, Crackle y Hideout, Coulomb: una lista de torneo anterior puede usar otros costos.","en":"On October 5, 2026 the points of Whisker, Crackle and Hideout, Coulomb went up: an earlier tournament list may use different costs."},{"es":"El Side Deck es criterio de la redacción: no hay una estadística de torneos que lo respalde.","en":"The Side Deck is editorial judgment: no tournament statistic backs it."}]},"gen/sacred-beast":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Arma los tres Sacred Beast de nivel 10 (Raviel, Hamon, Uria) con efectos de cartas Sacred Beast y sus monstruos y Magias de apoyo, sin pasar por la Invocación Normal.","en":"Builds the three Level 10 Sacred Beasts (Raviel, Hamon, Uria) through Sacred Beast card effects and their support monsters and Spells, without the Normal Summon."},{"es":"Raviel tributa 2 Sacred Beast para destruir todos los monstruos rivales que pueda y gana 1000 de ATK por carta destruida. Hamon inflige 1000 de daño, una vez por turno, si un monstruo va al Cementerio rival.","en":"Raviel Tributes 2 Sacred Beasts to destroy as many opposing monsters as possible and gains 1000 ATK per card destroyed. Hamon deals 1000 damage, once per turn, if a monster is sent to the opponent's GY."},{"es":"Fallen Paradise manda 3 cartas del mismo tipo al Cementerio (hasta tres veces por turno) para invocar un Sacred Beast; Thunderclap y Martyr dan ese combustible. The Chaotic Phantasmal Sacred Beasts (3 monstruos nivel 10) niega monstruos rivales.","en":"Fallen Paradise sends 3 cards of the same type to the GY (up to three times per turn) to Special Summon a Sacred Beast; Thunderclap and Martyr provide the fuel. The Chaotic Phantasmal Sacred Beasts (3 Level 10 monsters) negates opposing monsters."}]},"starters":[{"cards":["Sacred Beasts Released","Sacred Beasts Thunderclap"],"route":{"es":"Released agrega 3 Sacred Beast distintos y descarta 2; Thunderclap se pone 2 veces más y trae Fallen Paradise a la Zona de Campo, y esas 3 Magias son la ofrenda que invoca al Beast.","en":"Released adds 3 different Sacred Beasts and discards 2; Thunderclap places 2 more copies and brings Fallen Paradise to the Field Zone, and those 3 Spells are the cost that summons the Beast."}},{"cards":["Martyr of the Sacred Beasts"],"route":{"es":"Martyr pone un Campo o Continua Sacred Beast del Deck (Fallen Paradise) y, si controlás otro Sacred Beast, invoca 2 Martyr más: 3 monstruos como ofrenda de Fallen Paradise.","en":"Martyr places a Sacred Beast Field or Continuous card from the Deck (Fallen Paradise) and, if you control another Sacred Beast, summons 2 more Martyrs: 3 monsters as Fallen Paradise's offering."}},{"cards":["Summoner of the Sacred Beasts"],"route":{"es":"Summoner se revela, descarta 1 carta e invoca en Defensa un Sacred Beast que no sea de nivel 8 desde la mano, lo que cubre a Raviel, Hamon o Uria.","en":"Summoner is revealed, discards 1 card and Special Summons a non-Level 8 Sacred Beast from hand in Defense Position, which covers Raviel, Hamon or Uria."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa Released o el efecto de revelar de Raviel, Hamon o Uria que agrega una carta del Deck.","en":"When Released or the reveal effect of Raviel, Hamon or Uria that adds a card from the Deck is activated."},"loss":{"es":"Niega esa búsqueda (y con Released, también el descarte). Tené otra ruta, por ejemplo Martyr o Summoner, para la segunda jugada.","en":"It negates that search (and with Released, the discard too). Keep another route, such as Martyr or Summoner, for the second play."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En el efecto rápido de Raviel, después de pagar los dos Tributos.","en":"On Raviel's Quick Effect, after the two Tributes are paid."},"loss":{"es":"Niega a Raviel hasta el fin del turno y perdés los dos Sacred Beast del costo sin destruir nada. Esperá a que el rival gaste la Trampa antes de comprometer a Raviel.","en":"It negates Raviel until end of turn and you lose the two Sacred Beasts paid as cost without destroying anything. Wait for them to spend the Trap before committing Raviel."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de una búsqueda, cuando una carta se agrega a tu mano desde el Deck.","en":"After a search, when a card is added to your hand from the Deck."},"loss":{"es":"Corta las demás búsquedas del turno y el mazo depende de varias: Released, las revelaciones de los nivel 10. Hacé primero la búsqueda de menos valor.","en":"It cuts other searches that turn and the deck relies on several: Released, the Level 10 reveals. Make the lowest value search first."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta invocación del turno; Martyr invoca 2 más y Fallen Paradise otra.","en":"On the fifth summon of the turn; Martyr summons 2 more and Fallen Paradise another."},"loss":{"es":"Tributa todos los monstruos boca arriba del campo y deja un Token con el ATK sumado de los tributados. Con Martyrs y Fallen Paradise llegás rápido al quinto monstruo: contá antes de invocar el último.","en":"It Tributes every face-up monster on the field and leaves a Token with their combined ATK. With Martyrs and Fallen Paradise you reach the fifth monster fast: count before summoning the last."}},{"card":"Dimension Shifter","step":"activation","stepText":{"es":"En tu turno, con el Cementerio rival vacío: lo que va al Cementerio se destierra.","en":"On your turn, with their GY empty: anything sent to the GY is banished."},"loss":{"es":"Thunderclap vuelve a la mano desde el Cementerio, y Martyr y Summoner actúan desde allí; con el Shifter eso no pasa. Planificá la jugada sin contar con lo que va al Cementerio.","en":"Thunderclap returns to hand from the GY, and Martyr and Summoner act from there; with Shifter that does not happen. Plan the turn without counting on what goes to the GY."}}],"side":{"first":{"in":[{"card":"Cosmic Cyclone","qty":2,"why":{"es":"Destierra una Magia o Trampa rival (Macro Cosmos, The Eye of Truth) por 1000 LP.","en":"Banishes an opposing Spell or Trap (Macro Cosmos, The Eye of Truth) for 1000 LP."}}],"out":[{"card":"Pot of Sloth","qty":2,"why":{"es":"Roba según las cartas del rival: en el primer turno no controla ninguna.","en":"It draws based on the opponent's cards: on turn one they control none."}}]},"second":{"in":[{"card":"Lava Golem","qty":2,"why":{"es":"Se juega al campo rival tributando 2 monstruos suyos: si Hamon está en el campo, esos monstruos van al Cementerio rival e infligen 1000 (una vez por turno). Te cuesta 1000 LP en cada Standby Phase.","en":"It goes to their field Tributing 2 of their monsters: if Hamon is on the field, those monsters go to the opponent's GY and deal 1000 (once per turn). It costs you 1000 LP each Standby Phase."}}],"out":[{"card":"Light and Darkness Ritual","qty":1,"why":{"es":"Solo sirve para Invocar por Ritual a Black Chaos o a Soldier of Light and Darkness: rinde poco cuando hay que romper tablero.","en":"It only Ritual Summons Black Chaos or Soldier of Light and Darkness: it adds little when you need to break a board."}},{"card":"Nightmare Hands","qty":1,"why":{"es":"Manda un Illusion al Cementerio y revive un monstruo del Cementerio rival si controlás un Illusion de nivel 5 o más: queda fuera del plan Sacred Beast.","en":"It sends an Illusion to the GY and revives a monster from the opponent's GY if you control a Level 5 or higher Illusion: it sits outside the Sacred Beast plan."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Fallen Paradise of the Sacred Beasts","url":"https://yugipedia.com/wiki/Fallen_Paradise_of_the_Sacred_Beasts","kind":"cards","checked":"2026-10-27"},{"name":"Infinity of the Sacred Beasts - Raviel, Lord of Phantasms","url":"https://yugipedia.com/wiki/Infinity_of_the_Sacred_Beasts_-_Raviel,_Lord_of_Phantasms","kind":"cards","checked":"2026-10-27"},{"name":"Sacred Beasts Released","url":"https://yugipedia.com/wiki/Sacred_Beasts_Released","kind":"cards","checked":"2026-10-27"},{"name":"Springfield Genesys Regional - Yu-Gi-Oh! Tournament","url":"https://ygoprodeck.com/tournament/springfield-genesys-regional-5020","kind":"results","checked":"2026-10-27"},{"name":"Genesys 1st Anniversary Update [GENESYS]","url":"https://ygorganization.com/genesys-1st-anniversary-update-genesys","kind":"list","checked":"2026-10-27"},{"name":"Yu-Gi-Oh! GENESYS | Official Website","url":"https://www.yugioh-card.com/en/genesys/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Para este mazo no hay una guía de Genesys enlazada: el plan sale de los textos de las cartas y de los resultados del Springfield Genesys Regional.","en":"There is no Genesys guide linked for this deck: the plan comes from the card texts and the Springfield Genesys Regional results."},{"es":"El 5 de octubre de 2026 Raviel y Hamon subieron de 2 a 11 puntos, Released pasó de 0 a 33, The Chaotic Phantasmal Sacred Beasts de 0 a 21 y Thunderclap bajó de 3 a 0: los resultados anteriores usan otros costos.","en":"On October 5, 2026 Raviel and Hamon went from 2 to 11 points, Released from 0 to 33, The Chaotic Phantasmal Sacred Beasts from 0 to 21 and Thunderclap dropped from 3 to 0: earlier results use other costs."},{"es":"El Side Deck es criterio de la redacción: no hay una estadística de torneos que lo respalde.","en":"The Side Deck is editorial judgment: no tournament statistic backs it."}]},"gen/chimera":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Gana con ventaja de cartas: Fusiona Chimera the King of Phantom Beasts y Berfomet the Mythical King con Chimera Fusion, y los jefes se recuperan y se reemplazan solos.","en":"Wins on card advantage: Fusion Summons Chimera the King of Phantom Beasts and Berfomet the Mythical King with Chimera Fusion, and the bosses recover and replace themselves."},{"es":"Gazelle y Big-Winged Berfomet se buscan entre sí y a Chimera Fusion al invocarse; al ir al Cementerio como material, Gazelle trae un Illusion y Berfomet revive uno.","en":"Gazelle and Big-Winged Berfomet search each other and Chimera Fusion when summoned; sent to the GY as material, Gazelle adds an Illusion and Berfomet revives one."},{"es":"Chimera, al invocarse por Fusión, manda una carta al azar de la mano rival al Cementerio en la End Phase. Darkuriboh protege a los monstruos Fiend o de Fusión de blancos, destrucción y ataques, y evita que se les nieguen los efectos.","en":"Chimera, when Fusion Summoned, sends a random card from the opponent's hand to the GY in the End Phase. Darkuriboh protects Fiend or Fusion monsters from targeting, destruction and attacks, and stops their effects from being negated."}]},"starters":[{"cards":["Mirror Swordknight"],"route":{"es":"Swordknight, de Invocación Normal, se tributa (efecto rápido) para invocar a Big-Winged Berfomet del Deck, que agrega a Gazelle y a Chimera Fusion.","en":"Swordknight, Normal Summoned, is Tributed (Quick Effect) to Special Summon Big-Winged Berfomet from the Deck, which adds Gazelle and Chimera Fusion."}},{"cards":["Gazelle the King of Mythical Claws","Chimera Fusion"],"route":{"es":"Gazelle agrega un Fiend de nivel 5 o Chimera Fusion; con Fusion en mano se Fusiona usando un Beast o Fiend de la mano o el campo.","en":"Gazelle adds a Level 5 Fiend or Chimera Fusion; with Fusion in hand you Fusion Summon using a Beast or Fiend from hand or field."}},{"cards":["Nightmare Apprentice"],"route":{"es":"Apprentice se invoca de la mano descartando 1 carta y agrega un Illusion del Deck, por ejemplo Mirror Swordknight, para arrancar la ruta.","en":"Apprentice Special Summons itself from hand by discarding 1 card and adds an Illusion from the Deck, for example Mirror Swordknight, to start the route."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno, normalmente la de Swordknight, Berfomet o Gazelle.","en":"After the first search of the turn, normally Swordknight, Berfomet or Gazelle."},"loss":{"es":"El mazo necesita varias búsquedas en el mismo turno, y la guía de Branded Chimera dice que Droll suele frenar esa estrategia. Abrí con lo que ya trae Fusion para no depender de la segunda búsqueda.","en":"The deck needs several searches in one turn, and the Branded Chimera guide says Droll usually stops that strategy. Open with what already brings Fusion so you do not depend on the second search."}},{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa la búsqueda de Berfomet, de Gazelle o de Small World.","en":"When a Berfomet, Gazelle or Small World search is activated."},"loss":{"es":"Corta esa búsqueda. Small World o Polymerization son buen señuelo, porque la ventaja real está en Chimera y Berfomet.","en":"It stops that search. Small World or Polymerization make a good bait, since the real advantage lies in Chimera and Berfomet."}},{"card":"Dimensional Barrier","step":"activation","stepText":{"es":"Declarando Fusion en tu Main Phase, antes de resolver Chimera Fusion.","en":"Declaring Fusion in your Main Phase, before Chimera Fusion resolves."},"loss":{"es":"No podés invocar Fusiones ese turno y las que están en el campo pierden sus efectos; la guía de Branded Chimera dice que destruye al mazo. Aguantá la Fusión y jugá monstruos del Deck principal.","en":"You cannot Special Summon Fusions that turn and those on the field lose their effects; the Branded Chimera guide says it demolishes the deck. Hold the Fusion and play Main Deck monsters."}},{"card":"Dimension Shifter","step":"activation","stepText":{"es":"En tu turno, antes de usar los materiales: todo lo que va al Cementerio se destierra.","en":"On your turn, before you use materials: anything sent to the GY is banished."},"loss":{"es":"Los materiales se destierran en lugar de ir al Cementerio, y los efectos 'al ir al Cementerio como material' de Gazelle y Berfomet no se activan. Fusioná igual, pero sin contar con ese valor.","en":"Materials are banished instead of going to the GY, so Gazelle's and Berfomet's 'sent to the GY as material' effects do not trigger. Fusion Summon anyway but do not count on that value."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, sobre Berfomet, Gazelle o el Chimera ya invocado.","en":"In your Main Phase, on Berfomet, Gazelle or an already summoned Chimera."},"loss":{"es":"Niega el efecto del monstruo elegido hasta el fin del turno. Si Fusionás un Fiend con Dark Fusion, el rival no puede apuntarlo ese turno; y si apuntan a un Fiend o Fusión, Darkuriboh evita que se nieguen sus efectos.","en":"It negates the chosen monster's effect until end of turn. If you Fusion Summon a Fiend with Dark Fusion, the opponent cannot target it that turn; and if a Fiend or Fusion monster is targeted, Darkuriboh stops its effects from being negated."}}],"side":{"first":{"in":[{"card":"Chaos Hunter","qty":2,"why":{"es":"Se invoca de la mano (descartando 1 carta) cuando el rival invoca de Especial y evita que el rival destierre cartas.","en":"It Special Summons from hand (discarding 1 card) when the opponent Special Summons and stops the opponent from banishing cards."}}],"out":[{"card":"Kuriboh - Multiply!","qty":1,"why":{"es":"Reacciona a un efecto de monstruo o a un ataque del rival; yendo primero el rival no tiene monstruos que los activen en tu turno.","en":"It reacts to an opposing monster effect or attack; going first the opponent has no monsters to do either on your turn."}},{"card":"Detonating Kuriboh","qty":1,"why":{"es":"Se equipa a un monstruo rival que activa un efecto en el campo; sin tablero rival en tu turno no tiene objetivo.","en":"It equips to an opposing monster that activates an effect on the field; with no opposing board on your turn it has no target."}}]},"second":{"in":[{"card":"Lightning Vortex","qty":2,"why":{"es":"Descartando 1 carta destruye todos los monstruos boca arriba del rival: yendo segundo su tablero ya está armado.","en":"Discarding 1 card it destroys all face-up monsters the opponent controls: going second their board is already built."}}],"out":[{"card":"Small World","qty":2,"why":{"es":"No responde a nada del tablero rival: solo cambia una carta de la mano por otra del Deck.","en":"It answers nothing on the opposing board: it only swaps a card in hand for one from the Deck."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Chimera Fusion","url":"https://yugipedia.com/wiki/Chimera_Fusion","kind":"cards","checked":"2026-10-27"},{"name":"Mirror Swordknight","url":"https://yugipedia.com/wiki/Mirror_Swordknight","kind":"cards","checked":"2026-10-27"},{"name":"Beginner's Guide to Chimera Branded (Post LEDE)","url":"https://ygoprodeck.com/deck/beginner-s-guide-to-chimera-branded-post-lede-486403","kind":"guide","checked":"2026-10-27"},{"name":"Springfield Genesys Regional - Yu-Gi-Oh! Tournament","url":"https://ygoprodeck.com/tournament/springfield-genesys-regional-5020","kind":"results","checked":"2026-10-27"},{"name":"Yu-Gi-Oh! GENESYS | Official Website","url":"https://www.yugioh-card.com/en/genesys/","kind":"list","checked":"2026-10-27"},{"name":"Genesys 1st Anniversary Update [GENESYS]","url":"https://ygorganization.com/genesys-1st-anniversary-update-genesys","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La guía de Chimera Branded es anterior a Genesys y no analiza puntos: respalda el plan y los frenos (Droll, Dimensional Barrier, Shifter), pero no los costos ni el Side.","en":"The Chimera Branded guide predates Genesys and does not analyze points: it backs the plan and the brakes (Droll, Dimensional Barrier, Shifter), but not the costs or the Side Deck."},{"es":"Los resultados son de un solo torneo (Springfield, 12 de septiembre de 2026, dos Chimera en el Top 8), anterior al cambio de puntos del 5 de octubre: aquella lista pudo costar distinto.","en":"The results come from a single tournament (Springfield, September 12, 2026, two Chimera in the Top 8), before the October 5 points change: that list may have cost differently."},{"es":"El Side Deck es criterio de la redacción: no hay una estadística de torneos que lo respalde.","en":"The Side Deck is editorial judgment: no tournament statistic backs it."}]},"gen/exosister":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Martha, Elis, Irene y Sophia pueden ser el único material de un Xyz Exosister (se trata como Invocación Xyz) cuando una carta sale de un Cementerio: Martha con cualquiera, los otros tres cuando la mueve el rival. Al rival le cuesta usar su Cementerio.","en":"Martha, Elis, Irene and Sophia can be the sole material for an Exosister Xyz (treated as an Xyz Summon) when a card leaves a Graveyard: Martha for any, the other three when the opponent moves it. The opponent has a hard time using their Graveyard."},{"es":"Martha entra de la mano y trae a Elis; Aratama busca a Sakitama o Ichiki, y Ichiki trae un LIGHT o DARK de nivel 4 con 800 de ATK o DEF. Eso asegura los cuerpos para dos Xyz.","en":"Martha enters from hand and brings Elis; Aratama searches Sakitama or Ichiki, and Ichiki brings a Level 4 LIGHT or DARK with 800 ATK or DEF. That secures the bodies for two Xyz."},{"es":"Exosisters Magnifica quita una carta rival por turno y puede cambiarse por otro Xyz en el turno rival; Mikailis y Gibrine disrumpen la jugada. Los costos de 800 LP de Pax, Vadis y Returnia limitan cuánto se puede apurar.","en":"Exosisters Magnifica banishes one opposing card per turn and can swap into another Xyz on the opponent's turn; Mikailis and Gibrine disrupt the play. The 800 LP costs of Pax, Vadis and Returnia cap how much you can rush."}]},"starters":[{"cards":["Exosister Martha"],"route":{"es":"Martha se invoca de la mano si no controlás monstruos o solo Xyz, y trae a Elis del Deck. Después usan 'cuando una carta sale del Cementerio' y suben a Rango 4.","en":"Martha Special Summons from hand if you control no monsters or only Xyz, and brings Elis from the Deck. They then use 'when a card moves out of a GY' and rank up to Rank 4."}},{"cards":["Aratama","Ichiki Sayori-Hime"],"route":{"es":"Aratama (Invocación Normal) busca otro Spirit; Ichiki se invoca de la mano si controlás un monstruo de 800 ATK o DEF, y trae a un nivel 4 LIGHT o DARK de 800 ATK o DEF.","en":"Aratama (Normal Summon) searches another Spirit; Ichiki is Normal Summoned from hand if you control an 800 ATK or DEF monster, and brings a Level 4 LIGHT or DARK with 800 ATK or DEF."}},{"cards":["Exosister Betrayal"],"route":{"es":"Betrayal agrega 2 Exosister y descarta 1, permite una Invocación Normal extra de un Exosister mencionado y destierra un monstruo que vaya al Cementerio rival.","en":"Betrayal adds 2 Exosisters and discards 1, allows an extra Normal Summon of a mentioned Exosister and banishes a monster sent to the opponent's GY."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa la búsqueda de Aratama, Ichiki, Pax o Betrayal.","en":"When an Aratama, Ichiki, Pax or Betrayal search is activated."},"loss":{"es":"Niega esa búsqueda. Martha no busca sino que invoca a Elis del Deck, y eso Ash también lo frena: jugá primero la ruta de Martha y después las búsquedas.","en":"It negates that search. Martha does not search; she Special Summons Elis from the Deck, which Ash also stops. Play the Martha route first and the searches after."}},{"card":"Macro Cosmos","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase: ninguna carta va al Cementerio.","en":"Face-up before your Main Phase: no card goes to the GY."},"loss":{"es":"Si no hay cartas en el Cementerio, nada sale de él y los efectos de Exosister no se activan. Typhoon, MST o Unending Nightmare (de tu Side) la destruyen: es una Trampa Continua.","en":"If no cards reach the GY, nothing leaves it and Exosister effects do not activate. Typhoon, MST or Unending Nightmare (from your Side) destroy it: it is a Continuous Trap."}},{"card":"Dimension Shifter","step":"activation","stepText":{"es":"En tu turno, con el Cementerio rival vacío, antes de que algo se mueva de allí.","en":"On your turn, with their GY empty, before anything moves from there."},"loss":{"es":"Destierra todo lo que va al Cementerio hasta el fin del próximo turno, y sin cartas que salgan del Cementerio no se activan los efectos de Exosister. Martha y Elis se invocan igual, pero armá los Xyz con material normal.","en":"It banishes anything sent to the GY through the end of the next turn, and with no cards leaving the GY Exosister effects do not activate. Martha and Elis still summon, but build the Xyz with normal material."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Magnifica, Karmael o Mikailis, justo antes de usar su efecto.","en":"On Magnifica, Karmael or Mikailis, right before using its effect."},"loss":{"es":"Niega el efecto del Xyz elegido hasta el fin del turno. Si Magnifica tiene un Xyz anexado, podés cambiarla por ese Xyz en respuesta (efecto rápido), y Karmael puede transformar el efecto de la Trampa desmontando todos sus materiales.","en":"It negates the chosen Xyz's effect until end of turn. If Magnifica has an Xyz attached, you can swap it for that Xyz in response (Quick Effect), and Karmael can change the Trap's effect by detaching all its materials."}}],"side":{"first":{"in":[{"card":"Typhoon","qty":2,"why":{"es":"Destruye una Magia o Trampa rival boca arriba (Macro Cosmos, floodgates) que frene el plan.","en":"Destroys a face-up opposing Spell or Trap (Macro Cosmos, floodgates) that stops the plan."}}],"out":[{"card":"Gordian Slicer","qty":2,"why":{"es":"Devuelve a la mano cartas boca arriba del campo desterrando cartas de tu mano: yendo primero el rival no tiene nada que devolver.","en":"It returns face-up cards on the field to the hand by banishing cards from your hand: going first the opponent has nothing to return."}}]},"second":{"in":[{"card":"Typhoon","qty":1,"why":{"es":"Responde a una Magia o Trampa rival ya puesta.","en":"Answers an opposing Spell or Trap that is already set."}},{"card":"Blizzard","qty":1,"why":{"es":"Niega los efectos activados de una Magia rival boca arriba y de las que tengan su mismo nombre este turno.","en":"Negates the activated effects of a face-up opposing Spell and all Spells with the same name this turn."}}],"out":[{"card":"Forbidden Chalice","qty":2,"why":{"es":"Niega un monstruo solo hasta el fin del turno; ese espacio rinde más con respuestas a Magias y Trampas ya puestas.","en":"It negates a monster only until end of turn; that space is worth more as answers to Spells and Traps already set."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Exosister Martha","url":"https://yugipedia.com/wiki/Exosister_Martha","kind":"cards","checked":"2026-10-27"},{"name":"Exosisters Magnifica","url":"https://yugipedia.com/wiki/Exosisters_Magnifica","kind":"cards","checked":"2026-10-27"},{"name":"Exosister ZEXAL Spirits, ft. BPRO Support [CDP]","url":"https://ygorganization.com/cdp_exosister26","kind":"guide","checked":"2026-10-27"},{"name":"Genesys 1st Anniversary Update [GENESYS]","url":"https://ygorganization.com/genesys-1st-anniversary-update-genesys","kind":"list","checked":"2026-10-27"},{"name":"Yu-Gi-Oh! GENESYS | Official Website","url":"https://www.yugioh-card.com/en/genesys/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La guía es de enero de 2026, anterior al ajuste del 5 de octubre (Betrayal sube de 7 a 18, Pax de 5 a 7, Mikailis de 10 a 11), y no analiza puntos de Genesys.","en":"The guide is from January 2026, before the October 5 adjustment (Betrayal goes from 7 to 18, Pax from 5 to 7, Mikailis from 10 to 11), and does not analyze Genesys points."},{"es":"Los puntos de Exosister subieron por una recategorización de efectos, no por resultados: no los tomes como señal de rendimiento.","en":"Exosister's points went up because of a recategorization of effects, not because of results: do not read them as a performance signal."},{"es":"El Side Deck es criterio de la redacción: no hay una estadística de torneos que lo respalde.","en":"The Side Deck is editorial judgment: no tournament statistic backs it."}]},"gen/invoked":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Fusiona Invoked usando monstruos propios, del Cementerio y desterrados con Invocation, Sword y Grail. Con Magical Meltdown, la activación de esos efectos de Fusión no se puede negar y el rival no puede activar cartas cuando se hace la Fusión.","en":"Fusion Summons Invoked monsters using its own monsters, the GY and banished cards via Invocation, Sword and Grail. With Magical Meltdown, the activation of those Fusion effects cannot be negated and the opponent cannot activate cards when the Fusion is summoned."},{"es":"Aleister the Invoker agrega Invocation; Reminiscent se invoca de la mano y destierra un Invoked del Extra para agregar Invocation. Aiwass se destierra para traer un Aleister y vuelve del Cementerio cuando una de tus Fusiones se manda al Cementerio.","en":"Aleister the Invoker adds Invocation; Reminiscent Special Summons from hand and banishes an Invoked from the Extra Deck to add Invocation. Aiwass banishes itself to bring an Aleister and returns from the GY when one of your Fusions is sent to the GY."},{"es":"Los jefes son Invoked De Anima (destruye monstruos del Extra o Magias y Trampas), Mechaba (niega descartando una carta del mismo tipo) y Hyperinvoked Aeon, que destierra cartas del campo y de los Cementerios.","en":"The bosses are Invoked De Anima (destroys Extra Deck monsters or Spells and Traps), Mechaba (negates by discarding a card of the same type) and Hyperinvoked Aeon, which banishes cards from the field and Graveyards."}]},"starters":[{"cards":["Magical Meltdown"],"route":{"es":"Meltdown agrega a Aleister the Invoker al activarse; con él, Invocation y Aleister hacen una Fusión a la que el rival no puede responder.","en":"Meltdown adds Aleister the Invoker when activated; with it, Invocation and Aleister make a Fusion the opponent cannot respond to."}},{"cards":["Aleister the Reminiscent"],"route":{"es":"Reminiscent se invoca de la mano apuntando a un Spellcaster o Fusión (que gana 1000 ATK) y, al invocarse, agrega Invocation desterrando un Invoked del Extra.","en":"Reminiscent Special Summons itself from hand targeting a Spellcaster or Fusion (which gains 1000 ATK) and, when summoned, adds Invocation by banishing an Invoked from the Extra Deck."}},{"cards":["Aiwass, Divine Spirit of the Law","Sacred Spirit Sword Aiwass"],"route":{"es":"Aiwass se destierra de la mano y trae un Aleister; Sacred Spirit Sword Aiwass lo invoca del Deck o Cementerio, o toma un Aleister del Deck y lo manda al Cementerio o lo destierra.","en":"Aiwass banishes itself from hand and brings an Aleister; Sacred Spirit Sword Aiwass Special Summons it from the Deck or GY, or takes an Aleister from the Deck and sends it to the GY or banishes it."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa Meltdown, el efecto de Aleister the Invoker o el de Reminiscent que agrega Invocation.","en":"When Meltdown, Aleister the Invoker's effect or Reminiscent's Invocation search is activated."},"loss":{"es":"Niega esa búsqueda. El mazo tiene pocas fuentes de Fusión consistentes, así que Ash en el primer eslabón suele costar la jugada: guardá Virakam (necesita un Aleister en el campo o el Cementerio), que deja Invocation boca abajo, algo que Ash no frena.","en":"It negates that search. The deck has few consistent Fusion sources, so Ash at the first link often costs the play: keep Virakam (needs an Aleister on the field or in the GY), which Sets Invocation, something Ash does not stop."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno, normalmente Aleister o Invocation.","en":"After the first search of the turn, normally Aleister or Invocation."},"loss":{"es":"No hay más búsquedas ese turno: sin Invocation en la mano no hay Fusión. Abrí con Sword o Grail que ya estén en la mano para no depender de una segunda búsqueda.","en":"No more searches that turn: without Invocation in hand there is no Fusion. Open with Sword or Grail already in hand so you do not depend on a second search."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Cuando Aiwass se activa desde el Cementerio, o Invocation o Sword se mezclan de vuelta al Deck desde el Cementerio.","en":"When Aiwass activates from the GY, or Invocation or Sword shuffle back into the Deck from the GY."},"loss":{"es":"Niega esa activación (invocar del Cementerio, volver al Deck, desterrar del Cementerio). Sin recursión el mazo queda con las cartas de la mano, así que gastá primero lo que está en la mano.","en":"It negates that activation (Special Summon from the GY, return to the Deck, banish from the GY). Without recursion the deck is left with its hand, so spend what is in hand first."}},{"card":"Dimensional Barrier","step":"activation","stepText":{"es":"Declarando Fusion antes de tu Fusión, en respuesta a Invocation, Sword o Grail.","en":"Declaring Fusion before your Fusion, in response to Invocation, Sword or Grail."},"loss":{"es":"Meltdown evita la negación de la activación, pero esta Trampa no la niega: impide invocar Fusiones ese turno y las que están en el campo pierden sus efectos. Hay que rodearla con monstruos que no sean Fusión.","en":"Meltdown stops the activation from being negated, but this Trap does not negate it: it prevents Fusion Summons that turn and those on the field lose their effects. You have to play around it with non-Fusion monsters."}}],"side":{"first":{"in":[{"card":"D.D. Crow","qty":2,"why":{"es":"Destierra una carta del Cementerio rival en el turno rival, lo que corta sus efectos de Cementerio.","en":"Banishes a card in the opponent's GY on their turn, cutting their GY effects."}}],"out":[{"card":"Tuning","qty":2,"why":{"es":"Busca un Synchron y manda la carta de arriba del Deck al Cementerio: una carta lenta para el plan Invoked.","en":"Searches a Synchron and sends the top card of the Deck to the GY: a slow card for the Invoked plan."}}]},"second":{"in":[{"card":"Veidos the Eruption Dragon of Extinction","qty":2,"why":{"es":"Se juega desde la mano al campo rival sobre una carta en una Zona de Campo y la destruye; si va de su campo a tu Cementerio, destruye todos los monstruos del campo.","en":"It goes from hand to their field against a card in a Field Zone and destroys it; if it goes from their field to your GY, it destroys all monsters on the field."}}],"out":[{"card":"Revolution Synchron","qty":2,"why":{"es":"Solo apoya Sincros específicos y vuelve al campo con ayuda de un Sincro de nivel 7 o más: se juega en una ruta Synchro lenta.","en":"It only supports specific Synchros and returns to the field with a Level 7 or higher Synchro: it belongs to a slow Synchro route."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Magical Meltdown","url":"https://yugipedia.com/wiki/Magical_Meltdown","kind":"cards","checked":"2026-10-27"},{"name":"Aleister the Reminiscent","url":"https://yugipedia.com/wiki/Aleister_the_Reminiscent","kind":"cards","checked":"2026-10-27"},{"name":"Invoked Magistus - Tales of Aleister, ft. CORI Support [CDP]","url":"https://ygorganization.com/cdp_invokedmagistuscori/","kind":"guide","checked":"2026-10-27"},{"name":"Genesys 1st Anniversary Update [GENESYS]","url":"https://ygorganization.com/genesys-1st-anniversary-update-genesys","kind":"list","checked":"2026-10-27"},{"name":"Yu-Gi-Oh! GENESYS | Official Website","url":"https://www.yugioh-card.com/en/genesys/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La guía enlazada es de un Invoked Magistus con soporte de CORI (abril de 2026) y no analiza puntos de Genesys.","en":"The linked guide covers an Invoked Magistus build with CORI support (April 2026) and does not analyze Genesys points."},{"es":"Hyperinvoked Aeon subió de 15 a 20 puntos el 5 de octubre de 2026: revisá cuánto te queda para el resto de la lista.","en":"Hyperinvoked Aeon went from 15 to 20 points on October 5, 2026: check how much room is left for the rest of the list."},{"es":"Los puntos de interrupción y el Side Deck son criterio de la redacción, sin estadística de torneos detrás.","en":"The chokepoints and the Side Deck are editorial judgment, with no tournament statistics behind them."}]},"gen/white-forest-azamina":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"White Forest funciona como motor Sincro: Elzette, Astellar y Silvy llegan a Rciela y, según la guía de YGOPRODeck, a Glitch Clutch Nullgainer, que busca a Witness of the Ancient para poner los Angelechy. El ajuste del 5 de octubre bajó a Azamina Mu Rcielago de 33 a 15 puntos y a Deception of the Sinful Spoils de 40 a 20, y subió a Azamina Ilia Silvia de 20 a 33.","en":"White Forest works as a Synchro engine: Elzette, Astellar and Silvy reach Rciela and, per the YGOPRODeck guide, Glitch Clutch Nullgainer, which searches Witness of the Ancient to set the Angelechy. The October 5 adjustment lowered Azamina Mu Rcielago from 33 to 15 points and Deception of the Sinful Spoils from 40 to 20, and raised Azamina Ilia Silvia from 20 to 33."},{"es":"Los Angelechy se colocan como Magias Continuas con efecto de campo: Shatranga limita a 5 los efectos de monstruo del rival, Destrier le hace 500 por cada carta o efecto que active y Bastion protege al resto de la destrucción.","en":"The Angelechy are placed as Continuous Spells with field effects: Shatranga limits the opponent to 5 monster effects, Destrier deals 500 per card or effect it activates and Bastion protects the rest from destruction."},{"es":"Angelechy Problem es el punto de apoyo: descartando una Magia o Trampa invoca a un Angelechy de nivel 2 del Extra y pone otro como Magia. El mazo depende de él.","en":"Angelechy Problem is the fulcrum: discarding a Spell or Trap summons a Level 2 Angelechy from the Extra Deck and places another as a Spell. The deck depends on it."}]},"starters":[{"cards":["Elzette of the White Forest"],"route":{"es":"Elzette se invoca de la mano mandando una Magia o Trampa al Cementerio y agrega un White Forest, normalmente Silvy, que sigue con Tales of the White Forest.","en":"Elzette Special Summons from hand by sending a Spell or Trap to the GY and adds a White Forest, normally Silvy, which continues with Tales of the White Forest."}},{"cards":["Astellar of the White Forest","Silvy of the White Forest"],"route":{"es":"Astellar manda una Magia o Trampa al Cementerio e invoca del Deck un Tuner LIGHT Spellcaster; con Silvy se llega a Rciela.","en":"Astellar sends a Spell or Trap to the GY and Special Summons a LIGHT Spellcaster Tuner from the Deck; with Silvy you reach Rciela."}},{"cards":["Angelechy Problem"],"route":{"es":"Problem descarta una Magia o Trampa e invoca un Angelechy de nivel 2 del Extra Deck (Enlisted) y coloca un Angelechy más como Magia Continua.","en":"Problem discards a Spell or Trap and summons a Level 2 Angelechy from the Extra Deck (Enlisted) and places another Angelechy as a Continuous Spell."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa Elzette (agrega un White Forest), Silvy o Rciela (agregan del Deck).","en":"When Elzette (adds a White Forest), Silvy or Rciela (add from the Deck) is activated."},"loss":{"es":"Corta la búsqueda: sin Silvy ni Tales el motor Sincro se frena. Azamina (invoca desde la mano) y Problem (invoca desde el Extra) no se pueden frenar con Ash; Elzette sí, porque busca.","en":"It stops the search: without Silvy or Tales the Synchro engine stalls. Azamina (summons from hand) and Problem (summons from the Extra Deck) cannot be stopped by Ash; Elzette can, because it searches."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno.","en":"After the first search of the turn."},"loss":{"es":"Corta las demás búsquedas (Silvy, Tales, Rciela). Jugá primero la ruta que menos busca, por ejemplo Problem, y dejá la importante para después.","en":"It stops further searches (Silvy, Tales, Rciela). Play the least searching route first, such as Problem, and save the important one for later."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"Con la quinta invocación del turno: Tuner, Sincro, Angelechy y token suman rápido.","en":"On the fifth summon of the turn: Tuners, Synchros, Angelechy and tokens add up fast."},"loss":{"es":"Tributa todos los monstruos boca arriba del campo (los Sincro incluidos) y deja un Token. Los Angelechy colocados como Magias no se tributan, así que el daño es menor si ya los pusiste.","en":"It Tributes every face-up monster on the field (Synchros included) and leaves a Token. Angelechy placed as Spells are not Tributed, so the damage is smaller if you have placed them already."}},{"card":"Cosmic Cyclone","step":"main","stepText":{"es":"En tu Main Phase, sobre Angelechy Problem o un Angelechy colocado como Magia.","en":"In your Main Phase, on Angelechy Problem or an Angelechy placed as a Spell."},"loss":{"es":"Desterrar no es destruir, así que Bastion no lo protege. Sin Problem el plan se cae; guardá un segundo Angelechy en la mano o la fuente alternativa de Sincros.","en":"Banishing is not destroying, so Bastion does not protect it. Without Problem the plan falls apart; keep a second Angelechy in hand or the alternative Synchro source."}}],"side":{"first":{"in":[{"card":"Annihilate Retroglight","qty":1,"why":{"es":"Cuando el rival activa un efecto de monstruo en el campo, lo niega y puede desterrar boca abajo todos sus monstruos boca arriba: una buena Trampa para yendo primero.","en":"When the opponent activates a monster effect on the field, it negates it and can banish all their face-up monsters face-down: a good Trap going first."}},{"card":"Gravity Collapse","qty":1,"why":{"es":"Niega una invocación a cambio de mandar un Sincro al Cementerio.","en":"Negates a Summon by sending a Synchro to the GY."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Necesita que no controles cartas, algo que casi nunca pasa yendo primero tras armar el tablero.","en":"It needs you to control no cards, which almost never happens going first after building the board."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":1,"why":{"es":"Yendo segundo rompe una Magia o Trampa rival ya puesta.","en":"Going second it breaks an already set opposing Spell or Trap."}},{"card":"Twin Twisters","qty":1,"why":{"es":"Descartando 1 carta destruye hasta 2 Magias o Trampas.","en":"Discarding 1 card it destroys up to 2 Spells or Traps."}}],"out":[{"card":"Fifty Fifty?","qty":2,"why":{"es":"Es una apuesta al azar; con el rival ya armado conviene una respuesta fija.","en":"It is a random gamble; with the opponent already set up you want a fixed answer."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Elzette of the White Forest","url":"https://yugipedia.com/wiki/Elzette_of_the_White_Forest","kind":"cards","checked":"2026-10-27"},{"name":"Angelechy Problem","url":"https://yugipedia.com/wiki/Angelechy_Problem","kind":"cards","checked":"2026-10-27"},{"name":"White Moves First (White Forest-Angelechy)","url":"https://ygoprodeck.com/deck/white-moves-first-white-forest-angelechy-724014","kind":"guide","checked":"2026-10-27"},{"name":"Genesys 1st Anniversary Update [GENESYS]","url":"https://ygorganization.com/genesys-1st-anniversary-update-genesys","kind":"list","checked":"2026-10-27"},{"name":"Yu-Gi-Oh! GENESYS | Official Website","url":"https://www.yugioh-card.com/en/genesys/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Hay una sola guía y no analiza puntos de Genesys (arma White Forest con Angelechy). Antes de armar la lista mirá los puntos actuales en la página oficial: Silvy y Ilia Silvia suben el 5 de octubre de 2026.","en":"There is a single guide and it does not analyze Genesys points (it builds White Forest with Angelechy). Check the current points on the official page before building the list: Silvy and Ilia Silvia go up on October 5, 2026."},{"es":"El Side Deck es criterio de la redacción: no hay una estadística de torneos que lo respalde.","en":"The Side Deck is editorial judgment: no tournament statistic backs it."}]},"gen/fairy-tail":{"win":{"plan":"otk","pace":"medium","bullets":[{"es":"Fairy Tail Ball deja a los Fairy Tail atacar directo y niega un monstruo rival cuando invoca de Especial (queda como Prince of Fairies); varios Fairy Tail en el campo hacen daño directo rápido.","en":"Fairy Tail Ball lets Fairy Tail monsters attack directly and negates an opposing monster when it Special Summons (it becomes Prince of Fairies); several Fairy Tails on the field deal direct damage fast."},{"es":"Luna agrega un Spellcaster de 1850 de ATK, Matchgiru agrega una Magia o Trampa Fairy Tail y Tails of the Fairy Tails Fusiona (también con un Prince of Fairies del rival como material). Weaver vuelve Spellcaster a los Prince of Fairies, y Teller, si se Fusiona con uno, destruye cartas rivales e inflige 500 por cada una.","en":"Luna adds a Spellcaster with 1850 ATK, Matchgiru adds a Fairy Tail Spell or Trap and Tails of the Fairy Tails Fusion Summons (also with an opposing Prince of Fairies as material). Weaver turns Prince of Fairies into Spellcasters, and Teller, if Fusion Summoned using one, destroys opposing cards and deals 500 for each."},{"es":"Hay un motor Endymion (Regulus, Endymion Empire). Una guía de YGOPRODeck sobre Genesys lo describe como un mazo Spellcaster de varios motores.","en":"There is an Endymion engine (Regulus, Endymion Empire). A YGOPRODeck Genesys guide describes it as a multi-engine Spellcaster deck."}]},"starters":[{"cards":["Fairy Tail - Luna","Fairy Tail - Matchgiru"],"route":{"es":"Luna (Invocación Normal) agrega un Spellcaster de 1850 de ATK; Matchgiru se invoca de la mano si hay uno en el campo y agrega una Magia o Trampa Fairy Tail, como Ball.","en":"Luna (Normal Summon) adds a Spellcaster with 1850 ATK; Matchgiru Special Summons from hand if one is on the field and adds a Fairy Tail Spell or Trap, such as Ball."}},{"cards":["Regulus, the Prince of Endymion"],"route":{"es":"Regulus se invoca de la mano revelando otro Spellcaster y perdiendo LP, y al invocarse agrega una Magia que lo menciona. Es el arranque del motor Endymion.","en":"Regulus Special Summons from hand revealing another Spellcaster and losing LP, and when summoned adds a Spell that mentions it. It starts the Endymion engine."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa Luna, Matchgiru o Regulus (agregar del Deck).","en":"When Luna, Matchgiru or Regulus (add from the Deck) is activated."},"loss":{"es":"Corta esa búsqueda y con ella la jugada. Hay varios motores: si Ash cae en uno, pasá a otro en vez de insistir con el mismo.","en":"It stops that search and with it the play. There are several engines: if Ash lands on one, move to another instead of pushing the same one."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno (Luna, Matchgiru, Regulus).","en":"After the first search of the turn (Luna, Matchgiru, Regulus)."},"loss":{"es":"Ninguna otra búsqueda ese turno. Usá primero el efecto que no busca, por ejemplo la invocación de Matchgiru desde la mano.","en":"No further searches that turn. Use the effect that does not search first, such as Matchgiru's Special Summon from hand."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Cuando Snow o Matchgiru se activan desde el Cementerio.","en":"When Snow or Matchgiru activate from the GY."},"loss":{"es":"Niega esa invocación desde el Cementerio. Los Fairy Tail también se juegan desde la mano: gastá primero la mano y dejá el Cementerio para después.","en":"It negates that Special Summon from the GY. Fairy Tails also play from hand: spend the hand first and leave the GY for later."}},{"card":"Dimensional Barrier","step":"activation","stepText":{"es":"Declarando Fusion o Xyz en tu Main Phase, justo antes de Tails o Wiccat.","en":"Declaring Fusion or Xyz in your Main Phase, right before Tails or Wiccat."},"loss":{"es":"Cierra la invocación de ese tipo ese turno y los monstruos de ese tipo en el campo pierden sus efectos. El mazo juega los dos tipos, así que cambiá de motor al que no declararon.","en":"It closes Summons of that type this turn and monsters of that type on the field lose their effects. The deck plays both types, so switch to the engine they did not declare."}}],"side":{"first":{"in":[{"card":"The Eye of Truth","qty":2,"why":{"es":"Obliga al rival a mantener la mano revelada, para jugar alrededor de sus handtraps.","en":"Forces the opponent to keep their hand revealed, so you can play around their handtraps."}}],"out":[{"card":"Ghost Ogre & Snow Rabbit","qty":2,"why":{"es":"Solo destruye cartas que activan su efecto en el campo; The Eye of Truth muestra la mano rival antes de jugar.","en":"It only destroys cards that activate an effect on the field; The Eye of Truth shows the opponent's hand before you play."}}]},"second":{"in":[{"card":"Santa Claws","qty":2,"why":{"es":"Va al campo rival en Defensa tributando uno de sus monstruos y roba al final del turno: quita un obstáculo yendo segundo.","en":"Goes to their field in Defense Position Tributing one of their monsters and draws in the End Phase: removes an obstacle going second."}}],"out":[{"card":"Genia of the Ring","qty":2,"why":{"es":"Solo evita una destrucción por efecto de un monstruo; Santa Claws saca un monstruo del campo rival.","en":"It only prevents one effect destruction of a monster; Santa Claws removes a monster from the opponent's field."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Fairy Tail Ball","url":"https://yugipedia.com/wiki/Fairy_Tail_Ball","kind":"cards","checked":"2026-10-27"},{"name":"Fairy Tail - Matchgiru","url":"https://yugipedia.com/wiki/Fairy_Tail_-_Matchgiru","kind":"cards","checked":"2026-10-27"},{"name":"Budget Fairy Tail Genesys","url":"https://ygoprodeck.com/deck/budget-fairy-tail-genesys-725766","kind":"guide","checked":"2026-10-27"},{"name":"Genesys 1st Anniversary Update [GENESYS]","url":"https://ygorganization.com/genesys-1st-anniversary-update-genesys","kind":"list","checked":"2026-10-27"},{"name":"Yu-Gi-Oh! GENESYS | Official Website","url":"https://www.yugioh-card.com/en/genesys/","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La guía de YGOPRODeck es anterior al ajuste del 5 de octubre de 2026: allí Fairy Tail Ball cuesta 10 puntos y ahora cuesta 15 (Wiccat también de 10 a 15, Teller of Fairy Tails de 0 a 11).","en":"The YGOPRODeck guide predates the October 5, 2026 adjustment: it prices Fairy Tail Ball at 10 points and it now costs 15 (Wiccat also from 10 to 15, Teller of Fairy Tails from 0 to 11)."},{"es":"Hay una sola guía de este mazo en Genesys y es la de un jugador; los puntos de interrupción y el Side Deck son criterio de la redacción.","en":"There is a single guide to this deck in Genesys, written by one player; the chokepoints and the Side Deck are editorial judgment."},{"es":"La lista de la guía supera los 100 puntos de Genesys con los valores actuales: sirve para ver los motores del mazo, no como lista legal.","en":"The guide list exceeds the 100 Genesys points with the current values: use it to see the deck's engines, not as a legal list."}]},"goat/chaos-turbo":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Gana por ventaja de cartas: los monstruos Flip (Magician of Faith, Night Assailant, Gravekeeper's Spy, Dekoichi) y los flotadores rinden solos, y trampas de descarte como Raigeki Break presionan al rival.","en":"Wins on card advantage: Flip monsters (Magician of Faith, Night Assailant, Gravekeeper's Spy, Dekoichi) and floaters generate value on their own, and discard Traps like Raigeki Break pressure the opponent."},{"es":"Thunder Dragon es la carta más asociada al mazo: se descarta (su efecto busca hasta 2 copias más) y deja un LIGHT en el Cementerio para Chaos Sorcerer.","en":"Thunder Dragon is the card most associated with the deck: it is discarded (its effect adds up to 2 more copies) and leaves a LIGHT in the Graveyard for Chaos Sorcerer."},{"es":"Chaos Sorcerer es la amenaza principal: una vez por turno destierra un monstruo boca arriba y no puede atacar ese turno. Pide 1 LIGHT y 1 DARK en el Cementerio: si te faltan, queda trabado en la mano.","en":"Chaos Sorcerer is the main threat: once per turn it banishes a face-up monster and cannot attack that turn. It needs 1 LIGHT and 1 DARK in the Graveyard: if you lack them, it stays stuck in hand."}]},"starters":[{"cards":["Thunder Dragon"],"route":{"es":"Descartás Thunder Dragon: buscás más copias y queda un LIGHT en el Cementerio, la mitad de la condición de Chaos Sorcerer.","en":"Discard Thunder Dragon: you fetch more copies and a LIGHT stays in the Graveyard, half the condition for Chaos Sorcerer."}},{"cards":["Night Assailant","Raigeki Break"],"route":{"es":"Raigeki Break pide descartar 1 carta para destruir otra del campo; la receta mostrada juega 2 Raigeki Break (3 en la guía) y 2 Night Assailant, que acompañan a los Flip.","en":"Raigeki Break discards 1 card to destroy another card on the field; the recipe shown plays 2 Raigeki Break (3 in the guide) and 2 Night Assailant, which complement the Flips."}}],"chokepoints":[{"card":"Nobleman of Crossout","step":"activation","stepText":{"es":"Al activarla sobre tu Flip seteado, antes de que se pueda girar.","en":"On activation against your set Flip monster, before it can flip."},"loss":{"es":"Destierra el monstruo seteado y, si es un Flip, todas sus copias del Deck: perdés el valor de ese Flip. Seteá dos Flip distintos y no dependas de uno solo.","en":"Banishes the set monster and, if it is a Flip monster, every copy in the Deck: you lose that Flip's value. Set two different Flips and do not rely on one."}},{"card":"Tsukuyomi","step":"summon","stepText":{"es":"Al invocarla de Normal o girarla: pone boca abajo en Defensa a un monstruo boca arriba, el tuyo si es Chaos Sorcerer.","en":"On its Normal Summon or flip: it turns a face-up monster face-down in Defense, yours if it is Chaos Sorcerer."},"loss":{"es":"Tu amenaza queda sin atacar ese turno y la jugada se repite, porque Tsukuyomi vuelve a la mano en la End Phase. No pongas todo en un solo monstruo.","en":"Your threat cannot attack that turn and the play repeats, since Tsukuyomi returns to hand in the End Phase. Do not put everything on one monster."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba en el campo rival, antes de que invoques Chaos.","en":"Face-up on the opponent's field before you summon Chaos."},"loss":{"es":"Mientras esté boca arriba en el campo rival, vos no podés desterrar cartas de ningún Cementerio: Chaos Sorcerer y Black Luster Soldier - Envoy of the Beginning no se pueden invocar. La guía suma un Kycoo como bala de plata contra otros mazos Chaos (la receta mostrada no lo juega). Sacalo del campo primero, por ejemplo con Raigeki Break.","en":"While it is face-up on the opponent's field, you cannot banish cards from either Graveyard: Chaos Sorcerer and Black Luster Soldier - Envoy of the Beginning cannot be summoned. The guide adds a Kycoo as a silver bullet against other Chaos decks (the recipe shown does not play it). Remove it from the field first, for example with Raigeki Break."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Trap Dustshoot","qty":2,"why":{"es":"Si el rival tiene 4 o más cartas en la mano, mirás su mano y devolvés un monstruo al Deck.","en":"If the opponent has 4 or more cards in hand, you look at it and shuffle one monster back into the Deck."}}],"out":[{"card":"Jar of Greed","qty":2,"why":{"es":"Criterio de la redacción: carta de relleno frente a un rival con ritmo.","en":"Editorial judgment: filler card against an opponent with tempo."}}]},"second":{"in":[{"card":"Sakuretsu Armor","qty":2,"why":{"es":"Destruye al monstruo que declara el ataque, sin gastar monstruos propios.","en":"Destroys the monster that declares the attack, without spending your own monsters."}}],"out":[{"card":"Upstart Goblin","qty":2,"why":{"es":"Criterio de la redacción: regala LP al rival cuando ya vas atrás en el tablero.","en":"Editorial judgment: gives LP to the opponent when you are already behind on board."}}]}},"updated":"2026-10-26","sources":[{"name":"Chaos Turbo","url":"https://www.goatformat.com/chaos-turbo.html","kind":"guide","checked":"2026-10-27"},{"name":"Chaos Sorcerer","url":"https://yugipedia.com/wiki/Chaos_Sorcerer","kind":"cards","checked":"2026-10-27"},{"name":"Thunder Dragon","url":"https://yugipedia.com/wiki/Thunder_Dragon","kind":"cards","checked":"2026-10-27"},{"name":"Nobleman of Crossout","url":"https://yugipedia.com/wiki/Nobleman_of_Crossout","kind":"cards","checked":"2026-10-27"},{"name":"Tsukuyomi","url":"https://yugipedia.com/wiki/Tsukuyomi","kind":"cards","checked":"2026-10-27"},{"name":"Kycoo the Ghost Destroyer","url":"https://yugipedia.com/wiki/Kycoo_the_Ghost_Destroyer","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"El texto de las cartas enlazado es el actual de Yugipedia: en 2005 algunas se redactaban distinto (por ejemplo Chaos Sorcerer y Nobleman of Crossout). Las rutas valen igual, pero no cites el texto al pie de la letra.","en":"The linked card text is the current Yugipedia text: in 2005 some cards were worded differently (for example Chaos Sorcerer and Nobleman of Crossout). The routes still hold, but do not quote the text word for word."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas da esos cambios ni una estadística que los respalde.","en":"The Side Deck is editorial judgment: none of the linked sources gives those swaps or a statistic backing them."}]},"goat/warrior":{"win":{"plan":"tempo","pace":"medium","bullets":[{"es":"Presiona con monstruos que atacan turno tras turno para que el rival no arme el tablero; Blade Knight es de los Normal Summon con más ATK.","en":"Pressures with monsters that attack turn after turn so the opponent cannot build a board; Blade Knight is among the Normal Summons with the highest ATK."},{"es":"Reinforcement of the Army es el motor: agrega un Warrior de Nivel 4 o menos, así que busca la amenaza o la respuesta que pida la situación (D.D. Warrior Lady, Mystic Swordsman LV2, Blade Knight, Exiled Force).","en":"Reinforcement of the Army is the engine: it adds a Level 4 or lower Warrior, so it fetches the threat or answer the situation needs (D.D. Warrior Lady, Mystic Swordsman LV2, Blade Knight, Exiled Force)."},{"es":"Las Trampas (Solemn Judgment, Trap Dustshoot, Sakuretsu Armor, Dust Tornado) responden en el turno rival mientras los monstruos siguen atacando.","en":"Traps (Solemn Judgment, Trap Dustshoot, Sakuretsu Armor, Dust Tornado) answer on the opponent's turn while the monsters keep attacking."},{"es":"Genera poca ventaja propia: gana atacando por encima de los monstruos rivales o con efectos de descarte, por eso necesita el ritmo.","en":"It creates little card advantage of its own: it wins by attacking over the opponent's monsters or through discard effects, so it needs the tempo."}]},"starters":[{"cards":["Reinforcement of the Army"],"route":{"es":"Una carta que se convierte en la respuesta: D.D. Warrior Lady, Mystic Swordsman LV2 contra un monstruo seteado, Blade Knight para presionar o Exiled Force.","en":"One card that becomes the answer: D.D. Warrior Lady, Mystic Swordsman LV2 against a set monster, Blade Knight to pressure, or Exiled Force."}},{"cards":["Don Zaloog"],"route":{"es":"Su efecto de descarte le da al mazo la ventaja de cartas que le falta.","en":"Its discard effect gives the deck the card advantage it lacks."}},{"cards":["Mystic Swordsman LV2"],"route":{"es":"Se usa contra los monstruos boca abajo.","en":"It is used against face-down monsters."}}],"chokepoints":[{"card":"Tsukuyomi","step":"summon","stepText":{"es":"Al invocarla de Normal o girarla: pone boca abajo en Defensa a uno de tus monstruos boca arriba.","en":"On Normal Summon or flip: it turns one of your face-up monsters face-down in Defense."},"loss":{"es":"Tu mejor atacante deja de atacar ese turno y Tsukuyomi vuelve a la mano para repetirlo. No pongas todo en un solo monstruo y repone cuerpos con Reinforcement.","en":"Your best attacker stops attacking that turn and Tsukuyomi returns to hand to repeat it. Do not put everything on one monster and refill bodies with Reinforcement."}},{"card":"Scapegoat","step":"main","stepText":{"es":"En la Main Phase rival: invoca 4 Sheep Tokens en Defensa.","en":"In the opponent's Main Phase: it Special Summons 4 Sheep Tokens in Defense."},"loss":{"es":"Los Tokens absorben tus ataques y, al estar boca arriba, Mystic Swordsman LV2 no los destruye. No gastes monstruos atacándolos sin necesidad.","en":"The Tokens absorb your attacks and, being face-up, Mystic Swordsman LV2 cannot destroy them. Do not spend monsters attacking them needlessly."}},{"card":"Mirror Force","step":"attack","stepText":{"es":"Cuando un monstruo tuyo declara un ataque.","en":"When one of your monsters declares an attack."},"loss":{"es":"Destruye todos tus monstruos en Ataque. Atacá con uno solo si hay Trampas boca abajo y guardá Dust Tornado o Heavy Storm para destaparlas.","en":"Destroys all your Attack Position monsters. Attack with one only if face-down Traps are present and save Dust Tornado or Heavy Storm to clear them."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Gravekeeper's Spy","qty":2,"why":{"es":"Criterio de la redacción: un Flip defensivo frena atacantes y invoca de Especial desde el Deck un Gravekeeper de 1500 de ATK o menos.","en":"Editorial judgment: a defensive Flip stalls attackers and Special Summons a Gravekeeper with 1500 or less ATK from the Deck."}}],"out":[{"card":"Sakuretsu Armor","qty":2,"why":{"es":"Criterio de la redacción: contra control seteado tiene pocos blancos, porque pide que el rival declare un ataque.","en":"Editorial judgment: against set control it has few targets, since it needs the opponent to declare an attack."}}]},"second":{"in":[{"card":"Smashing Ground","qty":1,"why":{"es":"Destruye al monstruo boca arriba con más DEF del rival.","en":"Destroys the opponent's face-up monster with the highest DEF."}}],"out":[{"card":"Premature Burial","qty":1,"why":{"es":"Criterio de la redacción: pagar LP en una partida donde vas segundo y bajo presión no conviene.","en":"Editorial judgment: paying LP in a game where you are second and under pressure does not pay off."}}]}},"updated":"2026-10-26","sources":[{"name":"Warrior (Goat Format Deck Guide)","url":"https://beta.goatformat.com/deck-guides/warrior","kind":"guide","checked":"2026-10-27"},{"name":"Reinforcement of the Army","url":"https://yugipedia.com/wiki/Reinforcement_of_the_Army","kind":"cards","checked":"2026-10-27"},{"name":"Tsukuyomi","url":"https://yugipedia.com/wiki/Tsukuyomi","kind":"cards","checked":"2026-10-27"},{"name":"Scapegoat","url":"https://yugipedia.com/wiki/Scapegoat","kind":"cards","checked":"2026-10-27"},{"name":"Mirror Force","url":"https://yugipedia.com/wiki/Mirror_Force","kind":"cards","checked":"2026-10-27"},{"name":"Smashing Ground","url":"https://yugipedia.com/wiki/Smashing_Ground","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas da esos cambios ni una estadística que los respalde.","en":"The Side Deck is editorial judgment: none of the linked sources gives those swaps or a statistic backing them."},{"es":"El texto de las cartas enlazado es el actual de Yugipedia y puede diferir del de 2005. La guía del mazo no tiene fecha.","en":"The linked card text is the current Yugipedia text and may differ from 2005. The deck guide is undated."}]},"goat/chaos-control":{"win":{"plan":"grind","pace":"slow","bullets":[{"es":"Juega al desgaste al principio: Scapegoat protege contra las amenazas grandes y Metamorphosis llega a Thousand-Eyes Restrict, que impide a los demás monstruos atacar o cambiar de posición.","en":"Plays for attrition early: Scapegoat protects against big threats and Metamorphosis reaches Thousand-Eyes Restrict, which stops other monsters from attacking or changing position."},{"es":"Chaos Sorcerer es el aporte de Chaos Turbo: junto a Restrict es la remoción que da ventaja; destierra un monstruo boca arriba una vez por turno y no puede atacar ese turno.","en":"Chaos Sorcerer is what Chaos Turbo contributes: together with Restrict it is the removal that creates advantage; it banishes a face-up monster once per turn and cannot attack that turn."},{"es":"En la variante con Thunder Dragon, es el LIGHT central y abre los efectos de descarte como Raigeki Break y Tribe-Infecting Virus.","en":"In the Thunder Dragon variant it is the core LIGHT monster and opens discard effects like Raigeki Break and Tribe-Infecting Virus."},{"es":"Tsukuyomi trabaja con los monstruos Flip (Magician of Faith, Gravekeeper's Spy) para ganar cartas; la guía suma Book of Moon, que la receta mostrada no juega.","en":"Tsukuyomi works with the Flip monsters (Magician of Faith, Gravekeeper's Spy) to gain cards; the guide adds Book of Moon, which the recipe shown does not play."}]},"starters":[{"cards":["Scapegoat","Metamorphosis"],"route":{"es":"Scapegoat da Sheep Tokens y Metamorphosis sobre uno trae a Thousand-Eyes Restrict: los demás monstruos del campo no pueden cambiar de posición ni atacar.","en":"Scapegoat gives Sheep Tokens and Metamorphosis on one brings out Thousand-Eyes Restrict: other monsters on the field cannot change position or attack."}},{"cards":["Thunder Dragon","Chaos Sorcerer"],"route":{"es":"Con Thunder Dragon (LIGHT) en el Cementerio y un DARK, Chaos Sorcerer entra desde la mano y después destierra un monstruo rival boca arriba.","en":"With Thunder Dragon (LIGHT) in the Graveyard and a DARK, Chaos Sorcerer comes in from the hand and then banishes a face-up opposing monster."}}],"chokepoints":[{"card":"Scapegoat","step":"main","stepText":{"es":"El rival la activa en su Main Phase y llena su campo de Sheep Tokens.","en":"The opponent activates it in their Main Phase and fills their field with Sheep Tokens."},"loss":{"es":"Pasás a ser el que no puede atacar. La guía incluye una copia de Asura Priest justamente para las Scapegoat rivales.","en":"You become the one who cannot attack. The guide includes a single Asura Priest precisely for opposing Scapegoats."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba en el campo rival antes de tu Chaos.","en":"Face-up on the opponent's field before your Chaos monster."},"loss":{"es":"Mientras esté boca arriba en el campo rival, vos no podés desterrar cartas de ningún Cementerio: Chaos Sorcerer y Black Luster Soldier - Envoy of the Beginning no se pueden invocar. Sacalo del campo antes, con un Chaos Sorcerer que ya esté en juego o con una Trampa.","en":"While it is face-up on the opponent's field, you cannot banish cards from either Graveyard: Chaos Sorcerer and Black Luster Soldier - Envoy of the Beginning cannot be summoned. Remove it from the field first, with a Chaos Sorcerer already in play or a Trap."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Trap Dustshoot","qty":2,"why":{"es":"Si el rival tiene 4 o más cartas en la mano, mirás su mano y devolvés un monstruo al Deck.","en":"If the opponent has 4 or more cards in hand, you look at it and shuffle one monster back into the Deck."}}],"out":[{"card":"Jar of Greed","qty":2,"why":{"es":"Criterio de la redacción: es lenta cuando necesitás interactuar.","en":"Editorial judgment: slow when you need to interact."}}]},"second":{"in":[{"card":"Mind Control","qty":1,"why":{"es":"Toma el control de un monstruo rival hasta la End Phase (no puede atacar ni ser tributado).","en":"Takes control of an opposing monster until the End Phase (it cannot attack or be Tributed)."}}],"out":[{"card":"Delinquent Duo","qty":1,"why":{"es":"Criterio de la redacción: cuesta LP y contra decks rápidos no compensa.","en":"Editorial judgment: costs LP and does not pay off against fast decks."}}]}},"updated":"2026-10-26","sources":[{"name":"Chaos Control","url":"https://www.goatformat.com/chaos-control.html","kind":"guide","checked":"2026-10-27"},{"name":"Goat Control","url":"https://yugipedia.com/wiki/Goat_Control","kind":"guide","checked":"2026-10-27"},{"name":"Thousand-Eyes Restrict","url":"https://yugipedia.com/wiki/Thousand-Eyes_Restrict","kind":"cards","checked":"2026-10-27"},{"name":"Chaos Sorcerer","url":"https://yugipedia.com/wiki/Chaos_Sorcerer","kind":"cards","checked":"2026-10-27"},{"name":"Kycoo the Ghost Destroyer","url":"https://yugipedia.com/wiki/Kycoo_the_Ghost_Destroyer","kind":"cards","checked":"2026-10-27"},{"name":"Tsukuyomi","url":"https://yugipedia.com/wiki/Tsukuyomi","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas da esos cambios ni una estadística que los respalde.","en":"The Side Deck is editorial judgment: none of the linked sources gives those swaps or a statistic backing them."},{"es":"El texto de las cartas enlazado es el actual de Yugipedia y puede diferir del de 2005. La página de la guía principal no muestra fecha.","en":"The linked card text is the current Yugipedia text and may differ from 2005. The main guide page shows no date."}]},"goat/goat-control":{"win":{"plan":"control","pace":"slow","bullets":[{"es":"Base de control clásica: Scapegoat da cuatro Sheep Tokens y Metamorphosis sobre uno trae a Thousand-Eyes Restrict para trabar el combate rival.","en":"Classic control core: Scapegoat gives four Sheep Tokens and Metamorphosis on one brings out Thousand-Eyes Restrict to lock the opponent's combat."},{"es":"Royal Decree niega los efectos de todas las demás Trampas, también las propias: la receta mostrada lo juega x3 y no lleva Trampas en el Main (Mirror Force y Torrential Tribute quedan en el Side). En las listas de YGOPRODeck, en cambio, está como mucho en el Side (1 en la de Long) y el Main juega Trampas.","en":"Royal Decree negates every other Trap's effects, your own included: the recipe shown plays it x3 and carries no Traps in the Main (Mirror Force and Torrential Tribute stay in the Side). In the YGOPRODeck lists, by contrast, it is at most in the Side (1 in Long's) and the Main plays Traps."},{"es":"Magician of Faith es el LIGHT que habilita a Black Luster Soldier y, al girar, recupera una Magia gastada.","en":"Magician of Faith is the LIGHT that enables Black Luster Soldier and, on flip, recovers a spent Spell."},{"es":"Su punto flojo es Nobleman of Crossout sobre una Magician of Faith seteada: destierra sus copias del Deck y con ellas tu LIGHT.","en":"Its weak spot is Nobleman of Crossout on a set Magician of Faith: it banishes its copies from the Deck and your LIGHT with them."}]},"starters":[{"cards":["Scapegoat","Metamorphosis"],"route":{"es":"Scapegoat y Metamorphosis sobre un Sheep Token: Thousand-Eyes Restrict, que puede equipar al mejor monstruo rival.","en":"Scapegoat plus Metamorphosis on a Sheep Token: Thousand-Eyes Restrict, which can equip the opponent's best monster."}},{"cards":["Magician of Faith"],"route":{"es":"Setearla como cebo, girar para recuperar una Magia gastada y dejar un LIGHT en el Cementerio.","en":"Set it as bait, flip to recover a spent Spell and leave a LIGHT in the Graveyard."}}],"chokepoints":[{"card":"Nobleman of Crossout","step":"activation","stepText":{"es":"Al activarla sobre tu Magician of Faith seteada.","en":"On activation against your set Magician of Faith."},"loss":{"es":"Destierra el monstruo y, por ser Flip, todas sus copias del Deck. Guardá otro LIGHT para Black Luster Soldier.","en":"Banishes the monster and, since it is a Flip monster, every copy in the Deck. Keep another LIGHT for Black Luster Soldier."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba antes de que invoques Black Luster Soldier.","en":"Face-up before you summon Black Luster Soldier."},"loss":{"es":"Mientras esté boca arriba en el campo rival, vos no podés desterrar cartas de ningún Cementerio: Black Luster Soldier - Envoy of the Beginning no se puede invocar. Thousand-Eyes Restrict puede equiparlo para sacarlo de juego.","en":"While it is face-up on the opponent's field, you cannot banish cards from either Graveyard: Black Luster Soldier - Envoy of the Beginning cannot be summoned. Thousand-Eyes Restrict can equip it to take it off the field."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Kycoo the Ghost Destroyer","qty":1,"why":{"es":"Boca arriba en tu campo, impide al rival desterrar cartas de los Cementerios: frena los Chaos de Chaos Turbo.","en":"Face-up on your field, it stops the opponent from banishing cards from Graveyards: it stalls Chaos Turbo's Chaos monsters."}}],"out":[{"card":"Tsukuyomi","qty":1,"why":{"es":"Criterio de la redacción.","en":"Editorial judgment."}}]},"second":{"in":[{"card":"Chaos Sorcerer","qty":1,"why":{"es":"Destierra un monstruo boca arriba por turno.","en":"Banishes a face-up monster each turn."}}],"out":[{"card":"United We Stand","qty":1,"why":{"es":"Criterio de la redacción: yendo segundo necesitás respuestas, no un equipo que depende de tener tablero.","en":"Editorial judgment: going second you need answers, not an equip that relies on having a board."}}]}},"updated":"2026-10-26","sources":[{"name":"Goat Control","url":"https://yugipedia.com/wiki/Goat_Control","kind":"guide","checked":"2026-10-27"},{"name":"History of the Meta - Part 4: Goat Control","url":"https://ygoprodeck.com/history-of-the-meta-part-4-goat-control/","kind":"guide","checked":"2026-10-27"},{"name":"Thousand-Eyes Restrict","url":"https://yugipedia.com/wiki/Thousand-Eyes_Restrict","kind":"cards","checked":"2026-10-27"},{"name":"Royal Decree","url":"https://yugipedia.com/wiki/Royal_Decree","kind":"cards","checked":"2026-10-27"},{"name":"Nobleman of Crossout","url":"https://yugipedia.com/wiki/Nobleman_of_Crossout","kind":"cards","checked":"2026-10-27"},{"name":"Kycoo the Ghost Destroyer","url":"https://yugipedia.com/wiki/Kycoo_the_Ghost_Destroyer","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas da esos cambios ni una estadística que los respalde.","en":"The Side Deck is editorial judgment: none of the linked sources gives those swaps or a statistic backing them."}]},"goat/chaos-warrior-turbo":{"win":{"plan":"tempo","pace":"medium","bullets":[{"es":"Híbrido de Warrior y Chaos: un mazo agresivo que castiga a los Flip y a las configuraciones lentas; la guía presenta a Reinforcement of the Army como posiblemente su mejor carta y a Chaos Sorcerer como su aguante en el final de la partida.","en":"Hybrid of Warrior and Chaos: an aggressive deck that punishes Flip monsters and slow setups; the guide presents Reinforcement of the Army as arguably its best card and Chaos Sorcerer as its late-game staying power."},{"es":"Busca intercambios 1 a 1 con pocas cartas: los monstruos que mueren en batalla dejan en el Cementerio el LIGHT y el DARK que pide Chaos Sorcerer.","en":"It looks for 1-for-1 trades with few cards: monsters that die in battle leave in the Graveyard the LIGHT and DARK that Chaos Sorcerer needs."},{"es":"Kycoo responde a los monstruos LIGHT y DARK y, en parte, a Thunder Dragon, según la guía de Moxies, que lo juega x3 (la receta mostrada, x1).","en":"Kycoo answers LIGHT and DARK monsters and, to an extent, Thunder Dragon, according to Moxies' guide, which plays it x3 (the recipe shown, x1)."},{"es":"Se traba si tiene Chaos en la mano sin LIGHT y DARK en el Cementerio: la guía lista de 15 a 17 monstruos (13 a 14 en un Warrior estándar) para evitarlo.","en":"It stalls if you hold Chaos monsters without LIGHT and DARK in the Graveyard: the guide lists 15 to 17 monsters (13 to 14 in a standard Warrior) to avoid it."}]},"starters":[{"cards":["Reinforcement of the Army"],"route":{"es":"Agrega un Warrior de Nivel 4 o menos: D.D. Warrior Lady, Mystic Swordsman LV2, Blade Knight o Exiled Force; la guía destaca que se convierte en muchas cartas distintas.","en":"Adds a Level 4 or lower Warrior: D.D. Warrior Lady, Mystic Swordsman LV2, Blade Knight or Exiled Force; the guide highlights that it becomes many different cards."}},{"cards":["Chaos Sorcerer"],"route":{"es":"Con un LIGHT y un DARK en el Cementerio entra desde la mano y destierra un monstruo rival.","en":"With a LIGHT and a DARK in the Graveyard it comes in from the hand and banishes an opposing monster."}}],"chokepoints":[{"card":"Scapegoat","step":"main","stepText":{"es":"El rival activa Scapegoat en su Main Phase y llena su campo de Sheep Tokens.","en":"The opponent activates Scapegoat in their Main Phase and fills their field with Sheep Tokens."},"loss":{"es":"La guía marca que con poco Book of Moon el mazo sufre contra los mazos de Scapegoat y Metamorphosis. Chaos Sorcerer destierra un Token boca arriba por turno.","en":"The guide notes that with little Book of Moon the deck struggles against Scapegoat and Metamorphosis decks. Chaos Sorcerer banishes a face-up Token each turn."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba en el campo rival antes de tu Chaos.","en":"Face-up on the opponent's field before your Chaos."},"loss":{"es":"Mientras esté boca arriba en el campo rival, vos no podés desterrar cartas de ningún Cementerio: Chaos Sorcerer y Black Luster Soldier - Envoy of the Beginning no se pueden invocar. Sacalo del campo antes, por ejemplo con Exiled Force o Raigeki Break.","en":"While it is face-up on the opponent's field, you cannot banish cards from either Graveyard: Chaos Sorcerer and Black Luster Soldier - Envoy of the Beginning cannot be summoned. Remove it from the field first, for example with Exiled Force or Raigeki Break."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Gravekeeper's Spy","qty":2,"why":{"es":"Criterio de la redacción: la guía marca difíciles los cruces con Chaos Control y Goat Control, y este Flip defensivo invoca de Especial desde el Deck un Gravekeeper de 1500 de ATK o menos.","en":"Editorial judgment: the guide marks the Chaos Control and Goat Control matchups as difficult, and this defensive Flip Special Summons a Gravekeeper with 1500 or less ATK from the Deck."}}],"out":[{"card":"Nobleman of Crossout","qty":2,"why":{"es":"La guía marca a Nobleman of Crossout como débil en el Main.","en":"The guide marks Nobleman of Crossout as weak in the Main."}}]},"second":{"in":[{"card":"Sakuretsu Armor","qty":2,"why":{"es":"Destruye al monstruo que declara el ataque; cubre tu primer turno yendo segundo.","en":"Destroys the monster that declares the attack; it covers your first turn going second."}}],"out":[{"card":"Nobleman of Crossout","qty":2,"why":{"es":"La guía marca a Nobleman of Crossout como débil en el Main.","en":"The guide marks Nobleman of Crossout as weak in the Main."}}]}},"updated":"2026-10-26","sources":[{"name":"Chaos Warrior: An Analysis by Moxies","url":"https://www.goatformat.com/home/chaos-warrior-an-analysis-by-moxies","kind":"guide","checked":"2026-10-27"},{"name":"Warrior (Goat Format Deck Guide)","url":"https://beta.goatformat.com/deck-guides/warrior","kind":"guide","checked":"2026-10-27"},{"name":"Kycoo the Ghost Destroyer","url":"https://yugipedia.com/wiki/Kycoo_the_Ghost_Destroyer","kind":"cards","checked":"2026-10-27"},{"name":"Reinforcement of the Army","url":"https://yugipedia.com/wiki/Reinforcement_of_the_Army","kind":"cards","checked":"2026-10-27"},{"name":"Chaos Sorcerer","url":"https://yugipedia.com/wiki/Chaos_Sorcerer","kind":"cards","checked":"2026-10-27"},{"name":"April 2005 Lists","url":"https://yugipedia.com/wiki/April_2005_Lists","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"La guía principal es de mayo de 2021 y la de Warrior no tiene fecha.","en":"The main guide is from May 2021 and the Warrior one is undated."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas da esos cambios ni una estadística que los respalde.","en":"The Side Deck is editorial judgment: none of the linked sources gives those swaps or a statistic backing them."}]},"goat/chaos-return":{"win":{"plan":"tempo","pace":"medium","bullets":[{"es":"La guía lo arma sobre Return from the Different Dimension (3 copias; la receta mostrada juega 1): Chaos Sorcerer y Nobleman of Crossout (también sobre monstruos propios) destierran, y Return los trae de vuelta de golpe pagando la mitad de los LP; se destierran otra vez en la End Phase.","en":"The guide builds it on Return from the Different Dimension (3 copies; the recipe shown plays 1): Chaos Sorcerer and Nobleman of Crossout (also on your own monsters) banish, and Return brings them all back at once for half your LP; they are banished again in the End Phase."},{"es":"Gravekeeper's Spy y Dekoichi van x3 cada uno, en la guía y en la receta; si el rival usa Nobleman sobre uno de tus Flip, Return lo recupera. La guía suma Thunder Dragon x3, que la receta mostrada no juega.","en":"Gravekeeper's Spy and Dekoichi run x3 each, in the guide and in the recipe; if the opponent uses Nobleman on one of your Flips, Return gets it back. The guide adds Thunder Dragon x3, which the recipe shown does not play."},{"es":"Solemn Judgment x3 y Book of Moon (x3 en la guía, x2 en la receta mostrada) dan control; la guía suma Magician of Faith y Gravekeeper's Guard (x2 de cada uno), ausentes de la receta.","en":"Solemn Judgment x3 and Book of Moon (x3 in the guide, x2 in the recipe shown) give control; the guide adds Magician of Faith and Gravekeeper's Guard (x2 each), absent from the recipe."},{"es":"Las variantes más agresivas de la guía suman Asura Priest, Skilled Dark Magician y Skilled White Magician; Mystic Tomato y Shining Angel son opcionales y buenos blancos de Return por sus stats (la receta mostrada juega Shining Angel x3).","en":"The guide's more aggressive variants add Asura Priest, Skilled Dark Magician and Skilled White Magician; Mystic Tomato and Shining Angel are optional and good Return targets because of their stats (the recipe shown plays Shining Angel x3)."}]},"starters":[{"cards":["Return from the Different Dimension","Nobleman of Crossout"],"route":{"es":"Nobleman sobre un Flip (tuyo o del rival) lo destierra; cuando hay varios fuera, pagás la mitad de los LP y Return los trae de vuelta.","en":"Nobleman on a Flip monster (yours or theirs) banishes it; once several are out, pay half your LP and Return brings them back."}},{"cards":["Chaos Sorcerer"],"route":{"es":"El costo de destierro de Chaos Sorcerer deja monstruos fuera del juego para que Return los devuelva.","en":"Chaos Sorcerer's banish cost leaves monsters out of play for Return to bring back."}},{"cards":["Gravekeeper's Spy","Dekoichi the Battlechanted Locomotive"],"route":{"es":"Son el combustible principal de destierro de la guía, y la receta mostrada los juega x3 cada uno.","en":"They are the guide's main banish fuel, and the recipe shown plays them x3 each."}}],"chokepoints":[{"card":"Royal Decree","step":"activation","stepText":{"es":"Boca arriba antes de que actives Return: niega los efectos de las demás Trampas.","en":"Face-up before you activate Return: it negates other Traps' effects."},"loss":{"es":"Ese Royal Decree apaga tu Return. Sacalo con Mystical Space Typhoon o Heavy Storm antes de la jugada, sin que te destruya tu propio Return.","en":"That Royal Decree shuts off your Return. Clear it with Mystical Space Typhoon or Heavy Storm before the play, without it destroying your own Return."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba antes de tu Chaos Sorcerer.","en":"Face-up before your Chaos Sorcerer."},"loss":{"es":"Mientras esté boca arriba en el campo rival, vos no podés desterrar cartas de ningún Cementerio: Chaos Sorcerer no se puede invocar. Sacalo del campo antes con una Trampa o un Chaos Sorcerer ya en juego.","en":"While it is face-up on the opponent's field, you cannot banish cards from either Graveyard: Chaos Sorcerer cannot be summoned. Remove it from the field first with a Trap or a Chaos Sorcerer already in play."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Sakuretsu Armor","qty":2,"why":{"es":"Destruye al monstruo que declara el ataque, sin gastar monstruos propios.","en":"Destroys the monster that declares the attack, without spending your own monsters."}}],"out":[{"card":"Shining Angel","qty":2,"why":{"es":"La guía lo marca como opcional.","en":"The guide marks it as optional."}}]},"second":{"in":[{"card":"Smashing Ground","qty":1,"why":{"es":"Destruye al monstruo boca arriba con más DEF del rival.","en":"Destroys the opponent's face-up monster with the highest DEF."}}],"out":[{"card":"Shining Angel","qty":1,"why":{"es":"La guía lo marca como opcional.","en":"The guide marks it as optional."}}]}},"updated":"2026-10-26","sources":[{"name":"Chaos Return","url":"https://www.goatformat.com/chaos-return.html","kind":"guide","checked":"2026-10-27"},{"name":"Alternate Format Analysis - Goat Format - The Goat Format Metagame","url":"https://ygoprodeck.com/alternate-format-analysis-goat-format-goat-format-metagame/","kind":"guide","checked":"2026-10-27"},{"name":"Return from the Different Dimension","url":"https://yugipedia.com/wiki/Return_from_the_Different_Dimension","kind":"cards","checked":"2026-10-27"},{"name":"Nobleman of Crossout","url":"https://yugipedia.com/wiki/Nobleman_of_Crossout","kind":"cards","checked":"2026-10-27"},{"name":"Royal Decree","url":"https://yugipedia.com/wiki/Royal_Decree","kind":"cards","checked":"2026-10-27"},{"name":"Kycoo the Ghost Destroyer","url":"https://yugipedia.com/wiki/Kycoo_the_Ghost_Destroyer","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"La guía de Chaos Return difiere de la receta mostrada: la guía juega Return x3, Thunder Dragon, Magician of Faith y Gravekeeper's Guard, y la receta juega Return x1 y no lleva esos tres.","en":"The Chaos Return guide differs from the recipe shown: the guide plays Return x3, Thunder Dragon, Magician of Faith and Gravekeeper's Guard, while the recipe plays Return x1 and none of those three."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas da esos cambios ni una estadística que los respalde.","en":"The Side Deck is editorial judgment: none of the linked sources gives those swaps or a statistic backing them."}]},"hat/artifact-traptrix":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Juega a responder: los Artifacts se Setean desde la mano como Magias y, si el rival los destruye en su turno, entran por Invocación Especial con su efecto (Moralltach destruye una carta boca arriba del rival).","en":"It plays to respond: Artifacts are Set from the hand as Spells and, if the opponent destroys them on their turn, they Special Summon with their effect (Moralltach destroys a face-up card the opponent controls)."},{"es":"Traptrix Myrmeleo busca una trampa Hole al invocarse por Normal y destruye una Magia/Trampa rival si entra por Invocación Especial; Dionaea revive un Traptrix y vuelve a Setear una Hole del Cementerio.","en":"Traptrix Myrmeleo searches a Hole Trap when Normal Summoned and destroys an opposing Spell/Trap if Special Summoned; Dionaea revives a Traptrix and re-Sets a Hole Trap from the Graveyard."},{"es":"Fire Hand e Ice Hand castigan que el rival los destruya: uno destruye un monstruo, el otro una Magia/Trampa, y cada uno trae a su par del Deck. Por eso el rival duda en atacarlos.","en":"Fire Hand and Ice Hand punish the opponent for destroying them: one destroys a monster, the other a Spell/Trap, and each brings out its partner from the Deck. That is why the opponent hesitates to attack them."},{"es":"Es lento y poco explosivo: aguanta bien a Lightsworn Ruler, pero arranca flojo contra un Geargia que juega a la defensiva. Cierra con Rango 5 (Artifact Durendal, Constellar Pleiades) o Number 103: Ragnazero.","en":"It is slow and not very explosive: it holds up well against Lightsworn Ruler but starts weak against a defensive Geargia. It closes with Rank 5 (Artifact Durendal, Constellar Pleiades) or Number 103: Ragnazero."}]},"starters":[{"cards":["Traptrix Myrmeleo"],"route":{"es":"Normal Summon de Myrmeleo: buscás Bottomless Trap Hole, Void Trap Hole o Traptrix Trap Hole Nightmare y dejás el campo cubierto de trampas.","en":"Normal Summon Myrmeleo: you search Bottomless Trap Hole, Void Trap Hole or Traptrix Trap Hole Nightmare and leave the field covered in Traps."}},{"cards":["Artifact Moralltach","Artifact Ignition"],"route":{"es":"Ignition (rápida) destruye tu propio Moralltach Seteado en el turno del rival: entra por Invocación Especial y destruye una carta boca arriba, y además Seteás otro Artifact del Deck.","en":"Ignition (Quick-Play) destroys your own Set Moralltach on the opponent's turn: it Special Summons and destroys a face-up card, and you also Set another Artifact from the Deck."}},{"cards":["Artifact Sanctum","Soul Charge"],"route":{"es":"Sanctum trae un Artifact del Deck y Soul Charge revive otro del Cementerio: dos monstruos de Nivel 5 LIGHT para Constellar Pleiades o Artifact Durendal (Sanctum y Soul Charge te impiden pasar a la Battle Phase ese turno).","en":"Sanctum brings out an Artifact from the Deck and Soul Charge revives another from the Graveyard: two Level 5 LIGHT monsters for Constellar Pleiades or Artifact Durendal (Sanctum and Soul Charge stop you from going to the Battle Phase that turn)."}}],"chokepoints":[{"card":"Royal Decree","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Anula los efectos de las demás Trampas: Sanctum, Call of the Haunted y las Hole no hacen nada. Se saca con Double Cyclone, Artifact Ignition o Myrmeleo invocado por Invocación Especial.","en":"Negates the effects of all other Traps: Sanctum, Call of the Haunted and the Hole Traps do nothing. Remove it with Double Cyclone, Artifact Ignition or a Special Summoned Myrmeleo."}},{"card":"Trap Stun","step":"resolution","stepText":{"es":"En respuesta a tu Trampa, antes de que se resuelva.","en":"In response to your Trap, before it resolves."},"loss":{"es":"Anula los efectos de las demás Trampas ese turno, incluida la que acabás de activar. No frena a los monstruos: Myrmeleo, las Hands y Moralltach siguen funcionando, así que jugá con ellos ese turno.","en":"Negates the effects of all other Traps this turn, including the one you just activated. It does not stop monsters: Myrmeleo, the Hands and Moralltach keep working, so play with them that turn."}},{"card":"Skill Drain","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase.","en":"Face-up before your Main Phase."},"loss":{"es":"Anula a Myrmeleo y el efecto de destruir de Moralltach, que dependen del monstruo boca arriba en el campo. Las Hands actúan desde el Cementerio y Skill Drain no las frena. Sacalo con Double Cyclone o Artifact Ignition antes de jugar monstruos.","en":"Negates Myrmeleo and Moralltach's destruction effect, which depend on the monster being face-up on the field. The Hands act from the Graveyard and Skill Drain does not stop them. Remove it with Double Cyclone or Artifact Ignition before playing monsters."}},{"card":"Solemn Warning","step":"activation","stepText":{"es":"Cuando Moralltach activa su efecto para invocarse en el turno del rival.","en":"When Moralltach activates its effect to Special Summon itself on the opponent's turn."},"loss":{"es":"Anula la activación: Moralltach no vuelve al campo y no destruye nada. Tené más de un Artifact Seteado para que no sea tu única jugada.","en":"Negates the activation: Moralltach does not come back to the field and destroys nothing. Keep more than one Artifact Set so it is not your only play."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, en respuesta al efecto de Myrmeleo.","en":"In your Main Phase, in response to Myrmeleo's effect."},"loss":{"es":"Anula el efecto y no buscás la Hole. Normal Summon de Myrmeleo solo cuando ya tengas otra jugada de reserva en la mano.","en":"Negates the effect and you do not search the Hole. Normal Summon Myrmeleo only when you already have another play in hand."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Black Horn of Heaven","qty":1,"why":{"es":"Frena una Invocación Especial del rival que no abre cadena (Xyz, Sincro, Judgment Dragon): el rival va segundo y llega con la mano completa.","en":"Stops an opponent's Special Summon that does not start a Chain (Xyz, Synchro, Judgment Dragon): the opponent goes second and arrives with a full hand."}}],"out":[{"card":"Dark Hole","qty":1,"why":{"es":"Sin monstruos que destruir en tu primer turno.","en":"No monsters to destroy on your first turn."}}]},"second":{"in":[{"card":"Debunk","qty":2,"why":{"es":"Anula efectos de monstruos activados desde la mano o el Cementerio (Dragon Rulers, Mermail) de un rival que ya armó campo.","en":"Negates monster effects activated from the hand or Graveyard (Dragon Rulers, Mermail) from an opponent who already built a board."}}],"out":[{"card":"Cardcar D","qty":2,"why":{"es":"Termina tu turno y no se invoca por Invocación Especial; yendo segundo necesitás la Battle Phase y los recursos para responder.","en":"It ends your turn and cannot be Special Summoned; going second you need the Battle Phase and resources to respond."}}]}},"updated":"2026-10-26","sources":[{"name":"Format History: Early HAT Format","url":"https://ygoprodeck.com/format-history-early-hat-format/","kind":"guide","checked":"2026-10-27"},{"name":"Format History: High HAT Format","url":"https://ygoprodeck.com/article/format-history-high-hat-format-26051","kind":"guide","checked":"2026-10-27"},{"name":"Artifact Moralltach","url":"https://yugipedia.com/wiki/Artifact_Moralltach","kind":"cards","checked":"2026-10-27"},{"name":"Traptrix Myrmeleo","url":"https://yugipedia.com/wiki/Traptrix_Myrmeleo","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"Las guías hablan de variantes híbridas (la del EUWCQ y el NAWCQ era un Fire Fist-Artifact-Traptrix) y de que muchos jugadores recortaron las Hands más tarde: la lista exacta de la ficha es una versión, no la única.","en":"The guides talk about hybrid variants (the EUWCQ and NAWCQ build was a Fire Fist-Artifact-Traptrix) and say many players later cut the Hands: the sheet's exact list is one version, not the only one."},{"es":"HAT no tiene una lista publicada de cartas legales (se toman las de primera impresión hasta la fecha del formato): si una carta de la ficha te genera dudas, comprobá su fecha de salida.","en":"HAT has no published list of legal cards (cards with a first print up to the format's date are taken): if a card on this sheet raises doubts, check its release date."}]},"hat/mermail":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Todo gira alrededor de descartar monstruos WATER: Abyssteus (descarta 1) y Abyssmegalo (descarta 2) salen de la mano, y Abyssteus busca un Mermail de Nivel 4 o menos.","en":"Everything revolves around discarding WATER monsters: Abyssteus (discard 1) and Abyssmegalo (discard 2) come out of the hand, and Abyssteus searches a Level 4 or lower Mermail."},{"es":"El descarte dispara otros efectos: Abyssgunde revive un Mermail del Cementerio al ser descartado, y Atlantean Marksman o Heavy Infantry, mandados como coste, destruyen una carta Seteada o una boca arriba del rival.","en":"The discard triggers other effects: Abyssgunde revives a Mermail from the Graveyard when discarded, and Atlantean Marksman or Heavy Infantry, sent as a cost, destroy a Set card or a face-up card of the opponent."},{"es":"Soul Charge devuelve 2 o 3 monstruos de Nivel 7 del Cementerio para armar Mermail Abyssgaios (Rango 7) u otro Xyz que cierra la partida.","en":"Soul Charge brings back 2 or 3 Level 7 monsters from the Graveyard to build Mermail Abyssgaios (Rank 7) or another Xyz that finishes the game."},{"es":"Funciona bien en un formato lleno de trampas porque desgasta al rival hasta resolver Soul Charge o Abyssmegalo, pero depende del Cementerio y de tener WATER en la mano para pagar los descartes.","en":"It works well in a trap-heavy format because it grinds the opponent down until Soul Charge or Abyssmegalo resolves, but it depends on the Graveyard and on holding WATER monsters in hand to pay the discards."}]},"starters":[{"cards":["Mermail Abyssteus","Atlantean Marksman"],"route":{"es":"Descartás Marksman como coste de Abyssteus: destruye una carta Seteada del rival, y Abyssteus entra de la mano y busca otro Mermail de Nivel 4 o menos.","en":"Discard Marksman as Abyssteus's cost: it destroys a Set card of the opponent, and Abyssteus comes in from the hand and searches another Level 4 or lower Mermail."}},{"cards":["Mermail Abyssmegalo","Mermail Abyssgunde"],"route":{"es":"Abyssgunde descartado como coste de Megalo revive otro Mermail del Cementerio, y Megalo busca Abyss-sphere para seguir invocando Mermail del Deck.","en":"Abyssgunde discarded as Megalo's cost revives another Mermail from the Graveyard, and Megalo searches Abyss-sphere to keep summoning Mermail from the Deck."}},{"cards":["Soul Charge","Mermail Abyssteus"],"route":{"es":"Abyssteus de Nivel 7 queda en el Cementerio como descarte; Soul Charge lo trae de vuelta con otro Nivel 7 para Mermail Abyssgaios (cada monstruo invocado te cuesta 1000 LP).","en":"Level 7 Abyssteus sits in the Graveyard as a discard; Soul Charge brings it back with another Level 7 for Mermail Abyssgaios (each monster Summoned costs you 1000 LP)."}}],"chokepoints":[{"card":"Maxx \"C\"","step":"activation","stepText":{"es":"Antes de tu primera Invocación Especial, desde la mano.","en":"Before your first Special Summon, from the hand."},"loss":{"es":"Cada Invocación Especial le da una carta al rival, y Mermail hace muchas. Soul Charge invoca varios a la vez y cuenta como un solo robo.","en":"Each Special Summon gives the opponent a card, and Mermail makes many. Soul Charge summons several at once and counts as a single draw."}},{"card":"Solemn Warning","step":"activation","stepText":{"es":"Cuando activás el efecto de Abyssteus o Abyssmegalo para invocarlo desde la mano.","en":"When you activate Abyssteus's or Abyssmegalo's effect to summon it from the hand."},"loss":{"es":"Anula la activación con los descartes ya pagados y Abyssteus o Abyssmegalo no entra. Abrí con un Mermail de menos valor para gastar la Solemn Warning.","en":"Negates the activation with the discards already paid and Abyssteus or Abyssmegalo does not come in. Open with a lower-value Mermail to bait the Solemn Warning."}},{"card":"Debunk","step":"activation","stepText":{"es":"Cuando activás el efecto de Abyssteus o Abyssmegalo desde la mano.","en":"When you activate Abyssteus's or Abyssmegalo's effect from the hand."},"loss":{"es":"Anula el efecto y destierra el monstruo; los descartes no vuelven. Abrí con un Mermail de menos valor para gastarle el Debunk.","en":"Negates the effect and banishes the monster; the discards do not come back. Open with a lower-value Mermail to bait the Debunk."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Los monstruos mandados al Cementerio se destierran: Abyssgunde y los Atlantean dejan de funcionar, y los descartes ya no dejan monstruos para Soul Charge. Se saca con Mystical Space Typhoon.","en":"Monsters sent to the Graveyard are banished: Abyssgunde and the Atlantean stop working, and discards no longer leave monsters for Soul Charge. Remove it with Mystical Space Typhoon."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"En respuesta a Soul Charge, con sus objetivos ya elegidos.","en":"In response to Soul Charge, with its targets already chosen."},"loss":{"es":"Destierra uno de los monstruos objetivo y Soul Charge trae uno menos. Apuntá a la mayor cantidad posible de Nivel 7 para que queden suficientes para el Xyz.","en":"Banishes one of the targeted monsters and Soul Charge brings back one fewer. Target as many Level 7s as possible so enough remain for the Xyz."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Maxx \"C\"","qty":2,"why":{"es":"El rival que va segundo invoca mucho en su turno: cada invocación te hace robar.","en":"The opponent going second summons a lot on their turn: each summon draws you a card."}}],"out":[{"card":"Forbidden Lance","qty":2,"why":{"es":"Sin Battle Phase en tu primer turno, solo sirve para proteger o ganar un combate.","en":"With no Battle Phase on your first turn, it only protects or wins a combat."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":2,"why":{"es":"En un formato de backrow pesado, abre las trampas Seteadas del rival que ya movió primero.","en":"In a backrow-heavy format, it opens the Set Traps of an opponent who already moved first."}}],"out":[{"card":"Upstart Goblin","qty":2,"why":{"es":"Le da 1000 LP al rival, y yendo segundo te conviene más abrir su backrow que seguir robando.","en":"It gives the opponent 1000 LP, and going second you gain more from opening their backrow than from drawing further."}}]}},"updated":"2026-10-26","sources":[{"name":"Format History: Early HAT Format","url":"https://ygoprodeck.com/format-history-early-hat-format/","kind":"guide","checked":"2026-10-27"},{"name":"Format History: High HAT Format","url":"https://ygoprodeck.com/article/format-history-high-hat-format-26051","kind":"guide","checked":"2026-10-27"},{"name":"Mermail Abyssteus","url":"https://yugipedia.com/wiki/Mermail_Abyssteus","kind":"cards","checked":"2026-10-27"},{"name":"Soul Charge","url":"https://yugipedia.com/wiki/Soul_Charge","kind":"cards","checked":"2026-10-27"},{"name":"April 2014 Lists (TCG)","url":"https://yugipedia.com/wiki/April_2014_Lists_(TCG)","kind":"list","checked":"2026-10-27"}],"limits":[{"es":"Las fuentes separan dos momentos: en el Early HAT Mermail estaba poco desarrollado (Abyssgunde limitada en abril de 2014, un solo Mermail en el top 32 de YCS Philadelphia) y ganó el EUWCQ en el High HAT. La ficha describe el segundo.","en":"The sources split two moments: in Early HAT Mermail was underdeveloped (Abyssgunde Limited in April 2014, a single Mermail in the YCS Philadelphia top 32) and it won the EUWCQ in High HAT. The sheet describes the second."},{"es":"HAT no tiene una lista publicada de cartas legales (se toman las de primera impresión hasta la fecha del formato): si una carta de la ficha te genera dudas, comprobá su fecha de salida.","en":"HAT has no published list of legal cards (cards with a first print up to the format's date are taken): if a card on this sheet raises doubts, check its release date."}]},"hat/geargia":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Mazo de desgaste y defensa: pone monstruos baratos en Defensa y trampas atrás (Fiendish Chain, Solemn Warning, Torrential Tribute) en lugar de atacar.","en":"A grinding, defensive deck: it puts cheap monsters in Defense and Traps behind them (Fiendish Chain, Solemn Warning, Torrential Tribute) instead of attacking."},{"es":"Geargiarmor se Setea y, al voltearse, busca otro Geargia; Geargiarsenal se tributa para invocar uno del Deck; Geargiaccelerator suma un Geargia a la mano y Gear Gigant X invoca de Especial desde el Cementerio un Geargia de nivel 3 o menos.","en":"Geargiarmor is Set and, when flipped, searches another Geargia; Geargiarsenal Tributes itself to summon one from the Deck; Geargiaccelerator adds a Geargia to the hand and Gear Gigant X Special Summons a Level 3 or lower Geargia from the Graveyard."},{"es":"Geargiagear es el cierre en la End Phase del rival: trae 2 Geargiano de Nivel 4 para armar Gear Gigant X, y al rival le cuesta responder.","en":"Geargiagear is the closer on the opponent's End Phase: it brings 2 Level 4 Geargiano to build Gear Gigant X, and the opponent struggles to answer."},{"es":"Arranca lento: le gana a casi todo el campo, pero pierde contra un Lightsworn Ruler explosivo: Judgment Dragon barre sus cartas y Lightray Diabolos devuelve al Deck una carta Seteada.","en":"It starts slowly: it beats most of the field but loses to an explosive Lightsworn Ruler: Judgment Dragon wipes its cards and Lightray Diabolos sends a Set card back to the Deck."}]},"starters":[{"cards":["Geargiano Mk-II","Geargiaccelerator"],"route":{"es":"Mk-II invoca a Geargiarmor (de la mano o el Cementerio) en Defensa y Geargiaccelerator entra de la mano: dos Nivel 4 Machine para Gear Gigant X.","en":"Mk-II summons Geargiarmor (from the hand or Graveyard) in Defense and Geargiaccelerator enters from the hand: two Level 4 Machines for Gear Gigant X."}},{"cards":["Geargiarmor"],"route":{"es":"Seteado en Defensa: cuando lo ataquen se voltea y busca otro Geargia del Deck, así que el rival no sabe si atacarlo.","en":"Set in Defense: when attacked it flips and searches another Geargia from the Deck, so the opponent does not know whether to attack it."}},{"cards":["Geargiagear"],"route":{"es":"Seteada y activada en la End Phase del rival: dos Geargiano de Nivel 4 que armás en Gear Gigant X en tu turno.","en":"Set and activated on the opponent's End Phase: two Level 4 Geargiano that you turn into Gear Gigant X on your turn."}}],"chokepoints":[{"card":"Judgment Dragon","step":"activation","stepText":{"es":"Al pagar 1000 LP para destruir todas las demás cartas.","en":"When paying 1000 LP to destroy all other cards."},"loss":{"es":"Barre tus trampas y monstruos de un solo efecto. Geargiaccelerator y Gear Gigant X reponen Geargia al irse (uno a la mano, otro desde el Cementerio), así que conservá esos dos para reponer.","en":"Wipes your Traps and monsters with one effect. Geargiaccelerator and Gear Gigant X replace Geargia when they leave (one to the hand, one from the Graveyard), so keep those two to rebuild."}},{"card":"Lightray Diabolos","step":"activation","stepText":{"es":"En su Main Phase, apuntando a tu carta Seteada.","en":"In its Main Phase, targeting your Set card."},"loss":{"es":"Manda al Deck (arriba o abajo) una trampa o a Geargiarmor Seteados. Es un efecto de Ignición: solo lo usa en su Main Phase, así que podés responder activando la trampa Seteada si su condición se cumple.","en":"Sends a Set Trap or Geargiarmor to the Deck (top or bottom). It is an Ignition effect: they can only use it in their Main Phase, so you can respond by activating the Set Trap if its condition is met."}},{"card":"Nobleman of Crossout","step":"activation","stepText":{"es":"Contra Geargiarmor boca abajo, antes de que se voltee.","en":"Against a face-down Geargiarmor, before it flips."},"loss":{"es":"Lo destruye y lo destierra sin que busque nada. Jugá otro Geargia delante para que el rival no lo apunte primero.","en":"Destroys and banishes it without it searching anything. Play another Geargia in front so the opponent does not target it first."}},{"card":"Mind Crush","step":"resolution","stepText":{"es":"Al resolverse, nombrando Geargiaccelerator o Geargiano Mk-II.","en":"On resolution, naming Geargiaccelerator or Geargiano Mk-II."},"loss":{"es":"Descartás todas las copias de esa carta de la mano. Jugá primero la carta que más temés que nombren.","en":"You discard every copy of that card from your hand. Play first the card you fear they will name."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Los monstruos que irían al Cementerio se destierran: Geargiaccelerator, Gear Gigant X y Geargiano Mk-II pierden su recursión. Sacalo con Mystical Space Typhoon.","en":"Monsters that would go to the Graveyard are banished: Geargiaccelerator, Gear Gigant X and Geargiano Mk-II lose their recursion. Remove it with Mystical Space Typhoon."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Black Horn of Heaven","qty":1,"why":{"es":"Frena una Invocación Especial del rival que no abre cadena (Xyz, Sincro, Judgment Dragon): el rival va segundo.","en":"Stops an opponent's Special Summon that does not start a Chain (Xyz, Synchro, Judgment Dragon): the opponent goes second."}},{"card":"Debunk","qty":1,"why":{"es":"Anula un efecto activado desde la mano o el Cementerio del rival.","en":"Negates an effect activated from the opponent's hand or Graveyard."}}],"out":[{"card":"Mind Control","qty":1,"why":{"es":"Sin monstruos rivales que robar en el primer turno.","en":"No opposing monsters to steal on the first turn."}},{"card":"Trap Stun","qty":1,"why":{"es":"Anula también tus propias Trampas (Fiendish Chain, Geargiagear) ese turno.","en":"It also negates your own Traps (Fiendish Chain, Geargiagear) that turn."}}]},"second":{"in":[{"card":"Maxx \"C\"","qty":2,"why":{"es":"Contra Mermail, Lightsworn o Madolche, cada Invocación Especial que hagan en su turno te roba una carta.","en":"Against Mermail, Lightsworn or Madolche, each Special Summon they make on their turn draws you a card."}}],"out":[{"card":"Trap Stun","qty":1,"why":{"es":"Anula también tus propias Trampas (Fiendish Chain, Geargiagear) ese turno.","en":"It also negates your own Traps (Fiendish Chain, Geargiagear) that turn."}},{"card":"Needle Ceiling","qty":1,"why":{"es":"Si hay 4 o más monstruos en el campo, destruye todos los que están boca arriba, y vos solés armar ese campo.","en":"If there are 4 or more monsters on the field, it destroys all face-up monsters, and you are often the one building that field."}}]}},"updated":"2026-10-26","sources":[{"name":"Format History: Early HAT Format","url":"https://ygoprodeck.com/format-history-early-hat-format/","kind":"guide","checked":"2026-10-27"},{"name":"Format History: High HAT Format","url":"https://ygoprodeck.com/article/format-history-high-hat-format-26051","kind":"guide","checked":"2026-10-27"},{"name":"Geargiarmor","url":"https://yugipedia.com/wiki/Geargiarmor","kind":"cards","checked":"2026-10-27"},{"name":"Geargiagear","url":"https://yugipedia.com/wiki/Geargiagear","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"La banlist de julio de 2014 (anunciada el 3 y vigente desde el 14) limitó Geargiagear a 1 copia, según la guía del High HAT: según el momento del formato que juegues, revisá cuántas copias podés tener.","en":"The July 2014 banlist (announced on the 3rd and in effect from the 14th) limited Geargiagear to 1 copy, according to the High HAT guide: depending on which moment of the format you play, check how many copies you can run."},{"es":"HAT no tiene una lista publicada de cartas legales (se toman las de primera impresión hasta la fecha del formato): si una carta de la ficha te genera dudas, comprobá su fecha de salida.","en":"HAT has no published list of legal cards (cards with a first print up to the format's date are taken): if a card on this sheet raises doubts, check its release date."}]},"hat/lightsworn-ruler":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Muele el Deck para llenar el Cementerio: Raiden manda 2 cartas en la Main Phase y otras 2 en la End Phase, Lumina 3 en la End Phase, Needlebug Nest manda 5 y Solar Recharge roba 2 y manda 2.","en":"It mills the Deck to fill the Graveyard: Raiden sends 2 cards in the Main Phase and 2 more in the End Phase, Lumina 3 on the End Phase, Needlebug Nest sends 5 and Solar Recharge draws 2 and sends 2."},{"es":"Con el Cementerio lleno entra Judgment Dragon (4 Lightsworn distintos, destruye todo pagando 1000 LP) o Lightray Diabolos (5 LIGHT distintos, devuelve al Deck una carta Seteada).","en":"With the Graveyard loaded, Judgment Dragon comes in (4 different Lightsworn, destroys everything for 1000 LP) or Lightray Diabolos (5 different LIGHT, sends a Set card back to the Deck)."},{"es":"Raiden (Tuner Nivel 4) más Lumina arma a Michael, the Arch-Lightsworn (Nivel 7), que destierra una carta por 1000 LP.","en":"Raiden (Level 4 Tuner) plus Lumina builds Michael, the Arch-Lightsworn (Level 7), which banishes a card for 1000 LP."},{"es":"Sin Charge of the Light Brigade o Solar Recharge, el Cementerio se llena más despacio: depende de lo que muelen Raiden (2 en la Main Phase y 2 en la End Phase) y Lumina (3 en la End Phase).","en":"Without Charge of the Light Brigade or Solar Recharge, the Graveyard fills more slowly: it depends on what Raiden (2 in the Main Phase and 2 in the End Phase) and Lumina (3 in the End Phase) mill."}]},"starters":[{"cards":["Lumina, Lightsworn Summoner","Raiden, Hand of the Lightsworn"],"route":{"es":"Lumina (Normal Summon) descarta una carta y revive a Raiden si ya estaba en el Cementerio; Raiden (4) más Lumina (3) hacen Michael de Nivel 7.","en":"Lumina (Normal Summon) discards a card and revives Raiden if it is already in the Graveyard; Raiden (4) plus Lumina (3) make Level 7 Michael."}},{"cards":["Charge of the Light Brigade","Solar Recharge"],"route":{"es":"Charge manda 3 cartas y busca un Lightsworn de Nivel 4 o menos; Solar Recharge descarta un Lightsworn para robar 2: dos jugadas que dejan listo a Judgment Dragon.","en":"Charge sends 3 cards and searches a Level 4 or lower Lightsworn; Solar Recharge discards a Lightsworn to draw 2: two plays that set up Judgment Dragon."}},{"cards":["Needlebug Nest"],"route":{"es":"La Seteás el primer turno y la activás en el turno del rival: 5 cartas al Cementerio para que Judgment Dragon o Diabolos entren en tu turno.","en":"Set it on turn 1 and activate it on the opponent's turn: 5 cards to the Graveyard so Judgment Dragon or Diabolos come in on your turn."}}],"chokepoints":[{"card":"Breakthrough Skill","step":"activation","stepText":{"es":"Contra Raiden o Lumina, en tu Main Phase.","en":"Against Raiden or Lumina, in your Main Phase."},"loss":{"es":"Anula su efecto de moler y cortás la acumulación del Cementerio. Si ves una trampa Seteada, jugá primero un Lightsworn de poco valor.","en":"Negates its milling effect and cuts the Graveyard build-up. If you see a Set Trap, play a low-value Lightsworn first."}},{"card":"Fiendish Chain","step":"activation","stepText":{"es":"Apuntando a Raiden o Lumina.","en":"Targeting Raiden or Lumina."},"loss":{"es":"Los deja anulados y sin atacar: quedás dependiendo de Charge of the Light Brigade, Needlebug Nest y Solar Recharge. Sacala con Mystical Space Typhoon o destruyendo al monstruo.","en":"Leaves them negated and unable to attack: you depend on Charge of the Light Brigade, Needlebug Nest and Solar Recharge. Remove it with Mystical Space Typhoon or by destroying the monster."}},{"card":"Chaos Trap Hole","step":"summon","stepText":{"es":"Cuando Judgment Dragon, Diabolos o Michael van a invocarse.","en":"When Judgment Dragon, Diabolos or Michael is about to be summoned."},"loss":{"es":"Judgment Dragon y Diabolos son LIGHT: anula la invocación pagando 2000 LP y la destierra. No frena lo que se invoca con un efecto, como Lumina reviviendo a Raiden. Jugá cebos antes de tu carta clave.","en":"Judgment Dragon and Diabolos are LIGHT: it negates the Summon for 2000 LP and banishes it. It cannot stop what is summoned by an effect, like Lumina reviving Raiden. Play bait before your key card."}},{"card":"Vanity's Emptiness","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Ninguno puede invocar de forma especial: Judgment Dragon, Diabolos y Michael quedan trabados. Tu molienda no la destruye, es del rival. Se saca con Mystical Space Typhoon o Lyla.","en":"Neither player can Special Summon: Judgment Dragon, Diabolos and Michael are locked out. Your own milling does not destroy it, it is the opponent's. Remove it with Mystical Space Typhoon or Lyla."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Los monstruos molidos se destierran y el Cementerio nunca se llena: Judgment Dragon y Diabolos se apagan. Sacala con Mystical Space Typhoon o Lyla.","en":"Milled monsters are banished and the Graveyard never fills: Judgment Dragon and Diabolos shut off. Remove it with Mystical Space Typhoon or Lyla."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Maxx \"C\"","qty":2,"why":{"es":"El rival que va segundo invoca en su turno y cada Invocación Especial te hace robar.","en":"The opponent going second summons on their turn and each Special Summon makes you draw."}}],"out":[{"card":"Mind Control","qty":1,"why":{"es":"Sin monstruo rival que robar en tu primer turno.","en":"No opposing monster to steal on your first turn."}},{"card":"Forbidden Lance","qty":1,"why":{"es":"Sin Battle Phase en el primer turno, solo protege.","en":"With no Battle Phase on the first turn, it only protects."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":2,"why":{"es":"Contra backrow ya Seteada (Skill Drain, Fiendish Chain), abre el camino a Judgment Dragon.","en":"Against already Set backrow (Skill Drain, Fiendish Chain), it clears the way for Judgment Dragon."}}],"out":[{"card":"Honest","qty":1,"why":{"es":"Sirve para combate, y yendo segundo lo urgente es abrir el campo.","en":"It serves combat, and going second the priority is opening the field."}},{"card":"Rainbow Kuriboh","qty":1,"why":{"es":"Frena un ataque, pero tu plan es llenar el Cementerio, no defender.","en":"It stops an attack, but your plan is filling the Graveyard, not defending."}}]}},"updated":"2026-10-26","sources":[{"name":"Format History: High HAT Format","url":"https://ygoprodeck.com/article/format-history-high-hat-format-26051","kind":"guide","checked":"2026-10-27"},{"name":"Format History: Early HAT Format","url":"https://ygoprodeck.com/format-history-early-hat-format/","kind":"guide","checked":"2026-10-27"},{"name":"Judgment Dragon","url":"https://yugipedia.com/wiki/Judgment_Dragon","kind":"cards","checked":"2026-10-27"},{"name":"Raiden, Hand of the Lightsworn","url":"https://yugipedia.com/wiki/Raiden,_Hand_of_the_Lightsworn","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"Es un mazo del High HAT: las guías lo dejan como rogue en el Early HAT y su auge empieza con Structure Deck: Realm of Light (27 de junio de 2014). Antes de esa fecha la ficha no vale.","en":"It is a High HAT deck: the guides leave it as a rogue in Early HAT and its rise starts with Structure Deck: Realm of Light (June 27, 2014). Before that date the sheet does not apply."},{"es":"HAT no tiene una lista publicada de cartas legales (se toman las de primera impresión hasta la fecha del formato): si una carta de la ficha te genera dudas, comprobá su fecha de salida.","en":"HAT has no published list of legal cards (cards with a first print up to the format's date are taken): if a card on this sheet raises doubts, check its release date."}]},"hat/madolche":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Los Madolche destruidos por una carta rival vuelven al Deck, y Madolche Ticket, una vez por turno, suma otro Madolche del Deck a la mano cuando uno vuelve a la mano o al Deck por un efecto (o lo invoca, si controlás un Madolche Hada boca arriba).","en":"Madolche destroyed by an opposing card go back to the Deck, and Madolche Ticket, once per turn, adds another Madolche from the Deck to your hand when one returns to the hand or Deck by an effect (or summons it, if you control a face-up Fairy Madolche)."},{"es":"Anjelly se tributa para traer cualquier Madolche del Deck; Hootcake destierra un monstruo del Cementerio para hacer lo mismo y Messengelato busca una Magia/Trampa Madolche si controlás un Madolche Bestia boca arriba.","en":"Anjelly Tributes to bring any Madolche from the Deck; Hootcake banishes a monster from the Graveyard to do the same and Messengelato searches a Madolche Spell/Trap if you control a face-up Beast Madolche."},{"es":"Madolche Queen Tiaramisu (Rango 4) devuelve hasta 2 Madolche del Cementerio al Deck y mezcla del campo del rival hasta esa misma cantidad de cartas.","en":"Madolche Queen Tiaramisu (Rank 4) returns up to 2 Madolche from the Graveyard to the Deck and shuffles up to that many cards the opponent controls into the Deck."},{"es":"Es lento y vive de la Normal Summon; si no hay material en el Cementerio, Hootcake no hace nada.","en":"It is slow and lives off the Normal Summon; if the Graveyard has no fodder, Hootcake does nothing."}]},"starters":[{"cards":["Madolche Anjelly"],"route":{"es":"Normal Summon de Anjelly: la tributás para traer un Madolche del Deck (indestructible en batalla), y el que sale se baraja de vuelta en la End Phase de tu siguiente turno.","en":"Normal Summon Anjelly: Tribute her to bring a Madolche from the Deck (indestructible by battle), and the one that comes out shuffles back on the End Phase of your next turn."}},{"cards":["Madolche Magileine"],"route":{"es":"Normal Summon de Magileine: buscás otro Madolche de la lista (Hootcake o Messengelato) para la jugada del turno siguiente.","en":"Normal Summon Magileine: you search another Madolche from your list (Hootcake or Messengelato) for the next turn's play."}},{"cards":["Madolche Hootcake","Madolche Messengelato"],"route":{"es":"Hootcake destierra un monstruo del Cementerio e invoca a Messengelato del Deck; Messengelato busca Madolche Chateau o Madolche Ticket mientras Hootcake siga boca arriba.","en":"Hootcake banishes a monster from the Graveyard and summons Messengelato from the Deck; Messengelato searches Madolche Chateau or Madolche Ticket while Hootcake stays face-up."}}],"chokepoints":[{"card":"Skill Drain","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Anula los Madolche que actúan desde el campo: Magileine y Mewfeuille al invocarse por Normal, Hootcake y Messengelato. Anjelly se Tributa como coste y los Madolche destruidos se barajan desde el Cementerio, así que siguen funcionando. Se saca con Mystical Space Typhoon.","en":"Negates the Madolche that act from the field: Magileine and Mewfeuille when Normal Summoned, Hootcake and Messengelato. Anjelly Tributes herself as a cost and destroyed Madolche shuffle back from the Graveyard, so those still work. Remove it with Mystical Space Typhoon."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Los Madolche destruidos se destierran en vez de barajarse, y Hootcake no tiene material en el Cementerio. Se saca con Mystical Space Typhoon.","en":"Destroyed Madolche are banished instead of shuffling back, and Hootcake has no fodder in the Graveyard. Remove it with Mystical Space Typhoon."}},{"card":"Mistake","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Nadie puede añadir cartas del Deck a la mano salvo robando: Magileine, Messengelato, Madolche Ticket y Reinforcement of the Army no añaden nada. Jugá con Anjelly, Hootcake y Mewfeuille, que invocan en vez de añadir, o sacala con Mystical Space Typhoon.","en":"Nobody can add cards from the Deck to the hand except by drawing: Magileine, Messengelato, Madolche Ticket and Reinforcement of the Army add nothing. Play with Anjelly, Hootcake and Mewfeuille, which summon instead of adding, or remove it with Mystical Space Typhoon."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, en respuesta al efecto de Magileine.","en":"In your Main Phase, in response to Magileine's effect."},"loss":{"es":"Anula la búsqueda y perdés la Normal Summon del turno. Si ya tenés Anjelly o Hootcake en el campo, sus efectos no piden Normal Summon y podés seguir; si no, el turno queda sin jugada.","en":"Negates the search and you lose the turn's Normal Summon. If you already have Anjelly or Hootcake on the field, their effects do not need a Normal Summon and you can keep going; if not, the turn is left with no play."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Black Horn of Heaven","qty":1,"why":{"es":"Frena una Invocación Especial del rival que no abre cadena (Xyz, Sincro, Judgment Dragon): el rival va segundo.","en":"Stops an opponent's Special Summon that does not start a Chain (Xyz, Synchro, Judgment Dragon): the opponent goes second."}}],"out":[{"card":"Mind Control","qty":1,"why":{"es":"Sin monstruo rival que robar el primer turno.","en":"No opposing monster to steal on the first turn."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":2,"why":{"es":"Contra backrow Seteada del rival, abre el camino para que tus Madolche no choquen con una trampa.","en":"Against the opponent's Set backrow, it opens the way so your Madolche do not run into a Trap."}}],"out":[{"card":"Photon Thrasher","qty":2,"why":{"es":"Solo entra con tu campo vacío, y querés armar un campo de Madolche.","en":"It only enters with your field empty, and you want to build a Madolche field."}}]}},"updated":"2026-10-26","sources":[{"name":"Format History: Early HAT Format","url":"https://ygoprodeck.com/format-history-early-hat-format/","kind":"guide","checked":"2026-10-27"},{"name":"Format History: High HAT Format","url":"https://ygoprodeck.com/article/format-history-high-hat-format-26051","kind":"guide","checked":"2026-10-27"},{"name":"Madolche Anjelly","url":"https://yugipedia.com/wiki/Madolche_Anjelly","kind":"cards","checked":"2026-10-27"},{"name":"Madolche Ticket","url":"https://yugipedia.com/wiki/Madolche_Ticket","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"Las fuentes enlazadas no detallan cómo se juega Madolche más allá de que es lento, depende de la Normal Summon y fue top tier (ganó YCS Philadelphia): el resto de la ficha sale del texto de las cartas.","en":"The linked sources do not detail how Madolche plays beyond it being slow, relying on the Normal Summon and being top tier (it won YCS Philadelphia): the rest of the sheet comes from the card texts."},{"es":"HAT no tiene una lista publicada de cartas legales (se toman las de primera impresión hasta la fecha del formato): si una carta de la ficha te genera dudas, comprobá su fecha de salida.","en":"HAT has no published list of legal cards (cards with a first print up to the format's date are taken): if a card on this sheet raises doubts, check its release date."}]},"hat/infernity":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Funciona con la mano vacía: Infernity Archfiend entra si la robás sin otras cartas en la mano y busca una carta Infernity; Infernity Break, Barrier y el efecto de Launcher que invoca también piden mano vacía.","en":"It runs on an empty hand: Infernity Archfiend comes in if you draw it with no other cards in hand and searches an Infernity card; Infernity Break, Barrier and Launcher's summoning effect also require an empty hand."},{"es":"Para vaciar la mano usa Summoner Monk, Instant Fusion, Stygian Street Patrol, Tin Goldfish y Dynatherium, y arma Rango 3 y 4 como Lavalval Chain y Leviair the Sea Dragon.","en":"To empty the hand it uses Summoner Monk, Instant Fusion, Stygian Street Patrol, Tin Goldfish and Dynatherium, and builds Rank 3 and 4 like Lavalval Chain and Leviair the Sea Dragon."},{"es":"Leviair trae de vuelta desde el destierro a Stygian Street Patrol, que queda como otro Nivel 4 en el campo; Lavalval Chain manda una carta del Deck al Cementerio o pone un monstruo del Deck arriba del Deck.","en":"Leviair brings Stygian Street Patrol back from the banished zone as another Level 4 on the field; Lavalval Chain sends a card from the Deck to the Graveyard or puts a monster from the Deck on top of the Deck."},{"es":"Tiene techo muy alto pero sin cartas en mano casi no tiene juego largo: si el rival le corta el arranque, no hay plan de desgaste.","en":"It has a very high ceiling but with no cards in hand it has almost no long game: if the opponent breaks the opening, there is no grinding plan."}]},"starters":[{"cards":["Stygian Street Patrol","Infernity Archfiend"],"route":{"es":"Stygian Street Patrol se destierra del Cementerio e invoca a Archfiend de la mano (1800 de ATK, entra bajo el límite de 2000); si queda la mano vacía, Archfiend busca una carta Infernity.","en":"Stygian Street Patrol banishes itself from the Graveyard and summons Archfiend from the hand (1800 ATK, under the 2000 limit); if the hand is empty, Archfiend searches an Infernity card."}},{"cards":["Summoner Monk","Instant Fusion"],"route":{"es":"Monk descarta una Magia e invoca un Nivel 4 del Deck; Instant Fusion (1000 LP) pone a Kamionwizard: dos Nivel 4 para Lavalval Chain.","en":"Monk discards a Spell and summons a Level 4 from the Deck; Instant Fusion (1000 LP) puts out Kamionwizard: two Level 4s for Lavalval Chain."}},{"cards":["Tin Goldfish","Dynatherium"],"route":{"es":"Tin Goldfish invoca otro Nivel 4 de la mano y Dynatherium entra gratis: dos Nivel 4 para Rango 4 sin gastar la mano en Magias (el rival puede revivir un Nivel 4 con Dynatherium).","en":"Tin Goldfish summons another Level 4 from the hand and Dynatherium enters for free: two Level 4s for a Rank 4 without spending your hand on Spells (the opponent can revive a Level 4 off Dynatherium)."}}],"chokepoints":[{"card":"Maxx \"C\"","step":"activation","stepText":{"es":"Antes de tu primera Invocación Especial.","en":"Before your first Special Summon."},"loss":{"es":"Cada Invocación Especial le da una carta al rival, y Infernity invoca mucho. Armá la jugada con pocos eventos de invocación: Instant Fusion cuenta una sola vez.","en":"Each Special Summon gives the opponent a card, and Infernity summons a lot. Build the play with few summon events: Instant Fusion counts only once."}},{"card":"Debunk","step":"activation","stepText":{"es":"Cuando Archfiend activa su efecto desde la mano, o Stygian Street Patrol desde el Cementerio.","en":"When Archfiend activates its effect from the hand, or Stygian Street Patrol from the Graveyard."},"loss":{"es":"Anula el efecto y destierra la carta. Si tenés Tin Goldfish o Summoner Monk, empezá por esos para no depender de un único Archfiend.","en":"Negates the effect and banishes the card. If you have Tin Goldfish or Summoner Monk, start with those so you do not rely on a single Archfiend."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, en respuesta al efecto de Archfiend.","en":"In your Main Phase, in response to Archfiend's effect."},"loss":{"es":"Anula la búsqueda de Infernity Break o Barrier. Tené otro monstruo de Nivel 4 en el campo para seguir con el Xyz.","en":"Negates the search for Infernity Break or Barrier. Keep another Level 4 monster on the field to continue into the Xyz."}},{"card":"Vanity's Emptiness","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Nadie invoca de forma especial: Archfiend, Stygian Street Patrol y los Xyz quedan bloqueados. Se saca con Mystical Space Typhoon.","en":"Nobody Special Summons: Archfiend, Stygian Street Patrol and the Xyz are locked out. Remove it with Mystical Space Typhoon."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Forbidden Chalice","qty":2,"why":{"es":"Carta rápida: se puede usar con la mano vacía para anular a un monstruo clave del rival.","en":"A Quick-Play: usable with an empty hand to negate a key monster of the opponent."}}],"out":[{"card":"Dynatherium","qty":1,"why":{"es":"Deja que el rival invoque un Nivel 4 de cualquier Cementerio.","en":"Lets the opponent summon a Level 4 from either Graveyard."}},{"card":"Photon Thrasher","qty":1,"why":{"es":"Solo entra con el campo vacío y no ataca con otro monstruo.","en":"It only enters with an empty field and cannot attack with another monster."}}]},"second":{"in":[{"card":"Night Beam","qty":3,"why":{"es":"Destruye una Magia/Trampa Seteada sin darle respuesta: el rival que fue primero tiene backrow.","en":"Destroys a Set Spell/Trap without giving a response: the opponent who went first has backrow."}}],"out":[{"card":"Vanity's Emptiness","qty":3,"why":{"es":"Bloquea también tus propias Invocaciones Especiales, que necesitás para romper el campo.","en":"It also blocks your own Special Summons, which you need to break the board."}}]}},"updated":"2026-10-26","sources":[{"name":"Format History: High HAT Format","url":"https://ygoprodeck.com/article/format-history-high-hat-format-26051","kind":"guide","checked":"2026-10-27"},{"name":"Format History: Early HAT Format","url":"https://ygoprodeck.com/format-history-early-hat-format/","kind":"guide","checked":"2026-10-27"},{"name":"Infernity Archfiend","url":"https://yugipedia.com/wiki/Infernity_Archfiend","kind":"cards","checked":"2026-10-27"},{"name":"Stygian Street Patrol","url":"https://yugipedia.com/wiki/Stygian_Street_Patrol","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"Los resultados de Infernity son magros: 1 top en el EUWCQ y 3 en el NAWCQ, y las guías lo describen como un mazo con techo alto, no como líder del formato. No hay una guía de cómo se juega.","en":"Infernity's results are thin: 1 top cut at the EUWCQ and 3 at the NAWCQ, and the guides describe it as a high-ceiling deck, not a format leader. There is no guide on how to play it."},{"es":"HAT no tiene una lista publicada de cartas legales (se toman las de primera impresión hasta la fecha del formato): si una carta de la ficha te genera dudas, comprobá su fecha de salida.","en":"HAT has no published list of legal cards (cards with a first print up to the format's date are taken): if a card on this sheet raises doubts, check its release date."}]},"hat/sylvan":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Excavar es el motor: Marshalleaf, Komushroomo y Hermitree miran cartas del Deck, mandan los Plantas al Cementerio y disparan los efectos de 'cuando es excavado'.","en":"Excavating is the engine: Marshalleaf, Komushroomo and Hermitree look at cards from the Deck, send Plants to the Graveyard and trigger the 'when excavated' effects."},{"es":"Lo excavado pega: Marshalleaf destruye un monstruo, Komushroomo una Magia/Trampa y Sagequoia recupera una Magia/Trampa Sylvan; Sagequoia entra de la mano cuando un Sylvan va al Cementerio.","en":"What you excavate hits: Marshalleaf destroys a monster, Komushroomo a Spell/Trap and Sagequoia recovers a Sylvan Spell/Trap; Sagequoia enters from the hand when a Sylvan goes to the Graveyard."},{"es":"Soul Charge y Miracle Fertilizer ponen cuerpos de Nivel 7 u 8 para Orea, Alsei o Divine Dragon Knight Felgrand, que cierran la partida.","en":"Soul Charge and Miracle Fertilizer put out Level 7 or 8 bodies for Orea, Alsei or Divine Dragon Knight Felgrand, which close the game."},{"es":"Pide una sexta carta para arrancar y es difícil de jugar bien; Divine Wrath anula la activación de un efecto de monstruo y destruye a ese monstruo si descartás una carta.","en":"It needs a sixth card to get going and is hard to play well; Divine Wrath negates the activation of a monster effect and destroys that monster if you discard a card."}]},"starters":[{"cards":["Sylvan Marshalleaf"],"route":{"es":"Normal Summon de Marshalleaf: excavás 1 o 2 cartas, mandás los Plantas al Cementerio y, si una es Sylvan, empieza la cadena de efectos.","en":"Normal Summon Marshalleaf: excavate 1 or 2 cards, send the Plants to the Graveyard and, if one is Sylvan, the chain of effects begins."}},{"cards":["Sylvan Komushroomo"],"route":{"es":"Seteado el primer turno: al voltearse excavás de 1 a 5 cartas y dejás cargado el Cementerio de Plantas.","en":"Set on the first turn: when flipped you excavate 1 to 5 cards and load the Graveyard with Plants."}},{"cards":["Sylvan Hermitree","Miracle Fertilizer"],"route":{"es":"Hermitree en el Cementerio vuelve con Miracle Fertilizer y excava cada turno: si es Planta va al Cementerio y robás una carta.","en":"Hermitree in the Graveyard returns with Miracle Fertilizer and excavates every turn: if it is a Plant it goes to the Graveyard and you draw a card."}}],"chokepoints":[{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Los Plantas excavados se destierran en vez de ir al Cementerio, así que no se dispara ningún efecto de 'cuando es excavado'. Sacala con Mystical Space Typhoon.","en":"Excavated Plants are banished instead of going to the Graveyard, so no 'when excavated' effect triggers. Remove it with Mystical Space Typhoon."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"En respuesta a Miracle Fertilizer, apuntando a la Planta.","en":"In response to Miracle Fertilizer, targeting the Plant."},"loss":{"es":"Destierra la Planta objetivo y el efecto de Miracle Fertilizer no se resuelve. Tené otro Planta en el Cementerio como alternativa.","en":"Banishes the targeted Plant and Miracle Fertilizer's effect does not resolve. Keep another Plant in the Graveyard as an alternative."}},{"card":"Solemn Warning","step":"activation","stepText":{"es":"Cuando Sagequoia activa su efecto para invocarse desde la mano.","en":"When Sagequoia activates its effect to Special Summon itself from the hand."},"loss":{"es":"Anula la activación y Sagequoia se queda en la mano. Se puede reintentar si otro Sylvan vuelve a ir al Cementerio.","en":"Negates the activation and Sagequoia stays in the hand. You can try again if another Sylvan goes to the Graveyard."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, en respuesta al efecto de Hermitree o Marshalleaf.","en":"In your Main Phase, in response to Hermitree's or Marshalleaf's effect."},"loss":{"es":"Anula la excavación del turno. Reservá Komushroomo Seteado para el turno siguiente.","en":"Negates the turn's excavation. Save a Set Komushroomo for the next turn."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Maxx \"C\"","qty":2,"why":{"es":"Penaliza las Invocaciones Especiales del rival en su turno; Super Solar Nutrient y Cherubsprout solo suman si la jugada sale entera.","en":"Penalizes the opponent's Special Summons on their turn; Super Solar Nutrient and Cherubsprout only add value if the full play comes together."}}],"out":[{"card":"Super Solar Nutrient","qty":1,"why":{"es":"Pide un Planta de Nivel 2 o menos para tributar, un requisito que no siempre tenés.","en":"It needs a Level 2 or lower Plant to Tribute, a requirement you do not always have."}},{"card":"Sylvan Cherubsprout","qty":1,"why":{"es":"Solo suma con una excavación específica.","en":"It only adds value with a specific excavation."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":2,"why":{"es":"Contra backrow Seteada, protege a Hermitree y al resto de la excavación.","en":"Against Set backrow, it protects Hermitree and the rest of the excavation."}}],"out":[{"card":"Spore","qty":1,"why":{"es":"Solo se puede usar una vez por Duelo y depende de otro Planta en el Cementerio.","en":"It can only be used once per Duel and depends on another Plant in the Graveyard."}},{"card":"Terraforming","qty":1,"why":{"es":"Solo busca un Campo, y yendo segundo preferís una carta que abra el backrow del rival.","en":"It only searches a Field Spell, and going second you prefer a card that opens the opponent's backrow."}}]}},"updated":"2026-10-26","sources":[{"name":"Format History: High HAT Format","url":"https://ygoprodeck.com/article/format-history-high-hat-format-26051","kind":"guide","checked":"2026-10-27"},{"name":"Format History: Early HAT Format","url":"https://ygoprodeck.com/format-history-early-hat-format/","kind":"guide","checked":"2026-10-27"},{"name":"Sylvan Marshalleaf","url":"https://yugipedia.com/wiki/Sylvan_Marshalleaf","kind":"cards","checked":"2026-10-27"},{"name":"Sylvan Komushroomo","url":"https://yugipedia.com/wiki/Sylvan_Komushroomo","kind":"cards","checked":"2026-10-27"}],"limits":[{"es":"Las guías dicen que Sylvan exigía mucha habilidad, no se había refinado y no puso ningún top en YCS Philadelphia; el buen resultado es contra Lightsworn Ruler y en el NAWCQ (5 tops).","en":"The guides say Sylvan took a lot of skill, was not refined and had no top finish at YCS Philadelphia; its strong results are against Lightsworn Ruler and at the NAWCQ (5 tops)."},{"es":"HAT no tiene una lista publicada de cartas legales (se toman las de primera impresión hasta la fecha del formato): si una carta de la ficha te genera dudas, comprobá su fecha de salida.","en":"HAT has no published list of legal cards (cards with a first print up to the format's date are taken): if a card on this sheet raises doubts, check its release date."}]},"ocg/elfnote":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Arma una mesa de interrupciones a base de Sincros: Elfnote Power Patron sube 3 niveles al monstruo de la zona central y sincroniza en el acto, y los Elfnote de nivel 6 se mueven a esa zona.","en":"Builds an interruption board through Synchros: Elfnote Power Patron raises the center-zone monster by 3 Levels and Synchro Summons right away, and Level 6 Elfnotes move into that zone."},{"es":"En el turno rival los Elfnote se cambian de lugar con el monstruo central: Lucina devuelve un monstruo de nivel 6 o menos a la mano, Tinia destierra una carta al azar de la mano rival y Fortuna devuelve un Mágica/Trampa boca arriba.","en":"On the opponent's turn Elfnotes swap with the center monster: Lucina returns a Level 6 or lower monster to the hand, Tinia banishes a random card from the opponent's hand and Fortuna returns a face-up Spell/Trap."},{"es":"Las cartas Ars Magna suman remoción: Ars Magna the Finite and the Infinite destierra un monstruo si controlás un Link Power Patron, y Mediclius (con 3 enlaces) se destierra con todo el campo rival como efecto rápido.","en":"Ars Magna cards add removal: Ars Magna the Finite and the Infinite banishes a monster if you control a Power Patron Link, and Mediclius (pointing to 3) banishes itself and the opponent's whole field as a Quick Effect."},{"es":"Road of the King lo cuenta como el mazo más jugado de su reporte OCG 2026.07, y describe una jugada larga que termina en Baronne de Fleur, Artmage Diactorus y Rhapsodia of Madness.","en":"Road of the King counts it as the most played deck in its OCG 2026.07 report, and describes a long line ending on Baronne de Fleur, Artmage Diactorus and Rhapsodia of Madness."}]},"starters":[{"cards":["Elfnote Lucina","Elfnote Power Patron"],"route":{"es":"Lucina entra a la zona central desde la mano y busca a Power Patron; este sube su nivel 3 y sincroniza (Baronne de Fleur u otro Elfnote Sincro).","en":"Lucina Special Summons to the center zone from hand and adds Power Patron; it raises her Level by 3 and Synchro Summons (Baronne de Fleur or another Elfnote Synchro)."}},{"cards":["Theorealize Past Lull","Medius the Pure"],"route":{"es":"Past Lull invoca a Medius the Pure desde la mano o el Deck sin que el rival pueda responder; Medius busca o invoca un monstruo Power Patron.","en":"Past Lull Special Summons Medius the Pure from hand or Deck and the opponent cannot respond; Medius adds or Special Summons a Power Patron monster."}},{"cards":["Elfnotes: Welcome Home"],"route":{"es":"Manda un monstruo al Cementerio e invoca de Defensa un Elfnote de otro Atributo desde el Deck, y protege de destrucción por efecto al monstruo central.","en":"Sends a monster to the GY and Special Summons an Elfnote of a different Attribute from the Deck in Defense Position, and protects the center monster from effect destruction."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Al activar la búsqueda de Lucina, de Medius the Pure o la invocación desde el Deck de Regina.","en":"When Lucina's search, Medius the Pure's add or Regina's Deck Special Summon is activated."},"loss":{"es":"Sin la búsqueda de Lucina no llega Power Patron y se corta la ruta de Sincros. Conviene empezar por la carta que menos duele perder.","en":"Without Lucina's search Power Patron never arrives and the Synchro route is cut. Start with the card you mind losing least."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, tras la quinta invocación de la jugada.","en":"During the Main Phase, after the fifth Summon of the turn."},"loss":{"es":"La línea invoca muchos monstruos y Nibiru tributa todo el campo. Road of the King cuenta que varios jugadores ya meten Nibiru en el Side contra Elfnote, y que Baronne de Fleur o Crystal Wing Synchro Dragon salen bastante tarde en la jugada.","en":"The line Summons many monsters and Nibiru Tributes the whole field. Road of the King reports that several players are now siding Nibiru against Elfnote, and that Baronne de Fleur or Crystal Wing Synchro Dragon come out fairly late in the line."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse la primera búsqueda del turno (Lucina, Medius o el Sincro Power Patron).","en":"On resolution of the first search of the turn (Lucina, Medius or the Power Patron Synchro)."},"loss":{"es":"No frena la primera carta, pero corta el resto de las búsquedas del turno: queda sin los Elfnote y Ars Magna que buscaba después.","en":"It does not stop the first card, but cuts every later search that turn: you lose the Elfnotes and Ars Magna cards you wanted next."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto rápido de Elfnote Power Patron (subir nivel y sincronizar).","en":"When Elfnote Power Patron's Quick Effect (raise Level and Synchro Summon) is activated."},"loss":{"es":"Si se niega, no sube el nivel y no hay Sincro: se pierde el paso clave. Guardá un segundo camino (Seraphim Strelitzia o Regina) para la mano que se queda sin esa activación.","en":"If negated, the Level never rises and there is no Synchro: the key step is lost. Keep a second route (Seraphim Strelitzia or Regina) for hands that lose that activation."}}],"side":{"first":{"in":[{"card":"Solemn Warning","qty":2,"why":{"es":"Anula la invocación o la activación que invoca, así protege la mesa cuando el rival juega segundo.","en":"Negates the Summon or an activation that Special Summons, so it protects the board when the opponent goes second."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Solo se activa si no controlás cartas: yendo primero, con mesa armada queda muerta.","en":"Only activates if you control no cards: going first, with a board up, it is dead."}}]},"second":{"in":[{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"Corta de raíz la jugada rival cuando junta cinco invocaciones.","en":"Ends the opponent's line the moment they reach five Summons."}},{"card":"Triple Tactics Talent","qty":1,"why":{"es":"Se activa si el rival usó un efecto de monstruo en tu Main Phase: roba 2 o roba el monstruo.","en":"Activates if the opponent used a monster effect in your Main Phase: draw 2 or take the monster."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a una búsqueda del rival; yendo segundo ya jugó casi todo.","en":"It reacts to an opponent search; going second they have already played most of it."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de que el rival arme su mesa que después.","en":"Worth more before the opponent builds the board than after."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Elfnote Power Patron","url":"https://yugipedia.com/wiki/Elfnote_Power_Patron","kind":"cards","checked":"2026-10-27"},{"name":"Elfnote Lucina","url":"https://yugipedia.com/wiki/Elfnote_Lucina","kind":"cards","checked":"2026-10-27"},{"name":"Elfnote Kewl Tune, ft. BLZD Support [CDP]","url":"https://ygorganization.com/cdp_elfnotekewlz/","kind":"guide","checked":"2026-10-27"},{"name":"OCG 2026.07 Metagame Report #6, #7","url":"https://roadoftheking.com/ocg-2026-07-metagame-report-6-7/","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Ninguna fuente enlazada publica la banlist OCG vigente: revisala antes de armar el mazo (Elfnote Tinia, por ejemplo, está Prohibida en el TCG desde el 19 de octubre de 2026 y su estado en el OCG puede ser otro).","en":"No linked source publishes the current OCG banlist: check it before building the deck (Elfnote Tinia, for example, has been Forbidden in the TCG since October 19, 2026 and its OCG status may differ)."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas publica estadísticas de side para este mazo.","en":"The Side Deck is editorial judgment: none of the linked sources publishes side-deck statistics for this deck."}]},"ocg/raise-moon":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Juega con el robo: casi todos los monstruos son de nivel 7 y al robarlos se muestran y se invocan solos, así que cada robo extra es una jugada. No hay búsquedas en el tema.","en":"It plays off drawing: almost every monster is Level 7 and is revealed and Special Summoned when drawn, so each extra draw is a play. The theme has no searches."},{"es":"Blade Shayna manda un monstruo rival al fondo del Deck y Lamp Croucier hace lo mismo con un Mágica/Trampa, ambos al entrar por robo.","en":"Blade Shayna sends an opposing monster to the bottom of the Deck and Lamp Croucier does the same to a Spell/Trap, both when they come out by a draw."},{"es":"Cierra con el Xyz de rango 7 Raise Moon Sky Cielo - No More Bets: en la Zona de Monstruos Extra es inmune a otros efectos, y si el rival lo manda al Cementerio robás 1 carta.","en":"It finishes with the Rank 7 Xyz Raise Moon Sky Cielo - No More Bets: in the Extra Monster Zone it is unaffected by other effects, and if the opponent sends it to the GY you draw 1 card."},{"es":"Blade Shayna y Lamp Croucier también se pueden descartar para robar 1 carta, pero ese turno no podés añadir cartas del Deck a la mano salvo robando.","en":"Blade Shayna and Lamp Croucier can also be discarded to draw 1 card, but that turn you cannot add cards from the Deck to the hand except by drawing."}]},"starters":[{"cards":["Cielo, the Veil of Raise Moon"],"route":{"es":"Se invoca desde la mano mandando otra carta al fondo del Deck y roba 1 como efecto rápido: es la mejor carta para dejar en el campo final.","en":"Special Summons from hand by putting another card on the bottom of the Deck and draws 1 as a Quick Effect: the best draw engine to leave on the final board."}},{"cards":["The Stars of Raise Moon","Pot of Desires"],"route":{"es":"Stars deja un Raise Moon arriba del Deck y Pot of Desires roba 2: al robarlo entra solo y sigue la cadena de robos.","en":"Stars puts a Raise Moon on top of the Deck and Pot of Desires draws 2: it is Special Summoned on the draw and the chain of draws continues."}},{"cards":["The Glitter of Raise Moon"],"route":{"es":"Trampa que invoca de Especial un Xyz Raise Moon (por ejemplo Raise Moon Sky Cielo - No More Bets) y se adjunta a él; es lenta si vas segundo sin materiales.","en":"Trap that Special Summons a Raise Moon Xyz (for example Raise Moon Sky Cielo - No More Bets) and attaches itself to it; it is slow going second without setup."}}],"chokepoints":[{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de Blade Shayna o Lamp Croucier tras entrar por robo.","en":"When Blade Shayna's or Lamp Croucier's effect is activated after coming out by a draw."},"loss":{"es":"Niega la remoción al fondo del Deck y te deja un cuerpo de 2800 de ATK sin efecto. Seguí con los robos: el siguiente Raise Moon vuelve a tener efecto.","en":"It negates the bottom-of-Deck removal and leaves a 2800 ATK body with no effect. Keep drawing: the next Raise Moon has its effect again."}},{"card":"Dominus Impulse","step":"summon","stepText":{"es":"Al activarse el \"al robar esta carta, invocala\" de cualquier Raise Moon.","en":"When any Raise Moon's \"when you draw this card, Special Summon it\" is activated."},"loss":{"es":"Anula la invocación por robo, que es el motor del mazo. La carta queda en la mano para pagar el efecto de Cielo o descartarse.","en":"It negates the draw Summon, which is the deck's engine. The card stays in hand to pay for Cielo's effect or be discarded."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Contra \"Raise Moon\" the City that Never Sleeps o The Glitter of Raise Moon cuando mandan o devuelven cartas del Cementerio.","en":"Against \"Raise Moon\" the City that Never Sleeps or The Glitter of Raise Moon when they shuffle or return cards from the GY."},"loss":{"es":"City baraja los Raise Moon del Cementerio y el destierro al Deck en la End Phase; negar esa activación deja el Deck sin reciclarse.","en":"City shuffles Raise Moon cards from the GY and banishment into the Deck in the End Phase; negating that activation leaves the Deck unrecycled."}}],"side":{"first":{"in":[{"card":"Mistaken Arrest","qty":2,"why":{"es":"Nadie añade cartas del Deck a la mano por un turno; a Raise Moon no le cuesta nada porque no busca.","en":"Nobody adds cards from the Deck to the hand for a turn; it costs Raise Moon nothing because it never searches."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Deja pasar la primera búsqueda; Mistaken Arrest las corta todas.","en":"It lets the first search through; Mistaken Arrest stops them all."}},{"card":"Effect Veiler","qty":1,"why":{"es":"Una sola negación de monstruo, redundante con las demás reactivas.","en":"A single monster negation, redundant with the other reactive cards."}}]},"second":{"in":[{"card":"Ghost Belle & Haunted Mansion","qty":2,"why":{"es":"Contra mazos que reviven del Cementerio, niega la activación completa.","en":"Against decks that revive from the GY, it negates the whole activation."}}],"out":[{"card":"Ghost Ogre & Snow Rabbit","qty":2,"why":{"es":"Solo destruye; Belle corta efectos de Cementerio que Ogre no frena.","en":"It only destroys; Belle stops GY effects that Ogre cannot."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Cielo, the Veil of Raise Moon","url":"https://yugipedia.com/wiki/Cielo,_the_Veil_of_Raise_Moon","kind":"cards","checked":"2026-10-27"},{"name":"Raise Moon Blade Shayna","url":"https://yugipedia.com/wiki/Raise_Moon_Blade_Shayna","kind":"cards","checked":"2026-10-27"},{"name":"Raise Moon Lamp Croucier","url":"https://yugipedia.com/wiki/Raise_Moon_Lamp_Croucier","kind":"cards","checked":"2026-10-27"},{"name":"OCG: DBGV - Raise Moon","url":"https://www.yugiohmeta.com/articles/news/aug-11-2026/dbgv/","kind":"guide","checked":"2026-10-27"}],"limits":[{"es":"El arquetipo salió el 5 de septiembre de 2026 y no hay guía ni resultados de torneo dedicados enlazados: lo que dice la ficha sale del texto de las cartas.","en":"The archetype came out on 5 September 2026 and there is no linked dedicated guide or tournament results: what the sheet says comes from the card text."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas publica estadísticas de side para este mazo.","en":"The Side Deck is editorial judgment: none of the linked sources publishes side-deck statistics for this deck."}]},"ocg/chaos-ritual":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"La jugada clave es el primer Ritual del Caos: Black Luster Soldier o Magician of Dark Chaos, invocados con Light and Darkness Ritual.","en":"The key play is the first Chaos Ritual Summon: Black Luster Soldier or Magician of Dark Chaos, Ritual Summoned with Light and Darkness Ritual."},{"es":"Ambos son inmunes a efectos activados del rival que no los apunten, y al invocarse destierran una carta (BLS) o una boca abajo (Magician of Dark Chaos).","en":"Both are unaffected by the opponent's activated effects that do not target them, and banish a card (BLS) or one face-down (Magician of Dark Chaos) when Special Summoned."},{"es":"Black Chaos (nivel 8) destierra 2 cartas rivales cada Main Phase y es inmune a efectos activados mientras tengas un Ritual Spell en el Cementerio.","en":"Black Chaos (Level 8) banishes 2 opposing cards each Main Phase and is unaffected by activated effects while you have a Ritual Spell in the GY."},{"es":"Dark Time Wizard busca o, tirando la moneda, destruye todos los monstruos rivales; sirve como pivote cuando la mesa del rival estorba.","en":"Dark Time Wizard searches or, on a coin toss, destroys every opposing monster; it is the pivot when the opposing board is in the way."}]},"starters":[{"cards":["Griffoh","Mind Shuffle"],"route":{"es":"Griffoh descartado pone Mind Shuffle desde el Deck; este agrega Skull Archfiend of Chaos, que mandado al Cementerio busca el Ritual que pida un Ritual Spell.","en":"Discarded Griffoh Sets Mind Shuffle from the Deck; it adds Skull Archfiend of Chaos, which sent to the GY adds the Ritual Monster named on a Ritual Spell."}},{"cards":["Ragged Records of Rites","Light and Darkness Ritual"],"route":{"es":"Records revela Light and Darkness Ritual y agrega el monstruo que lo menciona; con eso se hace el Ritual en el mismo turno.","en":"Records reveals Light and Darkness Ritual and adds a monster that mentions it, giving a same-turn Ritual Summon."}},{"cards":["Celtic Mystic"],"route":{"es":"Si mostrás en la mano una carta que mencione Light and Darkness Ritual, robás 3 y descartás 2; también se tributa para invocar un Ritual desde la mano.","en":"If you reveal a card in hand that mentions Light and Darkness Ritual, you draw 3 and discard 2; it can also be Tributed to Special Summon a Ritual from hand."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra Ragged Records of Rites, Pre-Preparation of Rites o la búsqueda de Skull Archfiend.","en":"Against Ragged Records of Rites, Pre-Preparation of Rites or Skull Archfiend's search."},"loss":{"es":"Corta la búsqueda del Ritual o del monstruo. Por eso Griffoh y Mind Shuffle son la ruta alternativa: no dependen de una sola carta.","en":"It cuts the Ritual or monster search. That is why Griffoh and Mind Shuffle are the alternative route: they do not hang on one card."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse la primera búsqueda del turno (Records, Pre-Preparation o Celtic Mystic).","en":"On resolution of the first search of the turn (Records, Pre-Preparation or Celtic Mystic)."},"loss":{"es":"Lo que se buscó llega, pero no podés buscar más ese turno. Armá la mano pensando en que tras la primera búsqueda no hay segunda.","en":"What you searched arrives, but you cannot search again that turn. Plan the hand as if there is no second search after the first."}},{"card":"Maxx \"C\"","step":"main","stepText":{"es":"En la Main Phase, cada vez que invocás de Especial (Skull Archfiend, Black Chaos, el Ritual).","en":"In the Main Phase, each time you Special Summon (Skull Archfiend, Black Chaos, the Ritual)."},"loss":{"es":"El rival roba una carta por invocación; el mazo hace pocas invocaciones por turno, así que lo aguanta mejor que otros, pero regala recursos.","en":"The opponent draws a card per Summon; the deck makes few Summons per turn, so it handles it better than most, but it gives resources away."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de desterrar de Black Chaos o del Ritual (BLS y Magician of Dark Chaos).","en":"When the banish effect of Black Chaos or the Ritual (BLS or Magician of Dark Chaos) is activated."},"loss":{"es":"Niega la remoción y te deja un monstruo grande sin efecto. Si lo ves venir, activá primero el efecto que menos te importa.","en":"It negates the removal and leaves you a big monster without its effect. If you see it coming, activate the effect you care least about first."}}],"side":{"first":{"in":[{"card":"Solemn Warning","qty":2,"why":{"es":"Anula la invocación o activación que invoca: protege contra el combo rival de segundo turno.","en":"Negates the Summon or activation that Special Summons: protects against the opponent's second-turn combo."}}],"out":[{"card":"Mulcharmy Purulia","qty":1,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero queda muerta.","en":"Only activates with no cards on your field; going first it is dead."}},{"card":"Mulcharmy Fuwalos","qty":1,"why":{"es":"Misma restricción: no se activa con mesa armada.","en":"Same restriction: it does not activate with a board."}}]},"second":{"in":[{"card":"Pot of Sloth","qty":2,"why":{"es":"Robás tantas cartas como cartas controle el rival y devolvés al fondo todas menos 1: sirve contra una mesa ya armada.","en":"Draw as many cards as the opponent controls and put all but 1 on the bottom: useful against an already built board."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo el rival ya jugó su turno.","en":"Reacts to opposing searches; going second the opponent has already taken their turn."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opponent's line than after."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Black Luster Soldier - Soldier of Light and Darkness","url":"https://yugipedia.com/wiki/Black_Luster_Soldier_-_Soldier_of_Light_and_Darkness","kind":"cards","checked":"2026-10-27"},{"name":"Magician of Dark Chaos - Black Chaos","url":"https://yugipedia.com/wiki/Magician_of_Dark_Chaos_-_Black_Chaos","kind":"cards","checked":"2026-10-27"},{"name":"Light and Darkness Ritual","url":"https://yugipedia.com/wiki/Light_and_Darkness_Ritual","kind":"cards","checked":"2026-10-27"},{"name":"Dark Time Wizard","url":"https://yugipedia.com/wiki/Dark_Time_Wizard","kind":"cards","checked":"2026-10-27"},{"name":"Light and Darkness Ritual Mitsurugi, ft. CORI & UT01 Support [CDP]","url":"https://ygorganization.com/cdp_thechaosmegaarticlefollowupishere/","kind":"guide","checked":"2026-10-27"}],"limits":[{"es":"La única guía enlazada es la de YGOrganization, que mezcla Chaos con Mitsurugi: no describe una versión de Chaos Ritual puro ni habla de Nibiru o Maxx \"C\".","en":"The only linked guide is the YGOrganization one, which mixes Chaos with Mitsurugi: it does not describe a pure Chaos Ritual build or discuss Nibiru or Maxx \"C\"."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas publica estadísticas de side para este mazo.","en":"The Side Deck is editorial judgment: none of the linked sources publishes side-deck statistics for this deck."}]},"ocg/mitsurugi-chaos-ritual":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Mezcla dos motores Ritual: el de Mitsurugi (Rituales Reptil de nivel 8 que se tributan entre sí y buscan cartas) y el del Caos (Black Chaos, BLS, Magician of Dark Chaos con Light and Darkness Ritual).","en":"It mixes two Ritual engines: Mitsurugi (Level 8 Reptile Rituals that Tribute each other and search) and Chaos (Black Chaos, BLS, Magician of Dark Chaos with Light and Darkness Ritual)."},{"es":"Ame no Habakiri no Mitsurugi es el arranque: se revela desde la mano para invocar a otro Mitsurugi del Deck y tributar uno, y una vez tributado se invoca de vuelta.","en":"Ame no Habakiri no Mitsurugi starts it: revealed from hand it Special Summons another Mitsurugi from the Deck and Tributes one, and once Tributed it Special Summons itself back."},{"es":"El final suele incluir a Ame no Murakumo no Mitsurugi (destruye monstruos al invocarse y niega o hace descartar como efecto rápido) y una Mitsurugi Great Purification boca abajo.","en":"The end board usually includes Ame no Murakumo no Mitsurugi (destroys monsters when Special Summoned and negates or forces a discard as a Quick Effect) and a Set Mitsurugi Great Purification."},{"es":"Un artículo de YGOrganization marca el primer Ritual del Caos como el turno clave; a partir de ahí el motor Mitsurugi toma el control del turno.","en":"A YGOrganization article marks the first Chaos Ritual Summon as the key turn; after that the Mitsurugi engine takes over the turn."}]},"starters":[{"cards":["Ame no Habakiri no Mitsurugi"],"route":{"es":"Revelás la carta, invocás a Saji o a otro Mitsurugi del Deck y lo tributás; Saji busca Mitsurugi Ritual y la cadena de Rituales arranca sola. Solo una vez por Duelo.","en":"Reveal it, Special Summon Saji or another Mitsurugi from the Deck and Tribute it; Saji adds Mitsurugi Ritual and the Ritual chain starts. Once per Duel only."}},{"cards":["Griffoh","Mind Shuffle"],"route":{"es":"Griffoh descartado pone Mind Shuffle, que agrega Skull Archfiend of Chaos; este, mandado al Cementerio, busca el Ritual que pida un Ritual Spell.","en":"Discarded Griffoh Sets Mind Shuffle, which adds Skull Archfiend of Chaos; sent to the GY it adds the Ritual Monster named on a Ritual Spell."}},{"cards":["Mitsurugi no Mikoto, Saji","Mitsurugi Ritual"],"route":{"es":"Saji busca Mitsurugi Ritual; con ella invocás de Ritual un Reptil de nivel 8 del Deck tributando Reptiles.","en":"Saji adds Mitsurugi Ritual; with it you Ritual Summon a Level 8 Reptile from the Deck by Tributing Reptiles."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra la búsqueda de Saji, Aramasa, Pre-Preparation of Rites o Ragged Records of Rites.","en":"Against the search of Saji, Aramasa, Pre-Preparation of Rites or Ragged Records of Rites."},"loss":{"es":"Sin Mitsurugi Ritual en mano la cadena no arranca. Tener Ritual de respaldo (Mitsurugi Mirror o Light and Darkness Ritual) es lo que te salva.","en":"Without Mitsurugi Ritual in hand the chain does not start. Having a backup Ritual (Mitsurugi Mirror or Light and Darkness Ritual) is what saves you."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, tras la quinta invocación de la jugada.","en":"During the Main Phase, after the fifth Summon of the turn."},"loss":{"es":"Los Rituales se invocan y se tributan una y otra vez, así que se llega rápido a cinco invocaciones; Nibiru tributa toda la mesa.","en":"Rituals are Summoned and Tributed again and again, so five Summons arrive quickly; Nibiru Tributes the whole board."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse la primera búsqueda del turno.","en":"On resolution of the first search of the turn."},"loss":{"es":"Después del primer Mitsurugi Ritual o Mikoto buscado ya no podés agregar más: las respuestas de Aramasa y Kusanagi se quedan sin efecto de búsqueda.","en":"After the first Mitsurugi Ritual or Mikoto is added you cannot add more: Aramasa's and Kusanagi's add effects do nothing."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Contra el efecto de Habakiri (u otro Mitsurugi) que se invoca de vuelta desde el Cementerio al ser tributado.","en":"Against the effect of Habakiri (or another Mitsurugi) that Special Summons itself back from the GY when Tributed."},"loss":{"es":"El bucle depende de revivir Rituales; negar esa activación corta la recursión y deja la mesa corta.","en":"The loop depends on reviving Rituals; negating that activation cuts the recursion and leaves a short board."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de destruir monstruos de Ame no Murakumo no Mitsurugi.","en":"When the destroy-monsters effect of Ame no Murakumo no Mitsurugi is activated."},"loss":{"es":"Se pierde la limpieza del campo rival. Murakumo sigue siendo un cuerpo de 3200 de ATK, pero sin el barrido.","en":"The clear of the opposing field is lost. Murakumo is still a 3200 ATK body, but without the sweep."}}],"side":{"first":{"in":[{"card":"Solemn Judgment","qty":1,"why":{"es":"Anula una invocación o activación pagando la mitad de los LP; protege el combo rival de segundo turno.","en":"Negates a Summon or activation by paying half your LP; protects against the opponent's second-turn combo."}},{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"Corta el combo del rival cuando junta cinco invocaciones.","en":"Ends the opponent's combo once they reach five Summons."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero con mesa queda muerta.","en":"Only activates with no cards on your field; going first with a board it is dead."}}]},"second":{"in":[{"card":"Hey, Space Trunade!","qty":1,"why":{"es":"Devuelve hasta 2 cartas del campo a la mano: útil contra una mesa ya armada.","en":"Returns up to 2 cards from the field to the hand: useful against an already built board."}},{"card":"Ghost Ogre & Snow Rabbit","qty":1,"why":{"es":"Destruye un monstruo que activa su efecto en el campo, buena contra bosses rivales.","en":"Destroys a monster that activates its effect on the field, good against opposing bosses."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Ame no Habakiri no Mitsurugi","url":"https://yugipedia.com/wiki/Ame_no_Habakiri_no_Mitsurugi","kind":"cards","checked":"2026-10-27"},{"name":"Ame no Murakumo no Mitsurugi","url":"https://yugipedia.com/wiki/Ame_no_Murakumo_no_Mitsurugi","kind":"cards","checked":"2026-10-27"},{"name":"Light and Darkness Ritual","url":"https://yugipedia.com/wiki/Light_and_Darkness_Ritual","kind":"cards","checked":"2026-10-27"},{"name":"Light and Darkness Ritual Mitsurugi, ft. CORI & UT01 Support [CDP]","url":"https://ygorganization.com/cdp_thechaosmegaarticlefollowupishere/","kind":"guide","checked":"2026-10-27"}],"limits":[{"es":"Hay una sola guía sobre esta mezcla y no analiza las respuestas a Nibiru ni a Ghost Belle: esas ventanas de interrupción son criterio de la redacción.","en":"There is a single guide on this mix and it does not cover the answers to Nibiru or Ghost Belle: those interruption windows are editorial judgment."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas publica estadísticas de side para este mazo.","en":"The Side Deck is editorial judgment: none of the linked sources publishes side-deck statistics for this deck."}]},"ocg/sacred-beast":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Fallen Paradise of the Sacred Beasts manda 3 cartas del mismo tipo al Cementerio e invoca una Sacred Beast desde la mano, el Deck, el Cementerio o el destierro, inmune a Mágicas/Trampas activadas del rival.","en":"Fallen Paradise of the Sacred Beasts sends 3 cards of the same type to the GY and Special Summons a Sacred Beast from hand, Deck, GY or banishment, unaffected by the opponent's activated Spells/Traps."},{"es":"Con una Bestia de nivel 10 en campo, Fallen Paradise te da un robo de 2 por turno, y Sacred Beasts Released agrega 3 Bestias distintas descartando 2.","en":"With a Level 10 Beast on the field, Fallen Paradise draws 2 per turn, and Sacred Beasts Released adds 3 different Beasts for 2 discards."},{"es":"Martyr of the Sacred Beasts, al ser invocada, pone desde el Deck un Campo, una Mágica Continua o una Trampa Sacred Beast, y si controlás otra Bestia puede invocar de Especial 2 copias de sí misma.","en":"Martyr of the Sacred Beasts, when Summoned, places a Sacred Beast Field Spell, Continuous Spell or Trap from the Deck, and if you control another Beast it can Special Summon 2 copies of itself."}]},"starters":[{"cards":["Martyr of the Sacred Beasts"],"route":{"es":"Al entrar pone un Field Spell o un Continuo Sacred Beast del Deck (Fallen Paradise); con otra Bestia en campo invoca 2 Martyr más.","en":"On Summon it places a Sacred Beast Field Spell or Continuous Spell/Trap from the Deck (Fallen Paradise); with another Beast on the field it Special Summons 2 more Martyrs."}},{"cards":["Sacred Beasts Released"],"route":{"es":"Agrega 3 Sacred Beast distintas del Deck y descarta 2 cartas; deja la mano lista para Fallen Paradise.","en":"Adds 3 different Sacred Beasts from the Deck and discards 2 cards; it sets the hand up for Fallen Paradise."}},{"cards":["Sacred Beasts Thunderclap","Fallen Paradise of the Sacred Beasts"],"route":{"es":"Thunderclap pone 2 copias más boca arriba y, mostrando una Bestia de nivel 10, coloca Fallen Paradise del Deck en la Zona de Campo.","en":"Thunderclap places 2 more copies face-up and, revealing a Level 10 Beast, places Fallen Paradise from the Deck in the Field Zone."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra Sacred Beasts Released o contra la invocación desde el Deck de Fallen Paradise.","en":"Against Sacred Beasts Released or Fallen Paradise's Special Summon from the Deck."},"loss":{"es":"Sin la búsqueda o la invocación, la mano queda sin bosses. Guardá el segundo camino (Summoner of the Sacred Beasts o una Bestia revelada) para esos turnos.","en":"Without the search or the Summon, the hand has no bosses. Keep a second route (Summoner of the Sacred Beasts or a revealed Beast) for those turns."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Cuando la jugada ya está en marcha y las Bestias están en el campo.","en":"When the play is already underway and the Beasts are on the field."},"loss":{"es":"Los tributos son un costo: se pierden 2 Bestias y no destruís nada. Es el peor momento para recibir una negación.","en":"The Tributes are a cost: you lose 2 Beasts and destroy nothing. It is the worst moment to be negated."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse Released o la primera búsqueda del turno.","en":"On resolution of Released or the first search of the turn."},"loss":{"es":"Después de la primera búsqueda no podés usar las demás búsquedas del mazo: la mano queda corta.","en":"After the first search you cannot use the deck's other searches: the hand is short."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, cuando las Martyr y las Bestias suman la quinta invocación.","en":"During the Main Phase, when Martyrs and Beasts reach the fifth Summon."},"loss":{"es":"Con 2 Martyr extra y las Bestias invocadas por Fallen Paradise se llega rápido a cinco; Nibiru tributa la mesa que armaste.","en":"With 2 extra Martyrs and Beasts Summoned by Fallen Paradise, five arrives quickly; Nibiru Tributes the board you built."}}],"side":{"first":{"in":[{"card":"Solemn Warning","qty":2,"why":{"es":"Anula la invocación o activación que invoca: protege cuando el rival juega su combo en el segundo turno.","en":"Negates the Summon or an activation that Special Summons: protects against the opponent's second-turn combo."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero con mesa queda muerta.","en":"Only activates with no cards on your field; going first with a board it is dead."}}]},"second":{"in":[{"card":"Triple Tactics Talent","qty":2,"why":{"es":"Se activa tras un efecto de monstruo rival en tu Main Phase: roba 2, roba el monstruo o baraja una carta de su mano.","en":"Activates after an opposing monster effect in your Main Phase: draw 2, take the monster or shuffle a card from their hand."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Fallen Paradise of the Sacred Beasts","url":"https://yugipedia.com/wiki/Fallen_Paradise_of_the_Sacred_Beasts","kind":"cards","checked":"2026-10-27"},{"name":"Martyr of the Sacred Beasts","url":"https://yugipedia.com/wiki/Martyr_of_the_Sacred_Beasts","kind":"cards","checked":"2026-10-27"},{"name":"Sacred Beasts Released","url":"https://yugipedia.com/wiki/Sacred_Beasts_Released","kind":"cards","checked":"2026-10-27"},{"name":"Sacred Beast deck","url":"https://ygoprodeck.com/deck/sacred-beast-deck-81569","kind":"guide","checked":"2026-10-27"}],"limits":[{"es":"La guía de YGOPRODeck tiene unos 6 años: el mazo recibió cartas nuevas desde entonces, así que el plan puede estar desactualizado.","en":"The YGOPRODeck guide is about 6 years old: the deck has received new cards since, so its plan may be out of date."}]},"ocg/branded":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Fallen of Albaz es el motor: al invocarse, descarta 1 carta y fusiona usando monstruos de cualquiera de los dos campos, así llega a Mirrorjade the Iceblade Dragon con casi cualquier monstruo del Extra Deck rival.","en":"Fallen of Albaz is the engine: when Summoned it discards 1 card and Fusion Summons using monsters on either field, reaching Mirrorjade the Iceblade Dragon with almost any monster in the opponent's Extra Deck."},{"es":"Mirrorjade destierra un monstruo como efecto rápido, y Albion the Branded Dragon encadena otra Fusión de nivel 8 o menos al ser invocado.","en":"Mirrorjade banishes a monster as a Quick Effect, and Albion the Branded Dragon chains another Level 8 or lower Fusion when Summoned."},{"es":"Recicla recursos: Incredible Ecclesia, Blazing Cartesia y Branded in High Spirits vuelven a la mano en la End Phase si una Fusión fue al Cementerio ese turno.","en":"It recycles resources: Incredible Ecclesia, Blazing Cartesia and Branded in High Spirits return to hand in the End Phase if a Fusion went to the GY that turn."},{"es":"Albion the Branded Dragon se fusiona con Fallen of Albaz y 1 monstruo de LUZ.","en":"Albion the Branded Dragon is Fusion Summoned with Fallen of Albaz and 1 LIGHT monster."}]},"starters":[{"cards":["Aluber the Jester of Despia","Branded Fusion"],"route":{"es":"Aluber agrega un Mágica/Trampa Branded (Branded Fusion) y esta fusiona con materiales del Deck para llegar a Albion, Lubellion o Mirrorjade.","en":"Aluber adds a Branded Spell/Trap (Branded Fusion) and it Fusion Summons with materials from the Deck to reach Albion, Lubellion or Mirrorjade."}},{"cards":["Fallen of Albaz"],"route":{"es":"Invocado de Normal o de Especial, descarta 1 y fusiona con monstruos de ambos campos: Mirrorjade con cualquier monstruo del Extra Deck rival.","en":"Normal or Special Summoned, it discards 1 and Fusion Summons with monsters on both fields: Mirrorjade with any monster in the opponent's Extra Deck."}},{"cards":["Nadir Servant"],"route":{"es":"Manda un monstruo del Extra Deck al Cementerio y agrega Fallen of Albaz o un Dogmatika con ATK igual o menor; después no podés invocar del Extra Deck ese turno.","en":"Sends an Extra Deck monster to the GY and adds Fallen of Albaz or a Dogmatika with ATK less than or equal; you cannot Special Summon from the Extra Deck afterwards that turn."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra la búsqueda de Aluber, Nadir Servant o Branded in High Spirits.","en":"Against the add of Aluber, Nadir Servant or Branded in High Spirits."},"loss":{"es":"Sin Branded Fusion o Fallen of Albaz en mano la cadena no arranca. Tener copias extra de Fallen of Albaz y el motor Ecclesia es el plan B.","en":"Without Branded Fusion or Fallen of Albaz in hand the line does not start. Extra Albaz copies and the Ecclesia engine are plan B."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto rápido de Mirrorjade para desterrar.","en":"When Mirrorjade's Quick Effect to banish is activated."},"loss":{"es":"Niega la remoción de tu jefe principal y te deja con un cuerpo de 3000 sin efecto. Guardá Albion y su segunda fusión como alternativa.","en":"It negates your main boss's removal and leaves a 3000 body with no effect. Keep Albion and its second Fusion as an alternative."}},{"card":"Mulcharmy Fuwalos","step":"main","stepText":{"es":"En la Main Phase, cada vez que invocás del Extra Deck o el Deck.","en":"In the Main Phase, each time you Summon from the Extra Deck or Deck."},"loss":{"es":"El mazo invoca mucho de Extra Deck: el rival roba por cada una y al final de turno te obliga a barajar si tenés demasiadas cartas.","en":"The deck Summons from the Extra Deck a lot: the opponent draws for each one and you are forced to shuffle back down in the End Phase if the hand is too big."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Contra los efectos que recuperan o reviven desde el Cementerio (Branded in Red, Guiding Quem, Aluber).","en":"Against effects that recover or revive from the GY (Branded in Red, Guiding Quem, Aluber)."},"loss":{"es":"El mazo vive de recuperar Albaz y Despia del Cementerio; negar esa activación corta la recursión.","en":"The deck lives on recovering Albaz and Despia from the GY; negating that activation cuts the recursion."}},{"card":"Anti-Spell Fragrance","step":"main","stepText":{"es":"Cuando está en el campo: los Mágicas deben ponerse y esperar al turno siguiente.","en":"While it is on the field: Spells must be Set and wait until the next turn."},"loss":{"es":"Branded Fusion, Branded in Red y The Fallen & The Virtuous quedan un turno atrás: el mazo se queda sin su mejor inicio. Guardá cartas de remoción de Mágicas/Trampas en el Side.","en":"Branded Fusion, Branded in Red and The Fallen & The Virtuous fall a turn behind: the deck loses its best opening. Keep Spell/Trap removal in the Side."}}],"side":{"first":{"in":[{"card":"Solemn Accusation","qty":2,"why":{"es":"Niega la activación de una Mágica/Trampa, y se puede activar el turno que se pone mostrando otra Trampa boca abajo.","en":"Negates a Spell/Trap activation, and can be activated the turn it is Set by revealing another face-down Trap."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero queda muerta.","en":"Only activates with no cards on your field; going first it is dead."}}]},"second":{"in":[{"card":"Hey, Space Trunade!","qty":2,"why":{"es":"Devuelve hasta 2 cartas del campo a la mano: ayuda contra la zona de Mágicas/Trampas que el mazo no resuelve solo.","en":"Returns up to 2 cards from the field to the hand: helps against the Spell/Trap zone the deck cannot answer itself."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Fallen of Albaz","url":"https://yugipedia.com/wiki/Fallen_of_Albaz","kind":"cards","checked":"2026-10-27"},{"name":"Mirrorjade the Iceblade Dragon","url":"https://yugipedia.com/wiki/Mirrorjade_the_Iceblade_Dragon","kind":"cards","checked":"2026-10-27"},{"name":"Albion the Branded Dragon","url":"https://yugipedia.com/wiki/Albion_the_Branded_Dragon","kind":"cards","checked":"2026-10-27"},{"name":"Branded Bystial Despia et. al. of the Abyss [CDP]","url":"https://ygorganization.com/cdp_brandedabyss","kind":"guide","checked":"2026-10-27"}],"limits":[{"es":"La guía de YGOrganization es de junio de 2023: puede no reflejar la lista actual del mazo.","en":"The YGOrganization guide is from June 2023: it may not reflect the deck's current list."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas publica estadísticas de side para este mazo.","en":"The Side Deck is editorial judgment: none of the linked sources publishes side-deck statistics for this deck."}]},"ocg/sky-striker":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Raye es la carta principal: como efecto rápido se tributa para invocar un Sky Striker Ace del Extra Deck, y vuelve sola si un Link Sky Striker es destruido en batalla o se va por un efecto rival.","en":"Raye is the main card: as a Quick Effect she Tributes to Special Summon a Sky Striker Ace from the Extra Deck, and returns if a Sky Striker Link is destroyed by battle or leaves due to an opponent's effect."},{"es":"Los Mágicas Sky Striker se potencian con 3 Mágicas en el Cementerio: Engage roba 1, Widow Anchor puede robar el control del monstruo que niega y Kagari gana 100 de ATK por cada Mágica.","en":"Sky Striker Spells scale with 3 Spells in the GY: Engage draws 1, Widow Anchor can take control of the monster it negates and Kagari gains 100 ATK per Spell."},{"es":"El motor Radiant Typhoon llena el Cementerio de Mágicas y encuentra Mystical Space Typhoon (Eldam y Swen buscan; Chant y Vision se vuelven a poner si MST las destruye).","en":"The Radiant Typhoon engine fills the GY with Spells and finds Mystical Space Typhoon (Eldam and Swen search; Chant and Vision are Set again if MST destroys them)."},{"es":"El final típico es Shizuku con 4 o 5 cartas boca abajo, y la guía oficial muestra una línea de 8000 de daño yendo segundo con Linkage y Kagari.","en":"The typical end board is Shizuku with 4 or 5 Set cards, and the official guide shows an 8000-damage line going second with Linkage and Kagari."}]},"starters":[{"cards":["Sky Striker Mobilize - Engage!"],"route":{"es":"Con las Zonas de Monstruo Principales vacías, busca cualquier carta Sky Striker y roba 1 si ya hay 3 Mágicas en el Cementerio.","en":"With your Main Monster Zones empty, adds any Sky Striker card and draws 1 if there are already 3 Spells in the GY."}},{"cards":["Sky Striker Ace - Raye","Sky Striker Mobilize - Linkage!"],"route":{"es":"Raye entra y se tributa a velocidad rápida para invocar un Ace; Linkage invoca otro Ace al Extra Monster Zone, y Kagari recupera Linkage del Cementerio.","en":"Raye comes out and Tributes at Quick Effect speed for an Ace; Linkage Special Summons another Ace to the Extra Monster Zone, and Kagari recovers Linkage from the GY."}},{"cards":["Mystical Space Typhoon","Radiant Typhoon Vision"],"route":{"es":"MST destruye tu propia Radiant Typhoon Vision, que se vuelve a poner y roba 2 cartas: llena el Cementerio de Mágicas.","en":"MST destroys your own Radiant Typhoon Vision, which Sets itself again and draws 2 cards: it fills the GY with Spells."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra Sky Striker Mobilize - Engage! o la búsqueda de Eldam y Swen.","en":"Against Sky Striker Mobilize - Engage! or Eldam's and Swen's searches."},"loss":{"es":"No tenés Multirole en esta lista para hacer imparable a Engage. El Mágica igual va al Cementerio y suma para los 3, pero no buscás ni robás.","en":"This list has no Multirole to make Engage unresponsive. The Spell still goes to the GY and counts toward the 3, but you do not add or draw."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse la primera búsqueda del turno (Engage o Eldam).","en":"On resolution of the first search of the turn (Engage or Eldam)."},"loss":{"es":"Corta la segunda búsqueda: sin el segundo Sky Striker o el MST no se arma el Cementerio y las Mágicas se quedan con efecto sin activar.","en":"It cuts the second search: without the second Sky Striker card or MST the GY never builds and Spells stay below their bonus."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de Kagari o Zero al ser invocados (el que busca o recupera un Mágica).","en":"When Kagari's or Zero's on-Summon effect (the one that adds or recovers a Spell) is activated."},"loss":{"es":"Perdés la recuperación del Mágica; el monstruo queda de cuerpo. Contá con Raye en el Cementerio para volver si lo sacan del campo.","en":"You lose the Spell recovery; the monster is just a body. Count on Raye in the GY to come back if it is removed."}},{"card":"Anti-Spell Fragrance","step":"main","stepText":{"es":"En la Main Phase, cuando está boca arriba: los Mágicas se ponen y esperan al turno siguiente.","en":"In the Main Phase, while face-up: Spells are Set and wait until the next turn."},"loss":{"es":"Engage, Linkage y Widow Anchor ya no se activan en el momento: el mazo pierde casi toda su velocidad. Mystical Space Typhoon es la salida.","en":"Engage, Linkage and Widow Anchor can no longer be played on the spot: the deck loses most of its speed. Mystical Space Typhoon is the way out."}}],"side":{"first":{"in":[{"card":"Solemn Accusation","qty":2,"why":{"es":"Niega una Mágica o Trampa y puede activarse el turno que se pone mostrando otra Trampa boca abajo.","en":"Negates a Spell or Trap and can be activated the turn it is Set by revealing another face-down Trap."}}],"out":[{"card":"Ultimate Sky","qty":2,"why":{"es":"Pide que el rival controle más monstruos que vos, algo raro yendo primero con mesa vacía.","en":"Needs the opponent to control more monsters than you, which is rare going first with an empty board."}}]},"second":{"in":[{"card":"Harpie's Feather Duster","qty":1,"why":{"es":"Destruye todas las Mágicas/Trampas del rival: lo que el mazo no resuelve con su motor.","en":"Destroys all of the opponent's Spells/Traps: what the deck cannot handle with its own engine."}},{"card":"Hey, Space Trunade!","qty":1,"why":{"es":"Devuelve hasta 2 cartas del campo a la mano contra una mesa ya armada.","en":"Returns up to 2 cards from the field to the hand against an already built board."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Sky Striker Ace - Raye","url":"https://yugipedia.com/wiki/Sky_Striker_Ace_-_Raye","kind":"cards","checked":"2026-10-27"},{"name":"Sky Striker Ace - Shizuku","url":"https://yugipedia.com/wiki/Sky_Striker_Ace_-_Shizuku","kind":"cards","checked":"2026-10-27"},{"name":"Sky Striker Mobilize - Engage!","url":"https://yugipedia.com/wiki/Sky_Striker_Mobilize_-_Engage!","kind":"cards","checked":"2026-10-27"},{"name":"Radiant Typhoon Vision","url":"https://yugipedia.com/wiki/Radiant_Typhoon_Vision","kind":"cards","checked":"2026-10-27"},{"name":"Legendary Modern Decks 2026 - Sky Striker","url":"https://yugiohblog.konami.com/2026/news-updates/product-guide/legendary-modern-decks-2026-sky-striker/","kind":"guide","checked":"2026-10-27"}],"limits":[{"es":"La guía oficial de Konami es de un producto TCG (Legendary Modern Decks): el motor Radiant Typhoon aparece ahí solo como una carta sugerida, así que su rol en el mazo OCG es criterio de la redacción.","en":"Konami's official guide is for a TCG product (Legendary Modern Decks): the Radiant Typhoon engine shows up there only as a suggested card, so its role in the OCG deck is editorial judgment."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas publica estadísticas de side para este mazo.","en":"The Side Deck is editorial judgment: none of the linked sources publishes side-deck statistics for this deck."}]},"ocg/kewl-tune":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Todo el tema son Tuners: un Kewl Tune en el campo que se use de materia Sincro puede usar un Tuner de la mano como otro material, lo que acelera la cadena de Sincros.","en":"The whole theme is Tuners: a Kewl Tune on the field used as Synchro Material can use a Tuner in hand as another material, which speeds up the chain of Synchros."},{"es":"Cue invoca un Tuner de la mano, el Deck o el Cementerio al ser invocado de Normal; Mix y Reco buscan otro Kewl Tune; Rotary mira la mano rival y busca un Mágica Kewl Tune.","en":"Cue Special Summons a Tuner from hand, Deck or GY when Normal Summoned; Mix and Reco add another Kewl Tune; Rotary looks at the opponent's hand and adds a Kewl Tune Spell."},{"es":"Kewl Tune Clip se juega desde la mano en la Main Phase rival para sincronizar un Tuner Sincro.","en":"Kewl Tune Clip is played from hand in the opponent's Main Phase to Synchro Summon a Tuner Synchro."},{"es":"Kewl Tune B2B da doble ataque a los Tuners y, cuando el rival activa un efecto de monstruo, recicla un Tuner del Cementerio o de los desterrados.","en":"Kewl Tune B2B gives Tuners a second attack and, when the opponent activates a monster effect, recycles a Tuner from the GY or banishment."}]},"starters":[{"cards":["Kewl Tune Mix"],"route":{"es":"Invocado, agrega otro Kewl Tune de nivel distinto de 2 (por ejemplo Cue o Reco); mandado al Cementerio como material, destruye un monstruo rival.","en":"Summoned, it adds another Kewl Tune that is not Level 2 (for example Cue or Reco); sent to the GY as material, it destroys an opposing monster."}},{"cards":["Kewl Tune Synchro"],"route":{"es":"Agrega una carta Kewl Tune del Deck y sincroniza un Tuner Sincro de inmediato; después solo podés invocar Tuners ese turno.","en":"Adds a Kewl Tune card from the Deck and Synchro Summons a Tuner Synchro right away; afterwards you can only Special Summon Tuners that turn."}},{"cards":["Kewl Tune Clip"],"route":{"es":"En la Main Phase rival se invoca desde la mano y sincroniza un Tuner Sincro: sirve para interrumpir en el turno rival.","en":"In the opponent's Main Phase it Special Summons from hand and Synchro Summons a Tuner Synchro: it interrupts on the opponent's turn."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra las búsquedas de Mix, Reco, Kewl Tune Synchro o Duelist Genesis, y la invocación desde el Deck de Cue u Over Tuning.","en":"Against the adds of Mix, Reco, Kewl Tune Synchro or Duelist Genesis, and the Deck Summon of Cue or Over Tuning."},"loss":{"es":"Cada Tuner depende de que otro lo busque; negar esa activación deja un solo Tuner y rompe la cadena. Tené más de un inicio en la mano.","en":"Each Tuner depends on another one fetching it; negating that activation leaves a single Tuner and breaks the chain. Keep more than one opener in hand."}},{"card":"Maxx \"C\"","step":"main","stepText":{"es":"En la Main Phase, cada vez que el mazo invoca de Especial.","en":"In the Main Phase, each time the deck Special Summons."},"loss":{"es":"La cadena de Tuners son muchas invocaciones y Maxx \"C\" le da al rival un robo por cada invocación de Especial.","en":"The Tuner chain is many Summons and Maxx \"C\" gives the opponent a draw for each Special Summon."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, tras la quinta invocación del turno.","en":"During the Main Phase, after the fifth Summon of the turn."},"loss":{"es":"Los Sincros más los Tuners llegan a cinco invocaciones enseguida; Nibiru tributa toda la mesa.","en":"Synchros plus Tuners reach five Summons quickly; Nibiru Tributes the whole board."}},{"card":"Red Reboot","step":"activation","stepText":{"es":"Cuando activás una Trampa del mazo (Kewl Tune Playlist o Infinite Impermanence).","en":"When you activate a Trap from the deck (Kewl Tune Playlist or Infinite Impermanence)."},"loss":{"es":"Niega la activación y la pone boca abajo; además no podés activar más Trampas ese turno. Playlist y Impermanence no sirven en esa vuelta.","en":"It negates the activation and Sets the card; you also cannot activate more Traps that turn. Playlist and Impermanence do nothing that round."}}],"side":{"first":{"in":[{"card":"Nibiru, the Primal Being","qty":2,"why":{"es":"Una sola carta termina el combo rival cuando junta cinco invocaciones.","en":"One card ends the opponent's combo once they reach five Summons."}}],"out":[{"card":"Effect Veiler","qty":2,"why":{"es":"Niega un solo monstruo; Nibiru limpia toda la jugada.","en":"Negates one monster; Nibiru clears the whole line."}}]},"second":{"in":[{"card":"Ultimate Sky","qty":2,"why":{"es":"Con el rival con más monstruos que vos, niega varios efectos a la vez a 800 LP cada uno.","en":"With the opponent holding more monsters than you, it negates several effects at once for 800 LP each."}}],"out":[{"card":"Ghost Ogre & Snow Rabbit","qty":2,"why":{"es":"Destruye un solo monstruo; Ultimate Sky frena más de uno por turno.","en":"Destroys a single monster; Ultimate Sky stops more than one per turn."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Kewl Tune Cue","url":"https://yugipedia.com/wiki/Kewl_Tune_Cue","kind":"cards","checked":"2026-10-27"},{"name":"Kewl Tune Clip","url":"https://yugipedia.com/wiki/Kewl_Tune_Clip","kind":"cards","checked":"2026-10-27"},{"name":"Kewl Tune B2B","url":"https://yugipedia.com/wiki/Kewl_Tune_B2B","kind":"cards","checked":"2026-10-27"},{"name":"Elfnote Kewl Tune, ft. BLZD Support [CDP]","url":"https://ygorganization.com/cdp_elfnotekewlz/","kind":"guide","checked":"2026-10-27"},{"name":"Pure Kewl Tune","url":"https://ygoprodeck.com/deck/pure-kewl-tune-725494","kind":"guide","checked":"2026-10-27"}],"limits":[{"es":"La guía de YGOrganization es de febrero de 2026, anterior a la banlist OCG de octubre de 2026: revisá la banlist OCG vigente antes de copiar las cantidades.","en":"The YGOrganization guide is from February 2026, before the October 2026 OCG banlist: check the current OCG banlist before copying the copy counts."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas publica estadísticas de side para este mazo.","en":"The Side Deck is editorial judgment: none of the linked sources publishes side-deck statistics for this deck."}]},"ocg/maliss":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Los monstruos Maliss desterrados vuelven pagando 300 LP, y las Trampas Maliss se pueden activar el turno que se ponen desterrando un Maliss tuyo en el campo.","en":"Banished Maliss monsters return for 300 LP, and Maliss Traps can be activated the turn they are Set by banishing a face-up Maliss monster you control."},{"es":"Sube de Link con Cyberse: Maliss Hearts Crypter (barajá un Maliss desterrado para desterrar 1 carta del campo) y White Binder, y puede seguir subiendo hasta Accesscode Talker.","en":"It Link-climbs with Cyberse: Maliss Hearts Crypter (shuffle a banished Maliss to banish 1 card on the field) and White Binder, and can keep climbing up to Accesscode Talker."},{"es":"Maliss in Underground da 3000 de ATK a los Links Maliss con 3 Trampas Maliss distintas desterradas y obliga a los monstruos rivales a atacar solo a Links Maliss.","en":"Maliss in Underground gives Maliss Links 3000 ATK with 3 different Maliss Traps banished and forces opposing monsters to attack only Maliss Links."},{"es":"Maliss White Binder, al ser invocada de Especial, destierra hasta 3 cartas de cualquier Cementerio, y su efecto de ignición pone 1 Trampa Maliss desde el Deck o el Cementerio.","en":"Maliss White Binder, when Special Summoned, banishes up to 3 cards from either GY, and its ignition effect Sets 1 Maliss Trap from the Deck or GY."}]},"starters":[{"cards":["Terraforming","Maliss in Underground"],"route":{"es":"Terraforming busca el Field Spell Maliss in Underground; al activarlo destierra una carta Maliss de la mano, el Deck o el Cementerio y arma la mesa.","en":"Terraforming adds the Field Spell Maliss in Underground; on activation it banishes a Maliss card from hand, Deck or GY and sets the board up."}},{"cards":["Backup @Ignister","Wizard @Ignister"],"route":{"es":"Backup agrega un Cyberse DARK y descarta 1; Wizard se invoca junto a un Cyberse DARK del Cementerio si controlás un Cyberse del Extra Deck.","en":"Backup adds a DARK Cyberse and discards 1; Wizard Special Summons itself with a DARK Cyberse from the GY if you control a Cyberse from the Extra Deck."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra Backup @Ignister, Terraforming u otra búsqueda del mazo.","en":"Against Backup @Ignister, Terraforming or another search in the deck."},"loss":{"es":"Cortan el extensor que traía el Cyberse DARK. White Rabbit y las Trampas no son búsquedas, así que la mano puede seguir sin esa carta.","en":"It cuts the extender that brought the DARK Cyberse. White Rabbit and the Traps are not searches, so the hand can keep going without that card."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, tras la quinta invocación del turno.","en":"During the Main Phase, after the fifth Summon of the turn."},"loss":{"es":"Los Links y los Maliss que vuelven del destierro suman invocaciones rápido; Nibiru tributa toda la mesa de Links.","en":"Links and Maliss monsters coming back from banishment add Summons quickly; Nibiru Tributes the whole Link board."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de desterrar de Maliss Hearts Crypter.","en":"When Maliss Hearts Crypter's banish effect is activated."},"loss":{"es":"Crypter es inmune a la negación solo si apunta a un monstruo; si no, Impermanence lo frena. Apuntá a un monstruo con el Link antes de usarlo.","en":"Crypter cannot be negated only while pointing to a monster; otherwise Impermanence stops it. Make it point to a monster before using it."}},{"card":"Mulcharmy Fuwalos","step":"main","stepText":{"es":"En la Main Phase, cada vez que invocás del Extra Deck.","en":"In the Main Phase, each time you Summon from the Extra Deck."},"loss":{"es":"La subida de Links son muchas invocaciones: el rival roba por cada una. Si te frenan, quedás con menos tablero y el rival con más cartas.","en":"Link climbing is many Summons: the opponent draws for each one. If you are stopped you have less board and they have more cards."}}],"side":{"first":{"in":[{"card":"Solemn Warning","qty":2,"why":{"es":"Anula la invocación o activación que invoca: protege contra el combo rival en el segundo turno.","en":"Negates the Summon or an activation that Special Summons: protects against the opponent's second-turn combo."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero con mesa queda muerta.","en":"Only activates with no cards on your field; going first with a board it is dead."}}]},"second":{"in":[{"card":"Hey, Space Trunade!","qty":2,"why":{"es":"Devuelve hasta 2 cartas del campo a la mano: ayuda contra una mesa rival ya armada.","en":"Returns up to 2 cards from the field to the hand: helps against an already built opposing board."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Maliss in Underground","url":"https://yugipedia.com/wiki/Maliss_in_Underground","kind":"cards","checked":"2026-10-27"},{"name":"Pure Maliss","url":"https://ygoprodeck.com/deck/pure-maliss-679662","kind":"guide","checked":"2026-10-27"},{"name":"CDP: Maliss Live Twin Cynet, ft. DBCB Support","url":"https://ygorganization.com/cdp_malisslivetwin/","kind":"guide","checked":"2026-10-27"},{"name":"OCG 2026.07 Metagame Report #6, #7","url":"https://roadoftheking.com/ocg-2026-07-metagame-report-6-7/","kind":"results","checked":"2026-10-27"}],"limits":[{"es":"Pure Maliss es una lista casual: su autor aclara que no está pensada para ser competitiva ni meta. El peso del mazo en el meta sale del reporte de Road of the King 2026.07, que cuenta 6 Maliss entre 197 listas.","en":"Pure Maliss is a casual list: its author says it is not meant to be competitive or meta. The deck's weight in the meta comes from the Road of the King 2026.07 report, which counts 6 Maliss among 197 lists."}]},"ocg/trirealm-rift":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Cada monstruo Trirealm Rift destierra boca abajo las primeras cartas de tu Deck al entrar (Gehenna 1, Sheol 2, Tuonela 3, Naraka 4, Yomi 5, Helheim 6, Ploutonion 7, Darkness 8) y esa pila es un segundo Deck.","en":"Each Trirealm Rift monster banishes the top cards of your Deck face-down when it comes in (Gehenna 1, Sheol 2, Tuonela 3, Naraka 4, Yomi 5, Helheim 6, Ploutonion 7, Darkness 8) and that pile works as a second Deck."},{"es":"Gehenna recupera hasta 2 monstruos desterrados boca abajo y Sheol recupera Mágicas/Trampas; Valvols y Gospel destierran 5 cartas del Cementerio o del Deck para sostener la pila.","en":"Gehenna recovers up to 2 face-down banished monsters and Sheol recovers Spells/Traps; Valvols and Gospel banish 5 cards from the GY or Deck to feed the pile."},{"es":"Interactúa desde la mano y el destierro: Yomi niega un efecto de monstruo rival, Helheim se invoca como efecto rápido y Ploutonion baraja al Deck un monstruo rival del mismo Atributo.","en":"It interacts from hand and banishment: Yomi negates an opposing monster effect, Helheim Special Summons as a Quick Effect and Ploutonion shuffles an opposing monster of the same Attribute into the Deck."},{"es":"Trirealm Rift Darkness gana efectos según las cartas desterradas boca abajo: con 20 o más destruye una carta como efecto rápido, con 40 o más salta las Draw Phase.","en":"Trirealm Rift Darkness gains effects by face-down banished cards: with 20 or more it destroys a card as a Quick Effect, with 40 or more it skips Draw Phases."}]},"starters":[{"cards":["Trirealm Rift of Emptiness Gehenna","Trirealm Rift of Sky Sheol"],"route":{"es":"Gehenna se invoca de la mano sin monstruos y recupera monstruos desterrados; Sheol, invocado con un Trirealm Rift en campo, recupera Mágicas/Trampas.","en":"Gehenna Special Summons from hand with no monsters and recovers banished monsters; Sheol, Special Summoned with a Trirealm Rift on the field, recovers Spells/Traps."}},{"cards":["Trirealm Rift Territory - Valvols","Trirealm Rift Gospel"],"route":{"es":"Ambos se activan desterrando 5 cartas boca abajo del Cementerio o del Deck; Valvols agrega una carta Trirealm Rift desterrada y Gospel da una Invocación Normal extra.","en":"Both activate by banishing 5 face-down cards from the GY or Deck; Valvols adds a banished Trirealm Rift card and Gospel gives an extra Normal Summon."}},{"cards":["Mad Tempest Trirealm Rift Ploutonion"],"route":{"es":"Desde la mano, junto a otra carta Trirealm Rift, se destierran ambas boca abajo para robar 2: carga la pila y repone la mano.","en":"From hand with another Trirealm Rift card, both are banished face-down to draw 2: it loads the pile and refills the hand."}}],"chokepoints":[{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Contra Burial Summit Trirealm Rift Helheim, antes de que proteja a los demás.","en":"Against Burial Summit Trirealm Rift Helheim, before it protects the rest."},"loss":{"es":"Helheim impide que apunten o destruyan por efecto a las otras cartas Trirealm Rift, pero a él sí: quien lo niega primero deja la mesa sin escudo.","en":"Helheim stops targeting or effect destruction of your other Trirealm Rift cards, but not of itself: negating it first leaves the board without its shield."}},{"card":"Dominus Impulse","step":"summon","stepText":{"es":"Contra la invocación especial por efecto de Helheim, Naraka o Gehenna.","en":"Against the Special Summon effect of Helheim, Naraka or Gehenna."},"loss":{"es":"Anula el efecto que invoca desde el destierro. Con la pila intacta se puede reintentar con otra carta, pero se pierde la jugada del turno.","en":"It negates the effect that Special Summons from banishment. With the pile intact you can retry with another card, but the turn's play is lost."}},{"card":"Effect Veiler","step":"main","stepText":{"es":"En la Main Phase, contra Burial Summit Trirealm Rift Helheim boca arriba.","en":"In the Main Phase, against a face-up Burial Summit Trirealm Rift Helheim."},"loss":{"es":"Niega sus efectos ese turno, así que las otras cartas Trirealm Rift pierden el escudo contra efectos que apuntan o destruyen. Jugá Helheim solo cuando tengas con qué reponerlo.","en":"It negates its effects that turn, so the other Trirealm Rift cards lose their shield against targeting and destroying effects. Play Helheim only when you can replace it."}}],"side":{"first":{"in":[{"card":"Mistaken Arrest","qty":2,"why":{"es":"Nadie añade cartas del Deck a la mano por un turno; el mazo recupera desde el destierro, no del Deck.","en":"Nobody adds cards from the Deck to the hand for a turn; the deck recovers from banishment, not the Deck."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Deja pasar la primera búsqueda; Mistaken Arrest las corta todas.","en":"It lets the first search through; Mistaken Arrest stops them all."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Con Mistaken Arrest en el Side hay una forma más fiable de frenar combos.","en":"With Mistaken Arrest in the Side there is a more reliable way to stop combos."}}]},"second":{"in":[{"card":"Ultimate Sky","qty":2,"why":{"es":"Con el rival con más monstruos, niega varios efectos pagando 800 LP por cada uno.","en":"With the opponent holding more monsters, it negates several effects paying 800 LP each."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26","sources":[{"name":"Trirealm Rift of Emptiness Gehenna","url":"https://yugipedia.com/wiki/Trirealm_Rift_of_Emptiness_Gehenna","kind":"cards","checked":"2026-10-27"},{"name":"Trirealm Rift Darkness","url":"https://yugipedia.com/wiki/Trirealm_Rift_Darkness","kind":"cards","checked":"2026-10-27"},{"name":"Mad Tempest Trirealm Rift Ploutonion","url":"https://yugipedia.com/wiki/Mad_Tempest_Trirealm_Rift_Ploutonion","kind":"cards","checked":"2026-10-27"},{"name":"Trirealm Rift with Shining Sarcophagus, ft. DBGV Support [CDP]","url":"https://ygorganization.com/cdp_banishallthedeck","kind":"guide","checked":"2026-10-27"}],"limits":[{"es":"La única guía es de YGOrganization, enfocada en una versión con Shining Sarcophagus, y no habla de debilidades ni de interrupciones: eso es criterio de la redacción.","en":"The only guide is the YGOrganization one, focused on a Shining Sarcophagus build, and it does not discuss weaknesses or interruptions: that is editorial judgment."},{"es":"El Side Deck es criterio de la redacción: ninguna de las fuentes enlazadas publica estadísticas de side para este mazo.","en":"The Side Deck is editorial judgment: none of the linked sources publishes side-deck statistics for this deck."}]}});